import{n as i}from"./shared-CAKwAg2C.js";const h={"LEARN HOW THE INTERNET WORKS":"ΜΑΘΕΤΕ ΠΩΣ ΛΕΙΤΟΥΡΓΕΙ ΤΟ ΙΝΤΕΡΝΕΤ","NOW LEARNING":"ΜΑΘΑΙΝΕΤΕ ΤΩΡΑ","OSI LAYER":"ΕΠΙΠΕΔΟ OSI","LEARNING PROGRESS":"Η ΠΡΟΟΔΟΣ ΣΑΣ",COMPLETE:"ΟΛΟΚΛΗΡΩΜΕΝΑ","IN PROGRESS":"ΣΕ ΕΞΕΛΙΞΗ","{pct}% complete":"{pct}% ολοκληρώθηκε","DESIGNED BY":"ΣΧΕΔΙΑΣΜΟΣ","Dilum Sanjaya on X":"Ο Dilum Sanjaya στο X","Layer {n}: {name}":"Επίπεδο {n}: {name}",Physical:"Φυσικό","Data Link":"Ζεύξης δεδομένων",Network:"Δικτύου",Transport:"Μεταφοράς",Session:"Συνόδου",Presentation:"Παρουσίασης",Application:"Εφαρμογής","OVERVIEW · {n} STEPS":"ΕΠΙΣΚΟΠΗΣΗ · {n} ΒΗΜΑΤΑ","STEP {n}/{total} · {title}":"ΒΗΜΑ {n}/{total} · {title}","LESSON COMPLETE":"ΤΟ ΜΑΘΗΜΑ ΟΛΟΚΛΗΡΩΘΗΚΕ",PROTOCOLS:"ΠΡΩΤΟΚΟΛΛΑ",Protocols:"Πρωτόκολλα",Language:"Γλώσσα",Theme:"Θέμα","Light mode":"Φωτεινό θέμα","Dark mode":"Σκοτεινό θέμα","INTERNET PROTOCOLS":"ΠΡΩΤΟΚΟΛΛΑ ΔΙΑΔΙΚΤΥΟΥ","Close the protocol list":"Κλείσιμο λίστας πρωτοκόλλων","Close (Esc)":"Κλείσιμο (Esc)",ALL:"ΟΛΑ",CORE:"ΒΑΣΙΚΑ",APPLICATION:"ΕΦΑΡΜΟΓΕΣ",SECURITY:"ΑΣΦΑΛΕΙΑ",NETWORK:"ΔΙΚΤΥΟ",SEQUENCE:"ΑΚΟΛΟΥΘΙΑ",View:"Προβολή","Switch view (V)":"Αλλαγή προβολής (V)","Network diagram":"Διάγραμμα δικτύου","Sequence diagram":"Διάγραμμα ακολουθίας","STEP {n}":"ΒΗΜΑ {n}","PROTOCOL OVERVIEW":"ΕΠΙΣΚΟΠΗΣΗ ΠΡΩΤΟΚΟΛΛΟΥ","STEP DETAILS":"ΤΡΕΧΟΝ ΒΗΜΑ","LESSON SUMMARY":"ΣΥΝΟΨΗ ΜΑΘΗΜΑΤΟΣ",OVERVIEW:"ΕΠΙΣΚΟΠΗΣΗ",ACTIVE:"ΕΝΕΡΓΟ","STEP {n} OF {total}":"ΒΗΜΑ {n} ΑΠΟ {total}","PACKET {n} OF {total}":"ΠΑΚΕΤΟ {n} ΑΠΟ {total}","PACKETS {from}–{to} OF {total}":"ΠΑΚΕΤΑ {from}–{to} ΑΠΟ {total}","{n} LOST":"{n} ΧΑΘΗΚΑΝ","1 LOST":"1 ΧΑΘΗΚΕ",ENCRYPTED:"ΚΡΥΠΤΟΓΡΑΦΗΜΕΝΟ","LOST ON THE WAY":"ΧΑΘΗΚΕ ΣΤΗ ΔΙΑΔΡΟΜΗ","PACKET FLOW":"ΡΟΗ ΠΑΚΕΤΩΝ","Colour key":"Υπόμνημα χρωμάτων","Playback speed":"Ταχύτητα αναπαραγωγής","Previous step (←)":"Προηγούμενο βήμα (←)","Previous step":"Προηγούμενο βήμα","Play / pause (Space)":"Αναπαραγωγή / παύση (Space)",PLAY:"ΕΝΑΡΞΗ",PAUSE:"ΠΑΥΣΗ",REPLAY:"ΞΑΝΑ",STEP:"ΒΗΜΑ","One packet at a time":"Ένα πακέτο τη φορά",RESET:"ΕΠΑΝΑΦΟΡΑ",Reset:"Επαναφορά","Back to the overview (Esc)":"Επιστροφή στην επισκόπηση (Esc)","NO.":"Α/Α",TIME:"ΧΡΟΝΟΣ",SOURCE:"ΠΗΓΗ",DESTINATION:"ΠΡΟΟΡΙΣΜΟΣ",PROTOCOL:"ΠΡΩΤΟΚΟΛΛΟ",INFO:"ΠΛΗΡΟΦΟΡΙΕΣ",SIZE:"ΜΕΓΕΘΟΣ","No packets on the wire yet.":"Δεν υπάρχουν ακόμη πακέτα στη γραμμή.",LOST:"ΧΑΘΗΚΕ","Packet inspector":"Επιθεωρητής πακέτων","Previous packet":"Προηγούμενο πακέτο","Previous packet (←)":"Προηγούμενο πακέτο (←)","Next packet":"Επόμενο πακέτο","Next packet (→)":"Επόμενο πακέτο (→)",Close:"Κλείσιμο","E.G.":"Π.Χ.","an example value: it differs in every real capture":"ενδεικτική τιμή: διαφέρει σε κάθε πραγματική καταγραφή","bytes the lesson can’t show: encrypted, random, or a file’s contents":"byte που το μάθημα δεν μπορεί να δείξει: κρυπτογραφημένα, τυχαία ή το περιεχόμενο ενός αρχείου",BYTES:"BYTE","{n} in this frame":"{n} σε αυτό το πλαίσιο","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Αυτή η γραμμή αντιστοιχεί σε {n} τμήματα TCP που μεταφέρουν ένα μήνυμα {size} byte· εμφανίζεται το πρώτο τμήμα","This packet was lost on the way":"Αυτό το πακέτο χάθηκε στη διαδρομή",Padding:"Συμπλήρωμα","One packet at a time (S)":"Ένα πακέτο τη φορά (S)","KEYBOARD SHORTCUTS":"ΣΥΝΤΟΜΕΥΣΕΙΣ ΠΛΗΚΤΡΟΛΟΓΙΟΥ","Press {key} any time to see these again.":"Πατήστε {key} οποιαδήποτε στιγμή για να τις ξαναδείτε.","Search protocols":"Εύρεση πρωτοκόλλου","Search protocols and steps":"Αναζήτηση πρωτοκόλλων και βημάτων","Nothing matches.":"Δεν βρέθηκε τίποτα.","to move":"για μετακίνηση","to open":"για άνοιγμα","Protocol list":"Λίστα πρωτοκόλλων","Diagram only":"Μόνο το διάγραμμα",Fullscreen:"Πλήρης οθόνη","Keyboard shortcuts":"Συντομεύσεις πληκτρολογίου",Playback:"Αναπαραγωγή","Hide the protocol list (L)":"Απόκρυψη λίστας πρωτοκόλλων (L)","Diagram only (D)":"Μόνο το διάγραμμα (D)","Fullscreen (F)":"Πλήρης οθόνη (F)","Keyboard shortcuts (?)":"Συντομεύσεις πληκτρολογίου (?)","Show the protocol list (L)":"Εμφάνιση λίστας πρωτοκόλλων (L)","Show all panels (D)":"Εμφάνιση όλων των πλαισίων (D)","Exit fullscreen (F)":"Έξοδος από πλήρη οθόνη (F)","Play or pause":"Αναπαραγωγή ή παύση","Next step":"Επόμενο βήμα","Go to step 1 to 9":"Μετάβαση στα βήματα 1 έως 9","Slower, faster":"Πιο αργά, πιο γρήγορα","Back to the overview":"Επιστροφή στην επισκόπηση","Network or sequence view":"Προβολή δικτύου ή ακολουθίας","Show or hide the protocol list":"Εμφάνιση ή απόκρυψη λίστας πρωτοκόλλων","Light or dark theme":"Φωτεινό ή σκοτεινό θέμα",Find:"Αναζήτηση","Next or previous protocol":"Επόμενο ή προηγούμενο πρωτόκολλο","These shortcuts":"Αυτές οι συντομεύσεις","Previous or next packet":"Προηγούμενο ή επόμενο πακέτο","Close it":"Κλείσιμο"},d={"Hypertext Transfer Protocol":"Hypertext Transfer Protocol","HTTP Secure":"Ασφαλές HTTP","Transmission Control Protocol":"Transmission Control Protocol","User Datagram Protocol":"User Datagram Protocol","Internet Protocol":"Internet Protocol","Domain Name System":"Domain Name System","Dynamic Host Configuration":"Δυναμική ρύθμιση υπολογιστών","Internet Control Message":"Μηνύματα ελέγχου του Διαδικτύου","Simple Mail Transfer Protocol":"Simple Mail Transfer Protocol","Post Office Protocol v3":"Post Office Protocol v3","Internet Message Access":"Πρόσβαση σε μηνύματα του Διαδικτύου","File Transfer Protocol":"File Transfer Protocol","Secure Shell":"Secure Shell","Transport Layer Security":"Transport Layer Security",Internet:"Διαδίκτυο",Client:"Πελάτης",Router:"Δρομολογητής","DNS Resolver":"Επιλυτής DNS","Web Server":"Διακομιστής web","Root Server":"Ριζικός διακομιστής",".com TLD Server":"Διακομιστής TLD .com","Authoritative Server":"Έγκυρος διακομιστής","Mail Server":"Διακομιστής αλληλογραφίας",".com Server":"Διακομιστής .com",Authoritative:"Έγκυρος",Server:"Διακομιστής","Web Communication":"Επικοινωνία στο web",Request:"Αίτημα",Response:"Απάντηση","Data ACKs not shown":"Δεν φαίνονται τα ACK των δεδομένων","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"Το HTTP είναι το πρωτόκολλο του web: ένας πελάτης ζητά έναν πόρο, όπως μια σελίδα HTML, και ο διακομιστής απαντά με κωδικό κατάστασης, κεφαλίδες και συνήθως ένα σώμα. Κάθε ανταλλαγή είναι ένα αίτημα και μία απάντηση, γραμμένα ως αναγνώσιμο κείμενο στο HTTP/1.1.",Layer:"Επίπεδο","Application (Layer 7)":"Εφαρμογής (επίπεδο 7)","Default Port":"Προεπιλεγμένη θύρα","Data Format":"Μορφή δεδομένων","Text (headers + optional body)":"Κείμενο (κεφαλίδες + προαιρετικό σώμα)","Common Methods":"Συνήθεις μέθοδοι","Defined In":"Ορίζεται στο","Page delivered":"Η σελίδα παραδόθηκε","One request, one response":"Ένα αίτημα, μία απάντηση","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"Σε λιγότερο από ένα δέκατο του δευτερολέπτου ο φορητός βρήκε μια διεύθυνση, άνοιξε μια σύνδεση TCP και αντάλλαξε ένα αίτημα και μία απάντηση HTTP, όλα αναγνώσιμα από οποιονδήποτε στη διαδρομή. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","Round trips":"Διαδρομές μετ’ επιστροφής","Total time":"Συνολικός χρόνος","Page size":"Μέγεθος σελίδας","Sent as 9 TCP segments":"Στάλθηκε σε 9 τμήματα TCP","Client Request":"Αίτημα του πελάτη","Browser prepares the request":"Ο browser ετοιμάζει το αίτημα","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Ανοίγετε το http://www.example.com. Ο browser θα στείλει ένα αίτημα GET, όμως τα πακέτα ταξιδεύουν προς διευθύνσεις IP, όχι προς ονόματα, οπότε πρώτα χρειάζεται τη διεύθυνση του διακομιστή. (Σήμερα οι browser δοκιμάζουν πρώτα το https://· αυτή είναι η απλή εκδοχή.)",Method:"Μέθοδος","Next hop":"Επόμενο βήμα δρομολόγησης","Router 192.168.1.1":"Δρομολογητής 192.168.1.1","DNS Resolution":"Επίλυση DNS","Finds the server’s IP address":"Βρίσκει τη διεύθυνση IP του διακομιστή","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"Ο φορητός ρωτά τον διακομιστή DNS που του έδωσε το DHCP, το 8.8.8.8, για τη διεύθυνση του www.example.com. Η ερώτηση πηγαίνει μέσω UDP στη θύρα 53 και η απάντηση είναι μια εγγραφή A με τη διεύθυνση IPv4. (Σε δίκτυο με IPv6 θα ζητούσε και εγγραφή AAAA.)",Resolver:"Επιλυτής","8.8.8.8 (had it cached)":"8.8.8.8 (το είχε στη μνήμη cache)","UDP, port 53":"UDP, θύρα 53",Answer:"Απάντηση","DNS QUERY":"ΕΡΩΤΗΜΑ DNS","DNS REPLY":"ΑΠΑΝΤΗΣΗ DNS","TCP Connection":"Σύνδεση TCP","Establishes a reliable link":"Στήνει μια αξιόπιστη σύνδεση","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"Το HTTP λειτουργεί πάνω από το TCP. Πριν μετακινηθούν δεδομένα της σελίδας, ο φορητός και ο διακομιστής ανοίγουν σύνδεση προς τη θύρα 80 με χειραψία τριών βημάτων: SYN, SYN-ACK, ACK.","Server port":"Θύρα διακομιστή","Client port":"Θύρα πελάτη",Handshake:"Χειραψία","HTTP Exchange":"Ανταλλαγή HTTP","Request and response messages":"Μηνύματα αιτήματος και απάντησης","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Ο browser στέλνει ένα αίτημα GET με κεφαλίδα Host. Ο διακομιστής απαντά 200 OK με το HTML στο σώμα: 12.2 KB, πολύ για ένα πακέτο, οπότε το TCP το χωρίζει σε 9 τμήματα έως 1460 byte (εδώ σχεδιάζονται ως ένα).",Status:"Κατάσταση",Body:"Σώμα","text/html, 12.2 KB":"text/html, 12.2 KB","Sent as":"Στάλθηκε ως","12.2 KB in 9 segments":"12.2 KB σε 9 τμήματα","Page Rendering":"Απόδοση της σελίδας","Browser displays the content":"Ο browser εμφανίζει το περιεχόμενο","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Ο browser αναλύει το HTML και σχεδιάζει τη σελίδα. Τα συνδεδεμένα CSS, εικόνες και σενάρια θα ξεκινούσαν το καθένα νέα αιτήματα σαν αυτό, ξαναχρησιμοποιώντας την ανοιχτή σύνδεση όπου μπορούν.",Document:"Έγγραφο",Connection:"Σύνδεση","Kept open for reuse":"Μένει ανοιχτή για επαναχρησιμοποίηση","Seen on the laptop’s home network":"Όπως φαίνεται στο οικιακό δίκτυο του φορητού",Destination:"Προορισμός","The router: anything beyond the home network goes to it first.":"Ο δρομολογητής: ό,τι πηγαίνει πέρα από το οικιακό δίκτυο περνά πρώτα από αυτόν.",Source:"Πηγή","The laptop’s network card.":"Η κάρτα δικτύου του φορητού.",Type:"Τύπος","What the frame carries.":"Τι μεταφέρει το πλαίσιο.","Version, header length":"Έκδοση, μήκος κεφαλίδας","4, 20 bytes":"4, 20 byte","IPv4, with no options.":"IPv4, χωρίς επιλογές.","Priority and congestion marks; 0 means ordinary traffic.":"Προτεραιότητα και σημάδια συμφόρησης· 0 σημαίνει κανονική κίνηση.","Total length":"Συνολικό μήκος","This header and everything inside it.":"Αυτή η κεφαλίδα και ό,τι περιέχει.",Identification:"Αναγνώριση","Lets the receiver reassemble the pieces if the packet gets split.":"Επιτρέπει στον παραλήπτη να ενώσει τα κομμάτια αν το πακέτο χωριστεί.",Flags:"Σημαίες",none:"καμία","Routers may split it if a link is too small.":"Οι δρομολογητές μπορούν να το χωρίσουν αν μια ζεύξη είναι πολύ μικρή.","Time to live":"Χρόνος ζωής","Windows starts at 128.":"Τα Windows ξεκινούν από 128.",Protocol:"Πρωτόκολλο","Header checksum":"Άθροισμα ελέγχου κεφαλίδας","Covers this header only; every router recomputes it after lowering the TTL.":"Καλύπτει μόνο αυτή την κεφαλίδα· κάθε δρομολογητής το ξαναϋπολογίζει αφού μειώσει το TTL.","Source port":"Θύρα προέλευσης","Destination port":"Θύρα προορισμού",Length:"Μήκος","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"Κεφαλίδα UDP και δεδομένα. Αυτό είναι όλο το UDP: χωρίς αρίθμηση, χωρίς επιβεβαιώσεις.",Checksum:"Άθροισμα ελέγχου","Covers the header, the data and the IP addresses.":"Καλύπτει την κεφαλίδα, τα δεδομένα και τις διευθύνσεις IP.","Transaction ID":"ID συναλλαγής","Picked at random; the answer must carry the same one.":"Επιλέγεται τυχαία· η απάντηση πρέπει να φέρει το ίδιο.","0x0100: query, RD (recursion desired)":"0x0100: ερώτημα, RD (ζητείται αναδρομή)",Questions:"Ερωτήσεις",Answers:"Απαντήσεις","Authority records":"Εγγραφές αρχής","Additional records":"Πρόσθετες εγγραφές",Question:"Ερώτηση","www.example.com, type A, class IN":"www.example.com, τύπος A, κλάση IN","The laptop.":"Ο φορητός.","The router’s side facing the home network.":"Η πλευρά του δρομολογητή προς το οικιακό δίκτυο.","Started at 128; 10 routers on the way each took 1.":"Ξεκίνησε από 128· 10 δρομολογητές στη διαδρομή αφαίρεσαν από 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: απάντηση, RD (ζητείται αναδρομή), RA (διαθέσιμη αναδρομή)","DF (don’t fragment)":"DF (χωρίς κατάτμηση)","Routers must not split it; if it’s too big they report back instead.":"Οι δρομολογητές δεν πρέπει να το χωρίσουν· αν είναι πολύ μεγάλο, το αναφέρουν πίσω.","Picked by the laptop’s system for this connection.":"Επιλέχθηκε από το σύστημα του φορητού για αυτή τη σύνδεση.","Sequence number":"Αριθμός ακολουθίας","This side’s starting number. Shown as 0; the real one is random.":"Ο αρχικός αριθμός αυτής της πλευράς. Φαίνεται ως 0· ο πραγματικός είναι τυχαίος.","Real sequence number":"Πραγματικός αριθμός ακολουθίας",Acknowledgment:"Επιβεβαίωση","0 (not used yet)":"0 (δεν χρησιμοποιείται ακόμη)","A first SYN has nothing to acknowledge.":"Ένα πρώτο SYN δεν έχει τίποτα να επιβεβαιώσει.","Header length":"Μήκος κεφαλίδας","20 bytes, plus 12 of options.":"20 byte, συν 12 επιλογών.",Window:"Παράθυρο","How much more data this side can take right now.":"Πόσα ακόμη δεδομένα μπορεί να δεχτεί αυτή η πλευρά αυτή τη στιγμή.","Covers the header, the data and the IP addresses, so damage is caught.":"Καλύπτει την κεφαλίδα, τα δεδομένα και τις διευθύνσεις IP, ώστε να εντοπίζεται η αλλοίωση.","Urgent pointer":"Δείκτης επείγοντος",Options:"Επιλογές","Maximum segment size":"Μέγιστο μέγεθος τμήματος","The most data this side wants in one segment.":"Τα περισσότερα δεδομένα που θέλει αυτή η πλευρά σε ένα τμήμα.","Spacing, so the next option lines up.":"Συμπλήρωση, ώστε η επόμενη επιλογή να ευθυγραμμιστεί.","Window scale":"Κλίμακα παραθύρου","Window values are multiplied by this, so windows can be larger than 64 KB.":"Οι τιμές του παραθύρου πολλαπλασιάζονται με αυτό, ώστε τα παράθυρα να ξεπερνούν τα 64 KB.","SACK permitted":"Επιτρέπεται SACK",yes:"ναι","This side understands selective acknowledgements.":"Αυτή η πλευρά καταλαβαίνει επιλεκτικές επιβεβαιώσεις.","Started at 64; 12 routers on the way each took 1.":"Ξεκίνησε από 64· 12 δρομολογητές στη διαδρομή αφαίρεσαν από 1.","The next byte this side expects: everything before it has arrived.":"Το επόμενο byte που περιμένει αυτή η πλευρά: ό,τι προηγείται έχει φτάσει.","Position of this segment’s first byte, counted from this side’s SYN.":"Θέση του πρώτου byte αυτού του τμήματος, μετρημένη από το SYN αυτής της πλευράς.","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 byte)","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Τα πλαίσια Ethernet είναι τουλάχιστον 60 byte (64 με το άθροισμα ελέγχου που προσθέτει η κάρτα), οπότε τα μικρά συμπληρώνονται.",Text:"Κείμενο","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 byte)","covers bytes not shown here":"καλύπτει byte που δεν φαίνονται εδώ","12,500 bytes: the HTML page":"12,500 byte: η σελίδα HTML","The page itself; its contents are not part of the lesson.":"Η ίδια η σελίδα· το περιεχόμενό της δεν είναι μέρος του μαθήματος.","Secure Web":"Ασφαλές web","TLS handshake":"Χειραψία TLS","HTTP request":"Αίτημα HTTP","HTTP response":"Απάντηση HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"Το HTTPS είναι HTTP που στέλνεται μέσα από κρυπτογραφημένη σύνδεση TLS. Το TLS αποδεικνύει με ένα πιστοποιητικό ότι ο διακομιστής είναι αυτός που λέει, συμφωνεί νέα κλειδιά κρυπτογράφησης και μετά προστατεύει κάθε αίτημα και απάντηση από ανάγνωση ή αλλοίωση στη διαδρομή.","Application (HTTP over TLS)":"Εφαρμογής (HTTP πάνω από TLS)",Security:"Ασφάλεια","TLS 1.3 (1.2 still common)":"TLS 1.3 (το 1.2 ακόμη συνηθισμένο)",Proves:"Αποδεικνύει","Server identity (certificate)":"Ταυτότητα διακομιστή (πιστοποιητικό)","Secure page delivered":"Η ασφαλής σελίδα παραδόθηκε","Encrypted, except the lookup":"Κρυπτογραφημένα, εκτός από την αναζήτηση","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Ο browser βρήκε τη διεύθυνση με απλό DNS, άνοιξε σύνδεση TCP, έλεγξε το πιστοποιητικό του διακομιστή και συμφώνησε κλειδιά σε μία διαδρομή μετ’ επιστροφής. Κάθε byte HTTP μετά από αυτό ταξίδεψε κρυπτογραφημένο. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Cipher:"Κρυπτοαλγόριθμος","Still visible":"Ακόμη ορατά","IPs, server name, sizes":"IP, όνομα διακομιστή, μεγέθη","Secure Request":"Ασφαλές αίτημα","Browser asks for https://":"Ο browser ζητά https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Πληκτρολογείτε https://www.example.com. Το «s» λέει στον browser να προστατέψει τη σύνδεση με TLS, από προεπιλογή στη θύρα 443. Πριν συνδεθεί, πρέπει ακόμη να βρει τη διεύθυνση IP του διακομιστή.",Port:"Θύρα","DNS Lookup":"Αναζήτηση DNS","Same lookup as HTTP, not encrypted":"Ίδια αναζήτηση με το HTTP, χωρίς κρυπτογράφηση","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"Η αναζήτηση είναι ακριβώς ίδια με το απλό HTTP: ένα ερώτημα στο 8.8.8.8 μέσω UDP στη θύρα 53. Δεν είναι κρυπτογραφημένη, οπότε οποιοσδήποτε στη διαδρομή βλέπει ποιο όνομα ζητήσατε, εκτός αν ο browser χρησιμοποιεί DNS over HTTPS.",Encrypted:"Κρυπτογραφημένο","No (plain DNS)":"Όχι (απλό DNS)","TCP Handshake":"Χειραψία TCP","Opens a connection to port 443":"Ανοίγει σύνδεση προς τη θύρα 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"Το TLS λειτουργεί πάνω από το TCP, οπότε πρώτα γίνεται η ίδια χειραψία τριών βημάτων, αυτή τη φορά προς τη θύρα 443. Τίποτα δεν είναι ακόμη κρυπτογραφημένο.","TLS Handshake":"Χειραψία TLS","Agrees on keys, checks the certificate":"Συμφωνεί κλειδιά, ελέγχει το πιστοποιητικό","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Ο browser προσφέρει κρυπτοαλγορίθμους και μερίδια κλειδιών, μαζί κι ένα υβριδικό μετακβαντικό. Ο διακομιστής το επιλέγει και στέλνει το δικό του μερίδιο, μετά το πιστοποιητικό του, ήδη κρυπτογραφημένο. Ο browser το ελέγχει με βάση αρχές που εμπιστεύεται.",Version:"Έκδοση","Key exchange":"Ανταλλαγή κλειδιών","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (υβριδικό)","Server name":"Όνομα διακομιστή","Sent in clear (SNI)":"Στέλνεται ανοιχτά (SNI)","key shares: hybrid + x25519":"μερίδια κλειδιών: υβριδικό + x25519","cipher: AES_128_GCM_SHA256":"κρυπτοαλγόριθμος: AES_128_GCM_SHA256","then encrypted: cert, Finished":"μετά κρυπτογραφημένα: cert, Finished","CERTIFICATE VALID":"ΕΓΚΥΡΟ ΠΙΣΤΟΠΟΙΗΤΙΚΟ","handshake complete (encrypted)":"η χειραψία ολοκληρώθηκε (κρυπτογραφημένα)","Encrypted Exchange":"Κρυπτογραφημένη ανταλλαγή","HTTP inside TLS records":"HTTP μέσα σε εγγραφές TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"Το GET και το 200 OK είναι τα ίδια μηνύματα HTTP με πριν, σφραγισμένα σε εγγραφές TLS που στη γραμμή μοιάζουν με τυχαία «δεδομένα εφαρμογής». Ο διακομιστής δίνει και δύο εισιτήρια συνεδρίας, ώστε μια επόμενη επίσκεψη να παραλείψει μέρος της χειραψίας.",Inside:"Μέσα","GET / and 200 OK":"GET / και 200 OK",Tickets:"Εισιτήρια","2, for faster reconnects":"2, για ταχύτερες επανασυνδέσεις","APP DATA":"ΔΕΔΟΜΕΝΑ ΕΦΑΡΜΟΓΗΣ","inside: GET / HTTP/1.1":"μέσα: GET / HTTP/1.1","outside: encrypted bytes":"έξω: κρυπτογραφημένα byte","inside: HTTP/1.1 200 OK":"μέσα: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"έξω: 12.9 KB, 9 τμήματα","Browser shows the padlock":"Ο browser δείχνει το λουκέτο","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Ο browser αποκρυπτογραφεί την απάντηση, σχεδιάζει τη σελίδα και δείχνει ένα λουκέτο: η σύνδεση είναι ιδιωτική και ο διακομιστής απέδειξε την ταυτότητά του. Η κεφαλίδα Strict-Transport-Security του λέει να χρησιμοποιεί στο εξής HTTPS για αυτόν τον ιστότοπο.",Remembers:"Θυμάται","HTTPS only (HSTS), 1 year":"Μόνο HTTPS (HSTS), 1 έτος","Server Hello + encrypted handshake, 3 segments":"Server Hello + κρυπτογραφημένη χειραψία, 3 τμήματα","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (κρυπτογραφημένο)","Application Data (HTTP request)":"Application Data (αίτημα HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (κρυπτογραφημένα)","Application Data (HTTP response), 9 segments":"Application Data (απάντηση HTTP), 9 τμήματα",Record:"Εγγραφή","Content type":"Τύπος περιεχομένου","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Η εγγραφή ενός Client Hello γράφει TLS 1.0 ώστε να την αφήνουν να περάσει παλιές ενδιάμεσες συσκευές· οι πραγματικές εκδόσεις προσφέρονται μέσα.","Handshake type":"Τύπος χειραψίας",Contents:"Περιεχόμενα","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Ό,τι υποστηρίζει ο browser. Οι browser αλλάζουν μερικές λεπτομέρειες από σύνδεση σε σύνδεση.","Server name (SNI)":"Όνομα διακομιστή (SNI)","Versions offered":"Προσφερόμενες εκδόσεις","Key shares":"Μερίδια κλειδιών","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 byte), X25519","App protocols (ALPN)":"Πρωτόκολλα εφαρμογής (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"Οι εγγραφές TLS 1.3 γράφουν 1.2 εξωτερικά, για συμβατότητα.","The server’s choices and its half of the hybrid key exchange.":"Οι επιλογές του διακομιστή και το δικό του μισό της υβριδικής ανταλλαγής κλειδιών.","Cipher suite":"Σουίτα κρυπτογράφησης","Key share":"Μερίδιο κλειδιού","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 byte)","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"Δεν έχει ρόλο στο TLS 1.3· στέλνεται ώστε οι ενδιάμεσες συσκευές να βλέπουν μια γνώριμη χειραψία.","Every encrypted record says Application Data on the outside; the real type is inside.":"Κάθε κρυπτογραφημένη εγγραφή γράφει εξωτερικά Application Data· ο πραγματικός τύπος είναι μέσα.","Encrypted data":"Κρυπτογραφημένα δεδομένα","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Κρυπτοκείμενο που τελειώνει σε ετικέτα 16 byte η οποία αποκαλύπτει κάθε αλλαγή. Μόνο τα δύο άκρα μπορούν να το διαβάσουν.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (η αλυσίδα), Certificate Verify (η υπογραφή), Finished","Finished: a check value over the whole handshake":"Finished: μια τιμή ελέγχου πάνω σε όλη τη χειραψία","The HTTP request":"Το αίτημα HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket: επιτρέπει σε μια επόμενη επίσκεψη να συνεχίσει","The HTTP response, then the 12,500-byte page":"Η απάντηση HTTP, μετά η σελίδα των 12,500 byte","Reliable Delivery":"Αξιόπιστη παράδοση","Handshake and ACKs":"Χειραψία και ACK","Data from laptop":"Δεδομένα από τον φορητό","Data from server":"Δεδομένα από τον διακομιστή","Closing (FIN)":"Κλείσιμο (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"Το TCP μετατρέπει την παράδοση πακέτων «κατά το δυνατόν» του Διαδικτύου σε αξιόπιστη, ταξινομημένη ροή byte. Αριθμεί κάθε byte, επιβεβαιώνει ό,τι φτάνει, ξαναστέλνει ό,τι χάνεται και ρυθμίζει τον ρυθμό του αποστολέα ώστε να μην πνιγεί ούτε η άλλη πλευρά ούτε το δίκτυο.","Transport (Layer 4)":"Μεταφοράς (επίπεδο 4)","Three-way handshake":"Χειραψία τριών βημάτων",Reliability:"Αξιοπιστία","Sequence numbers + ACKs":"Αριθμοί ακολουθίας + ACK",Recovery:"Ανάκτηση",Retransmission:"Επανεκπομπή",Header:"Κεφαλίδα","20–60 bytes":"20–60 byte","Connection closed":"Η σύνδεση έκλεισε","Every byte accounted for":"Κανένα byte δεν χάθηκε","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"Το TCP άνοιξε σύνδεση, αρίθμησε και επιβεβαίωσε κάθε byte, εντόπισε ένα κενό και ξανάστειλε μόνο το τμήμα που έλειπε, μετά έκλεισε καθαρά και τις δύο κατευθύνσεις. Το curl έλαβε κάθε byte με τη σειρά και δεν κατάλαβε ποτέ την απώλεια. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Segments:"Τμήματα","14 (1 lost, 1 resent)":"14 (1 χάθηκε, 1 ξαναστάλθηκε)","Bytes delivered":"Byte που παραδόθηκαν","78 up, 2,920 down":"78 προς τα πάνω, 2,920 προς τα κάτω","Loss found by":"Η απώλεια βρέθηκε με","Duplicate ACK + SACK":"Διπλό ACK + SACK","Open Connection":"Άνοιγμα σύνδεσης","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"Το curl ξέρει ήδη τη διεύθυνση του διακομιστή. Πριν μετακινηθούν δεδομένα, οι δύο πλευρές επιλέγουν αρχικό αριθμό ακολουθίας και τον επιβεβαιώνουν: SYN, SYN-ACK, ACK. Οι αριθμοί εδώ είναι σχετικοί· οι πραγματικοί ξεκινούν από τυχαία τιμή.","203.0.113.10, port 80":"203.0.113.10, θύρα 80","Send Data":"Αποστολή δεδομένων","Every byte is numbered":"Κάθε byte αριθμείται","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"Το curl στέλνει το αίτημα HTTP των 78 byte: τα byte 1 έως 78. Ο αριθμός ACK του διακομιστή, 79, είναι το επόμενο byte που περιμένει, άρα ό,τι προηγείται έχει φτάσει.",Sent:"Στάλθηκαν","78 bytes (seq 1–78)":"78 byte (seq 1–78)","79 = next byte expected":"79 = επόμενο αναμενόμενο byte","Two Segments Back":"Δύο τμήματα πίσω","One of them is lost":"Το ένα χάνεται","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Ο διακομιστής απαντά με 2,920 byte: δύο γεμάτα τμήματα των 1,460 byte, το μέγιστο που χωρά εδώ σε ένα πακέτο, σταλμένα το ένα πίσω από το άλλο. Το πρώτο πετιέται κάπου στο Διαδίκτυο· το δεύτερο περνά.","Segment 1":"Τμήμα 1","bytes 1–1460 (lost)":"byte 1–1460 (χάθηκε)","Segment 2":"Τμήμα 2","bytes 1461–2920":"byte 1461–2920","Segment size":"Μέγεθος τμήματος","1,460 bytes (MSS)":"1,460 byte (MSS)","2 SEGMENTS":"2 ΤΜΗΜΑΤΑ","seq=1 and seq=1461":"seq=1 και seq=1461","the first is lost":"το πρώτο χάνεται","SEGMENT 1 LOST":"ΤΟ ΤΜΗΜΑ 1 ΧΑΘΗΚΕ","A Gap Is Noticed":"Εντοπίζεται κενό","Duplicate ACK with SACK":"Διπλό ACK με SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Τα byte 1461–2920 φτάνουν, όμως τα 1–1460 δεν ήρθαν ποτέ. Ένα ACK μετρά μόνο byte που ήρθαν με τη σειρά, οπότε ο φορητός επαναλαμβάνει αμέσως ACK 1 και προσθέτει ένα μπλοκ SACK που λέει ότι έχει ήδη τα 1461–2920.","1 (still waiting for byte 1)":"1 (περιμένει ακόμη το byte 1)","holds bytes 1461–2920":"έχει τα byte 1461–2920","At once, not delayed":"Αμέσως, χωρίς καθυστέρηση","DUP ACK":"ΔΙΠΛΟ ACK","sack: has 1461–2920":"sack: έχει 1461–2920","Resend the Gap":"Επαναποστολή του κενού","Only the missing bytes":"Μόνο τα byte που λείπουν","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"Το SACK λέει στον διακομιστή ακριβώς τι λείπει, οπότε ξαναστέλνει μόνο το τμήμα 1 και ο φορητός επιβεβαιώνει τα πάντα. Αν δεν είχε επιστρέψει κανένα ACK, θα έμπαιναν χρονόμετρα: ένας έλεγχος μετά από περίπου δύο διαδρομές μετ’ επιστροφής, μετά λήξη χρόνου επανεκπομπής (τουλάχιστον 200 ms στο Linux).",Resent:"Ξαναστάλθηκαν","bytes 1–1460 only":"μόνο τα byte 1–1460","Next ACK":"Επόμενο ACK","2921 (everything)":"2921 (όλα)","curl saw":"Το curl είδε","Every byte, in order":"Κάθε byte, με τη σειρά",RESEND:"ΕΠΑΝΑΠΟΣΤΟΛΗ","just the missing segment":"μόνο το τμήμα που λείπει","Close Connection":"Κλείσιμο σύνδεσης","Each side says goodbye":"Κάθε πλευρά αποχαιρετά","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"Το curl τελείωσε, οπότε κλείνει. Κάθε κατεύθυνση κλείνει χωριστά: ο φορητός στέλνει FIN και ο διακομιστής το επιβεβαιώνει, μετά ο διακομιστής στέλνει το δικό του FIN και ο φορητός το επιβεβαιώνει. Ο φορητός κρατά για λίγο τα στοιχεία της σύνδεσης (TIME-WAIT).","Closed by":"Κλείνει με","A FIN from each side":"Ένα FIN από κάθε πλευρά",Order:"Σειρά",Then:"Μετά","Laptop waits (TIME-WAIT)":"Ο φορητός περιμένει (TIME-WAIT)",Data:"Δεδομένα","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 byte: η απάντηση HTTP, byte 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 byte: η απάντηση HTTP, byte 1461–2920","has 1461–2920":"έχει 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Byte που ήρθαν μετά το κενό, οπότε χρειάζεται επαναποστολή μόνο το κενό.","Fast Datagrams":"Γρήγορα datagram","Your voice":"Η φωνή σας","Their voice":"Η φωνή του άλλου","Media Server":"Διακομιστής πολυμέσων","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"Το UDP στέλνει δεδομένα σε ανεξάρτητα πακέτα, τα datagram, χωρίς σύνδεση, χωρίς επιβεβαιώσεις και χωρίς επαναποστολές. Έτσι μένει γρήγορο και ελαφρύ: ιδανικό για φωνή, βίντεο, παιχνίδια και DNS, όπου μια καθυστερημένη απάντηση είναι χειρότερη από μια που λείπει.",None:"Καμία","None (no ACKs, no resends)":"Καμία (χωρίς ACK, χωρίς επαναποστολές)",Ordering:"Σειρά","Not guaranteed":"Δεν εγγυάται","Call keeps flowing":"Η κλήση συνεχίζεται","Fast, simple, no guarantees":"Γρήγορο, απλό, χωρίς εγγυήσεις","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"Ο ήχος ξεκίνησε με το πρώτο κιόλας πακέτο, κάθε datagram ταξίδεψε μόνο του και αυτό που χάθηκε απλώς χάθηκε: το UDP δεν το πρόσεξε ποτέ. Η εφαρμογή κάλυψε το κενό και η κλήση συνεχίστηκε. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Datagrams:"Datagram","11 (1 lost, never resent)":"11 (1 χάθηκε, δεν ξαναστάλθηκε)","Setup time":"Χρόνος εγκατάστασης","0 ms (no handshake)":"0 ms (χωρίς χειραψία)","8 bytes (TCP: 20+)":"8 byte (TCP: 20+)",Shown:"Φαίνεται","The first 0.2 s of a call":"Τα πρώτα 0.2 s μιας κλήσης","Send Right Away":"Αποστολή αμέσως","No handshake, data goes first":"Χωρίς χειραψία, πρώτα τα δεδομένα","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Μια εφαρμογή κλήσεων ξέρει ήδη τη διεύθυνση και τη θύρα του διακομιστή πολυμέσων από τη σύνδεση. Δεν ανοίγει σύνδεση: το πρώτο κιόλας datagram φέρει 20 ms της φωνής σας, πίσω από μια κεφαλίδα UDP 8 byte.",Setup:"Εγκατάσταση",Ports:"Θύρες","VOICE 1":"ΦΩΝΗ 1","92 B of audio, no setup":"92 B ήχου, χωρίς εγκατάσταση","A Stream of Datagrams":"Μια ροή από datagram","One every 20 ms, each on its own":"Ένα κάθε 20 ms, το καθένα μόνο του","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"Η εφαρμογή συνεχίζει να στέλνει ένα datagram κάθε 20 ms. Το καθένα στέκεται μόνο του, με δική του κεφαλίδα και χωρίς σύνδεση με τα άλλα. Το UDP δεν τα αριθμεί και τίποτα δεν επιστρέφει για να επιβεβαιώσει ότι έφτασαν.",Rate:"Ρυθμός","1 datagram / 20 ms":"1 datagram / 20 ms",Numbering:"Αρίθμηση","None in UDP itself":"Καμία στο ίδιο το UDP",Confirmation:"Επιβεβαίωση","None (no ACKs)":"Καμία (χωρίς ACK)","4 DATAGRAMS":"4 DATAGRAM","voice frames 2–5":"πλαίσια φωνής 2–5","each with its own 8-byte header":"το καθένα με δική του κεφαλίδα 8 byte","Lost on the Way":"Χάθηκε στον δρόμο","Nobody resends it":"Κανείς δεν το ξαναστέλνει","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Το πλαίσιο 7 πετιέται κάπου στο Διαδίκτυο. Ο διακομιστής πολυμέσων δεν το ζητά ποτέ και το UDP δεν το λέει ποτέ στον φορητό: δεν υπάρχουν επιβεβαιώσεις που να λείπουν. Τα datagram που ακολουθούν φτάνουν κανονικά.",Lost:"Χάθηκε","Voice frame 7":"Πλαίσιο φωνής 7","Never (no ACKs)":"Ποτέ (χωρίς ACK)",Missing:"Λείπουν","20 ms of audio":"20 ms ήχου","3 DATAGRAMS":"3 DATAGRAM","voice frames 6–8":"πλαίσια φωνής 6–8","frame 7 is lost":"το πλαίσιο 7 χάνεται","FRAME 7 LOST · NOT RESENT":"ΤΟ ΠΛΑΙΣΙΟ 7 ΧΑΘΗΚΕ · ΔΕΝ ΞΑΝΑΣΤΑΛΘΗΚΕ","Replies Come Back":"Έρχονται απαντήσεις","The other voice comes back":"Η άλλη φωνή επιστρέφει","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"Η φωνή του άλλου φτάνει με τον ίδιο τρόπο, ως χωριστά datagram προς τη θύρα 50000. Περνούν επειδή ο δρομολογητής σας θυμήθηκε την εξερχόμενη θύρα όταν μετέφρασε τη διεύθυνσή σας (NAT).",Direction:"Κατεύθυνση","Independent of ours":"Ανεξάρτητη από τη δική μας","Through NAT":"Μέσω NAT","Router remembers the port":"Ο δρομολογητής θυμάται τη θύρα","the other person’s voice":"η φωνή του άλλου","sent to port 50000":"στάλθηκε στη θύρα 50000","The App Decides":"Αποφασίζει η εφαρμογή","Reliability is up to the app":"Η αξιοπιστία είναι δουλειά της εφαρμογής","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"Η εφαρμογή κλήσεων αριθμεί μόνη της τα πλαίσιά της (αυτό κάνει το RTP), οπότε βλέπει ότι λείπει το πλαίσιο 7 και εξομαλύνει το κενό των 20 ms αντί να περιμένει. Η αναμονή για επαναποστολή θα καθυστερούσε όλη την κλήση.","App’s job (e.g. RTP)":"Δουλειά της εφαρμογής (π.χ. RTP)",Loss:"Απώλεια","Hidden by the app":"Την κρύβει η εφαρμογή","Also on UDP":"Επίσης σε UDP","DNS, games, QUIC":"DNS, παιχνίδια, QUIC","APP COVERS THE 20 MS GAP":"Η ΕΦΑΡΜΟΓΗ ΚΑΛΥΠΤΕΙ ΤΟ ΚΕΝΟ 20 MS","RTP + audio":"RTP + ήχος","Version etc.":"Έκδοση κ.λπ.","2, no padding, no extension, no CSRCs":"2, χωρίς συμπλήρωση, χωρίς επέκταση, χωρίς CSRC","Marker, payload type":"Δείκτης, τύπος φορτίου","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, συμφωνήθηκε στην έναρξη της κλήσης)","Counts up by one per packet, so the app can spot a missing or late one.":"Αυξάνεται κατά ένα σε κάθε πακέτο, ώστε η εφαρμογή να εντοπίζει ένα που λείπει ή αργεί.",Timestamp:"Χρονοσήμανση","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Ρολόι ήχου στα 48,000 ανά δευτερόλεπτο: +960 ανά πλαίσιο 20 ms.","Identifies this audio stream.":"Αναγνωρίζει αυτή τη ροή ήχου.",Audio:"Ήχος","80 bytes of Opus audio (20 ms)":"80 byte ήχου Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, συμφωνήθηκε στην έναρξη της κλήσης)","Addressing & Routing":"Διευθυνσιοδότηση και δρομολόγηση","Outgoing packet":"Εξερχόμενο πακέτο",Reply:"Απάντηση","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"Το IP δίνει σε κάθε συσκευή μια διεύθυνση και μετακινεί πακέτα από δίκτυο σε δίκτυο. Κάθε δρομολογητής κοιτά μόνο τη διεύθυνση προορισμού για να διαλέξει το επόμενο βήμα. Το IP λειτουργεί «κατά το δυνατόν»: δεν υπόσχεται ούτε παράδοση ούτε σειρά. Αυτά τα προσθέτει το TCP από πάνω.","Network (Layer 3)":"Δικτύου (επίπεδο 3)",Address:"Διεύθυνση","32 bits (IPv4), 128 (IPv6)":"32 bit (IPv4), 128 (IPv6)","20–60 bytes (IPv4)":"20–60 byte (IPv4)","Lowered by 1 at each router":"Μειώνεται κατά 1 σε κάθε δρομολογητή",Delivery:"Παράδοση","Best effort":"Κατά το δυνατόν","There and back":"Πήγαινε κι έλα","Twelve routers each way":"Δώδεκα δρομολογητές προς κάθε κατεύθυνση","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"Ο φορητός έστειλε το πακέτο στον δρομολογητή του, που έβαλε τη δημόσια διεύθυνσή του. Συνολικά δώδεκα δρομολογητές το προώθησαν μόνο με βάση τη διεύθυνση προορισμού, και η απάντηση βρήκε τον δρόμο πίσω με τον ίδιο τρόπο. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Routers:"Δρομολογητές","12 each way (1 home + 11)":"12 ανά κατεύθυνση (1 οικιακός + 11)","TTL at server":"TTL στον διακομιστή","116 (sent with 128)":"116 (στάλθηκε με 128)","Rewritten by NAT":"Ξαναγράφονται από το NAT","Source out, destination back":"Η πηγή στο πήγαινε, ο προορισμός στο έλα","IPv4 (IPv6 works alike)":"IPv4 (το IPv6 λειτουργεί παρόμοια)","Local or Not?":"Τοπικό ή όχι;","Compare the address with the subnet":"Σύγκριση της διεύθυνσης με το υποδίκτυο","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"Ο φορητός είναι 192.168.1.10 με μάσκα /24, άρα το δίκτυό του είναι από 192.168.1.0 έως 192.168.1.255. Ο διακομιστής, 203.0.113.10, είναι εκτός αυτού του εύρους, οπότε το πακέτο πρέπει να πάει στην προεπιλεγμένη πύλη: τον οικιακό δρομολογητή.",Laptop:"Φορητός","Local range":"Τοπικό εύρος",Gateway:"Πύλη","203.0.113.10 IS NOT LOCAL":"ΤΟ 203.0.113.10 ΔΕΝ ΕΙΝΑΙ ΤΟΠΙΚΟ","Find the Router":"Εύρεση του δρομολογητή","ARP turns an IP into a MAC":"Το ARP κάνει ένα IP διεύθυνση MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Στο τοπικό δίκτυο τα πλαίσια παραδίδονται με βάση τη διεύθυνση MAC. Αν η MAC του δρομολογητή δεν είναι στη μνήμη ARP του φορητού, αυτός ρωτά όλους «ποιος έχει το 192.168.1.1;» και ο δρομολογητής απαντά με τη διεύθυνση MAC του.",Asks:"Ρωτά","Who has 192.168.1.1?":"Ποιος έχει το 192.168.1.1;","Sent to":"Στάλθηκε σε","Everyone (broadcast)":"Όλους (εκπομπή)",Learns:"Μαθαίνει","Router’s MAC address":"Τη MAC του δρομολογητή","ARP REQUEST":"ΑΙΤΗΜΑ ARP","who has 192.168.1.1?":"ποιος έχει το 192.168.1.1;","tell 192.168.1.10":"πες το στο 192.168.1.10","ARP REPLY":"ΑΠΑΝΤΗΣΗ ARP","Send the Packet":"Αποστολή του πακέτου","Addresses, TTL and protocol":"Διευθύνσεις, TTL και πρωτόκολλο","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"Η κεφαλίδα IP φέρει τις διευθύνσεις προέλευσης και προορισμού, ένα TTL και το πρωτόκολλο που περιέχει. Εδώ περιέχει ένα TCP SYN προς τη θύρα 443. Τα Windows ξεκινούν το TTL από 128 (τα Linux και macOS από 64).","From → to":"Από → προς","IP PACKET":"ΠΑΚΕΤΟ IP","TTL 128 · protocol TCP":"TTL 128 · πρωτόκολλο TCP","NAT, Then Hop by Hop":"NAT, μετά βήμα βήμα","The router rewrites and forwards":"Ο δρομολογητής ξαναγράφει και προωθεί","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Ο δρομολογητής αντικαθιστά την ιδιωτική πηγή με τη δημόσια διεύθυνσή του 198.51.100.7 (κι εδώ τη θύρα 52344 με 40112), σημειώνει την αντιστοίχιση και κατεβάζει το TTL στο 127. Μετά 11 δρομολογητές στο Διαδίκτυο επιλέγουν ο καθένας το επόμενο βήμα με βάση τον προορισμό και κατεβάζουν ξανά το TTL.","New source":"Νέα πηγή","Leaves home":"Φεύγει από το σπίτι","At the server":"Στον διακομιστή","TTL 116 (11 more hops)":"TTL 116 (11 βήματα ακόμη)","TTL 127 · after NAT":"TTL 127 · μετά το NAT","ARRIVED WITH TTL 116":"ΕΦΤΑΣΕ ΜΕ TTL 116","The Reply Comes Back":"Η απάντηση επιστρέφει","NAT translates it for the laptop":"Το NAT τη μεταφράζει για τον φορητό","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Ο διακομιστής απαντά στη διεύθυνση που είδε, 198.51.100.7:40112. Ο δρομολογητής την αναζητά στον πίνακα NAT, ξαναγράφει τον προορισμό σε 192.168.1.10:52344 και την προωθεί. Η απάντηση ξεκίνησε με TTL 64 και φτάνει με 52.","Delivered to":"Παραδόθηκε σε","64 → 52 (12 routers)":"64 → 52 (12 δρομολογητές)",REPLY:"ΑΠΑΝΤΗΣΗ","TTL 52 · after NAT":"TTL 52 · μετά το NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (μετά το NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (μετά το NAT)","ARP request · 28 bytes":"Αίτημα ARP · 28 byte","Broadcast: every device on the network receives it.":"Εκπομπή: το λαμβάνει κάθε συσκευή του δικτύου.","The sender’s network card.":"Η κάρτα δικτύου του αποστολέα.","Hardware type":"Τύπος υλικού","1 (Ethernet)":"1 (Ethernet)","Protocol type":"Τύπος πρωτοκόλλου","Address sizes":"Μεγέθη διευθύνσεων",Operation:"Λειτουργία","1 (request: who has …?)":"1 (αίτημα: ποιος έχει …;)","Sender MAC":"MAC αποστολέα","Sender IP":"IP αποστολέα","Target MAC":"MAC στόχου","All zeros: this is what the request wants to find out.":"Όλα μηδέν: αυτό ακριβώς θέλει να μάθει το αίτημα.","Target IP":"IP στόχου","ARP reply · 28 bytes":"Απάντηση ARP · 28 byte","Straight back to the device that asked.":"Κατευθείαν πίσω στη συσκευή που ρώτησε.","2 (reply: … is at …)":"2 (απάντηση: το … είναι στο …)","Seen as it leaves the router’s internet side":"Όπως φαίνεται καθώς φεύγει από την πλευρά Διαδικτύου του δρομολογητή","The internet provider’s router, the next hop.":"Ο δρομολογητής του παρόχου Διαδικτύου, το επόμενο βήμα.","The router’s internet-facing port.":"Η θύρα του δρομολογητή προς το Διαδίκτυο.","As sent: this system starts at 64.":"Όπως στάλθηκε: αυτό το σύστημα ξεκινά από 64.","The router’s NAT swapped in its own port for the laptop’s.":"Το NAT του δρομολογητή έβαλε δική του θύρα στη θέση της θύρας του φορητού.","The sender’s next router; each hop puts the packet in a new frame.":"Ο επόμενος δρομολογητής του αποστολέα· κάθε βήμα βάζει το πακέτο σε νέο πλαίσιο.","Name Resolution":"Επίλυση ονομάτων",Query:"Ερώτημα",Referral:"Παραπομπή","DNSSEC not requested here":"Δεν ζητείται DNSSEC εδώ","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"Το DNS μετατρέπει ονόματα όπως το www.example.com στις διευθύνσεις IP που χρησιμοποιούν οι υπολογιστές για να βρίσκουν ο ένας τον άλλον. Κανένας διακομιστής δεν ξέρει κάθε όνομα: το σύστημα είναι μια ιεραρχία διακομιστών, και οι απαντήσεις αποθηκεύονται στη μνήμη cache στη διαδρομή, ώστε οι περισσότερες αναζητήσεις να μη χρειάζεται να πάνε μακριά.","53, UDP (TCP if large)":"53, UDP (TCP αν είναι μεγάλο)",Turns:"Μετατρέπει","Names into IP addresses":"Ονόματα σε διευθύνσεις IP",Hierarchy:"Ιεραρχία","Root → TLD → authoritative":"Ρίζα → TLD → έγκυρος",Caching:"Cache","For each record’s TTL":"Για το TTL κάθε εγγραφής","Name resolved":"Το όνομα επιλύθηκε","And remembered for an hour":"Και απομνημονεύτηκε για μία ώρα","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Ξεκινώντας με άδεια cache, ο επιλυτής πήγε από τη ρίζα στο .com και στον διακομιστή του example.com, και μετά απάντησε στον φορητό. Μέχρι να λήξει το TTL, η επόμενη αναζήτηση αυτού του ονόματος απαντιέται κατευθείαν από μια cache. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Queries:"Ερωτήματα","4 (laptop 1, resolver 3)":"4 (φορητός 1, επιλυτής 3)","Cached for":"Στην cache για","Ask the Resolver":"Ερώτηση στον επιλυτή","The laptop hands the question off":"Ο φορητός παραδίδει την ερώτηση","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Ο browser χρειάζεται τη διεύθυνση IP του www.example.com και ούτε αυτός ούτε τα Windows την έχουν στη cache. Ο φορητός στέλνει μία ερώτηση στον αναδρομικό επιλυτή που του δόθηκε, το 8.8.8.8, και του ζητά να κάνει όλη την αναζήτηση (ζητείται αναδρομή).","www.example.com, type A":"www.example.com, τύπος A",Asked:"Ρωτήθηκε","8.8.8.8 (recursive)":"8.8.8.8 (αναδρομικός)","RD (recursion desired)":"RD (ζητείται αναδρομή)","flags: RD":"σημαίες: RD","Points the way to .com":"Δείχνει τον δρόμο προς το .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Η cache του επιλυτή είναι άδεια (μόλις ξεκίνησε), οπότε αρχίζει από την κορυφή. Ένας ριζικός διακομιστής δεν ξέρει τη διεύθυνση, αλλά ξέρει ποιοι διακομιστές χειρίζονται το .com και απαντά με παραπομπή. Πολλοί επιλυτές του στέλνουν μόνο «com», όχι ολόκληρο το όνομα.","Root servers":"Ριζικοί διακομιστές","13 names, 1,000+ anycast sites":"13 ονόματα, 1,000+ τοποθεσίες anycast","Referral (13 .com servers)":"Παραπομπή (13 διακομιστές .com)","NOT IN CACHE":"ΔΕΝ ΕΙΝΑΙ ΣΤΗΝ CACHE",REFERRAL:"ΠΑΡΑΠΟΜΠΗ","no answer: ask .com":"καμία απάντηση: ρωτήστε το .com","Points the way to example.com":"Δείχνει τον δρόμο προς το example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Ο επιλυτής ρωτά έναν από τους διακομιστές .com. Ούτε αυτοί κρατούν διευθύνσεις για κάθε ιστότοπο, ξέρουν όμως ποιους διακομιστές ονομάτων χρησιμοποιεί κάθε τομέας .com, οπότε αυτή η απάντηση είναι άλλη μια παραπομπή, με συνημμένες τις διευθύνσεις αυτών των διακομιστών (glue).",Knows:"Ξέρει","Name servers of .com domains":"Διακομιστές ονομάτων τομέων .com","Referral + glue addresses":"Παραπομπή + διευθύνσεις glue","no answer: ask example.com":"καμία απάντηση: ρωτήστε το example.com","Gives the actual answer":"Δίνει την πραγματική απάντηση","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Τέλος ο επιλυτής ρωτά τον διακομιστή ονομάτων του ίδιου του example.com, που κρατά τις εγγραφές του τομέα. Απαντά με την εγγραφή A και σημειώνει την απάντηση ως έγκυρη. Ο κάτοχος του τομέα ορίζει πόσο μπορεί να μείνει στη cache: εδώ 3600 δευτερόλεπτα.","AA (authoritative), TTL 3600":"AA (έγκυρη), TTL 3600",ANSWER:"ΑΠΑΝΤΗΣΗ","TTL 3600 · flag AA":"TTL 3600 · σημαία AA","Answer & Cache":"Απάντηση και cache","The laptop gets its address":"Ο φορητός παίρνει τη διεύθυνσή του","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Ο επιλυτής στέλνει την απάντηση πίσω στον φορητό και κρατά ένα αντίγραφο. Για την επόμενη ώρα μπορεί να απαντά αμέσως για αυτό το όνομα, γι’ αυτό η αναζήτηση στο μάθημα HTTP πήρε μόνο 24 ms. Την κρατά και ο φορητός στη cache.","RD, RA (recursion available)":"RD, RA (διαθέσιμη αναδρομή)","Cached by":"Στην cache του","Resolver and laptop":"Επιλυτή και φορητού","flags: RD RA":"σημαίες: RD RA","CACHED · TTL 3600 S":"ΣΤΗΝ CACHE · TTL 3600 S","Referral: com. NS ×13 (with glue)":"Παραπομπή: com. NS ×13 (με glue)","Referral: example.com. NS ×2 (with glue)":"Παραπομπή: example.com. NS ×2 (με glue)","Response A 203.0.113.10 (authoritative)":"Απάντηση A 203.0.113.10 (έγκυρη)","As sent: this system starts at 128.":"Όπως στάλθηκε: αυτό το σύστημα ξεκινά από 128.","0x0000: query":"0x0000: ερώτημα","UDP size 1232, DNSSEC OK = 0":"Μέγεθος UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Λέει πόσο μεγάλη μπορεί να είναι μια απάντηση UDP. Οι υπογραφές DNSSEC δεν ζητούνται εδώ, για να μείνει σύντομο το μάθημα· ένας επιλυτής που επικυρώνει, όπως το 8.8.8.8, τις ζητά.","0x8000: response":"0x8000: απάντηση",Authority:"Αρχή",Additional:"Πρόσθετα","0x8400: response, AA (authoritative)":"0x8400: απάντηση, AA (έγκυρη)","Getting an Address":"Απόκτηση διεύθυνσης","From the laptop":"Από τον φορητό","From the DHCP server":"Από τον διακομιστή DHCP","No IP address":"Χωρίς διεύθυνση IP","192.168.1.1 · DHCP server":"192.168.1.1 · διακομιστής DHCP","Dynamic Host Configuration Protocol":"Dynamic Host Configuration Protocol","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"Το DHCP δίνει σε μια συσκευή ό,τι χρειάζεται για να χρησιμοποιήσει ένα δίκτυο: διεύθυνση IP, μάσκα υποδικτύου, τον δρομολογητή μέσω του οποίου στέλνει την κίνηση και τους διακομιστές DNS που ρωτά. Οι διευθύνσεις εκμισθώνονται για ορισμένο χρόνο και ανανεώνονται όσο η συσκευή μένει στο δίκτυο.","UDP 67 (server), 68 (client)":"UDP 67 (διακομιστής), 68 (πελάτης)","Hands out":"Μοιράζει","IP, mask, gateway, DNS":"IP, μάσκα, πύλη, DNS",Exchange:"Ανταλλαγή",Lease:"Μίσθωση","Renewed at half its time":"Ανανεώνεται στο μισό του χρόνου","On the network":"Στο δίκτυο","Leased, and kept up to date":"Μισθωμένη και πάντα ενημερωμένη","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Τέσσερα μηνύματα πήγαν τον φορητό από καμία διεύθυνση σε λειτουργική ρύθμιση, και στη μέση της 24ωρης μίσθωσης την ανανέωσε με απευθείας αίτημα στον δρομολογητή. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Messages:"Μηνύματα","4 to join, 2 per renewal":"4 για ένταξη, 2 ανά ανανέωση","24 h, renewed at 12 h":"24 h, ανανέωση στις 12 h","No Address Yet":"Ακόμη χωρίς διεύθυνση","The laptop joins the network":"Ο φορητός μπαίνει στο δίκτυο","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"Ο φορητός μόλις συνδέθηκε. Έχει ενσωματωμένη διεύθυνση MAC, αλλά καμία διεύθυνση IP, πύλη ή διακομιστή DNS, οπότε δεν μπορεί ακόμη να μιλήσει με τίποτα πέρα από το δικό του δίκτυο. Τα ζητά με DHCP.","IP address":"Διεύθυνση IP","None (uses 0.0.0.0)":"Καμία (χρησιμοποιεί 0.0.0.0)","MAC address":"Διεύθυνση MAC",Needs:"Χρειάζεται","NO IP ADDRESS YET":"ΑΚΟΜΗ ΧΩΡΙΣ ΔΙΕΥΘΥΝΣΗ IP",Discover:"Discover","Shout to the whole network":"Φωνάζει σε όλο το δίκτυο","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Χωρίς δική του διεύθυνση, ο φορητός στέλνει από το 0.0.0.0 στη διεύθυνση εκπομπής 255.255.255.255, ώστε να το λάβει κάθε συσκευή του τοπικού δικτύου. Απαντούν μόνο οι διακομιστές DHCP.",From:"Από","0.0.0.0, UDP port 68":"0.0.0.0, θύρα UDP 68","255.255.255.255, port 67":"255.255.255.255, θύρα 67",Carries:"Φέρει","MAC, transaction ID":"MAC, ID συναλλαγής","any DHCP server out there?":"υπάρχει κάπου διακομιστής DHCP;",Offer:"Offer","The router proposes an address":"Ο δρομολογητής προτείνει διεύθυνση","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Ο διακομιστής DHCP του δρομολογητή διαλέγει μια ελεύθερη διεύθυνση και την προσφέρει μαζί με τις υπόλοιπες ρυθμίσεις. Ο φορητός δεν μπορεί ακόμη να χρησιμοποιήσει διεύθυνση IP, οπότε η προσφορά πηγαίνει κατευθείαν στη διεύθυνση MAC του (κάποιοι πελάτες ζητούν αντί γι’ αυτό εκπομπή).",Offered:"Προσφέρεται","Gateway, DNS":"Πύλη, DNS","offer: 192.168.1.10/24":"προσφορά: 192.168.1.10/24","gateway, DNS, lease 24 h":"πύλη, DNS, μίσθωση 24 h","Accept, out loud":"Αποδοχή, φωναχτά","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"Ο φορητός ζητά την προσφερόμενη διεύθυνση, κατονομάζοντας τον διακομιστή που επέλεξε. Στέλνει ακόμη με εκπομπή, ώστε κάθε άλλος διακομιστής DHCP που έκανε προσφορά να μάθει ότι δεν επιλέχθηκε και να αποδεσμεύσει τη διεύθυνσή του.",Requests:"Ζητά","Chosen server":"Επιλεγμένος διακομιστής","I’ll take 192.168.1.10":"παίρνω το 192.168.1.10","from server 192.168.1.1":"από τον διακομιστή 192.168.1.1",Acknowledge:"Επιβεβαίωση","The address is the laptop’s":"Η διεύθυνση ανήκει στον φορητό","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Ο διακομιστής επιβεβαιώνει, και ο φορητός ρυθμίζει διεύθυνση, μάσκα, πύλη και διακομιστή DNS. Πολλά συστήματα ελέγχουν πρώτα με ARP ότι καμία άλλη συσκευή δεν χρησιμοποιεί ήδη τη διεύθυνση.","DNS server":"Διακομιστής DNS","192.168.1.10 is yours":"το 192.168.1.10 είναι δικό σας","for 24 hours":"για 24 ώρες","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · ΜΙΣΘΩΣΗ 24 H",Renew:"Ανανέωση","Halfway through the lease":"Στη μέση της μίσθωσης","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Δώδεκα ώρες αργότερα, έχει περάσει η μισή μίσθωση. Ο φορητός έχει πια διεύθυνση, οπότε ζητά απευθείας από τον δρομολογητή να παρατείνει τη μίσθωση, και ο δρομολογητής την επαναφέρει στις 24 ώρες. Αν ο δρομολογητής δεν απαντούσε, θα έστελνε με εκπομπή στο 87.5%.",When:"Πότε","50% of lease (T1 = 12 h)":"50% της μίσθωσης (T1 = 12 h)","The router (unicast)":"Ο δρομολογητής (unicast)","If unanswered":"Χωρίς απάντηση","Broadcast at 87.5% (T2)":"Εκπομπή στο 87.5% (T2)","renew 192.168.1.10":"ανανέωση 192.168.1.10","sent straight to 192.168.1.1":"στάλθηκε κατευθείαν στο 192.168.1.1","lease renewed":"η μίσθωση ανανεώθηκε","another 24 hours":"άλλες 24 ώρες",Message:"Μήνυμα","1 (request, from a client)":"1 (αίτημα, από πελάτη)",Hardware:"Υλικό","Ethernet, 6-byte addresses":"Ethernet, διευθύνσεις 6 byte",Hops:"Βήματα","Chosen by the client; every reply repeats it.":"Το επιλέγει ο πελάτης· κάθε απάντηση το επαναλαμβάνει.",Seconds:"Δευτερόλεπτα","0x0000 (unicast replies are fine)":"0x0000 (οι απαντήσεις unicast είναι εντάξει)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Σημαία εκπομπής κλειστή: ο διακομιστής μπορεί να στείλει κατευθείαν στη διεύθυνση MAC του πελάτη.","Client address":"Διεύθυνση πελάτη","Filled in only when the client already has an address (renewing).":"Συμπληρώνεται μόνο όταν ο πελάτης έχει ήδη διεύθυνση (ανανέωση).","Your address":"Η διεύθυνσή σας","The address the server is giving out.":"Η διεύθυνση που δίνει ο διακομιστής.","Next server":"Επόμενος διακομιστής","Relay agent":"Πράκτορας αναμετάδοσης","Client MAC":"MAC πελάτη","Server name, boot file":"Όνομα διακομιστή, αρχείο εκκίνησης",empty:"κενό","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Σημειώνει ότι οι επιλογές που ακολουθούν είναι DHCP.","Message type: 1 (Discover)":"Τύπος μηνύματος: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Αναγνωριστικό πελάτη: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Όνομα υπολογιστή: alice-laptop","Vendor class: MSFT 5.0":"Κλάση κατασκευαστή: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Ζητούμενες παράμετροι: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252",End:"Τέλος","2 (reply, from a server)":"2 (απάντηση, από διακομιστή)","Message type: 2 (Offer)":"Τύπος μηνύματος: 2 (Offer)","Server identifier: 192.168.1.1":"Αναγνωριστικό διακομιστή: 192.168.1.1","Lease time: 86,400 s (24 h)":"Διάρκεια μίσθωσης: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Χρόνος ανανέωσης (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Χρόνος επανασύνδεσης (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Μάσκα υποδικτύου: 255.255.255.0","Broadcast address: 192.168.1.255":"Διεύθυνση εκπομπής: 192.168.1.255","Router: 192.168.1.1":"Δρομολογητής: 192.168.1.1","DNS server: 8.8.8.8":"Διακομιστής DNS: 8.8.8.8","Message type: 3 (Request)":"Τύπος μηνύματος: 3 (Request)","Requested address: 192.168.1.10":"Ζητούμενη διεύθυνση: 192.168.1.10","Client FQDN: alice-laptop":"FQDN πελάτη: alice-laptop","Message type: 5 (ACK)":"Τύπος μηνύματος: 5 (ACK)","Network Diagnostics":"Διαγνωστικά δικτύου","Ping / probe":"Ping / έλεγχος","Echo reply":"Απάντηση echo","Error report":"Αναφορά σφάλματος","Internet Control Message Protocol":"Internet Control Message Protocol","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"Το ICMP είναι ο τρόπος με τον οποίο το δίκτυο απαντά: ένας δρομολογητής λέει ότι ο χρόνος ενός πακέτου τελείωσε, ένας διακομιστής λέει ότι τίποτα δεν ακούει σε μια θύρα. Εργαλεία όπως τα ping και traceroute βασίζονται σε αυτά τα μηνύματα. Ταξιδεύει μέσα στο IP, αλλά δεν φέρει δεδομένα εφαρμογής.","Carried in":"Μεταφέρεται σε","IP (protocol 1)":"IP (πρωτόκολλο 1)","A type and a code":"Ένας τύπος και ένας κωδικός",Tools:"Εργαλεία",Often:"Συχνά","Filtered by firewalls":"Φιλτράρεται από τείχη προστασίας","The network answered":"Το δίκτυο απάντησε","Replies, expiries and errors":"Απαντήσεις, λήξεις και σφάλματα","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Ένα αίτημα echo μέτρησε τη διαδρομή μετ’ επιστροφής, πακέτα με μικρό TTL έκαναν κάθε δρομολογητή στη διαδρομή να συστηθεί, και μια κλειστή θύρα αναφέρθηκε αμέσως πίσω. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","Round trip":"Μετ’ επιστροφής",Path:"Διαδρομή","12 routers, server at hop 13":"12 δρομολογητές, διακομιστής στο βήμα 13","Types used":"Τύποι που χρησιμοποιήθηκαν","8, 0, 11 and 3":"8, 0, 11 και 3","Reply TTL":"TTL απάντησης","52 (64 − 12 routers)":"52 (64 − 12 δρομολογητές)",Ping:"Ping","Echo request":"Αίτημα echo","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"Το «ping -n 1 203.0.113.10» στέλνει ένα αίτημα echo ICMP (το απλό ping στέλνει τέσσερα, ανά δευτερόλεπτο): τύπος 8, κωδικός 0, με αναγνωριστικό, αριθμό ακολουθίας και 32 byte συμπλήρωσης. Το σύστημα του διακομιστή απαντά μόνο του, χωρίς εφαρμογή.","Type, code":"Τύπος, κωδικός","8, 0 (echo request)":"8, 0 (αίτημα echo)","32 bytes (Windows)":"32 byte (Windows)","ECHO REQUEST":"ΑΙΤΗΜΑ ECHO","type 8 · seq 1":"τύπος 8 · seq 1","32 bytes of data":"32 byte δεδομένων","Echo Reply":"Απάντηση echo","Round-trip time":"Χρόνος μετ’ επιστροφής","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Ο διακομιστής στέλνει πίσω απάντηση echo, τύπος 0, με το ίδιο αναγνωριστικό, τον ίδιο αριθμό ακολουθίας και τα ίδια δεδομένα. Το ping τυπώνει τον χρόνο που χρειάστηκε και το TTL με το οποίο έφτασε η απάντηση: «bytes=32 time=34ms TTL=52».","0, 0 (echo reply)":"0, 0 (απάντηση echo)","TTL on arrival":"TTL κατά την άφιξη","ECHO REPLY":"ΑΠΑΝΤΗΣΗ ECHO","type 0 · seq 1":"τύπος 0 · seq 1","same 32 bytes back":"τα ίδια 32 byte πίσω","TIME=34MS TTL=52":"TIME=34MS TTL=52","The first router answers":"Απαντά ο πρώτος δρομολογητής","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"Το «ping -n 1 -i 1» στέλνει το ίδιο αίτημα με TTL 1. Ο οικιακός δρομολογητής το κατεβάζει στο 0, άρα πρέπει να πετάξει το πακέτο, και στέλνει πίσω μήνυμα Time Exceeded από τη δική του διεύθυνση: «Reply from 192.168.1.1: TTL expired in transit.»","Sent with":"Στάλθηκε με","Dropped by":"Πετάχτηκε από","11, 0 (time exceeded)":"11, 0 (λήξη χρόνου)","echo request":"αίτημα echo","expires at the first router":"λήγει στον πρώτο δρομολογητή","TIME EXCEEDED":"ΛΗΞΗ ΧΡΟΝΟΥ","type 11 · from 192.168.1.1":"τύπος 11 · από 192.168.1.1","quotes the dropped header":"παραθέτει την κεφαλίδα που πετάχτηκε","The next router answers":"Απαντά ο επόμενος δρομολογητής","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Με «-i 2», ο οικιακός δρομολογητής κατεβάζει το TTL στο 1 και το προωθεί. Ο πρώτος δρομολογητής του παρόχου Διαδικτύου το κατεβάζει στο 0 και απαντά από το 198.51.100.1. Ο οικιακός δρομολογητής μεταφράζει την αναφορά πίσω στον φορητό όπως κάθε απάντηση.","ISP router 198.51.100.1":"Δρομολογητής παρόχου 198.51.100.1","expires at the second router":"λήγει στον δεύτερο δρομολογητή","HOP 2 · 198.51.100.1":"ΒΗΜΑ 2 · 198.51.100.1","type 11 · from 198.51.100.1":"τύπος 11 · από 198.51.100.1","That’s Traceroute":"Αυτό είναι το traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … μέχρι να φτάσει","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"Το tracert το αυτοματοποιεί: ανεβάζει το TTL κατά ένα κάθε φορά, στέλνει τρεις ελέγχους ανά βήμα και καταγράφει ποιος απαντά. Τα βήματα 3 έως 12 λειτουργούν το ίδιο, και με TTL 13 το αίτημα φτάνει τελικά στον διακομιστή, που απαντά κανονικά.","12 routers, then the server":"12 δρομολογητές, μετά ο διακομιστής","Per hop":"Ανά βήμα","3 probes":"3 έλεγχοι","On Linux":"Στο Linux","traceroute sends UDP":"το traceroute στέλνει UDP","enough hops to arrive":"αρκετά βήματα για να φτάσει","the server itself answers":"απαντά ο ίδιος ο διακομιστής","end of the route":"τέλος της διαδρομής",Unreachable:"Μη προσβάσιμο","Nothing listening on that port":"Τίποτα δεν ακούει σε αυτή τη θύρα","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Μια εφαρμογή στέλνει ένα datagram UDP στη θύρα 9999, όπου τίποτα δεν ακούει. Ο διακομιστής δεν μπορεί να το παραδώσει, οπότε απαντά με Destination Unreachable, κωδικός 3 (μη προσβάσιμη θύρα), παραθέτοντας την αρχή του datagram. Πολλά τείχη προστασίας αντίθετα πετούν τέτοια πακέτα σιωπηλά.","3, 3 (port unreachable)":"3, 3 (μη προσβάσιμη θύρα)","Other codes":"Άλλοι κωδικοί","0 net, 1 host, 4 too big":"0 δίκτυο, 1 υπολογιστής, 4 πολύ μεγάλο",Firewalls:"Τείχη προστασίας","Often silent instead":"Συχνά σιωπούν αντίθετα","to port 9999":"προς τη θύρα 9999","nothing listening there":"τίποτα δεν ακούει εκεί",UNREACHABLE:"ΜΗ ΠΡΟΣΒΑΣΙΜΟ","type 3 · code 3":"τύπος 3 · κωδικός 3","port unreachable":"μη προσβάσιμη θύρα","ICMP · Echo request":"ICMP · Αίτημα echo",Code:"Κωδικός","Covers the whole ICMP message.":"Καλύπτει όλο το μήνυμα ICMP.",Identifier:"Αναγνωριστικό","Matches replies to this ping program.":"Αντιστοιχίζει απαντήσεις σε αυτό το πρόγραμμα ping.","Windows counts up across every ping it sends.":"Τα Windows μετρούν προς τα πάνω σε κάθε ping που στέλνουν.",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 byte)',"Windows ping’s filler: the alphabet, a to w, then again.":"Η συμπλήρωση του ping των Windows: το αλφάβητο από a έως w, και πάλι από την αρχή.","ICMP · Echo reply":"ICMP · Απάντηση echo","Sent back exactly as it came.":"Στέλνεται πίσω ακριβώς όπως ήρθε.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Λήξη χρόνου (το TTL έφτασε στο 0)","Time exceeded (TTL reached 0)":"Λήξη χρόνου (το TTL έφτασε στο 0)",Unused:"Αχρησιμοποίητο","Original packet":"Αρχικό πακέτο","Its source, destination":"Η πηγή και ο προορισμός του","its IP header and first 8 bytes (28 bytes)":"η κεφαλίδα IP του και τα πρώτα 8 byte (28 byte)","App data":"Δεδομένα εφαρμογής",'"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 byte)',"What the app sent; nothing on the server is listening for it.":"Αυτό που έστειλε η εφαρμογή· τίποτα στον διακομιστή δεν το περιμένει.","ICMP · Destination unreachable (port unreachable)":"ICMP · Μη προσβάσιμος προορισμός (μη προσβάσιμη θύρα)","Destination unreachable (port unreachable)":"Μη προσβάσιμος προορισμός (μη προσβάσιμη θύρα)","Sending Email":"Αποστολή email","SMTP command":"Εντολή SMTP","SMTP reply":"Απάντηση SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"Το SMTP μετακινεί τα email: από την εφαρμογή αλληλογραφίας σας στον διακομιστή του παρόχου σας, και από εκείνον στον διακομιστή του παραλήπτη. Είναι μια συζήτηση με σύντομες εντολές κειμένου, που η καθεμιά παίρνει απάντηση με τριψήφιο κωδικό. Η ανάγνωση της αλληλογραφίας είναι άλλη δουλειά, που γίνεται με IMAP ή POP3.","465/587 submit, 25 relay":"465/587 υποβολή, 25 αναμετάδοση","TCP, usually with TLS":"TCP, συνήθως με TLS",Commands:"Εντολές",Replies:"Απαντήσεις","2xx ok, 3xx go on, 4/5xx error":"2xx εντάξει, 3xx συνέχεια, 4/5xx σφάλμα","Mail delivered":"Το μήνυμα παραδόθηκε","Two hops, one message":"Δύο βήματα, ένα μήνυμα","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"Η εφαρμογή της Alice παρέδωσε το μήνυμα στον πάροχό της μέσω κρυπτογραφημένης σύνδεσης με σύνδεση χρήστη. Ο πάροχος βρήκε τον διακομιστή αλληλογραφίας του Bob στο DNS και το αναμετέδωσε εκεί, αναβαθμίζοντας αυτή τη σύνδεση σε TLS. Τώρα περιμένει στο γραμματοκιβώτιο του Bob μέχρι να το διαβάσει με IMAP ή POP3.","Laptop → provider → Bob’s":"Φορητός → πάροχος → Bob",Submission:"Υποβολή","Port 465, TLS, login":"Θύρα 465, TLS, σύνδεση",Relay:"Αναμετάδοση","Port 25, STARTTLS":"Θύρα 25, STARTTLS","Checks at Bob’s":"Έλεγχοι στον Bob","Connect Securely":"Ασφαλής σύνδεση","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Η Alice πατά Αποστολή. Η εφαρμογή αλληλογραφίας της συνδέεται στον διακομιστή υποβολής του παρόχου, smtp.example.com, στη θύρα 465. Σε αυτή τη θύρα το TLS ξεκινά αμέσως, οπότε όλη η συζήτηση SMTP, μαζί με τον κωδικό της, είναι κρυπτογραφημένη.","TLS from the start":"TLS από την αρχή","SMTP inside TLS":"SMTP μέσα σε TLS","Greeting & Login":"Χαιρετισμός και σύνδεση","EHLO, then AUTH":"EHLO, μετά AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Ο διακομιστής χαιρετά με κωδικό 220. Η εφαρμογή λέει EHLO και ο διακομιστής απαριθμεί τι υποστηρίζει, μαζί και το AUTH. Η εφαρμογή συνδέεται με AUTH PLAIN (όνομα χρήστη και κωδικός σε base64) και παίρνει 235: πιστοποιήθηκε.",Greeting:"Χαιρετισμός",Capabilities:"Δυνατότητες","Login result":"Αποτέλεσμα σύνδεσης","user and password, base64":"χρήστης και κωδικός, base64","Send the Message":"Αποστολή του μηνύματος","Envelope, then content":"Φάκελος, μετά περιεχόμενο","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"Τα MAIL FROM και RCPT TO είναι ο φάκελος: αποστολέας και παραλήπτης. Το PIPELINING επιτρέπει και στις τρεις εντολές να μπουν σε ένα πακέτο. Μετά το 354 έρχεται το μήνυμα, που τελειώνει με μια γραμμή με μόνο μια τελεία.",Envelope:"Φάκελος","Content ends":"Το περιεχόμενο τελειώνει","A line with only “.”":"Μια γραμμή με μόνο «.»",Result:"Αποτέλεσμα",MESSAGE:"ΜΗΝΥΜΑ","… message …":"… μήνυμα …","250 QUEUED":"250 ΣΕ ΟΥΡΑ","Find Bob’s Server":"Ο διακομιστής του Bob","An MX lookup in DNS":"Αναζήτηση MX στο DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Ο πάροχος της Alice πρέπει τώρα να παραδώσει στο example.org. Ζητά από το DNS την εγγραφή MX αυτού του τομέα, που ονομάζει τον διακομιστή που δέχεται την αλληλογραφία του, και μετά αναζητά τη διεύθυνση αυτού του διακομιστή.","MX record":"Εγγραφή MX","Asked by":"Ρωτά","Alice’s provider":"Ο πάροχος της Alice","Server to Server":"Από διακομιστή σε διακομιστή","Port 25, upgraded with STARTTLS":"Θύρα 25, αναβάθμιση με STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Ο πάροχος συνδέεται στο mx.example.org στη θύρα 25. Αυτή η συζήτηση ξεκινά σε απλό κείμενο: ο χαιρετισμός και η απάντηση στο EHLO διαφημίζουν το STARTTLS, ο πάροχος το ζητά, παίρνει 220 και οι δύο πλευρές περνούν σε TLS.","Starts as":"Ξεκινά ως","Plain text":"Απλό κείμενο",Upgrade:"Αναβάθμιση",Deliver:"Παράδοση","The same transaction again":"Η ίδια συναλλαγή ξανά","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Με ενεργό TLS, ο πάροχος επαναλαμβάνει το EHLO, μετά τον φάκελο και το μήνυμα, τώρα με προσθήκη υπογραφής DKIM και κεφαλίδας Received. Ο διακομιστής του Bob ελέγχει SPF, DKIM και DMARC και το δέχεται.","Login needed":"Απαιτείται σύνδεση","No (server to server)":"Όχι (από διακομιστή σε διακομιστή)","1,316 bytes (signed)":"1,316 byte (υπογεγραμμένο)","IN BOB’S MAILBOX":"ΣΤΟ ΓΡΑΜΜΑΤΟΚΙΒΩΤΙΟ ΤΟΥ BOB","Server Hello + encrypted handshake, 2 segments":"Server Hello + κρυπτογραφημένη χειραψία, 2 τμήματα","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 δυνατότητες (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (διαπιστευτήρια)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (σε pipeline)","Message (316 bytes), then “.”":"Μήνυμα (316 byte), μετά «.»","250 capabilities (PIPELINING, STARTTLS …)":"250 δυνατότητες (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 δυνατότητες (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Μήνυμα (1,316 byte), μετά «.»","What this client supports. Its exact contents vary from client to client; this is an example.":"Τι υποστηρίζει αυτός ο πελάτης. Το ακριβές περιεχόμενο διαφέρει από πελάτη σε πελάτη· αυτό είναι ένα παράδειγμα.","up to 512 bytes":"έως 512 byte","The server’s choices and its key share.":"Οι επιλογές του διακομιστή και το μερίδιο κλειδιού του.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (η αλυσίδα), Certificate Verify (η υπογραφή), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Το μήνυμα της Alice (316 byte), μετά μια γραμμή με μόνο «.»","example.org, type MX, class IN":"example.org, τύπος MX, κλάση IN","mx.example.org, type A, class IN":"mx.example.org, τύπος A, κλάση IN",Timestamps:"Χρονοσημάνσεις","Used to measure round trips; both sides offered them.":"Χρησιμοποιούνται για τη μέτρηση διαδρομών μετ’ επιστροφής· τις πρόσφεραν και οι δύο πλευρές.","The signed message (1,316 bytes), then a line holding only “.”":"Το υπογεγραμμένο μήνυμα (1,316 byte), μετά μια γραμμή με μόνο «.»","Downloading Email":"Λήψη email","POP3 command":"Εντολή POP3","POP3 reply":"Απάντηση POP3","Post Office Protocol, version 3":"Post Office Protocol, έκδοση 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"Το POP3 επιτρέπει σε μια εφαρμογή αλληλογραφίας να κατεβάζει μηνύματα από ένα γραμματοκιβώτιο σε διακομιστή. Σχεδιάστηκε για μία συσκευή που παίρνει την αλληλογραφία και μετά τη σβήνει από τον διακομιστή. Οι εντολές είναι σύντομες λέξεις, και κάθε απάντηση αρχίζει με +OK ή -ERR.",Model:"Μοντέλο","Download, then delete":"Λήψη, μετά διαγραφή","+OK or -ERR":"+OK ή -ERR","Mail downloaded":"Η αλληλογραφία κατέβηκε","And gone from the server":"Και έφυγε από τον διακομιστή","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"Η εφαρμογή του Bob συνδέθηκε, είδε δύο μηνύματα, κατέβασε το πρώτο και το διέγραψε, κάτι που ο διακομιστής εκτέλεσε στο QUIT. Αυτό το μήνυμα υπάρχει πια μόνο σε αυτόν τον φορητό, γι’ αυτό το POP3 ταιριάζει σε μία συσκευή και το IMAP σε πολλές.","2 waiting, 1 downloaded":"2 σε αναμονή, 1 κατέβηκε",Deleted:"Διαγράφηκε","At QUIT (UPDATE state)":"Στο QUIT (κατάσταση UPDATE)","Best for":"Ιδανικό για","A single device":"Μία συσκευή","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"Η εφαρμογή αλληλογραφίας του Bob συνδέεται στο pop.example.org στη θύρα 995, όπου το TLS ξεκινά αμέσως. Μέσα σε αυτό ο διακομιστής χαιρετά με +OK. (Στη θύρα 110 η συνεδρία ξεκινά σε απλό κείμενο και αναβαθμίζεται με την εντολή STLS.)","Log In":"Σύνδεση","USER, then PASS":"USER, μετά PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"Η εφαρμογή στέλνει το όνομα χρήστη με USER και τον κωδικό με PASS. Κάθε εντολή παίρνει το δικό της +OK. Επειδή η συνεδρία είναι μέσα σε TLS, ο κωδικός δεν διαβάζεται στη διαδρομή.","Protected by":"Προστατεύεται από","Check the Mailbox":"Έλεγχος γραμματοκιβωτίου","STAT and LIST":"STAT και LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"Το STAT επιστρέφει τον αριθμό των μηνυμάτων και το συνολικό μέγεθός τους: 2 μηνύματα, 5120 byte. Το LIST δίνει τον αριθμό και το μέγεθος κάθε μηνύματος και τελειώνει με μια γραμμή με μόνο μια τελεία.","Message 1":"Μήνυμα 1","Message 2":"Μήνυμα 2",Download:"Λήψη","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"Το RETR 1 ζητά το πρώτο μήνυμα. Ο διακομιστής απαντά +OK με το μέγεθός του, μετά το μήνυμα και μια τελεία στο τέλος: 1904 byte συν τη γραμμή απάντησης, δύο τμήματα TCP.",Command:"Εντολή","Delete & Quit":"Διαγραφή και έξοδος","Deleted only at QUIT":"Διαγράφεται μόνο στο QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"Το DELE 1 απλώς σημαδεύει το μήνυμα. Ο διακομιστής το αφαιρεί όταν η εφαρμογή πει QUIT: αν η σύνδεση έπεφτε πριν, τίποτα δεν θα διαγραφόταν. Πολλές εφαρμογές προσφέρουν «διατήρηση αντιγράφου στον διακομιστή», που παραλείπει το DELE.","Marks message 1":"Σημαδεύει το μήνυμα 1",Removed:"Αφαιρέθηκε","At QUIT":"Στο QUIT",Option:"Επιλογή","Leave a copy on server":"Αντίγραφο στον διακομιστή","MESSAGE 1 DELETED":"ΤΟ ΜΗΝΥΜΑ 1 ΔΙΑΓΡΑΦΗΚΕ","PASS (password)":"PASS (κωδικός)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, μήνυμα, «.» (2 τμήματα)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, το μήνυμα των 1,904 byte, μετά μια γραμμή με μόνο «.»","IMAP command":"Εντολή IMAP","IMAP response":"Απάντηση IMAP","Internet Message Access Protocol":"Internet Message Access Protocol","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"Το IMAP επιτρέπει στις εφαρμογές αλληλογραφίας να δουλεύουν με ένα γραμματοκιβώτιο που μένει στον διακομιστή. Φάκελοι, σημάδια ανάγνωσης και σήμανσης και διαγραφές κρατιούνται εκεί, ώστε κινητό, φορητός και webmail να βλέπουν το ίδιο γραμματοκιβώτιο. Ο διακομιστής μπορεί επίσης να ειδοποιεί μια εφαρμογή για νέα αλληλογραφία μόλις φτάνει.","Mail stays on the server":"Η αλληλογραφία μένει στον διακομιστή",Syncs:"Συγχρονίζει","Folders and flags":"Φακέλους και σημαίες","Mailbox in sync":"Γραμματοκιβώτιο σε συγχρονισμό","Read once, read everywhere":"Διαβάστηκε μία φορά, παντού","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"Η εφαρμογή του Bob άνοιξε τα εισερχόμενα και διάβασε ένα μήνυμα, που σημειώθηκε \\Seen στον διακομιστή για όλες τις συσκευές του, και μετά περίμενε με IDLE μέχρι ο διακομιστής να ανακοινώσει νέα αλληλογραφία. Τίποτα δεν διαγράφηκε: ο διακομιστής κρατά ακόμη τα πάντα.","2, then 3 (new mail)":"2, μετά 3 (νέα αλληλογραφία)","Read mark":"Σημάδι ανάγνωσης","\\Seen, stored on server":"\\Seen, αποθηκευμένο στον διακομιστή","New mail":"Νέα αλληλογραφία","Pushed during IDLE":"Στέλνεται κατά το IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"Η εφαρμογή του Bob συνδέεται στο imap.example.org στη θύρα 993, όπου το TLS ξεκινά αμέσως. Ο διακομιστής χαιρετά με μια γραμμή «* OK» χωρίς ετικέτα που απαριθμεί και τις δυνατότητές του, όπως το IDLE.","Commands carry tags":"Οι εντολές έχουν ετικέτες","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Κάθε εντολή ξεκινά με μια ετικέτα που επιλέγει η εφαρμογή, όπως a1, και ο διακομιστής κλείνει την απάντησή του με την ίδια ετικέτα. Έτσι πολλές εντολές μπορούν να εκκρεμούν και κάθε απάντηση αντιστοιχίζεται. Οι γραμμές που αρχίζουν με * είναι δεδομένα χωρίς ετικέτα.",Tags:"Ετικέτες","Match replies to commands":"Αντιστοιχίζουν απαντήσεις σε εντολές","Open the Inbox":"Άνοιγμα εισερχομένων","SELECT a folder":"SELECT ενός φακέλου","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"Το SELECT INBOX ανοίγει τον φάκελο. Ο διακομιστής αναφέρει τον αριθμό μηνυμάτων, τις σημαίες που υποστηρίζει και το πρώτο αδιάβαστο μήνυμα, και μετά επιβεβαιώνει ότι ο φάκελος είναι ανοιχτός για ανάγνωση και εγγραφή.","First unread":"Πρώτο αδιάβαστο",Access:"Πρόσβαση","Read a Message":"Ανάγνωση μηνύματος","FETCH, and the \\Seen flag":"FETCH και η σημαία \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"Το FETCH 2 BODY[] κατεβάζει το μήνυμα 2 (τρία τμήματα TCP). Αυτό ορίζει τη σημαία \\Seen στον διακομιστή, οπότε φαίνεται διαβασμένο και στο κινητό του Bob, και το μήνυμα μένει εκεί.","Flag set":"Σημαία που ορίστηκε","\\Seen (on the server)":"\\Seen (στον διακομιστή)","STILL ON SERVER · \\SEEN":"ΑΚΟΜΗ ΣΤΟΝ ΔΙΑΚΟΜΙΣΤΗ · \\SEEN","Wait for New Mail":"Αναμονή για νέα αλληλογραφία","IDLE: the server pushes":"IDLE: ο διακομιστής ειδοποιεί","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"Το IDLE λέει στον διακομιστή «ενημέρωσέ με όταν κάτι αλλάξει». Περίπου 42 δευτερόλεπτα αργότερα φτάνει το μήνυμα της Alice και ο διακομιστής στέλνει αμέσως «* 3 EXISTS». Η εφαρμογή τερματίζει το IDLE με DONE και μπορεί να κατεβάσει τη νέα αλληλογραφία.","Server says":"Ο διακομιστής λέει","* 3 EXISTS (new mail)":"* 3 EXISTS (νέα αλληλογραφία)","Ended by":"Τερματίζεται με","NEW MAIL ARRIVED":"ΗΡΘΕ ΝΕΑ ΑΛΛΗΛΟΓΡΑΦΙΑ","a1 LOGIN (user and password)":"a1 LOGIN (χρήστης και κωδικός)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, το μήνυμα των 3,216 byte, μετά a3 OK FETCH completed","Transferring Files":"Μεταφορά αρχείων","FTP command":"Εντολή FTP","FTP reply":"Απάντηση FTP","File data":"Δεδομένα αρχείου","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"Το FTP μετακινεί αρχεία μεταξύ πελάτη και διακομιστή. Είναι ασυνήθιστο, γιατί χρησιμοποιεί δύο συνδέσεις TCP: μία για εντολές και απαντήσεις, και μια νέα για κάθε αρχείο ή λίστα. Χρονολογείται από τις αρχές της δεκαετίας του 1970 και στέλνει τα πάντα, μαζί και τους κωδικούς, ως απλό κείμενο.","21 control, data varies":"21 έλεγχος, δεδομένα ποικίλλει",Connections:"Συνδέσεις","Control + one per transfer":"Έλεγχος + μία ανά μεταφορά",Encryption:"Κρυπτογράφηση","None (plain text)":"Καμία (απλό κείμενο)","Safer options":"Ασφαλέστερες επιλογές","SFTP, or FTPS (FTP + TLS)":"SFTP, ή FTPS (FTP + TLS)","File downloaded":"Το αρχείο κατέβηκε","Two connections, no encryption":"Δύο συνδέσεις, χωρίς κρυπτογράφηση","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Οι εντολές πέρασαν από τη σύνδεση ελέγχου, το αρχείο από τη δική του σύνδεση δεδομένων, και το κλείσιμο εκείνης της σύνδεσης σημάδεψε το τέλος του αρχείου. Οποιοσδήποτε στη διαδρομή μπορούσε να διαβάσει τον κωδικό και το αρχείο, γι’ αυτό σήμερα χρησιμοποιείται SFTP ή FTPS.","2 (control + data)":"2 (έλεγχος + δεδομένα)",File:"Αρχείο","4,000 bytes, 3 segments":"4,000 byte, 3 τμήματα",Password:"Κωδικός","Sent in plain text":"Στάλθηκε ως απλό κείμενο","Use instead":"Χρησιμοποιήστε αντί γι’ αυτό","SFTP or FTPS":"SFTP ή FTPS","Control Connection":"Σύνδεση ελέγχου","Port 21, plain text":"Θύρα 21, απλό κείμενο","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"Η εφαρμογή FTP ανοίγει σύνδεση TCP προς το ftp.example.com στη θύρα 21. Αυτή η σύνδεση ελέγχου μεταφέρει εντολές και απαντήσεις για όλη τη συνεδρία. Ο διακομιστής χαιρετά με 220. Όπως στο SMTP, κάθε απάντηση αρχίζει με τριψήφιο κωδικό.","USER and PASS, readable by anyone":"USER και PASS, αναγνώσιμα από όλους","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"Η εφαρμογή στέλνει USER, ο διακομιστής ζητά τον κωδικό με 331 και το PASS τον στέλνει. Τίποτα δεν είναι κρυπτογραφημένο, οπότε όνομα χρήστη και κωδικός περνούν από κάθε δίκτυο στη διαδρομή ως αναγνώσιμο κείμενο.","Visible to":"Ορατό σε","Anyone on the path":"Οποιονδήποτε στη διαδρομή","PASSWORD IN PLAIN TEXT":"ΚΩΔΙΚΟΣ ΣΕ ΑΠΛΟ ΚΕΙΜΕΝΟ","Passive Mode":"Παθητική λειτουργία","The server names a data port":"Ο διακομιστής ορίζει θύρα δεδομένων","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"Το TYPE I ζητά δυαδικό αντίγραφο byte προς byte. Το PASV ζητά από τον διακομιστή να ανοίξει θύρα για τη σύνδεση δεδομένων. Η απάντηση κωδικοποιεί διεύθυνση και θύρα ως έξι αριθμούς: 195 × 256 + 149 = θύρα 50069. Ο φορητός συνδέεται προς τα έξω, κάτι που λειτουργεί μέσα από NAT.","Data port":"Θύρα δεδομένων","Active mode":"Ενεργή λειτουργία","Server dials in: NAT blocks":"Ο διακομιστής καλεί: το NAT μπλοκάρει","Data Connection":"Σύνδεση δεδομένων","A second TCP connection":"Μια δεύτερη σύνδεση TCP","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"Η εφαρμογή ανοίγει δεύτερη σύνδεση TCP, προς τη θύρα 50069, και ζητά το αρχείο στη σύνδεση ελέγχου με RETR. Ο διακομιστής απαντά εκεί 150 και αρχίζει να στέλνει το αρχείο από τη νέα σύνδεση.","Data to":"Δεδομένα προς","The File Arrives":"Το αρχείο φτάνει","Closing the connection ends it":"Το κλείσιμο της σύνδεσης το τελειώνει","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"Τα 4,000 byte φτάνουν σε 3 τμήματα TCP. Το FTP δεν βάζει ένδειξη μήκους στα ίδια τα δεδομένα: ο διακομιστής κλείνει τη σύνδεση δεδομένων για να σημάνει το τέλος του αρχείου. Μόλις ο φορητός επιβεβαιώσει τα πάντα, ο διακομιστής επιβεβαιώνει με 226 στη σύνδεση ελέγχου.","report.pdf, 4,000 bytes":"report.pdf, 4,000 byte","End of file":"Τέλος αρχείου","Data connection closed":"Η σύνδεση δεδομένων έκλεισε","3 SEGMENTS":"3 ΤΜΗΜΑΤΑ","4,000 bytes, readable by anyone":"4,000 byte, αναγνώσιμα από όλους","end of file:":"τέλος αρχείου:","data connection closed":"η σύνδεση δεδομένων έκλεισε",Quit:"Έξοδος","Close the control connection":"Κλείσιμο της σύνδεσης ελέγχου","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"Το QUIT τερματίζει τη συνεδρία και ο διακομιστής αποχαιρετά με 221. Για οτιδήποτε ευαίσθητο, το SFTP (άλλο πρωτόκολλο, πάνω από SSH) ή το FTPS (FTP μέσα σε TLS) κάνουν την ίδια δουλειά με κρυπτογράφηση.","Encrypted cousins":"Κρυπτογραφημένα ξαδέρφια","FTP data":"Δεδομένα FTP","The file itself, unencrypted: anyone on the path could read it.":"Το ίδιο το αρχείο, μη κρυπτογραφημένο: οποιοσδήποτε στη διαδρομή μπορεί να το διαβάσει.","Secure Remote Login":"Ασφαλής απομακρυσμένη σύνδεση","Plain setup":"Απλή εγκατάσταση","From laptop":"Από τον φορητό","From server":"Από τον διακομιστή","Some packets not shown":"Κάποια πακέτα δεν φαίνονται","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"Το SSH σας δίνει κρυπτογραφημένη, πιστοποιημένη σύνδεση με έναν άλλο υπολογιστή, για να εκτελείτε εντολές σε αυτόν, να αντιγράφετε αρχεία (SFTP, scp) ή να μεταφέρετε άλλες συνδέσεις. Ο διακομιστής αποδεικνύει ποιος είναι με ένα κλειδί κεντρικού υπολογιστή· εσείς αποδεικνύετε ποιος είστε με ζεύγος κλειδιών ή κωδικό.","Server proves":"Ο διακομιστής αποδεικνύει","Host key (known_hosts)":"Κλειδί υπολογιστή (known_hosts)","You prove":"Εσείς αποδεικνύετε","Key pair or password":"Ζεύγος κλειδιών ή κωδικό","Logged in securely":"Ασφαλής σύνδεση","Encrypted from the key exchange on":"Κρυπτογραφημένο από την ανταλλαγή κλειδιών και μετά","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Οι δύο πλευρές συμφώνησαν αλγορίθμους, έφτιαξαν κοινά κλειδιά με υβριδική μετακβαντική ανταλλαγή, και ο διακομιστής απέδειξε την ταυτότητά του με το κλειδί του. Η Alice απέδειξε τη δική της υπογράφοντας με ιδιωτικό κλειδί που δεν έφυγε ποτέ από τον φορητό, και μετά πληκτρολόγησε μια εντολή, ένα πακέτο ανά πλήκτρο.",Login:"Σύνδεση","Ed25519 key, no password":"Κλειδί Ed25519, χωρίς κωδικό","Say Hello":"Χαιρετισμός","Versions, in plain text":"Εκδόσεις, σε απλό κείμενο","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Η Alice εκτελεί «ssh alice@server.example.com». Μετά τη χειραψία TCP στη θύρα 22, κάθε πλευρά στέλνει μία γραμμή απλού κειμένου με την έκδοση του πρωτοκόλλου SSH (2.0) και το λογισμικό της. Όλα τα υπόλοιπα στο SSH είναι δυαδικά.",VERSION:"ΕΚΔΟΣΗ","Agree on Algorithms":"Συμφωνία αλγορίθμων","KEXINIT lists, first match wins":"Λίστες KEXINIT, κερδίζει η πρώτη αντιστοιχία","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Κάθε πλευρά στέλνει ένα KEXINIT με κάθε αλγόριθμο που υποστηρίζει, κατά σειρά προτίμησης, για ανταλλαγή κλειδιών, κλειδιά υπολογιστή, κρυπτογράφηση, ακεραιότητα και συμπίεση. Σε κάθε κατηγορία επιλέγεται ο πρώτος αλγόριθμος της λίστας του φορητού που υποστηρίζει και ο διακομιστής.","Host key":"Κλειδί υπολογιστή","server’s algorithm lists":"λίστες αλγορίθμων του διακομιστή","in order of preference":"κατά σειρά προτίμησης","laptop’s algorithm lists":"λίστες αλγορίθμων του φορητού","Key Exchange":"Ανταλλαγή κλειδιών","Shared keys, and a host key check":"Κοινά κλειδιά και έλεγχος κλειδιού υπολογιστή","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"Ο φορητός στέλνει το μισό του μιας υβριδικής ανταλλαγής: ένα κλειδί Streamlined NTRU Prime, επιλεγμένο ώστε να αντέχει σε μελλοντικούς κβαντικούς υπολογιστές, συν ένα κλειδί X25519. Ο διακομιστής απαντά με το μισό του, το κλειδί του και μια υπογραφή πάνω στην ανταλλαγή. Το NEWKEYS ενεργοποιεί την κρυπτογράφηση.",Hybrid:"Υβριδικό","Matches known_hosts":"Ταιριάζει με known_hosts","First visit":"Πρώτη επίσκεψη","ssh asks you to confirm":"το ssh ζητά επιβεβαίωση","public keys":"δημόσια κλειδιά","its half, its host key":"το μισό του, το κλειδί του","and a signature":"και μια υπογραφή","HOST KEY MATCHES KNOWN_HOSTS":"ΤΟ ΚΛΕΙΔΙ ΤΑΙΡΙΑΖΕΙ ΜΕ ΤΟ KNOWN_HOSTS","Log In with a Key":"Σύνδεση με κλειδί","Sign, don’t send a secret":"Υπογραφή, όχι αποστολή μυστικού","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Ο διακομιστής απαριθμεί τις μεθόδους σύνδεσης που δέχεται. Ο φορητός προσφέρει το δημόσιο κλειδί της Alice, και ο διακομιστής λέει ότι θα το δεχόταν. Μετά ο φορητός υπογράφει αυτή τη συνεδρία με το ιδιωτικό κλειδί, που δεν φεύγει ποτέ από τον φορητό. Ο διακομιστής ελέγχει την υπογραφή με βάση το authorized_keys.",Methods:"Μέθοδοι",Key:"Κλειδί","Ed25519, private stays here":"Ed25519, το ιδιωτικό μένει εδώ","Checked with":"Ελέγχεται με","AUTH FAILURE":"ΑΠΟΤΥΧΙΑ AUTH","OFFER KEY":"ΠΡΟΣΦΟΡΑ ΚΛΕΙΔΙΟΥ","alice’s public key":"δημόσιο κλειδί της alice","would you accept it?":"θα το δεχόσουν;","yes, that key":"ναι, αυτό το κλειδί","is in authorized_keys":"είναι στο authorized_keys",SIGNED:"ΥΠΟΓΕΓΡΑΜΜΕΝΟ","same key, plus a signature":"ίδιο κλειδί, συν υπογραφή","made with the private key":"με το ιδιωτικό κλειδί",SUCCESS:"ΕΠΙΤΥΧΙΑ","logged in":"συνδέθηκε","Open a Session":"Άνοιγμα συνεδρίας","Channels inside one connection":"Κανάλια μέσα σε μία σύνδεση","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Μία σύνδεση SSH μπορεί να μεταφέρει πολλά κανάλια: ένα κέλυφος, μεταφορές αρχείων, προωθημένες θύρες. Ο φορητός ανοίγει ένα κανάλι συνεδρίας, μετά ζητά τερματικό και κέλυφος (δεν φαίνονται), και ο διακομιστής στέλνει το κείμενο υποδοχής και μια προτροπή.",Channel:"Κανάλι",session:"session","Then asks for":"Μετά ζητά","A terminal and a shell":"Τερματικό και κέλυφος","Also possible":"Επίσης δυνατά","SFTP, port forwarding":"SFTP, προώθηση θυρών","CHANNEL OPEN":"ΑΝΟΙΓΜΑ ΚΑΝΑΛΙΟΥ","open a channel:":"άνοιξε κανάλι:",CONFIRMED:"ΕΠΙΒΕΒΑΙΩΘΗΚΕ","channel open":"το κανάλι άνοιξε","Type a Command":"Πληκτρολόγηση εντολής","Every key is a packet":"Κάθε πλήκτρο είναι ένα πακέτο","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Η Alice πληκτρολογεί pwd. Κάθε πλήκτρο φεύγει αμέσως στο δικό του κρυπτογραφημένο πακέτο, και ο διακομιστής στέλνει πίσω τον χαρακτήρα για να εμφανιστεί (η ηχώ). Από την έκδοση 9.5, το OpenSSH στέλνει τα πλήκτρα σε ρυθμό 20 ms και προσθέτει δολώματα, ώστε ο ρυθμός πληκτρολόγησης να διαβάζεται δυσκολότερα από τους χρόνους.","Per key":"Ανά πλήκτρο","1 packet, 90 bytes":"1 πακέτο, 90 byte",Echo:"Ηχώ","Sent back by the server":"Στέλνεται πίσω από τον διακομιστή",Timing:"Χρονισμός","20 ms beat plus decoys":"Ρυθμός 20 ms συν δολώματα",ECHO:"ΗΧΩ",ENTER:"ENTER","Enter key":"Πλήκτρο Enter",OUTPUT:"ΕΞΟΔΟΣ","EACH KEY IS ITS OWN PACKET":"ΚΑΘΕ ΠΛΗΚΤΡΟ ΕΙΝΑΙ ΧΩΡΙΣΤΟ ΠΑΚΕΤΟ","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Πελάτης: KEX_ECDH_INIT (δημόσια κλειδιά sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Διακομιστής: KEX_ECDH_REPLY (κλειδί υπολογιστή, το μισό του, υπογραφή)","Encrypted (len=44): service request, ssh-userauth":"Κρυπτογραφημένο (len=44): αίτημα υπηρεσίας, ssh-userauth","Encrypted (len=44): service accept":"Κρυπτογραφημένο (len=44): η υπηρεσία έγινε δεκτή","Encrypted (len=68): login with method none":"Κρυπτογραφημένο (len=68): σύνδεση με μέθοδο none","Encrypted (len=52): try publickey,password":"Κρυπτογραφημένο (len=52): δοκιμάστε publickey,password","Encrypted (len=140): offer public key":"Κρυπτογραφημένο (len=140): προσφορά δημόσιου κλειδιού","Encrypted (len=100): public key OK":"Κρυπτογραφημένο (len=100): δημόσιο κλειδί OK","Encrypted (len=308): public key + signature":"Κρυπτογραφημένο (len=308): δημόσιο κλειδί + υπογραφή","Encrypted (len=28): login success":"Κρυπτογραφημένο (len=28): επιτυχής σύνδεση","Encrypted (len=52): channel open: session":"Κρυπτογραφημένο (len=52): άνοιγμα καναλιού: session","Encrypted (len=44): channel open confirmed":"Κρυπτογραφημένο (len=44): επιβεβαίωση ανοίγματος καναλιού","Encrypted (len=36): keystroke":"Κρυπτογραφημένο (len=36): πάτημα πλήκτρου","Encrypted (len=36): echo":"Κρυπτογραφημένο (len=36): ηχώ","Encrypted (len=36): keystroke (Enter)":"Κρυπτογραφημένο (len=36): πάτημα πλήκτρου (Enter)","Encrypted (len=132): output and a new prompt":"Κρυπτογραφημένο (len=132): έξοδος και νέα προτροπή","Packet length":"Μήκος πακέτου","Bytes after this field.":"Byte μετά από αυτό το πεδίο.","Padding length":"Μήκος συμπλήρωσης","Random padding brings the packet to a multiple of 8 bytes.":"Τυχαία συμπλήρωση φέρνει το πακέτο σε πολλαπλάσιο των 8 byte.",Cookie:"Cookie","Host keys":"Κλειδιά υπολογιστή","Ciphers, out":"Κρυπτοαλγόριθμοι, εξερχόμενα","Ciphers, in":"Κρυπτοαλγόριθμοι, εισερχόμενα","MACs, out":"MAC, εξερχόμενα","MACs, in":"MAC, εισερχόμενα","Compression, out":"Συμπίεση, εξερχόμενα","Compression, in":"Συμπίεση, εισερχόμενα","Languages, out":"Γλώσσες, εξερχόμενα","Languages, in":"Γλώσσες, εισερχόμενα","First packet follows":"Ακολουθεί το πρώτο πακέτο",Reserved:"Δεσμευμένο","Public keys":"Δημόσια κλειδιά","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 byte (sntrup761 1,158 + X25519 32)","51 bytes: ssh-ed25519 public key":"51 byte: δημόσιο κλειδί ssh-ed25519","Server’s half":"Το μισό του διακομιστή","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 byte (κρυπτοκείμενο sntrup761 1,039 + X25519 32)",Signature:"Υπογραφή","83 bytes: ssh-ed25519 signature over the exchange":"83 byte: υπογραφή ssh-ed25519 πάνω στην ανταλλαγή","From the next packet on, this side encrypts.":"Από το επόμενο πακέτο, αυτή η πλευρά κρυπτογραφεί.","SSH · encrypted packet":"SSH · κρυπτογραφημένο πακέτο","Encrypted packet":"Κρυπτογραφημένο πακέτο","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Με το chacha20-poly1305 κρυπτογραφείται ακόμη και το μήκος· μια ετικέτα 16 byte στο τέλος αποκαλύπτει κάθε αλλαγή.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): χρήστης «alice», υπηρεσία «ssh-connection», μέθοδος «none»","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): μέθοδοι για να συνεχίσετε: «publickey,password»","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): μέθοδος «publickey», χωρίς υπογραφή, το δημόσιο κλειδί ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): το ίδιο κλειδί ssh-ed25519","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): μέθοδος «publickey-hostbound-v00@openssh.com», το κλειδί, το κλειδί υπολογιστή του διακομιστή και μια υπογραφή","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): «session», κανάλι 0, παράθυρο 2 MB, πακέτα έως 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): το κανάλι 0 είναι ανοιχτό","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), κανάλι 0: 1 byte, «p»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), κανάλι 0: 1 byte, «p», στέλνεται πίσω για εμφάνιση","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), κανάλι 0: 1 byte, «w»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), κανάλι 0: 1 byte, «w», στέλνεται πίσω για εμφάνιση","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), κανάλι 0: 1 byte, «d»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), κανάλι 0: 1 byte, «d», στέλνεται πίσω για εμφάνιση","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), κανάλι 0: 1 byte, επαναφορά κεφαλής (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), κανάλι 0: 94 byte: νέα γραμμή, οι κωδικοί τερματικού του κελύφους, «/home/alice» και η έγχρωμη προτροπή","From browser":"Από τον browser","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"Το TLS βάζει ένα ασφαλές κανάλι πάνω από το TCP. Αποδεικνύει την ταυτότητα του διακομιστή με πιστοποιητικό, συμφωνεί νέα κλειδιά και μετά κρυπτογραφεί και πιστοποιεί ό,τι στέλνεται. Το HTTPS, το ασφαλές email και πολλά άλλα πρωτόκολλα λειτουργούν μέσα του. SSL ήταν το όνομα του προκατόχου του.",Sits:"Θέση","Between TCP and the app":"Ανάμεσα σε TCP και εφαρμογή","OSI layer":"Επίπεδο OSI","Often placed at 6":"Συχνά τοποθετείται στο 6",Current:"Τρέχουσα",Retired:"Αποσυρμένες","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 και 3, TLS 1.0 και 1.1","The app’s own (443, 993 …)":"Της εφαρμογής (443, 993 …)","Secure from start to finish":"Ασφαλές από την αρχή ως το τέλος","One round trip to set up":"Μία διαδρομή μετ’ επιστροφής για εγκατάσταση","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Μία διαδρομή μετ’ επιστροφής συμφώνησε έκδοση, κρυπτοαλγόριθμο και υβριδικό μετακβαντικό κλειδί. Η αλυσίδα πιστοποιητικών απέδειξε ποιος ήταν ο διακομιστής, και κάθε byte μετά το Server Hello κρυπτογραφήθηκε και πιστοποιήθηκε, μέχρι το close_notify. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","1 round trip":"1 διαδρομή μετ’ επιστροφής","Everything the browser supports":"Ό,τι υποστηρίζει ο browser","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Μετά τη χειραψία TCP ο browser απαριθμεί τι μπορεί να κάνει: εκδόσεις TLS, σουίτες κρυπτογράφησης και μερίδια κλειδιών για τις ομάδες που περιμένει, μαζί με το υβριδικό μετακβαντικό X25519MLKEM768. Δηλώνει επίσης τον ιστότοπο (SNI) και τα πρωτόκολλα που μιλά (ALPN).",Versions:"Εκδόσεις","versions, ciphers, key shares":"εκδόσεις, κρυπτοαλγόριθμοι, μερίδια κλειδιών","Choices made, keys computed":"Επιλογές έγιναν, κλειδιά υπολογίστηκαν","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Ο διακομιστής επιλέγει TLS 1.3, τη σουίτα κρυπτογράφησης και την υβριδική ομάδα, και στέλνει το δικό του μερίδιο κλειδιού. Από τα δύο μερίδια οι δύο πλευρές υπολογίζουν το ίδιο μυστικό χωρίς αυτό να περάσει ποτέ από το δίκτυο. Ό,τι ακολουθεί αυτό το μήνυμα είναι κρυπτογραφημένο.",Group:"Ομάδα","From here on":"Από εδώ και πέρα","its key share":"το μερίδιο κλειδιού του","SHARED SECRET COMPUTED":"ΤΟ ΚΟΙΝΟ ΜΥΣΤΙΚΟ ΥΠΟΛΟΓΙΣΤΗΚΕ",Certificate:"Πιστοποιητικό","Who the server is, proven":"Ποιος είναι ο διακομιστής, αποδεδειγμένα","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Πλέον κρυπτογραφημένη, η πτήση συνεχίζεται: το επιλεγμένο πρωτόκολλο (http/1.1), η αλυσίδα πιστοποιητικών, μια υπογραφή με το ιδιωτικό κλειδί του πιστοποιητικού και το Finished.",Chain:"Αλυσίδα","Site → intermediate → root":"Ιστότοπος → ενδιάμεσο → ρίζα","Proves the private key":"Αποδεικνύει το ιδιωτικό κλειδί",Checked:"Ελέγχεται","Name, dates, trusted root":"Όνομα, ημερομηνίες, έμπιστη ρίζα","encrypted: http/1.1, certificates,":"κρυπτογραφημένα: http/1.1, πιστοποιητικά,","signature, Finished":"υπογραφή, Finished","CHAIN LEADS TO A TRUSTED ROOT":"Η ΑΛΥΣΙΔΑ ΟΔΗΓΕΙ ΣΕ ΕΜΠΙΣΤΗ ΡΙΖΑ","One round trip, then data":"Μία διαδρομή μετ’ επιστροφής, μετά δεδομένα","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Ο browser στέλνει το δικό του Finished: μια τιμή ελέγχου πάνω σε όσα είπαν οι δύο πλευρές, με κλειδί το νέο μυστικό, ώστε κάθε αλλοίωση των χαιρετισμών να φανεί. Το TLS 1.3 θέλει μία διαδρομή μετ’ επιστροφής πριν ρέουν δεδομένα· το TLS 1.2 ήθελε δύο.",Covers:"Καλύπτει","The whole handshake":"Όλη τη χειραψία","For old middleboxes":"Για παλιές ενδιάμεσες συσκευές","check value over":"τιμή ελέγχου πάνω σε","the whole handshake":"όλη τη χειραψία","Encrypted Data":"Κρυπτογραφημένα δεδομένα","Records, tags and tickets":"Εγγραφές, ετικέτες και εισιτήρια","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"Το HTTP ταξιδεύει πλέον σε κρυπτογραφημένες εγγραφές, η καθεμιά με ετικέτα 16 byte που αποκαλύπτει κάθε αλλαγή. Ο διακομιστής στέλνει και δύο εισιτήρια συνεδρίας: την επόμενη φορά ο browser μπορεί να συνεχίσει με ένα από αυτά και να παραλείψει το πιστοποιητικό.","Per record":"Ανά εγγραφή","22 bytes of overhead":"22 byte επιβάρυνση","2, for resuming later":"2, για συνέχιση αργότερα",Visible:"Ορατά","IPs, SNI, sizes, timing":"IP, SNI, μεγέθη, χρονισμός","2 session tickets":"2 εισιτήρια συνεδρίας","for resuming later":"για συνέχιση αργότερα",Closing:"Κλείσιμο","close_notify, then TCP":"close_notify, μετά TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Μετά από 75 δευτερόλεπτα αδράνειας ο διακομιστής κλείνει τη σύνδεση. Πρώτα στέλνει ειδοποίηση close_notify, κρυπτογραφημένη όπως όλα τα άλλα, ώστε ο browser να ξέρει ότι τα δεδομένα τελείωσαν σκόπιμα και δεν κόπηκαν από επιτιθέμενο. Μετά το TCP κλείνει κανονικά.",Alert:"Ειδοποίηση",Why:"Γιατί","Shows nothing was cut off":"Δείχνει ότι τίποτα δεν κόπηκε","TCP FIN from both sides":"TCP FIN και από τις δύο πλευρές","alert: close_notify":"ειδοποίηση: close_notify",encrypted:"κρυπτογραφημένη","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ κρυπτογραφημένα)","Encrypted handshake (continued)":"Κρυπτογραφημένη χειραψία (συνέχεια)","Encrypted handshake (certificate, verify, Finished)":"Κρυπτογραφημένη χειραψία (πιστοποιητικό, επαλήθευση, Finished)","Application Data (inside: close_notify alert)":"Application Data (μέσα: ειδοποίηση close_notify)","Alert: close_notify (the data ends here, on purpose)":"Ειδοποίηση: close_notify (τα δεδομένα τελειώνουν εδώ, σκόπιμα)"},c={"Two-way web messaging":"Αμφίδρομα μηνύματα web","Browser video calls":"Βιντεοκλήσεις στον browser","HTTP/3 over UDP":"HTTP/3 πάνω από UDP","Routing between networks":"Δρομολόγηση μεταξύ δικτύων","Address setup, neighbour discovery":"Διευθύνσεις και εύρεση γειτόνων","Private DNS lookups":"Ιδιωτικές αναζητήσεις DNS","Signed DNS answers":"Υπογεγραμμένες απαντήσεις DNS","Network Time Protocol":"Network Time Protocol","Joining a network (WPA2)":"Σύνδεση σε δίκτυο (WPA2)","Wi-Fi Protected Access 3":"Wi-Fi Protected Access 3","802.1X Enterprise Wi-Fi":"Εταιρικό Wi-Fi με 802.1X","Hotel and café Wi-Fi logins":"Σύνδεση σε Wi-Fi ξενοδοχείων","Windows file sharing":"Κοινή χρήση αρχείων των Windows","Forward proxy and CONNECT":"Προωθητικό proxy και CONNECT","Socket Secure proxy":"Proxy Socket Secure","TLS offloading":"Αποφόρτιση TLS","A modern VPN":"Ένα σύγχρονο VPN","IKEv2 and ESP":"IKEv2 και ESP","Industrial control (OT)":"Βιομηχανικός έλεγχος (OT)",Proxy:"Proxy","App Server":"Διακομιστής εφαρμογής","File Server":"Διακομιστής αρχείων","ISP Router":"Δρομολογητής παρόχου","Transit Router":"Δρομολογητής διέλευσης","Hosting Router":"Δρομολογητής φιλοξενίας","Their Router":"Δρομολογητής του άλλου","Their Laptop":"Φορητός του άλλου",Transit:"Διέλευση",Hosting:"Φιλοξενία","The router itself.":"Ο ίδιος ο δρομολογητής.","Mail in Sync":"Συγχρονισμένη αλληλογραφία","Live Updates":"Ζωντανές ενημερώσεις","From the browser":"Από τον browser","From the server":"Από τον διακομιστή","The WebSocket Protocol":"The WebSocket Protocol","A WebSocket keeps one connection open between a web page and a server, so either side can send a message at any moment: chat, live scores, games, shared documents. It starts as an ordinary HTTP request asking to upgrade; after that, messages travel in small frames with a header of just a few bytes.":"Ένα WebSocket κρατά ανοιχτή μία σύνδεση ανάμεσα σε μια ιστοσελίδα και έναν διακομιστή, ώστε κάθε πλευρά να στέλνει μήνυμα οποιαδήποτε στιγμή: συνομιλίες, ζωντανά σκορ, παιχνίδια, κοινόχρηστα έγγραφα. Ξεκινά ως ένα συνηθισμένο αίτημα HTTP που ζητά αναβάθμιση· μετά τα μηνύματα ταξιδεύουν σε μικρά πλαίσια με κεφαλίδα λίγων byte.","80 (ws://), 443 (wss://)":"80 (ws://), 443 (wss://)","An HTTP request (Upgrade)":"Ένα αίτημα HTTP (Upgrade)","Frames both ways, any time":"Πλαίσια προς τις δύο πλευρές, ανά πάσα στιγμή","Frame header":"Κεφαλίδα πλαισίου","2–14 bytes":"2–14 byte","One request, then messages":"Ένα αίτημα, μετά μηνύματα","One HTTP request turned an ordinary TCP connection into a two-way channel. After that every message cost a few bytes of header, and the server could send whenever it had something to say. Press REPLAY to watch it again.":"Ένα αίτημα HTTP μετέτρεψε μια συνηθισμένη σύνδεση TCP σε κανάλι διπλής κατεύθυνσης. Από εκεί και πέρα κάθε μήνυμα κόστιζε λίγα byte κεφαλίδας, και ο διακομιστής μπορούσε να στέλνει όποτε είχε κάτι να πει. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","GET with Upgrade, then 101":"GET με Upgrade, μετά 101","Smallest frame":"Μικρότερο πλαίσιο","2 bytes (a ping)":"2 byte (ένα ping)","Server push":"Αποστολή από τον διακομιστή","Any time, unasked":"Ανά πάσα στιγμή, χωρίς αίτημα","Real sites":"Πραγματικοί ιστότοποι","wss:// (inside TLS)":"wss:// (μέσα σε TLS)","TCP to the server, as for HTTP":"TCP προς τον διακομιστή, όπως για HTTP",'The chat page is already open, loaded from www.example.com. Its script calls new WebSocket("ws://www.example.com/chat"), and the browser starts with an ordinary TCP connection to port 80. (Real sites use wss://, the same thing inside TLS; plain ws:// lets you read every byte.)':'Η σελίδα συνομιλίας είναι ήδη ανοιχτή, φορτωμένη από το www.example.com. Το script της καλεί new WebSocket("ws://www.example.com/chat"), και ο browser ξεκινά με μια συνηθισμένη σύνδεση TCP στη θύρα 80. (Οι πραγματικοί ιστότοποι χρησιμοποιούν wss://, το ίδιο μέσα σε TLS· το απλό ws:// σας αφήνει να διαβάσετε κάθε byte.)',"ws://www.example.com/chat":"ws://www.example.com/chat","Ask to Upgrade":"Αίτημα αναβάθμισης","An HTTP request with Upgrade: websocket":"Ένα αίτημα HTTP με Upgrade: websocket","The browser sends an HTTP GET with Upgrade: websocket and Connection: Upgrade. Sec-WebSocket-Key is 16 random bytes written in base64, which the server has to answer correctly. The browser also offers to compress messages (permessage-deflate).":"Ο browser στέλνει ένα HTTP GET με Upgrade: websocket και Connection: Upgrade. Το Sec-WebSocket-Key είναι 16 τυχαία byte γραμμένα σε base64, στα οποία ο διακομιστής πρέπει να απαντήσει σωστά. Ο browser προσφέρει επίσης συμπίεση μηνυμάτων (permessage-deflate).","Asks for":"Ζητά","16 random bytes, base64":"16 τυχαία byte, base64",UPGRADE:"UPGRADE","Switch Protocols":"Αλλαγή πρωτοκόλλου","101: from now on, WebSocket":"101: από εδώ και πέρα, WebSocket","The server answers 101 Switching Protocols. Its Sec-WebSocket-Accept is the key with a fixed string added, hashed with SHA-1 and written in base64: proof that it understood the request. It didn’t take up compression, so messages go as plain text. HTTP is finished on this connection; from now on both sides send WebSocket frames.":"Ο διακομιστής απαντά 101 Switching Protocols. Το Sec-WebSocket-Accept του είναι το κλειδί συν μια σταθερή συμβολοσειρά, κατακερματισμένο με SHA-1 και γραμμένο σε base64: απόδειξη ότι κατάλαβε το αίτημα. Δεν δέχτηκε τη συμπίεση, οπότε τα μηνύματα πηγαίνουν ως απλό κείμενο. Το HTTP τελείωσε σε αυτή τη σύνδεση· από εδώ και πέρα και οι δύο πλευρές στέλνουν πλαίσια WebSocket.",Accept:"Accept","SHA-1 of the key + a fixed string":"SHA-1 του κλειδιού + σταθερή συμβολοσειρά",Compression:"Συμπίεση","Offered, not taken":"Προσφέρθηκε, δεν έγινε δεκτή","NOW A WEBSOCKET":"ΤΩΡΑ ΕΙΝΑΙ WEBSOCKET","Small frames, from either side":"Μικρά πλαίσια, από κάθε πλευρά",'You send "Hello": a 2-byte header, a 4-byte masking key and the 5 masked bytes, 11 bytes in all instead of a whole HTTP request. Seconds later the server pushes Bob’s message without being asked: the connection is still open, so it can. Frames from the browser are always masked; frames from the server never are.':'Στέλνετε "Hello": κεφαλίδα 2 byte, κλειδί κάλυψης 4 byte και τα 5 καλυμμένα byte, 11 byte συνολικά αντί για ολόκληρο αίτημα HTTP. Δευτερόλεπτα αργότερα ο διακομιστής στέλνει χωρίς να του ζητηθεί το μήνυμα του Bob: η σύνδεση είναι ακόμη ανοιχτή, άρα μπορεί. Τα πλαίσια από τον browser καλύπτονται πάντα· από τον διακομιστή ποτέ.',"You send":"Στέλνετε","Server pushes":"Ο διακομιστής στέλνει",'"bob: hi there"':'"bob: hi there"',Masked:"Καλυμμένα","From the browser only":"Μόνο από τον browser",TEXT:"ΚΕΙΜΕΝΟ",masked:"καλυμμένο",unasked:"χωρίς αίτημα","Keeping It Alive":"Διατήρηση ζωντανής σύνδεσης","Ping and pong":"Ping και pong","After half a minute with nothing to say, the server sends a ping, so routers and firewalls on the way don’t forget the quiet connection. The browser answers with a pong on its own; the page’s script never sees either.":"Μετά από μισό λεπτό χωρίς τίποτα να πει, ο διακομιστής στέλνει ένα ping, ώστε δρομολογητές και τείχη προστασίας στη διαδρομή να μην ξεχάσουν την ήσυχη σύνδεση. Ο browser απαντά μόνος του με pong· το script της σελίδας δεν βλέπει κανένα από τα δύο.","Opcode 9, from either side":"Opcode 9, από κάθε πλευρά",Pong:"Pong","Opcode 10, by itself":"Opcode 10, αυτόματα","How often":"Πόσο συχνά","Up to the server (30 s)":"Το ορίζει ο διακομιστής (30 s)","A close frame each way":"Ένα πλαίσιο κλεισίματος προς κάθε κατεύθυνση","When you leave the chat, the page’s script closes the WebSocket with status 1000 (normal closure): the browser sends a close frame and the server answers with its own. Then the server closes the TCP connection. (Simply closing the tab would send 1001, going away.)":"Όταν φεύγετε από τη συνομιλία, το script της σελίδας κλείνει το WebSocket με κατάσταση 1000 (κανονικό κλείσιμο): ο browser στέλνει πλαίσιο κλεισίματος και ο διακομιστής απαντά με το δικό του. Μετά ο διακομιστής κλείνει τη σύνδεση TCP. (Αν απλώς κλείνατε την καρτέλα θα στελνόταν 1001, αποχώρηση.)",Opcode:"Opcode","8 (close)":"8 (κλείσιμο)","1000 (normal closure)":"1000 (κανονικό κλείσιμο)","TCP closes":"Το TCP κλείνει",CLOSE:"ΚΛΕΙΣΙΜΟ","1000 normal closure":"1000 κανονικό κλείσιμο","FIN 1: this frame is a whole message. The opcode says what it carries.":"FIN 1: αυτό το πλαίσιο είναι ολόκληρο μήνυμα. Το opcode λέει τι μεταφέρει.","Mask, length":"Κάλυψη, μήκος","Everything a browser sends is masked.":"Ό,τι στέλνει ένας browser καλύπτεται.","Masking key":"Κλειδί κάλυψης","Chosen at random for every frame.":"Επιλέγεται τυχαία για κάθε πλαίσιο.",Payload:"Φορτίο","Each byte XORed with the masking key in turn; the server XORs it back.":"Κάθε byte κάνει XOR με το κλειδί κάλυψης με τη σειρά· ο διακομιστής κάνει πάλι XOR.","A server never masks what it sends.":"Ένας διακομιστής δεν καλύπτει ποτέ ό,τι στέλνει.","Status code":"Κωδικός κατάστασης","Joining a Network":"Σύνδεση σε δίκτυο","From the access point":"Από το σημείο πρόσβασης","4-way handshake":"Χειραψία 4 βημάτων","Access Point":"Σημείο πρόσβασης","Wi-Fi (802.11) with WPA2":"Wi-Fi (802.11) με WPA2","Wi-Fi carries a network over radio. Before a device can send anything, it has to find the network, join it and prove it knows the password. With WPA2-Personal that proof is the 4-way handshake: four short messages that turn the password into fresh encryption keys, without the password ever going over the air.":"Το Wi-Fi μεταφέρει ένα δίκτυο μέσω ραδιοκυμάτων. Πριν στείλει οτιδήποτε, μια συσκευή πρέπει να βρει το δίκτυο, να ενταχθεί σε αυτό και να αποδείξει ότι ξέρει τον κωδικό. Στο WPA2-Personal αυτή η απόδειξη είναι η χειραψία 4 βημάτων: τέσσερα σύντομα μηνύματα που μετατρέπουν τον κωδικό σε νέα κλειδιά κρυπτογράφησης, χωρίς ο κωδικός να περάσει ποτέ στον αέρα.","Data Link (Layer 2)":"Ζεύξης δεδομένων (επίπεδο 2)",Standard:"Πρότυπο",Joining:"Ένταξη","Probe, authenticate, associate":"Probe, πιστοποίηση, συσχέτιση","Keys from":"Κλειδιά από","The 4-way handshake":"Τη χειραψία 4 βημάτων",Connected:"Συνδέθηκε","Eleven frames to a secure link":"Έντεκα πλαίσια ως μια ασφαλή ζεύξη","The laptop found the network, joined it with two formalities and proved it knew the password in a four-message handshake, without ever sending it. Everything after that was encrypted with keys made for this connection alone. Press REPLAY to watch it again.":"Ο φορητός βρήκε το δίκτυο, εντάχθηκε με δύο τυπικότητες και απέδειξε ότι ήξερε τον κωδικό σε χειραψία τεσσάρων μηνυμάτων, χωρίς να τον στείλει ποτέ. Ό,τι ακολούθησε κρυπτογραφήθηκε με κλειδιά φτιαγμένα μόνο για αυτή τη σύνδεση. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","Frames to join":"Πλαίσια για ένταξη","Password sent":"Κωδικός που στάλθηκε",Never:"Ποτέ","Session keys":"Κλειδιά συνεδρίας","New every time":"Νέα κάθε φορά",Next:"Επόμενο","DHCP, for an IP address":"DHCP, για διεύθυνση IP","Find the Network":"Εύρεση του δικτύου","A beacon, then a probe":"Ένα beacon, μετά ένα probe",'About ten times a second the router’s Wi-Fi sends a beacon: here is "HomeNet", protected with WPA2, on channel 36. The laptop could simply wait to hear one; to be quicker it also asks out loud with a probe request, and the access point answers with a probe response.':'Περίπου δέκα φορές το δευτερόλεπτο το Wi-Fi του δρομολογητή στέλνει ένα beacon: εδώ είναι το "HomeNet", προστατευμένο με WPA2, στο κανάλι 36. Ο φορητός θα μπορούσε απλώς να περιμένει να ακούσει ένα· για να είναι ταχύτερος ρωτά και φωναχτά με ένα probe request, και το σημείο πρόσβασης απαντά με probe response.',"WPA2-Personal (password)":"WPA2-Personal (κωδικός)",BEACON:"BEACON","WPA2 · channel 36":"WPA2 · κανάλι 36",PROBE:"PROBE","any networks here?":"υπάρχουν δίκτυα εδώ;","PROBE RESPONSE":"PROBE RESPONSE","Join the Network":"Ένταξη στο δίκτυο","Two formalities: hello, then join":"Δύο τυπικότητες: γεια, μετά ένταξη","Open System authentication lets anyone this far: no password yet. Then the laptop asks to associate, repeating the security it chose (CCMP, with a password), and the access point gives it association ID 1. The laptop is connected, but the only thing it may send is the handshake that comes next.":"Η πιστοποίηση Open System αφήνει οποιονδήποτε να φτάσει ως εδώ: ακόμη χωρίς κωδικό. Μετά ο φορητός ζητά συσχέτιση, επαναλαμβάνοντας την ασφάλεια που επέλεξε (CCMP, με κωδικό), και το σημείο πρόσβασης του δίνει αναγνωριστικό συσχέτισης 1. Ο φορητός είναι συνδεδεμένος, αλλά το μόνο που μπορεί να στείλει είναι η χειραψία που ακολουθεί.",Authentication:"Πιστοποίηση","Open System (no password)":"Open System (χωρίς κωδικό)","Association ID":"ID συσχέτισης","Allowed so far":"Επιτρέπεται ως τώρα",success:"επιτυχία",ASSOCIATE:"ΣΥΣΧΕΤΙΣΗ",'join "HomeNet"':'ένταξη στο "HomeNet"',"CCMP, password":"CCMP, κωδικός",ASSOCIATED:"ΣΥΣΧΕΤΙΣΤΗΚΕ","association ID 1":"ID συσχέτισης 1","Messages 1 and 2":"Μηνύματα 1 και 2","The 4-way handshake: nonces":"Η χειραψία 4 βημάτων: nonce","Both sides already hold the same key, worked out from the password and the network’s name (the PMK); it never goes over the air. The access point sends a random number, the ANonce. The laptop sends its own, the SNonce, with a check value (MIC). From the PMK, the two nonces and both MAC addresses, each side now works out the same session keys.":"Και οι δύο πλευρές έχουν ήδη το ίδιο κλειδί, υπολογισμένο από τον κωδικό και το όνομα του δικτύου (το PMK)· δεν περνά ποτέ στον αέρα. Το σημείο πρόσβασης στέλνει έναν τυχαίο αριθμό, το ANonce. Ο φορητός στέλνει τον δικό του, το SNonce, με μια τιμή ελέγχου (MIC). Από το PMK, τα δύο nonce και τις δύο διευθύνσεις MAC, κάθε πλευρά υπολογίζει τώρα τα ίδια κλειδιά συνεδρίας.","Shared key":"Κοινό κλειδί","PMK, from the password":"PMK, από τον κωδικό",Exchanged:"Ανταλλάσσονται","Two random nonces":"Δύο τυχαία nonce","Worked out":"Υπολογίζονται","Session keys (PTK)":"Κλειδιά συνεδρίας (PTK)","MESSAGE 1":"ΜΗΝΥΜΑ 1","MESSAGE 2":"ΜΗΝΥΜΑ 2","Messages 3 and 4":"Μηνύματα 3 και 4","The 4-way handshake: keys":"Η χειραψία 4 βημάτων: κλειδιά","Message 3 shows the access point has the same keys (its MIC checks out) and brings the group key (GTK) for broadcasts, encrypted. Message 4 says the laptop is ready, and both ends start encrypting.":"Το μήνυμα 3 δείχνει ότι το σημείο πρόσβασης έχει τα ίδια κλειδιά (το MIC του επαληθεύεται) και φέρνει το κλειδί ομάδας (GTK) για τις εκπομπές, κρυπτογραφημένο. Το μήνυμα 4 λέει ότι ο φορητός είναι έτοιμος, και τα δύο άκρα αρχίζουν να κρυπτογραφούν.","Group key":"Κλειδί ομάδας","GTK, sent encrypted":"GTK, στέλνεται κρυπτογραφημένο",Install:"Εγκατάσταση","Both ends at once":"Και τα δύο άκρα μαζί","MESSAGE 3":"ΜΗΝΥΜΑ 3","group key, encrypted":"κλειδί ομάδας, κρυπτογραφημένο","MESSAGE 4":"ΜΗΝΥΜΑ 4","keys installed":"τα κλειδιά εγκαταστάθηκαν","Encrypted Now":"Πλέον κρυπτογραφημένο","And what a listener could still do":"Και τι μπορεί ακόμη να κάνει ένας ωτακουστής","Every data frame is encrypted now, like this first one carrying a DHCP Discover: anyone nearby sees only the MAC addresses and the size. But someone who recorded the four handshake messages can try password guesses at home, as fast as their computer allows: a guess is right when it gives the same MIC. A long, random password makes that hopeless; WPA3 removes the weakness.":"Κάθε πλαίσιο δεδομένων είναι πλέον κρυπτογραφημένο, όπως αυτό το πρώτο που μεταφέρει ένα DHCP Discover: όποιος βρίσκεται κοντά βλέπει μόνο τις διευθύνσεις MAC και το μέγεθος. Όμως κάποιος που κατέγραψε τα τέσσερα μηνύματα της χειραψίας μπορεί να δοκιμάζει κωδικούς στο σπίτι, όσο γρήγορα του επιτρέπει ο υπολογιστής του: μια δοκιμή είναι σωστή όταν δίνει το ίδιο MIC. Ένας μακρύς, τυχαίος κωδικός το κάνει μάταιο· το WPA3 αφαιρεί την αδυναμία.","Others see":"Οι άλλοι βλέπουν","MAC addresses, sizes, timing":"Διευθύνσεις MAC, μεγέθη, χρονισμό","Weak point":"Αδύναμο σημείο","Offline password guessing":"Μαντεψιά κωδικού εκτός σύνδεσης",Defence:"Άμυνα","A long password, or WPA3":"Μακρύς κωδικός, ή WPA3","DHCP Discover inside":"Μέσα ένα DHCP Discover","ENCRYPTED FROM HERE ON":"ΚΡΥΠΤΟΓΡΑΦΗΜΕΝΟ ΑΠΟ ΕΔΩ ΚΑΙ ΠΕΡΑ","QoS Data (encrypted)":"QoS Data (κρυπτογραφημένο)","Seen over the air, on Wi-Fi channel 36":"Όπως φαίνεται στον αέρα, στο κανάλι Wi-Fi 36","Frame type":"Τύπος πλαισίου","Management, Beacon":"Διαχείριση, Beacon",Duration:"Διάρκεια","Nobody acknowledges a broadcast, so nothing is booked.":"Κανείς δεν επιβεβαιώνει μια εκπομπή, οπότε τίποτα δεν δεσμεύεται.",Receiver:"Παραλήπτης","Broadcast: every device in range listens.":"Εκπομπή: ακούει κάθε συσκευή στην εμβέλεια.",Transmitter:"Πομπός","The access point.":"Το σημείο πρόσβασης.","The access point’s own address: which network this is about.":"Η διεύθυνση του ίδιου του σημείου πρόσβασης: για ποιο δίκτυο πρόκειται.","Lets the receiver spot a repeat when a frame is sent again.":"Επιτρέπει στον παραλήπτη να εντοπίσει επανάληψη όταν ένα πλαίσιο ξαναστέλνεται.","The access point’s clock; devices on the network keep theirs in step with it.":"Το ρολόι του σημείου πρόσβασης· οι συσκευές του δικτύου συγχρονίζουν το δικό τους με αυτό.","Beacon interval":"Διάστημα beacon","A beacon goes out about ten times a second.":"Ένα beacon φεύγει περίπου δέκα φορές το δευτερόλεπτο.","0x0011: access point network, encrypted":"0x0011: δίκτυο με σημείο πρόσβασης, κρυπτογραφημένο","Privacy bit set: joining takes a key.":"Bit ιδιωτικότητας ενεργό: η ένταξη θέλει κλειδί.","The network’s name.":"Το όνομα του δικτύου.","Supported rates":"Υποστηριζόμενοι ρυθμοί","Only the oldest, slowest rates; the fast ones are in the elements that follow.":"Μόνο οι παλαιότεροι, πιο αργοί ρυθμοί· οι γρήγοροι είναι στα στοιχεία που ακολουθούν.","DTIM count 0, period 1":"Μετρητής DTIM 0, περίοδος 1","Tells sleeping devices whether frames are waiting for them.":"Λέει στις συσκευές σε αναμονή αν τις περιμένουν πλαίσια.","Robust Security Network: how this network is protected.":"Robust Security Network: πώς προστατεύεται αυτό το δίκτυο.","Element ID, length":"ID στοιχείου, μήκος","48, 20 bytes":"48, 20 byte","Group cipher":"Κρυπτογράφηση ομάδας","Encrypts broadcasts, which every device on the network can read.":"Κρυπτογραφεί τις εκπομπές, που μπορεί να διαβάσει κάθε συσκευή του δικτύου.","Pairwise cipher":"Κρυπτογράφηση ανά ζεύγος","Encrypts each device’s own traffic, with keys only it and the access point have.":"Κρυπτογραφεί τη δική της κίνηση κάθε συσκευής, με κλειδιά που έχουν μόνο αυτή και το σημείο πρόσβασης.","Key management":"Διαχείριση κλειδιών","1: PSK (a shared password)":"1: PSK (κοινός κωδικός)","More elements":"Περισσότερα στοιχεία","Wi-Fi 4, 5 and 6 capabilities and settings (HT, VHT, HE: channel 36, 80 MHz wide), and vendor extras.":"Δυνατότητες και ρυθμίσεις Wi-Fi 4, 5 και 6 (HT, VHT, HE: κανάλι 36, πλάτος 80 MHz) και πρόσθετα του κατασκευαστή.","Management, Probe Request":"Διαχείριση, Probe Request","The laptop’s Wi-Fi card.":"Η κάρτα Wi-Fi του φορητού.","empty (any network)":"κενό (οποιοδήποτε δίκτυο)","Any access point may answer. (Devices used to ask for every network they had joined by name, telling anyone listening where they had been.)":"Μπορεί να απαντήσει οποιοδήποτε σημείο πρόσβασης. (Παλιότερα οι συσκευές ρωτούσαν ονομαστικά για κάθε δίκτυο στο οποίο είχαν συνδεθεί, λέγοντας σε όποιον άκουγε πού είχαν βρεθεί.)","What the laptop’s radio can do: Wi-Fi 4, 5 and 6 capabilities, and vendor extras.":"Τι μπορεί να κάνει ο ασύρματος του φορητού: δυνατότητες Wi-Fi 4, 5 και 6 και πρόσθετα του κατασκευαστή.","Management, Probe Response":"Διαχείριση, Probe Response","How long the channel stays booked for this exchange; other devices wait.":"Πόσο μένει δεσμευμένο το κανάλι για αυτή την ανταλλαγή· οι άλλες συσκευές περιμένουν.","The radio this frame is for.":"Ο ασύρματος για τον οποίο προορίζεται το πλαίσιο.","Authentication · Open System":"Πιστοποίηση · Open System","Management, Authentication":"Διαχείριση, Authentication",Algorithm:"Αλγόριθμος","Open: anyone may get this far. The password is checked later, in the 4-way handshake.":"Open: οποιοσδήποτε μπορεί να φτάσει ως εδώ. Ο κωδικός ελέγχεται αργότερα, στη χειραψία 4 βημάτων.",Transaction:"Συναλλαγή","0 (success)":"0 (επιτυχία)","Management, Association Request":"Διαχείριση, Association Request","Listen interval":"Διάστημα ακρόασης","10 beacons":"10 beacon","How often the laptop wakes to check for waiting frames when saving power.":"Πόσο συχνά ξυπνά ο φορητός σε εξοικονόμηση ενέργειας για να ελέγξει για πλαίσια σε αναμονή.","What the laptop’s radio can do (Wi-Fi 4, 5 and 6), and vendor extras.":"Τι μπορεί να κάνει ο ασύρματος του φορητού (Wi-Fi 4, 5 και 6) και πρόσθετα του κατασκευαστή.","Management, Association Response":"Διαχείριση, Association Response","The laptop’s number at this access point (the top two bits are always set).":"Ο αριθμός του φορητού σε αυτό το σημείο πρόσβασης (τα δύο ανώτερα bit είναι πάντα ενεργά).","The settings the access point uses (Wi-Fi 4, 5 and 6), and vendor extras.":"Οι ρυθμίσεις που χρησιμοποιεί το σημείο πρόσβασης (Wi-Fi 4, 5 και 6) και πρόσθετα του κατασκευαστή.","Data, QoS Data":"Δεδομένα, QoS Data","0x02 (from the access point)":"0x02 (από το σημείο πρόσβασης)","Sent by the access point itself.":"Στάλθηκε από το ίδιο το σημείο πρόσβασης.","QoS control":"Έλεγχος QoS","Priority 7, the highest: the handshake goes first.":"Προτεραιότητα 7, η υψηλότερη: η χειραψία περνά πρώτη.",Organization:"Οργανισμός","0x888e (802.1X authentication)":"0x888e (πιστοποίηση 802.1X)","What follows: plays the part an Ethernet type field does on a cable.":"Τι ακολουθεί: παίζει τον ρόλο που έχει στο καλώδιο το πεδίο τύπου Ethernet.","Descriptor type":"Τύπος περιγραφέα","Key information":"Πληροφορίες κλειδιού","0x008a: pairwise, ACK":"0x008a: ανά ζεύγος, ACK","ACK: the laptop must answer.":"ACK: ο φορητός πρέπει να απαντήσει.","Key length":"Μήκος κλειδιού","The pairwise key is 16 bytes (AES-128).":"Το κλειδί ανά ζεύγος είναι 16 byte (AES-128).","Replay counter":"Μετρητής επανάληψης","Counts up with each message from the access point; an old one sent again is ignored.":"Αυξάνεται με κάθε μήνυμα από το σημείο πρόσβασης· ένα παλιό που ξαναστέλνεται αγνοείται.","A random number from the access point.":"Ένας τυχαίος αριθμός από το σημείο πρόσβασης.","Key IV":"IV κλειδιού",zeros:"μηδενικά","Key RSC":"RSC κλειδιού","No keys yet, so nothing to check with.":"Ακόμη κανένα κλειδί, άρα τίποτα για έλεγχο.","Key data length":"Μήκος δεδομένων κλειδιού","0x01 (to the access point)":"0x01 (προς το σημείο πρόσβασης)","The access point itself.":"Το ίδιο το σημείο πρόσβασης.","0x010a: pairwise, MIC":"0x010a: ανά ζεύγος, MIC","MIC: this message carries a check value.":"MIC: αυτό το μήνυμα φέρει τιμή ελέγχου.","A random number from the laptop. From both numbers, both MAC addresses and the key that comes from the password, each side works out the same session keys.":"Ένας τυχαίος αριθμός από τον φορητό. Από τους δύο αριθμούς, τις δύο διευθύνσεις MAC και το κλειδί που προκύπτει από τον κωδικό, κάθε πλευρά υπολογίζει τα ίδια κλειδιά συνεδρίας.","Worked out with the new keys: it proves the sender knows the password, and that the message wasn’t changed.":"Υπολογισμένο με τα νέα κλειδιά: αποδεικνύει ότι ο αποστολέας ξέρει τον κωδικό και ότι το μήνυμα δεν άλλαξε.","0x13ca: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13ca: ανά ζεύγος, εγκατάσταση, ACK, MIC, ασφαλές, κρυπτογραφημένα δεδομένα κλειδιού","Install: start using the keys. The group key comes encrypted.":"Εγκατάσταση: αρχίστε να χρησιμοποιείτε τα κλειδιά. Το κλειδί ομάδας έρχεται κρυπτογραφημένο.","Where the group key’s packet numbers start.":"Από πού ξεκινούν οι αριθμοί πακέτων του κλειδιού ομάδας.","Key data":"Δεδομένα κλειδιού","Encrypted with a key from the handshake.":"Κρυπτογραφημένα με κλειδί από τη χειραψία.","The access point’s RSN element":"Το στοιχείο RSN του σημείου πρόσβασης","GTK: the group key, for broadcasts":"GTK: το κλειδί ομάδας, για εκπομπές","0x030a: pairwise, MIC, secure":"0x030a: ανά ζεύγος, MIC, ασφαλές","Secure: the keys are in place.":"Ασφαλές: τα κλειδιά είναι στη θέση τους.","CCMP · encrypted":"CCMP · κρυπτογραφημένο","0x41 (protected, to the access point)":"0x41 (προστατευμένο, προς το σημείο πρόσβασης)","Protected: what follows the header is encrypted.":"Προστατευμένο: ό,τι ακολουθεί την κεφαλίδα είναι κρυπτογραφημένο.","Where the access point should pass it on to: everyone on the network.":"Σε ποιον να το προωθήσει το σημείο πρόσβασης: σε όλους στο δίκτυο.","CCMP header":"Κεφαλίδα CCMP","packet number 1, key 0":"αριθμός πακέτου 1, κλειδί 0","Counts up with every frame; one seen before is thrown away.":"Αυξάνεται με κάθε πλαίσιο· όποιο έχει ξαναφανεί πετιέται.","LLC/SNAP: an IPv4 packet":"LLC/SNAP: ένα πακέτο IPv4","Shows any change to the frame.":"Αποκαλύπτει κάθε αλλαγή στο πλαίσιο.","Safer Wi-Fi":"Ασφαλέστερο Wi-Fi","WPA3 is the current Wi-Fi security standard. Its Personal mode keeps the simple shared password but changes how it is checked: SAE, a password exchange that no recording can attack offline, gives every connection a fresh key. It also makes protected management frames compulsory.":"Το WPA3 είναι το τρέχον πρότυπο ασφάλειας Wi-Fi. Η λειτουργία Personal κρατά τον απλό κοινό κωδικό, αλλά αλλάζει τον τρόπο ελέγχου του: το SAE, μια ανταλλαγή κωδικού που καμία καταγραφή δεν μπορεί να επιτεθεί εκτός σύνδεσης, δίνει σε κάθε σύνδεση νέο κλειδί. Κάνει επίσης υποχρεωτικά τα προστατευμένα πλαίσια διαχείρισης.","Password check":"Έλεγχος κωδικού",Required:"Υποχρεωτικά","Protected management frames":"Προστατευμένα πλαίσια διαχείρισης",Since:"Από το","Connected with WPA3":"Συνδέθηκε με WPA3","Same password, better protocol":"Ίδιος κωδικός, καλύτερο πρωτόκολλο","The laptop and the access point proved to each other that they know the password without giving anyone a way to test guesses offline, then made fresh keys exactly as WPA2 does. Press REPLAY to watch it again.":"Ο φορητός και το σημείο πρόσβασης απέδειξαν το ένα στο άλλο ότι ξέρουν τον κωδικό χωρίς να δώσουν σε κανέναν τρόπο να δοκιμάζει μαντεψιές εκτός σύνδεσης, και μετά έφτιαξαν νέα κλειδιά ακριβώς όπως το WPA2. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","SAE frames":"Πλαίσια SAE","4 (commit, confirm)":"4 (commit, confirm)","4 EAPOL-Key frames":"4 πλαίσια EAPOL-Key","Offline guessing":"Μαντεψιά εκτός σύνδεσης","Not possible":"Αδύνατη","Forged disconnects":"Πλαστές αποσυνδέσεις",Ignored:"Αγνοούνται","A WPA3 Network":"Ένα δίκτυο WPA3","The beacon asks for SAE":"Το beacon ζητά SAE","The beacon looks like WPA2’s with two changes in its RSN element: the key management is SAE instead of PSK, and protected management frames are required. Everyone still uses one shared password.":"Το beacon μοιάζει με του WPA2 με δύο αλλαγές στο στοιχείο RSN: η διαχείριση κλειδιών είναι SAE αντί για PSK, και τα προστατευμένα πλαίσια διαχείρισης είναι υποχρεωτικά. Όλοι χρησιμοποιούν ακόμη έναν κοινό κωδικό.","Management frames":"Πλαίσια διαχείρισης","Protected (required)":"Προστατευμένα (υποχρεωτικά)","Still one for everyone":"Ακόμη ένας για όλους","SAE Commit":"SAE Commit","Each side commits to the password":"Κάθε πλευρά δεσμεύεται στον κωδικό","Instead of Open System authentication, the two sides run SAE, a password exchange between equals. Each picks a random secret and sends a scalar and an element worked out from that secret and the password. The password is the same on both sides, the secrets are not, so every connection ends up with a new key.":"Αντί για πιστοποίηση Open System, οι δύο πλευρές εκτελούν SAE, μια ανταλλαγή κωδικού μεταξύ ίσων. Η καθεμιά επιλέγει ένα τυχαίο μυστικό και στέλνει έναν βαθμωτό και ένα στοιχείο που προκύπτουν από αυτό το μυστικό και τον κωδικό. Ο κωδικός είναι ίδιος και στις δύο πλευρές, τα μυστικά όχι, οπότε κάθε σύνδεση καταλήγει σε νέο κλειδί.","19 (256-bit curve)":"19 (καμπύλη 256 bit)","Each sends":"Η καθεμιά στέλνει","A scalar and an element":"Έναν βαθμωτό και ένα στοιχείο",Replaces:"Αντικαθιστά","Open System authentication":"Την πιστοποίηση Open System",COMMIT:"COMMIT","scalar + element":"βαθμωτός + στοιχείο","SAE Confirm":"SAE Confirm","Proof, without the password":"Απόδειξη, χωρίς τον κωδικό","Each side now works out the shared key and sends a confirm, a value only someone with the right password could produce. Recording all four SAE frames doesn’t let an attacker test guesses at home: every guess takes a live exchange with the access point, which can slow them down or shut them out.":"Κάθε πλευρά υπολογίζει τώρα το κοινό κλειδί και στέλνει ένα confirm, μια τιμή που μόνο κάποιος με τον σωστό κωδικό θα μπορούσε να παραγάγει. Η καταγραφή και των τεσσάρων πλαισίων SAE δεν επιτρέπει σε επιτιθέμενο να δοκιμάζει μαντεψιές στο σπίτι: κάθε μαντεψιά θέλει ζωντανή ανταλλαγή με το σημείο πρόσβασης, που μπορεί να τον επιβραδύνει ή να τον αποκλείσει.","A new key (PMK) each time":"Νέο κλειδί (PMK) κάθε φορά",Guessing:"Μαντεψιά","Live only, never offline":"Μόνο ζωντανά, ποτέ εκτός σύνδεσης","Password leaks":"Διαρροή κωδικού","Past traffic stays safe":"Η παλιά κίνηση μένει ασφαλής",CONFIRM:"CONFIRM","proof of the key":"απόδειξη του κλειδιού","Join, Handshake":"Ένταξη, χειραψία","Then the 4-way handshake, as in WPA2":"Μετά η χειραψία 4 βημάτων, όπως στο WPA2","Association works as before, repeating the choice of SAE. The 4-way handshake that follows is WPA2’s, starting from the key SAE just made, except that message 3 also brings the IGTK, a key that signs broadcast management frames.":"Η συσχέτιση λειτουργεί όπως πριν, επαναλαμβάνοντας την επιλογή του SAE. Η χειραψία 4 βημάτων που ακολουθεί είναι του WPA2, ξεκινώντας από το κλειδί που μόλις έφτιαξε το SAE, με τη διαφορά ότι το μήνυμα 3 φέρνει και το IGTK, ένα κλειδί που υπογράφει τα πλαίσια διαχείρισης εκπομπής.","Message 3 adds":"Το μήνυμα 3 προσθέτει","Why It’s Safer":"Γιατί είναι ασφαλέστερο","Forged disconnects stop working":"Οι πλαστές αποσυνδέσεις σταματούν να λειτουργούν","With WPA2, anyone in range could forge a “disconnect” frame and knock a device off the network, often to record its handshake when it joined again. WPA3 requires protected management frames, so forged disconnects are ignored. Many routers also offer a transition mode that lets WPA2 devices join too; those devices keep WPA2’s weaknesses.":"Με το WPA2 οποιοσδήποτε στην εμβέλεια μπορούσε να πλαστογραφήσει ένα πλαίσιο «αποσύνδεσης» και να πετάξει μια συσκευή από το δίκτυο, συχνά για να καταγράψει τη χειραψία της όταν ξαναμπεί. Το WPA3 απαιτεί προστατευμένα πλαίσια διαχείρισης, οπότε οι πλαστές αποσυνδέσεις αγνοούνται. Πολλοί δρομολογητές προσφέρουν και μεταβατική λειτουργία που αφήνει να μπαίνουν και συσκευές WPA2· αυτές οι συσκευές κρατούν τις αδυναμίες του WPA2.",Protected:"Προστατευμένα","Disconnects, other management":"Αποσυνδέσεις, άλλη διαχείριση","WPA2/3 mode":"Λειτουργία WPA2/3","WPA2 devices stay at risk":"Οι συσκευές WPA2 μένουν εκτεθειμένες","Stronger still":"Ακόμη ισχυρότερο","WPA3-Enterprise (192-bit)":"WPA3-Enterprise (192 bit)","MANAGEMENT FRAMES PROTECTED":"ΠΡΟΣΤΑΤΕΥΜΕΝΑ ΠΛΑΙΣΙΑ ΔΙΑΧΕΙΡΙΣΗΣ","0x00c0: management frame protection required":"0x00c0: υποχρεωτική προστασία πλαισίων διαχείρισης","Disconnect messages and other management frames are signed, so they can’t be forged.":"Τα μηνύματα αποσύνδεσης και τα άλλα πλαίσια διαχείρισης είναι υπογεγραμμένα, οπότε δεν πλαστογραφούνται.","Authentication · SAE Commit":"Πιστοποίηση · SAE Commit","Simultaneous Authentication of Equals: WPA3’s password exchange.":"Simultaneous Authentication of Equals: η ανταλλαγή κωδικού του WPA3.","19 (256-bit elliptic curve)":"19 (ελλειπτική καμπύλη 256 bit)",Scalar:"Βαθμωτός","Worked out from a random secret and the password.":"Προκύπτει από ένα τυχαίο μυστικό και τον κωδικό.",Element:"Στοιχείο","A point on the curve, also tied to the password. Recording the scalar and element doesn’t let anyone test password guesses afterwards.":"Ένα σημείο στην καμπύλη, επίσης δεμένο με τον κωδικό. Η καταγραφή του βαθμωτού και του στοιχείου δεν επιτρέπει σε κανέναν να δοκιμάσει αργότερα μαντεψιές κωδικού.","Authentication · SAE Confirm":"Πιστοποίηση · SAE Confirm","Proves this side worked out the same key, without giving it away.":"Αποδεικνύει ότι αυτή η πλευρά υπολόγισε το ίδιο κλειδί, χωρίς να το αποκαλύψει.","0x0088: pairwise, ACK":"0x0088: ανά ζεύγος, ACK","0x0108: pairwise, MIC":"0x0108: ανά ζεύγος, MIC","0x13c8: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13c8: ανά ζεύγος, εγκατάσταση, ACK, MIC, ασφαλές, κρυπτογραφημένα δεδομένα κλειδιού","IGTK: the key that signs broadcast management frames":"IGTK: το κλειδί που υπογράφει τα πλαίσια διαχείρισης εκπομπής","0x0308: pairwise, MIC, secure":"0x0308: ανά ζεύγος, MIC, ασφαλές","Sign-In":"Σύνδεση","From the router":"Από τον δρομολογητή","From the test server":"Από τον διακομιστή ελέγχου","Hotel Router":"Δρομολογητής ξενοδοχείου","192.168.1.1 · captive portal":"192.168.1.1 · captive portal","Wi-Fi login pages":"Σελίδες σύνδεσης Wi-Fi","Hotels, cafés, airports and trains often put a login page in front of their Wi-Fi. Until you accept the terms (or pay), the router lets nothing out to the internet. It catches your device’s first plain HTTP request and answers it with a redirect to its own page; your device notices because a test page it knows comes back wrong.":"Ξενοδοχεία, καφέ, αεροδρόμια και τρένα βάζουν συχνά μια σελίδα σύνδεσης μπροστά από το Wi-Fi τους. Μέχρι να αποδεχτείτε τους όρους (ή να πληρώσετε), ο δρομολογητής δεν αφήνει τίποτα να βγει στο Διαδίκτυο. Πιάνει το πρώτο απλό αίτημα HTTP της συσκευής σας και απαντά με ανακατεύθυνση στη δική του σελίδα· η συσκευή σας το καταλαβαίνει επειδή μια σελίδα ελέγχου που ξέρει επιστρέφει λάθος.",Where:"Πού","Hotels, cafés, airports":"Ξενοδοχεία, καφέ, αεροδρόμια",How:"Πώς","Catches plain HTTP requests":"Πιάνει απλά αιτήματα HTTP","Noticed by":"Εντοπίζεται από","Your system’s test page":"Τη σελίδα ελέγχου του συστήματος","Logging in":"Σύνδεση","Lets your MAC address through":"Αφήνει να περάσει η MAC σας","Newer way":"Νεότερος τρόπος","DHCP option 114 (RFC 8910)":"Επιλογή DHCP 114 (RFC 8910)","Described In":"Περιγράφεται στο",Online:"Σε σύνδεση","Noticed, logged in, let through":"Εντοπίστηκε, συνδέθηκε, πέρασε","Windows asked a test page for an answer it knows and got a redirect instead, so it knew a portal was in the way and opened the login page. Once the terms were accepted, the router let the laptop through, and the same check came back right. Press REPLAY to watch it again.":"Τα Windows ζήτησαν από μια σελίδα ελέγχου μια απάντηση που ξέρουν και πήραν αντί γι’ αυτό ανακατεύθυνση, οπότε κατάλαβαν ότι παρεμβαλλόταν portal και άνοιξαν τη σελίδα σύνδεσης. Μόλις έγιναν δεκτοί οι όροι, ο δρομολογητής άφησε τον φορητό να περάσει, και ο ίδιος έλεγχος βγήκε σωστός. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","A plain HTTP test page":"Μια απλή σελίδα ελέγχου HTTP","Faked by":"Πλαστογραφείται από","The router (TTL 64)":"Τον δρομολογητή (TTL 64)","Let through":"Περνά","The laptop’s MAC address":"Η MAC του φορητού","Open Wi-Fi":"Ανοιχτό Wi-Fi","Use HTTPS, or a VPN":"Χρησιμοποιήστε HTTPS ή VPN","Joined, Offline":"Συνδεδεμένος, εκτός Διαδικτύου","An address, but no way out":"Διεύθυνση, αλλά καμία έξοδος","The laptop has joined the hotel’s Wi-Fi, which has no password, and got an address from the router by DHCP. The router answers the laptop itself and passes on its DNS lookups, but drops anything else bound for the internet until the guest has logged in. (An open network also means anyone nearby can read whatever isn’t protected by HTTPS.)":"Ο φορητός μπήκε στο Wi-Fi του ξενοδοχείου, που δεν έχει κωδικό, και πήρε διεύθυνση από τον δρομολογητή μέσω DHCP. Ο δρομολογητής απαντά στον ίδιο τον φορητό και προωθεί τις αναζητήσεις DNS του, αλλά πετά οτιδήποτε άλλο προς το Διαδίκτυο μέχρι να συνδεθεί ο επισκέπτης. (Ένα ανοιχτό δίκτυο σημαίνει επίσης ότι όποιος βρίσκεται κοντά μπορεί να διαβάσει ό,τι δεν προστατεύεται από HTTPS.)","192.168.1.10 (by DHCP)":"192.168.1.10 (μέσω DHCP)","Wi-Fi password":"Κωδικός Wi-Fi","None (open network)":"Κανένας (ανοιχτό δίκτυο)","Blocked until you log in":"Μπλοκαρισμένο μέχρι τη σύνδεση","CONNECTED, NO INTERNET YET":"ΣΥΝΔΕΔΕΜΕΝΟΣ, ΑΚΟΜΗ ΧΩΡΙΣ ΔΙΑΔΙΚΤΥΟ","Internet Check":"Έλεγχος Διαδικτύου","Windows checks a test page":"Τα Windows ελέγχουν μια σελίδα δοκιμής",'After joining any network, Windows looks up www.msftconnecttest.com (the router passes the lookup on) and asks it for /connecttest.txt over plain HTTP; the right answer is the text "Microsoft Connect Test". The router catches the connection and answers the handshake itself, in the test server’s name. The laptop can’t tell yet.':'Μετά την ένταξη σε οποιοδήποτε δίκτυο, τα Windows αναζητούν το www.msftconnecttest.com (ο δρομολογητής προωθεί την αναζήτηση) και του ζητούν το /connecttest.txt μέσω απλού HTTP· η σωστή απάντηση είναι το κείμενο "Microsoft Connect Test". Ο δρομολογητής πιάνει τη σύνδεση και απαντά μόνος του στη χειραψία, στο όνομα του διακομιστή δοκιμής. Ο φορητός δεν το καταλαβαίνει ακόμη.',"Test page":"Σελίδα δοκιμής","msftconnecttest.com/connecttest.txt":"msftconnecttest.com/connecttest.txt",Expected:"Αναμενόμενο","Answered by":"Απαντά","The router, posing as the server":"Ο δρομολογητής, παριστάνοντας τον διακομιστή",'from "203.0.113.30"':'από "203.0.113.30"',"/connecttest.txt":"/connecttest.txt",Redirected:"Ανακατεύθυνση","The wrong answer gives it away":"Η λάθος απάντηση τον προδίδει",'Instead of the test text, the "server" answers 302 Found, pointing to the router’s login page. Its TTL is 64, not lowered at all, because it came straight from the router. Windows sees the wrong answer, marks the network as needing action and opens the browser, whose first request the router redirects the same way, to its login page. This only works with plain HTTP: the router can’t fake an HTTPS page without a certificate error.':"Αντί για το κείμενο δοκιμής, ο «διακομιστής» απαντά 302 Found, δείχνοντας τη σελίδα σύνδεσης του δρομολογητή. Το TTL του είναι 64, καθόλου μειωμένο, γιατί ήρθε κατευθείαν από τον δρομολογητή. Τα Windows βλέπουν τη λάθος απάντηση, σημειώνουν ότι το δίκτυο χρειάζεται ενέργεια και ανοίγουν τον browser, του οποίου το πρώτο αίτημα ο δρομολογητής ανακατευθύνει με τον ίδιο τρόπο, στη σελίδα σύνδεσης. Αυτό λειτουργεί μόνο με απλό HTTP: ο δρομολογητής δεν μπορεί να πλαστογραφήσει σελίδα HTTPS χωρίς σφάλμα πιστοποιητικού.","302 → 192.168.1.1/login":"302 → 192.168.1.1/login","Give-away":"Τον προδίδει","TTL 64, from one hop away":"TTL 64, από ένα βήμα μακριά","Why HTTP":"Γιατί HTTP","HTTPS can’t be faked":"Το HTTPS δεν πλαστογραφείται","302 FOUND":"302 FOUND","ACTION NEEDED":"ΑΠΑΙΤΕΙΤΑΙ ΕΝΕΡΓΕΙΑ","The Login Page":"Η σελίδα σύνδεσης","Served by the router itself":"Την εξυπηρετεί ο ίδιος ο δρομολογητής","The browser opens http://192.168.1.1/login, a page the router serves itself: the hotel’s name, the terms of use and an Accept button. This connection really does go to the router.":"Ο browser ανοίγει το http://192.168.1.1/login, μια σελίδα που εξυπηρετεί ο ίδιος ο δρομολογητής: το όνομα του ξενοδοχείου, οι όροι χρήσης και ένα κουμπί Αποδοχή. Αυτή η σύνδεση πηγαίνει πράγματι στον δρομολογητή.",Page:"Σελίδα","http://192.168.1.1/login":"http://192.168.1.1/login","Served by":"Εξυπηρετείται από","The router":"Τον δρομολογητή",Size:"Μέγεθος","2,400 bytes of HTML":"2,400 byte HTML","/login":"/login","the login page":"η σελίδα σύνδεσης","Accept the Terms":"Αποδοχή όρων","The router lets the laptop out":"Ο δρομολογητής αφήνει τον φορητό να βγει","Clicking Accept posts a small form back to the router. It adds the laptop’s MAC address to the list of devices allowed out, often for the length of the stay, and redirects the browser on its way.":"Το κλικ στην Αποδοχή στέλνει μια μικρή φόρμα στον δρομολογητή. Αυτός προσθέτει τη διεύθυνση MAC του φορητού στη λίστα των συσκευών που επιτρέπεται να βγουν, συχνά για όλη τη διαμονή, και στέλνει τον browser εκεί που πήγαινε.",Form:"Φόρμα","terms=accepted":"terms=accepted","Router allows":"Ο δρομολογητής επιτρέπει","302 to where you were going":"302 προς εκεί που πηγαίνατε","you’re online":"είστε συνδεδεμένοι","MAC ADDRESS ALLOWED":"Η ΔΙΕΥΘΥΝΣΗ MAC ΕΠΙΤΡΕΠΕΤΑΙ","The same check, now real":"Ο ίδιος έλεγχος, τώρα αληθινός","Windows checks again. This time the router lets the connection through to the real test server, twelve routers away (its replies arrive with TTL 52), and the answer is the expected text. The network is marked as connected to the internet.":"Τα Windows ελέγχουν ξανά. Αυτή τη φορά ο δρομολογητής αφήνει τη σύνδεση να φτάσει στον πραγματικό διακομιστή δοκιμής, δώδεκα δρομολογητές μακριά (οι απαντήσεις του φτάνουν με TTL 52), και η απάντηση είναι το αναμενόμενο κείμενο. Το δίκτυο σημειώνεται ως συνδεδεμένο στο Διαδίκτυο.","Connected to the internet":"Συνδεδεμένο στο Διαδίκτυο",ONLINE:"ΣΕ ΣΥΝΔΕΣΗ","www.msftconnecttest.com, type A, class IN":"www.msftconnecttest.com, τύπος A, κλάση IN","www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)":"www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)","Sent with 64 and not lowered at all: it came from the router next door, not from a server 12 routers away.":"Στάλθηκε με 64 και καθόλου μειωμένο: ήρθε από τον διπλανό δρομολογητή, όχι από διακομιστή 12 δρομολογητές μακριά.","2,400 bytes: the login page":"2,400 byte: η σελίδα σύνδεσης","Via a Proxy":"Μέσω proxy","TLS, through the tunnel":"TLS, μέσα από το τούνελ","Forward proxy, and CONNECT for HTTPS":"Προωθητικό proxy, και CONNECT για HTTPS","A forward proxy fetches web pages on your behalf. Companies and schools use one to filter sites, keep copies of popular pages and log what goes out; the sites you visit see the proxy, not you. Plain HTTP passes through it in the clear. For HTTPS the browser asks the proxy for a tunnel, and the encrypted connection runs through it unread.":"Ένα προωθητικό proxy φέρνει ιστοσελίδες για λογαριασμό σας. Εταιρείες και σχολεία το χρησιμοποιούν για να φιλτράρουν ιστότοπους, να κρατούν αντίγραφα δημοφιλών σελίδων και να καταγράφουν ό,τι βγαίνει· οι ιστότοποι που επισκέπτεστε βλέπουν το proxy, όχι εσάς. Το απλό HTTP περνά από μέσα του αναγνώσιμο. Για HTTPS ο browser ζητά από το proxy ένα τούνελ, και η κρυπτογραφημένη σύνδεση περνά από μέσα του χωρίς να διαβαστεί.","Common ports":"Συνήθεις θύρες","http:// pages":"Σελίδες http://","Fetched by the proxy":"Τις φέρνει το proxy","https:// pages":"Σελίδες https://","Tunnelled with CONNECT":"Σε τούνελ με CONNECT","Used for":"Χρησιμοποιείται για","Filtering, caching, logging":"Φιλτράρισμα, cache, καταγραφή","Two ways through":"Δύο τρόποι να περάσει","Fetched for you, or tunnelled":"Το φέρνει για εσάς, ή σε τούνελ","For the plain page, the proxy did the work: it read the request, fetched the page on its own connection and could have kept, changed or refused it. For HTTPS it only opened a tunnel and copied encrypted bytes, knowing nothing but the site’s name. Press REPLAY to watch it again.":"Για την απλή σελίδα τη δουλειά την έκανε το proxy: διάβασε το αίτημα, έφερε τη σελίδα με δική του σύνδεση και θα μπορούσε να την κρατήσει, να την αλλάξει ή να την αρνηθεί. Για το HTTPS απλώς άνοιξε ένα τούνελ και αντέγραφε κρυπτογραφημένα byte, χωρίς να ξέρει τίποτα πέρα από το όνομα του ιστότοπου. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","Server sees":"Ο διακομιστής βλέπει","The proxy (192.0.2.80)":"Το proxy (192.0.2.80)","Plain HTTP":"Απλό HTTP","The proxy reads it all":"Το proxy τα διαβάζει όλα","Name and sizes only":"Μόνο όνομα και μεγέθη","DNS for the site":"DNS για τον ιστότοπο","Done by the proxy":"Το κάνει το proxy","Proxy Settings":"Ρυθμίσεις proxy","The browser sends everything there":"Ο browser στέλνει τα πάντα εκεί","The browser is set to send everything through a proxy at 192.0.2.80, port 8080, as many companies and schools require. You open http://www.example.com. The browser doesn’t look up www.example.com itself: it connects to the proxy and leaves the rest to it.":"Ο browser είναι ρυθμισμένος να στέλνει τα πάντα μέσω proxy στο 192.0.2.80, θύρα 8080, όπως απαιτούν πολλές εταιρείες και σχολεία. Ανοίγετε το http://www.example.com. Ο browser δεν αναζητά μόνος του το www.example.com: συνδέεται στο proxy και του αφήνει τα υπόλοιπα.","Left to the proxy":"Αφήνεται στο proxy","To the Proxy":"Προς το proxy","TCP to port 8080":"TCP στη θύρα 8080","The laptop opens an ordinary TCP connection, not to the website, but to the proxy’s port 8080.":"Ο φορητός ανοίγει μια συνηθισμένη σύνδεση TCP, όχι προς τον ιστότοπο, αλλά προς τη θύρα 8080 του proxy.","192.0.2.80, port 8080":"192.0.2.80, θύρα 8080","Not to":"Όχι προς","The Whole URL":"Ολόκληρο το URL","Sent to a proxy, the request line carries the whole address, not just the path: GET http://www.example.com/ HTTP/1.1. That is how the proxy knows where to go. Chrome adds Proxy-Connection: keep-alive, a header only proxies read.":"Όταν στέλνεται σε proxy, η γραμμή αιτήματος φέρει ολόκληρη τη διεύθυνση, όχι μόνο τη διαδρομή: GET http://www.example.com/ HTTP/1.1. Έτσι ξέρει το proxy πού να πάει. Το Chrome προσθέτει Proxy-Connection: keep-alive, μια κεφαλίδα που διαβάζουν μόνο τα proxy.","Request line":"Γραμμή αιτήματος","To a server":"Προς διακομιστή","Readable by":"Αναγνώσιμο από","The proxy (plain HTTP)":"Το proxy (απλό HTTP)","to the proxy":"προς το proxy","Proxy Fetches It":"Το proxy το φέρνει","Its own connection to the server":"Δική του σύνδεση με τον διακομιστή","The proxy looks up www.example.com itself (not shown) and opens its own connection to the server. Its request is the ordinary kind, GET /, with headers of its own: Via names the proxy, and X-Forwarded-For gives the address the request came from (the home router’s public address, since the laptop is behind NAT).":"Το proxy αναζητά μόνο του το www.example.com (δεν φαίνεται) και ανοίγει δική του σύνδεση με τον διακομιστή. Το αίτημά του είναι συνηθισμένο, GET /, με δικές του κεφαλίδες: το Via κατονομάζει το proxy, και το X-Forwarded-For δίνει τη διεύθυνση από την οποία ήρθε το αίτημα (τη δημόσια διεύθυνση του οικιακού δρομολογητή, αφού ο φορητός είναι πίσω από NAT).","The proxy’s own":"Του proxy","1.1 proxy.example.net":"1.1 proxy.example.net","Forwarded for":"Προωθήθηκε για","Page Passed On":"Η σελίδα προωθήθηκε","The page, passed on":"Η σελίδα, προωθημένη","The server answers the proxy, and the proxy passes the page on to the laptop with a Via header of its own. It could keep a copy and give it to the next person who asks without troubling the server (X-Cache: MISS says it had none yet), and it can refuse sites that aren’t allowed.":"Ο διακομιστής απαντά στο proxy, και το proxy προωθεί τη σελίδα στον φορητό με δική του κεφαλίδα Via. Θα μπορούσε να κρατήσει αντίγραφο και να το δώσει στον επόμενο που θα το ζητήσει χωρίς να ενοχλήσει τον διακομιστή (το X-Cache: MISS λέει ότι δεν είχε ακόμη), και μπορεί να αρνείται ιστότοπους που δεν επιτρέπονται.","The proxy, not the laptop":"Το proxy, όχι ο φορητός",Cache:"Cache","MISS (first request)":"MISS (πρώτο αίτημα)","Proxy can":"Το proxy μπορεί","Cache, filter, log, change":"Cache, φιλτράρισμα, καταγραφή, αλλαγή","CONNECT www.example.com:443":"CONNECT www.example.com:443","Now you open https://www.example.com. A proxy can’t fetch an HTTPS page for you without breaking its encryption, so the browser asks for a tunnel instead: CONNECT www.example.com:443. The proxy opens a TCP connection to port 443 and answers 200 Connection established.":"Τώρα ανοίγετε το https://www.example.com. Ένα proxy δεν μπορεί να σας φέρει σελίδα HTTPS χωρίς να σπάσει την κρυπτογράφησή της, οπότε ο browser ζητά αντί γι’ αυτό ένα τούνελ: CONNECT www.example.com:443. Το proxy ανοίγει σύνδεση TCP στη θύρα 443 και απαντά 200 Connection established.","Proxy opens":"Το proxy ανοίγει","TCP to port 443":"TCP στη θύρα 443","200 Connection established":"200 Connection established","Connection established":"Η σύνδεση δημιουργήθηκε","In the Tunnel":"Μέσα στο τούνελ","The proxy copies, unread":"Το proxy αντιγράφει, χωρίς να διαβάζει","From now on the proxy copies bytes both ways without reading them. The browser’s TLS Client Hello goes in on the laptop’s connection and comes out, byte for byte the same, on the proxy’s connection to the server. TLS runs from end to end, so the proxy learns the site’s name and the sizes, never the pages. (Some company proxies do open HTTPS, using a certificate authority installed on every company laptop; then they see everything.)":"Από εδώ και πέρα το proxy αντιγράφει byte και προς τις δύο κατευθύνσεις χωρίς να τα διαβάζει. Το TLS Client Hello του browser μπαίνει από τη σύνδεση του φορητού και βγαίνει, ίδιο byte προς byte, από τη σύνδεση του proxy με τον διακομιστή. Το TLS πηγαίνει από άκρη σε άκρη, οπότε το proxy μαθαίνει το όνομα του ιστότοπου και τα μεγέθη, ποτέ τις σελίδες. (Κάποια εταιρικά proxy ανοίγουν όντως το HTTPS, με μια αρχή πιστοποίησης εγκατεστημένη σε κάθε εταιρικό φορητό· τότε βλέπουν τα πάντα.)","Proxy sees":"Το proxy βλέπει","Site name, sizes, timing":"Όνομα ιστότοπου, μεγέθη, χρονισμό","Hidden from it":"Κρυφά από αυτό","Pages, passwords, cookies":"Σελίδες, κωδικοί, cookies","TLS, laptop to server":"TLS, από φορητό σε διακομιστή","the same bytes":"τα ίδια byte","COPIES BYTES, CAN’T READ THEM":"ΑΝΤΙΓΡΑΦΕΙ BYTE, ΔΕΝ ΤΑ ΔΙΑΒΑΖΕΙ","Any Connection":"Οποιαδήποτε σύνδεση","From the proxy":"Από το proxy","SOCKS Proxy":"Proxy SOCKS","Socket Secure, version 5":"Socket Secure, έκδοση 5","SOCKS is a general-purpose proxy. Where an HTTP proxy understands web requests, a SOCKS proxy simply opens a connection on your behalf and copies the bytes, whatever the protocol: web, email, games, SSH. Apps use it to reach a network through one gateway, or to hide their own address; ssh -D and Tor both offer one.":"Το SOCKS είναι ένα proxy γενικής χρήσης. Ενώ ένα proxy HTTP καταλαβαίνει αιτήματα web, ένα proxy SOCKS απλώς ανοίγει μια σύνδεση για λογαριασμό σας και αντιγράφει τα byte, όποιο κι αν είναι το πρωτόκολλο: web, email, παιχνίδια, SSH. Οι εφαρμογές το χρησιμοποιούν για να φτάσουν σε ένα δίκτυο μέσω μιας πύλης ή για να κρύψουν τη διεύθυνσή τους· το ssh -D και το Tor προσφέρουν από ένα.","Session (Layer 5)":"Συνεδρίας (επίπεδο 5)","Any TCP, and UDP":"Οποιοδήποτε TCP, και UDP",Logins:"Σύνδεση","None, or user and password":"Καμία, ή χρήστης και κωδικός","Offered by":"Το προσφέρουν","ssh -D, Tor, proxy servers":"ssh -D, Tor, διακομιστές proxy","Tunnel open":"Το τούνελ άνοιξε","A few bytes, then just copying":"Λίγα byte, μετά μόνο αντιγραφή","Four tiny messages told the proxy where to connect; after that it only copied bytes. The website saw the proxy’s address, and because the laptop sent a name rather than an address, even the DNS lookup happened at the proxy. Press REPLAY to watch it again.":"Τέσσερα μικροσκοπικά μηνύματα είπαν στο proxy πού να συνδεθεί· μετά απλώς αντέγραφε byte. Ο ιστότοπος είδε τη διεύθυνση του proxy, και επειδή ο φορητός έστειλε όνομα αντί για διεύθυνση, ακόμη και η αναζήτηση DNS έγινε στο proxy. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","4 messages, 37 bytes":"4 μηνύματα, 37 byte","DNS lookup":"Αναζήτηση DNS","At the proxy":"Στο proxy","Only the TLS inside":"Μόνο το TLS μέσα","TCP to port 1080":"TCP στη θύρα 1080","An app set to use a SOCKS proxy (a browser, a game launcher, or a tunnel made with ssh -D) opens a TCP connection to it, port 1080. SOCKS doesn’t care what will travel inside: it can carry any TCP connection.":"Μια εφαρμογή ρυθμισμένη να χρησιμοποιεί proxy SOCKS (browser, πρόγραμμα εκκίνησης παιχνιδιών ή τούνελ με ssh -D) ανοίγει σύνδεση TCP προς αυτό, θύρα 1080. Το SOCKS δεν νοιάζεται τι θα ταξιδέψει μέσα: μπορεί να μεταφέρει οποιαδήποτε σύνδεση TCP.","Any TCP connection":"Οποιαδήποτε σύνδεση TCP","Wants to reach":"Θέλει να φτάσει","https://www.example.com":"https://www.example.com","Version 5, and how to log in":"Έκδοση 5, και τρόπος σύνδεσης","The laptop sends three bytes: version 5, one login method offered, and that method, 0: no login. The proxy answers with two: version 5, method 0. Had it chosen method 2, the app would next send a user name and password, in plain text.":"Ο φορητός στέλνει τρία byte: έκδοση 5, μία προσφερόμενη μέθοδος σύνδεσης, και αυτή η μέθοδος, 0: χωρίς σύνδεση. Το proxy απαντά με δύο: έκδοση 5, μέθοδος 0. Αν είχε επιλέξει τη μέθοδο 2, η εφαρμογή θα έστελνε μετά όνομα χρήστη και κωδικό, σε απλό κείμενο.","Laptop sends":"Ο φορητός στέλνει","05 01 00 (3 bytes)":"05 01 00 (3 byte)","Proxy answers":"Το proxy απαντά","05 00 (2 bytes)":"05 00 (2 byte)","None needed here":"Δεν χρειάζεται εδώ",GREETING:"ΧΑΙΡΕΤΙΣΜΟΣ","no login, please":"χωρίς σύνδεση, παρακαλώ",METHOD:"ΜΕΘΟΔΟΣ","no login needed":"δεν χρειάζεται σύνδεση","Where To?":"Πού;","Connect to www.example.com:443":"Σύνδεση στο www.example.com:443","The laptop asks the proxy to connect to www.example.com, port 443. It gives the name rather than an address, so the proxy does the DNS lookup and the laptop needs none. The proxy opens its own TCP connection to the server, then replies: succeeded, and the address and port it connected from.":"Ο φορητός ζητά από το proxy να συνδεθεί στο www.example.com, θύρα 443. Δίνει το όνομα αντί για διεύθυνση, οπότε την αναζήτηση DNS την κάνει το proxy και ο φορητός δεν χρειάζεται. Το proxy ανοίγει δική του σύνδεση TCP με τον διακομιστή και μετά απαντά: επιτυχία, με τη διεύθυνση και τη θύρα από τις οποίες συνδέθηκε.","www.example.com (a name)":"www.example.com (όνομα)","Succeeded, from 192.0.2.80:40220":"Επιτυχία, από 192.0.2.80:40220",SUCCEEDED:"ΕΠΙΤΥΧΙΑ","from 192.0.2.80:40220":"από 192.0.2.80:40220","Copied both ways, unread":"Αντιγράφεται και προς τις δύο, χωρίς ανάγνωση","Now the proxy just copies. The app starts TLS with the server: its Client Hello goes in on the laptop’s connection and comes out unchanged on the proxy’s, and the server’s answer comes back the same way. The server only ever sees the proxy’s address; the proxy sees only encrypted bytes.":"Τώρα το proxy απλώς αντιγράφει. Η εφαρμογή ξεκινά TLS με τον διακομιστή: το Client Hello της μπαίνει από τη σύνδεση του φορητού και βγαίνει αμετάβλητο από τη σύνδεση του proxy, και η απάντηση του διακομιστή επιστρέφει με τον ίδιο τρόπο. Ο διακομιστής βλέπει πάντα μόνο τη διεύθυνση του proxy· το proxy βλέπει μόνο κρυπτογραφημένα byte.","The proxy’s address":"Τη διεύθυνση του proxy","Encrypted bytes":"Κρυπτογραφημένα byte","Same bytes":"Ίδια byte","On both connections":"Και στις δύο συνδέσεις",unchanged:"αμετάβλητο","+ encrypted handshake":"+ κρυπτογραφημένη χειραψία","Version 5, 1 method: no login":"Έκδοση 5, 1 μέθοδος: χωρίς σύνδεση","Version 5, method chosen: no login":"Έκδοση 5, επιλεγμένη μέθοδος: χωρίς σύνδεση","Succeeded, bound to 192.0.2.80:40220":"Επιτυχία, δεμένο στο 192.0.2.80:40220","SOCKS5 · greeting":"SOCKS5 · χαιρετισμός","Methods offered":"Προσφερόμενες μέθοδοι","0 (no login)":"0 (χωρίς σύνδεση)","SOCKS5 · method chosen":"SOCKS5 · επιλεγμένη μέθοδος","Method chosen":"Επιλεγμένη μέθοδος","SOCKS5 · connect request":"SOCKS5 · αίτημα σύνδεσης","Open a TCP connection on my behalf.":"Άνοιξε μια σύνδεση TCP για λογαριασμό μου.","Address type":"Τύπος διεύθυνσης","3 (domain name)":"3 (όνομα τομέα)","The proxy looks the name up itself, so the laptop needs no DNS lookup of its own.":"Το proxy αναζητά μόνο του το όνομα, οπότε ο φορητός δεν χρειάζεται δική του αναζήτηση DNS.","SOCKS5 · reply":"SOCKS5 · απάντηση","0 (succeeded)":"0 (επιτυχία)","The address the proxy connects from.":"Η διεύθυνση από την οποία συνδέεται το proxy.",Offloading:"Αποφόρτιση","Reverse Proxy":"Αντίστροφο proxy","TLS (SSL) offloading":"Αποφόρτιση TLS (SSL)","A reverse proxy stands in front of a website’s servers: visitors connect to it, and it passes their requests on to an app server behind it. It can spread the load over many servers, keep copies of pages and turn away attacks. Often it also does the TLS work, decrypting HTTPS at the edge so the servers behind it speak plain HTTP. That is SSL (or TLS) offloading.":"Ένα αντίστροφο proxy στέκεται μπροστά από τους διακομιστές ενός ιστότοπου: οι επισκέπτες συνδέονται σε αυτό, και αυτό προωθεί τα αιτήματά τους σε έναν διακομιστή εφαρμογής πίσω του. Μπορεί να μοιράζει το φορτίο σε πολλούς διακομιστές, να κρατά αντίγραφα σελίδων και να αποκρούει επιθέσεις. Συχνά κάνει και τη δουλειά του TLS, αποκρυπτογραφώντας το HTTPS στην άκρη ώστε οι διακομιστές πίσω του να μιλούν απλό HTTP. Αυτό είναι η αποφόρτιση SSL (ή TLS).","Visitors reach":"Οι επισκέπτες φτάνουν","The proxy, never the app":"Στο proxy, ποτέ στην εφαρμογή","TLS ends":"Το TLS τελειώνει","At the proxy (offloading)":"Στο proxy (αποφόρτιση)","Plain HTTP (or TLS again)":"Απλό HTTP (ή πάλι TLS)",Adds:"Προσθέτει","For example":"Για παράδειγμα","nginx, HAProxy, cloud LBs":"nginx, HAProxy, LB στο cloud","Served from the edge":"Εξυπηρέτηση από την άκρη","Encrypted outside, plain inside":"Κρυπτογραφημένο έξω, απλό μέσα","The laptop saw one HTTPS website. Behind it, the reverse proxy decrypted the request, asked an app server in plain HTTP over the private network and encrypted the answer for the trip back. Press REPLAY to watch it again.":"Ο φορητός είδε έναν ιστότοπο HTTPS. Πίσω του, το αντίστροφο proxy αποκρυπτογράφησε το αίτημα, ρώτησε έναν διακομιστή εφαρμογής με απλό HTTP μέσω του ιδιωτικού δικτύου και κρυπτογράφησε την απάντηση για τον δρόμο της επιστροφής. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","Laptop ↔ proxy only":"Μόνο φορητός ↔ proxy","App learns visitor":"Η εφαρμογή μαθαίνει τον επισκέπτη","From X-Forwarded-For":"Από το X-Forwarded-For","Certificate kept":"Το πιστοποιητικό φυλάσσεται","On the proxy":"Στο proxy","The Front Door":"Η κεντρική είσοδος","The proxy holds the certificate":"Το proxy κρατά το πιστοποιητικό","The laptop opens https://www.example.com. The address DNS gives for the name belongs to the reverse proxy, which holds the site’s certificate and does the TLS handshake. Nothing tells the laptop there is another server behind it.":"Ο φορητός ανοίγει το https://www.example.com. Η διεύθυνση που δίνει το DNS για το όνομα ανήκει στο αντίστροφο proxy, που κρατά το πιστοποιητικό του ιστότοπου και κάνει τη χειραψία TLS. Τίποτα δεν λέει στον φορητό ότι υπάρχει άλλος διακομιστής πίσω του.","Laptop connects to":"Ο φορητός συνδέεται σε","On the reverse proxy":"Στο αντίστροφο proxy","Also called":"Λέγεται και","Load balancer, edge":"Εξισορροπητής φορτίου, edge","TLS Ends Here":"Το TLS τελειώνει εδώ","Offloading: the proxy does the TLS work":"Αποφόρτιση: τη δουλειά TLS την κάνει το proxy","The request arrives encrypted, and the reverse proxy decrypts it. That is the offloading: the TLS work is done here, once, instead of on every app server. Now the proxy can read the URL, headers and cookies, and pick a server by them.":"Το αίτημα φτάνει κρυπτογραφημένο, και το αντίστροφο proxy το αποκρυπτογραφεί. Αυτό είναι η αποφόρτιση: η δουλειά του TLS γίνεται εδώ, μία φορά, αντί για κάθε διακομιστή εφαρμογής. Τώρα το proxy μπορεί να διαβάσει το URL, τις κεφαλίδες και τα cookies, και να επιλέξει διακομιστή με βάση αυτά.","At the reverse proxy":"Στο αντίστροφο proxy","Proxy can read":"Το proxy διαβάζει","URL, headers, cookies":"URL, κεφαλίδες, cookies","Then picks":"Μετά επιλέγει","An app server":"Έναν διακομιστή εφαρμογής","TLS ENDS HERE":"ΤΟ TLS ΤΕΛΕΙΩΝΕΙ ΕΔΩ","In the Clear":"Σε απλό κείμενο","Passed on to the app server":"Προωθείται στον διακομιστή εφαρμογής","The proxy passes the request on over the data centre’s private network, as plain HTTP to port 8080. It adds X-Forwarded-For, the visitor’s address, and X-Forwarded-Proto: https, how the visitor came in; otherwise the app would see only the proxy. Anyone able to watch this private network could read it all.":"Το proxy προωθεί το αίτημα μέσω του ιδιωτικού δικτύου του κέντρου δεδομένων, ως απλό HTTP στη θύρα 8080. Προσθέτει X-Forwarded-For, τη διεύθυνση του επισκέπτη, και X-Forwarded-Proto: https, πώς μπήκε ο επισκέπτης· αλλιώς η εφαρμογή θα έβλεπε μόνο το proxy. Όποιος μπορεί να παρακολουθεί αυτό το ιδιωτικό δίκτυο θα μπορούσε να τα διαβάσει όλα.","The App Answers":"Η εφαρμογή απαντά","In plain HTTP too":"Επίσης με απλό HTTP","The app server builds the page and answers the proxy, in plain HTTP: it never deals with TLS or certificates at all.":"Ο διακομιστής εφαρμογής φτιάχνει τη σελίδα και απαντά στο proxy με απλό HTTP: δεν ασχολείται ποτέ με TLS ή πιστοποιητικά.","text/html, 12,500 bytes":"text/html, 12,500 byte","readable inside":"αναγνώσιμο μέσα","Encrypted Again":"Ξανά κρυπτογραφημένο","An ordinary HTTPS answer":"Μια συνηθισμένη απάντηση HTTPS","The reverse proxy encrypts the answer in the TLS session it holds with the laptop and sends it on. From outside, it is an ordinary HTTPS site.":"Το αντίστροφο proxy κρυπτογραφεί την απάντηση στη συνεδρία TLS που έχει με τον φορητό και τη στέλνει. Από έξω, είναι ένας συνηθισμένος ιστότοπος HTTPS.","Laptop sees":"Ο φορητός βλέπει","One HTTPS server":"Έναν διακομιστή HTTPS","App servers":"Διακομιστές εφαρμογής","Never handle TLS":"Δεν ασχολούνται ποτέ με TLS",Certificates:"Πιστοποιητικά","Renewed in one place":"Ανανεώνονται σε ένα σημείο","Three Options":"Τρεις επιλογές","Offload, re-encrypt or pass through":"Αποφόρτιση, επανακρυπτογράφηση ή διέλευση","Offloading, as here, is simple and fast but leaves the inside traffic readable. Re-encrypting opens a second TLS connection from the proxy to the app server, so it stays encrypted inside too. Passing through forwards the TLS bytes without opening them: the certificate lives on the app servers, and the proxy can only choose a server by address and the name in the Client Hello, not by URL.":"Η αποφόρτιση, όπως εδώ, είναι απλή και γρήγορη, αλλά αφήνει την εσωτερική κίνηση αναγνώσιμη. Η επανακρυπτογράφηση ανοίγει δεύτερη σύνδεση TLS από το proxy στον διακομιστή εφαρμογής, ώστε να μένει κρυπτογραφημένη και μέσα. Η διέλευση προωθεί τα byte του TLS χωρίς να τα ανοίξει: το πιστοποιητικό βρίσκεται στους διακομιστές εφαρμογής, και το proxy μπορεί να επιλέξει διακομιστή μόνο με βάση τη διεύθυνση και το όνομα στο Client Hello, όχι το URL.",Offload:"Αποφόρτιση","Plain HTTP inside":"Απλό HTTP μέσα","Re-encrypt":"Επανακρυπτογράφηση","TLS inside as well":"TLS και μέσα","Pass through":"Διέλευση","Proxy can’t read it":"Το proxy δεν το διαβάζει","PLAIN HTTP INSIDE":"ΑΠΛΟ HTTP ΜΕΣΑ","A Modern VPN":"Ένα σύγχρονο VPN","WireGuard (encrypted)":"WireGuard (κρυπτογραφημένο)","TCP beyond the VPN":"TCP πέρα από το VPN",Keepalive:"Keepalive","VPN Server":"Διακομιστής VPN","A VPN carries your traffic inside an encrypted tunnel to a VPN server, which sends it on to the internet. On a café’s Wi-Fi, others see only encrypted packets going to the VPN server; websites see the VPN server’s address instead of yours. WireGuard is a modern VPN: a small amount of code, one fixed set of modern algorithms and a handshake of two messages.":"Ένα VPN μεταφέρει την κίνησή σας μέσα σε κρυπτογραφημένο τούνελ ως έναν διακομιστή VPN, που τη στέλνει στο Διαδίκτυο. Στο Wi-Fi ενός καφέ οι άλλοι βλέπουν μόνο κρυπτογραφημένα πακέτα προς τον διακομιστή VPN· οι ιστότοποι βλέπουν τη διεύθυνση του διακομιστή VPN αντί για τη δική σας. Το WireGuard είναι ένα σύγχρονο VPN: λίγος κώδικας, ένα σταθερό σύνολο σύγχρονων αλγορίθμων και χειραψία δύο μηνυμάτων.","UDP (51820 by default)":"UDP (51820 από προεπιλογή)","2 messages, 1 round trip":"2 μηνύματα, 1 διαδρομή μετ’ επιστροφής",Crypto:"Κρυπτογραφία",Identity:"Ταυτότητα","Public keys, like SSH":"Δημόσια κλειδιά, όπως στο SSH","The WireGuard whitepaper":"Η λευκή βίβλος του WireGuard","Tunnel up":"Το τούνελ λειτουργεί","Encrypted to the VPN, plain beyond it":"Κρυπτογραφημένο ως το VPN, απλό μετά","Two handshake messages made the keys. After that every packet the laptop sent was sealed whole inside a UDP packet to the VPN server, and the website saw only the VPN server’s address. Beyond the VPN server traffic is no better protected than without one, so HTTPS still matters. Press REPLAY to watch it again.":"Δύο μηνύματα χειραψίας έφτιαξαν τα κλειδιά. Μετά κάθε πακέτο που έστελνε ο φορητός σφραγιζόταν ολόκληρο μέσα σε ένα πακέτο UDP προς τον διακομιστή VPN, και ο ιστότοπος έβλεπε μόνο τη διεύθυνση του διακομιστή VPN. Πέρα από τον διακομιστή VPN η κίνηση δεν προστατεύεται καλύτερα απ’ ό,τι χωρίς VPN, οπότε το HTTPS εξακολουθεί να μετράει. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","Others nearby see":"Όσοι είναι κοντά βλέπουν","UDP to 192.0.2.51":"UDP προς 192.0.2.51","Websites see":"Οι ιστότοποι βλέπουν","The VPN server":"Τον διακομιστή VPN","Beyond the VPN":"Πέρα από το VPN","Only HTTPS protects":"Προστατεύει μόνο το HTTPS",Overhead:"Επιβάρυνση","60 bytes + padding":"60 byte + συμπλήρωση","Set Up Once":"Ρύθμιση μία φορά","Keys, not passwords":"Κλειδιά, όχι κωδικοί","The laptop runs the WireGuard app with a short configuration: its own private key, the server’s public key and address (192.0.2.51, UDP port 51820), and AllowedIPs = 0.0.0.0/0, which means everything goes through the tunnel. Inside the tunnel the laptop’s address is 10.8.0.2.":"Ο φορητός τρέχει την εφαρμογή WireGuard με μια σύντομη ρύθμιση: το δικό του ιδιωτικό κλειδί, το δημόσιο κλειδί και τη διεύθυνση του διακομιστή (192.0.2.51, θύρα UDP 51820), και AllowedIPs = 0.0.0.0/0, που σημαίνει ότι όλα περνούν από το τούνελ. Μέσα στο τούνελ η διεύθυνση του φορητού είναι 10.8.0.2.","Inside address":"Εσωτερική διεύθυνση","Through the tunnel":"Μέσα από το τούνελ","Everything (0.0.0.0/0)":"Όλα (0.0.0.0/0)","TUNNEL ADDRESS 10.8.0.2":"ΔΙΕΥΘΥΝΣΗ ΤΟΥΝΕΛ 10.8.0.2","Two messages, one round trip":"Δύο μηνύματα, μία διαδρομή μετ’ επιστροφής","When the laptop first has something to send, it starts a handshake: 148 bytes with a fresh public key, its own long-term key (encrypted, so only the server learns who is calling) and the time (encrypted, so a recording can’t be replayed). The server answers only keys it knows, here with 92 bytes. One round trip, and both sides have new session keys.":"Όταν ο φορητός έχει για πρώτη φορά κάτι να στείλει, ξεκινά χειραψία: 148 byte με νέο δημόσιο κλειδί, το μόνιμο κλειδί του (κρυπτογραφημένο, ώστε μόνο ο διακομιστής να μάθει ποιος καλεί) και την ώρα (κρυπτογραφημένη, ώστε μια καταγραφή να μην μπορεί να αναπαραχθεί). Ο διακομιστής απαντά μόνο σε κλειδιά που ξέρει, εδώ με 92 byte. Μία διαδρομή μετ’ επιστροφής, και οι δύο πλευρές έχουν νέα κλειδιά συνεδρίας.",Initiation:"Έναρξη","Server answers":"Ο διακομιστής απαντά","Only keys it knows":"Μόνο σε κλειδιά που ξέρει",INITIATION:"INITIATION","fresh key + identity":"νέο κλειδί + ταυτότητα",RESPONSE:"RESPONSE","keys agreed":"τα κλειδιά συμφωνήθηκαν","Into the Tunnel":"Μέσα στο τούνελ","A packet inside a packet":"Ένα πακέτο μέσα σε πακέτο","You open https://www.example.com; its address was looked up through the tunnel too (not shown). The first packet of the connection, a TCP SYN from 10.8.0.2 to the web server, is encrypted whole and sent inside a UDP packet to the VPN server. On the café’s Wi-Fi only the outer packet shows: from the laptop to 192.0.2.51, port 51820.":"Ανοίγετε το https://www.example.com· και η διεύθυνσή του αναζητήθηκε μέσα από το τούνελ (δεν φαίνεται). Το πρώτο πακέτο της σύνδεσης, ένα TCP SYN από το 10.8.0.2 προς τον διακομιστή web, κρυπτογραφείται ολόκληρο και στέλνεται μέσα σε ένα πακέτο UDP προς τον διακομιστή VPN. Στο Wi-Fi του καφέ φαίνεται μόνο το εξωτερικό πακέτο: από τον φορητό προς 192.0.2.51, θύρα 51820.",Outside:"Έξω","UDP to 192.0.2.51:51820":"UDP προς 192.0.2.51:51820","inside: TCP SYN to :443":"μέσα: TCP SYN προς :443","Out to the Web":"Προς το web","Decrypted, then sent on":"Αποκρυπτογραφείται, μετά προωθείται","The VPN server decrypts the packet, swaps 10.8.0.2 for its own public address (NAT) and sends the SYN on, one hop older (TTL 127). The SYN offers a maximum segment of 1380 bytes, not 1460: the tunnel adds 60 bytes to every packet. The web server sees a visitor at 192.0.2.51 and answers there.":"Ο διακομιστής VPN αποκρυπτογραφεί το πακέτο, αντικαθιστά το 10.8.0.2 με τη δημόσια διεύθυνσή του (NAT) και προωθεί το SYN, ένα βήμα παλαιότερο (TTL 127). Το SYN προσφέρει μέγιστο τμήμα 1380 byte, όχι 1460: το τούνελ προσθέτει 60 byte σε κάθε πακέτο. Ο διακομιστής web βλέπει έναν επισκέπτη στο 192.0.2.51 και απαντά εκεί.","Website sees":"Ο ιστότοπος βλέπει","192.0.2.51 (the VPN)":"192.0.2.51 (το VPN)","Hidden from the site":"Κρυφό από τον ιστότοπο","127 (one hop, the VPN)":"127 (ένα βήμα, το VPN)","from 192.0.2.51":"από 192.0.2.51","The Way Back":"Ο δρόμος της επιστροφής","Sealed again, for the laptop":"Ξανά σφραγισμένο, για τον φορητό","The answer goes back the same way. The VPN server seals the SYN-ACK in a WireGuard packet for the laptop, which opens it and hands it to Windows as if it had come straight from the web server.":"Η απάντηση επιστρέφει με τον ίδιο τρόπο. Ο διακομιστής VPN σφραγίζει το SYN-ACK σε πακέτο WireGuard για τον φορητό, που το ανοίγει και το δίνει στα Windows σαν να ήρθε κατευθείαν από τον διακομιστή web.",Counter:"Μετρητής","Each side counts its own":"Κάθε πλευρά μετρά τον δικό της",Replays:"Επαναλήψεις","Thrown away":"Πετιούνται","inside: TCP SYN-ACK":"μέσα: TCP SYN-ACK","Keeping It Open":"Διατήρηση ανοιχτού","A keepalive, and new keys":"Ένα keepalive, και νέα κλειδιά","With nothing to send, a WireGuard tunnel goes quiet. Because the laptop is behind NAT, it is set to send an empty packet every 25 seconds (PersistentKeepalive), a keepalive of 32 bytes, so the router doesn’t forget the connection. Every two minutes a new handshake makes fresh keys, and if the laptop moves to another network, the tunnel simply carries on from its new address.":"Χωρίς τίποτα να στείλει, ένα τούνελ WireGuard σωπαίνει. Επειδή ο φορητός είναι πίσω από NAT, είναι ρυθμισμένος να στέλνει ένα κενό πακέτο κάθε 25 δευτερόλεπτα (PersistentKeepalive), ένα keepalive 32 byte, ώστε ο δρομολογητής να μην ξεχάσει τη σύνδεση. Κάθε δύο λεπτά μια νέα χειραψία φτιάχνει νέα κλειδιά, κι αν ο φορητός πάει σε άλλο δίκτυο, το τούνελ απλώς συνεχίζει από τη νέα του διεύθυνση.","Every 25 s, 32 bytes":"Κάθε 25 s, 32 byte","New keys":"Νέα κλειδιά","Every 2 minutes":"Κάθε 2 λεπτά","New network":"Νέο δίκτυο","The tunnel carries on":"Το τούνελ συνεχίζει",KEEPALIVE:"KEEPALIVE","empty, 32 bytes":"κενό, 32 byte","Message type":"Τύπος μηνύματος","Sender index":"Δείκτης αποστολέα","A number this side picked for the session; the other side puts it in every packet it sends back.":"Ένας αριθμός που διάλεξε αυτή η πλευρά για τη συνεδρία· η άλλη πλευρά τον βάζει σε κάθε πακέτο που στέλνει πίσω.","Ephemeral key":"Εφήμερο κλειδί","A new public key, made just for this handshake.":"Ένα νέο δημόσιο κλειδί, φτιαγμένο μόνο για αυτή τη χειραψία.","Encrypted static key":"Κρυπτογραφημένο στατικό κλειδί","The laptop’s long-term public key (32 bytes) and a 16-byte tag, encrypted: only the server learns who is calling.":"Το μόνιμο δημόσιο κλειδί του φορητού (32 byte) και μια ετικέτα 16 byte, κρυπτογραφημένα: μόνο ο διακομιστής μαθαίνει ποιος καλεί.","Encrypted timestamp":"Κρυπτογραφημένη χρονοσήμανση","The time (12 bytes) and a tag, encrypted. An old initiation sent again is refused.":"Η ώρα (12 byte) και μια ετικέτα, κρυπτογραφημένα. Μια παλιά έναρξη που ξαναστέλνεται απορρίπτεται.","Keyed with the server’s public key: without it, the server doesn’t answer at all.":"Υπολογίζεται με το δημόσιο κλειδί του διακομιστή: χωρίς αυτό, ο διακομιστής δεν απαντά καθόλου.","Used only when the server is busy and asks for a cookie first.":"Χρησιμοποιείται μόνο όταν ο διακομιστής είναι απασχολημένος και ζητά πρώτα cookie.","Receiver index":"Δείκτης παραλήπτη","The other side’s index: which session this packet belongs to.":"Ο δείκτης της άλλης πλευράς: σε ποια συνεδρία ανήκει αυτό το πακέτο.","The server’s new public key for this handshake.":"Το νέο δημόσιο κλειδί του διακομιστή για αυτή τη χειραψία.","Encrypted nothing":"Κρυπτογραφημένο τίποτα","Only a tag: it proves the server holds its private key.":"Μόνο μια ετικέτα: αποδεικνύει ότι ο διακομιστής έχει το ιδιωτικό του κλειδί.","Counts up with every packet; one seen before is thrown away.":"Αυξάνεται με κάθε πακέτο· όποιο έχει ξαναφανεί πετιέται.","The whole inner packet, padded to a multiple of 16 bytes, then a 16-byte tag.":"Ολόκληρο το εσωτερικό πακέτο, συμπληρωμένο σε πολλαπλάσιο των 16 byte, μετά μια ετικέτα 16 byte.","then 12 bytes of padding, and the tag":"μετά 12 byte συμπλήρωσης, και η ετικέτα","The laptop sent it with 128; the VPN server took 1 when it passed it on.":"Ο φορητός το έστειλε με 128· ο διακομιστής VPN αφαίρεσε 1 όταν το προώθησε.","Nothing but the 16-byte tag: an empty packet that keeps the tunnel open.":"Τίποτα πέρα από την ετικέτα 16 byte: ένα κενό πακέτο που κρατά το τούνελ ανοιχτό.","ESP (encrypted)":"ESP (κρυπτογραφημένο)","TCP beyond the gateway":"TCP πέρα από την πύλη","VPN Gateway":"Πύλη VPN","IP Security":"IP Security","IPsec protects IP packets themselves. IKEv2 sets things up: the two sides agree on algorithms, make keys and prove who they are with certificates or other credentials. Then ESP carries each packet encrypted inside another. IPsec links offices together and brings laptops into company networks, and it is built into most operating systems and firewalls.":"Το IPsec προστατεύει τα ίδια τα πακέτα IP. Το IKEv2 στήνει τα πράγματα: οι δύο πλευρές συμφωνούν αλγορίθμους, φτιάχνουν κλειδιά και αποδεικνύουν ποιες είναι με πιστοποιητικά ή άλλα διαπιστευτήρια. Μετά το ESP μεταφέρει κάθε πακέτο κρυπτογραφημένο μέσα σε άλλο. Το IPsec συνδέει γραφεία μεταξύ τους και φέρνει φορητούς σε εταιρικά δίκτυα, και είναι ενσωματωμένο στα περισσότερα λειτουργικά συστήματα και τείχη προστασίας.","Behind NAT":"Πίσω από NAT","ESP (IP protocol 50)":"ESP (πρωτόκολλο IP 50)","Certificates, EAP, keys":"Πιστοποιητικά, EAP, κλειδιά","IKE to set up, ESP to carry":"IKE για στήσιμο, ESP για μεταφορά","Four IKE messages agreed on algorithms, found the NAT, proved both identities and set up the tunnel. After that each packet travelled whole inside ESP, encrypted and checked, and wrapped in UDP to get through the home router. Press REPLAY to watch it again.":"Τέσσερα μηνύματα IKE συμφώνησαν αλγορίθμους, εντόπισαν το NAT, απέδειξαν και τις δύο ταυτότητες και έστησαν το τούνελ. Μετά κάθε πακέτο ταξίδευε ολόκληρο μέσα στο ESP, κρυπτογραφημένο και ελεγμένο, και τυλιγμένο σε UDP για να περάσει από τον οικιακό δρομολογητή. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","IKE messages":"Μηνύματα IKE","4 (2 exchanges)":"4 (2 ανταλλαγές)","NAT traversal":"Διάσχιση NAT","One SPI each way":"Ένα SPI ανά κατεύθυνση","Agree on algorithms, swap keys":"Συμφωνία αλγορίθμων, ανταλλαγή κλειδιών","The VPN client opens with IKE on UDP port 500. Its first message proposes the algorithms (AES-GCM with 256-bit keys, SHA-256, Curve25519) and carries a public key and a random nonce; the gateway picks the proposal and sends its own key and nonce. Both now share a secret, but neither has proved who it is yet.":"Ο πελάτης VPN ξεκινά με IKE στη θύρα UDP 500. Το πρώτο του μήνυμα προτείνει αλγορίθμους (AES-GCM με κλειδιά 256 bit, SHA-256, Curve25519) και φέρει ένα δημόσιο κλειδί και ένα τυχαίο nonce· η πύλη επιλέγει την πρόταση και στέλνει το δικό της κλειδί και nonce. Και οι δύο μοιράζονται πλέον ένα μυστικό, αλλά καμία δεν έχει ακόμη αποδείξει ποια είναι.",Proposed:"Προτείνονται","After this":"Μετά από αυτό","Shared keys, no identities":"Κοινά κλειδιά, χωρίς ταυτότητες","proposal, key, nonce":"πρόταση, κλειδί, nonce","NAT detection":"εντοπισμός NAT","chosen proposal, key, nonce":"επιλεγμένη πρόταση, κλειδί, nonce","A NAT in the Way":"Ένα NAT στη μέση","So everything moves to port 4500":"Οπότε όλα μετακομίζουν στη θύρα 4500","Both messages also carried hashes of the address and port each side sent from. At the gateway they don’t match what arrived: the home router rewrote the laptop’s address on the way (NAT). ESP has no port numbers, so a NAT can’t pass it; both sides move to UDP port 4500 and wrap ESP in UDP from now on.":"Και τα δύο μηνύματα έφεραν επίσης κατακερματισμούς της διεύθυνσης και της θύρας από τις οποίες έστειλε κάθε πλευρά. Στην πύλη δεν ταιριάζουν με ό,τι έφτασε: ο οικιακός δρομολογητής ξανάγραψε στη διαδρομή τη διεύθυνση του φορητού (NAT). Το ESP δεν έχει αριθμούς θυρών, άρα ένα NAT δεν μπορεί να το περάσει· και οι δύο πλευρές περνούν στη θύρα UDP 4500 και από εδώ και πέρα τυλίγουν το ESP σε UDP.","Hashes of":"Κατακερματισμοί","Address and port sent from":"Διεύθυνσης και θύρας αποστολής",Mismatch:"Αναντιστοιχία","The router rewrote them":"Ο δρομολογητής τα ξανάγραψε",Fix:"Λύση","Everything over UDP 4500":"Όλα μέσω UDP 4500","NAT DETECTED":"ΕΝΤΟΠΙΣΤΗΚΕ NAT","Prove who you are, encrypted":"Αποδείξτε ποιος είστε, κρυπτογραφημένα","Now encrypted, each side sends its identity, its certificate and a signature over everything said so far, so anyone in the middle would be caught. The laptop asks for an address inside the network and gets 10.8.0.2. The same exchange sets up the ESP tunnel itself, with its own keys and an SPI for each direction.":"Πλέον κρυπτογραφημένα, κάθε πλευρά στέλνει την ταυτότητά της, το πιστοποιητικό της και μια υπογραφή πάνω σε όσα ειπώθηκαν ως τώρα, ώστε όποιος βρίσκεται στη μέση να πιαστεί. Ο φορητός ζητά διεύθυνση μέσα στο δίκτυο και παίρνει 10.8.0.2. Η ίδια ανταλλαγή στήνει και το ίδιο το τούνελ ESP, με δικά του κλειδιά και ένα SPI για κάθε κατεύθυνση.","UDP 4500 (NAT traversal)":"UDP 4500 (διάσχιση NAT)","Identity, by certificate":"Ταυτότητα, με πιστοποιητικό","Laptop gets":"Ο φορητός παίρνει","10.8.0.2, and a DNS server":"10.8.0.2, και διακομιστή DNS","identity, certificate":"ταυτότητα, πιστοποιητικό",signature:"υπογραφή","address 10.8.0.2":"διεύθυνση 10.8.0.2","The whole packet, encrypted":"Ολόκληρο το πακέτο, κρυπτογραφημένο","You open https://www.example.com, looked up through the tunnel at the DNS server the gateway gave (not shown). The SYN from 10.8.0.2 is encrypted whole into an ESP packet: an SPI that names the tunnel, a sequence number, then the encrypted packet and a check value, all inside UDP port 4500. Its UDP checksum is zero: ESP checks its own contents.":"Ανοίγετε το https://www.example.com, που αναζητήθηκε μέσα από το τούνελ στον διακομιστή DNS που έδωσε η πύλη (δεν φαίνεται). Το SYN από το 10.8.0.2 κρυπτογραφείται ολόκληρο σε πακέτο ESP: ένα SPI που κατονομάζει το τούνελ, ένας αριθμός ακολουθίας, μετά το κρυπτογραφημένο πακέτο και μια τιμή ελέγχου, όλα μέσα στη θύρα UDP 4500. Το άθροισμα ελέγχου UDP είναι μηδέν: το ESP ελέγχει μόνο του το περιεχόμενό του.","Names the tunnel":"Κατονομάζει το τούνελ","The whole IP packet":"Ολόκληρο το πακέτο IP","62 bytes + padding":"62 byte + συμπλήρωση","Out and Back":"Πήγαινε κι έλα","Through the gateway and home again":"Μέσα από την πύλη και πίσω στο σπίτι","The gateway decrypts the packet and sends the SYN on from its own address, one hop older. The answer comes back to the gateway and returns through the tunnel as another ESP packet, with the SPI for the laptop’s direction and its own sequence numbers.":"Η πύλη αποκρυπτογραφεί το πακέτο και προωθεί το SYN από τη δική της διεύθυνση, ένα βήμα παλαιότερο. Η απάντηση γυρίζει στην πύλη και επιστρέφει μέσα από το τούνελ ως άλλο πακέτο ESP, με το SPI της κατεύθυνσης προς τον φορητό και δικούς της αριθμούς ακολουθίας.","192.0.2.51 (the gateway)":"192.0.2.51 (η πύλη)","Each direction":"Κάθε κατεύθυνση","Its own SPI and keys":"Δικό της SPI και κλειδιά","Which VPN?":"Ποιο VPN;","IPsec or WireGuard":"IPsec ή WireGuard","IPsec is older and very flexible: it negotiates its algorithms, takes many kinds of credentials and is built into Windows, macOS, iOS, Android and most firewalls, which makes it the usual way to join a company network or link two offices. WireGuard does less, with far less code and one fixed set of algorithms.":"Το IPsec είναι παλαιότερο και πολύ ευέλικτο: διαπραγματεύεται αλγορίθμους, δέχεται πολλά είδη διαπιστευτηρίων και είναι ενσωματωμένο σε Windows, macOS, iOS, Android και στα περισσότερα τείχη προστασίας, γι’ αυτό είναι ο συνήθης τρόπος για ένταξη σε εταιρικό δίκτυο ή σύνδεση δύο γραφείων. Το WireGuard κάνει λιγότερα, με πολύ λιγότερο κώδικα και ένα σταθερό σύνολο αλγορίθμων.","Built into":"Ενσωματωμένο σε","Also links":"Συνδέει επίσης","Office to office":"Γραφείο με γραφείο",Negotiates:"Διαπραγματεύεται","Its algorithms (WireGuard: no)":"Τους αλγορίθμους του (WireGuard: όχι)","Initiator SPI":"SPI εκκινητή","Picked by the laptop: which IKE session this is.":"Το επιλέγει ο φορητός: ποια συνεδρία IKE είναι αυτή.","Responder SPI":"SPI αποκριτή","0 (not known yet)":"0 (άγνωστο ακόμη)","Next payload":"Επόμενο φορτίο","Exchange type":"Τύπος ανταλλαγής","0x08 (initiator)":"0x08 (εκκινητής)","Message ID":"ID μηνύματος","Each request and its response share a number; the next exchange counts up.":"Κάθε αίτημα και η απάντησή του μοιράζονται έναν αριθμό· η επόμενη ανταλλαγή μετρά προς τα πάνω.","SA payload":"Φορτίο SA","Next payload, length":"Επόμενο φορτίο, μήκος",Proposal:"Πρόταση","What the laptop offers; a real client often offers several.":"Τι προσφέρει ο φορητός· ένας πραγματικός πελάτης συχνά προσφέρει πολλές.","KE payload":"Φορτίο KE","DH group":"Ομάδα DH","This side’s public key. From the two, both work out the same secret.":"Το δημόσιο κλειδί αυτής της πλευράς. Από τα δύο, και οι δύο υπολογίζουν το ίδιο μυστικό.","Nonce payload":"Φορτίο nonce","Notify payload":"Φορτίο notify",Notify:"Notify",Hash:"Κατακερματισμός","A hash of the SPIs and the address and port this side sent from. If what arrives doesn’t match, a NAT changed it on the way.":"Κατακερματισμός των SPI και της διεύθυνσης και θύρας από τις οποίες έστειλε αυτή η πλευρά. Αν ό,τι φτάνει δεν ταιριάζει, ένα NAT το άλλαξε στη διαδρομή.","The same for the address and port it sent to.":"Το ίδιο για τη διεύθυνση και τη θύρα προς τις οποίες έστειλε.","0x20 (response)":"0x20 (απάντηση)","The one the server chose from the laptop’s offer.":"Αυτή που επέλεξε ο διακομιστής από την προσφορά του φορητού.","Non-ESP marker":"Δείκτης μη ESP","Four zero bytes: an IKE message, not an ESP packet (they share port 4500).":"Τέσσερα μηδενικά byte: μήνυμα IKE, όχι πακέτο ESP (μοιράζονται τη θύρα 4500).","Encrypted payload":"Κρυπτογραφημένο φορτίο","Encrypted payloads":"Κρυπτογραφημένα φορτία","Everything else in this message, encrypted with the keys from IKE_SA_INIT.":"Όλα τα υπόλοιπα αυτού του μηνύματος, κρυπτογραφημένα με τα κλειδιά από το IKE_SA_INIT.","IDi, CERT, AUTH: who the laptop is, proven":"IDi, CERT, AUTH: ποιος είναι ο φορητός, αποδεδειγμένα","CP: asks for an inside address and DNS":"CP: ζητά εσωτερική διεύθυνση και DNS","SA: what to use for ESP (AES-GCM)":"SA: τι να χρησιμοποιηθεί για ESP (AES-GCM)","TSi, TSr: which traffic goes in the tunnel":"TSi, TSr: ποια κίνηση μπαίνει στο τούνελ","Integrity check":"Έλεγχος ακεραιότητας","IDr, CERT, AUTH: who the gateway is, proven":"IDr, CERT, AUTH: ποια είναι η πύλη, αποδεδειγμένα","CP: inside address 10.8.0.2, DNS 10.8.0.1":"CP: εσωτερική διεύθυνση 10.8.0.2, DNS 10.8.0.1","SA: ESP with AES-GCM, and the SPIs":"SA: ESP με AES-GCM, και τα SPI","TSi, TSr: everything (0.0.0.0/0)":"TSi, TSr: όλα (0.0.0.0/0)","0 (not used)":"0 (δεν χρησιμοποιείται)","ESP checks its own contents, so ESP carried in UDP leaves this at zero.":"Το ESP ελέγχει μόνο του το περιεχόμενό του, οπότε το ESP μέσα σε UDP αφήνει αυτό στο μηδέν.","Which tunnel (security association) this belongs to; the receiving side chose it during IKE_AUTH.":"Σε ποιο τούνελ (security association) ανήκει· η πλευρά λήψης το επέλεξε κατά το IKE_AUTH.","Different for every packet.":"Διαφορετικό για κάθε πακέτο.","The whole inner packet, then padding, the pad length and the next header (4: an IPv4 packet).":"Ολόκληρο το εσωτερικό πακέτο, μετά συμπλήρωση, το μήκος συμπλήρωσης και η επόμενη κεφαλίδα (4: πακέτο IPv4).","then padding, pad length and next header (4)":"μετά συμπλήρωση, μήκος συμπλήρωσης και επόμενη κεφαλίδα (4)","Shows any change to the packet.":"Αποκαλύπτει κάθε αλλαγή στο πακέτο.","The laptop sent it with 128; the gateway took 1 when it passed it on.":"Ο φορητός το έστειλε με 128· η πύλη αφαίρεσε 1 όταν το προώθησε.","HTTP/3 over QUIC":"HTTP/3 πάνω από QUIC","QUIC is a newer transport that runs over UDP and has TLS 1.3 built in. Its first packets do the transport and the encryption handshakes together, so a page request can leave after one round trip. It carries many streams at once, so one lost packet doesn’t hold up the rest, and it survives a change of network. HTTP/3 is HTTP running over QUIC.":"Το QUIC είναι ένα νεότερο πρωτόκολλο μεταφοράς που λειτουργεί πάνω από UDP και έχει ενσωματωμένο το TLS 1.3. Τα πρώτα του πακέτα κάνουν μαζί τη χειραψία μεταφοράς και κρυπτογράφησης, ώστε ένα αίτημα σελίδας να φύγει μετά από μία διαδρομή μετ’ επιστροφής. Μεταφέρει πολλές ροές ταυτόχρονα, οπότε ένα χαμένο πακέτο δεν καθυστερεί τις υπόλοιπες, και αντέχει αλλαγή δικτύου. Το HTTP/3 είναι HTTP πάνω από QUIC.","Runs over":"Λειτουργεί πάνω από","UDP, port 443":"UDP, θύρα 443","TLS 1.3, always":"TLS 1.3, πάντα","1 round trip (0 when returning)":"1 διαδρομή μετ’ επιστροφής (0 σε επιστροφή)",Streams:"Ροές","Many, independent":"Πολλές, ανεξάρτητες","One round trip, then the request":"Μία διαδρομή μετ’ επιστροφής, μετά το αίτημα","QUIC folded the transport and TLS handshakes into one round trip, so the request left 36 ms after the first packet; over TCP and TLS it would have waited twice as long. Everything after the first packets was encrypted, even most of each packet’s header. Press REPLAY to watch it again.":"Το QUIC συγχώνευσε τις χειραψίες μεταφοράς και TLS σε μία διαδρομή μετ’ επιστροφής, οπότε το αίτημα έφυγε 36 ms μετά το πρώτο πακέτο· με TCP και TLS θα περίμενε διπλάσιο χρόνο. Ό,τι ακολούθησε τα πρώτα πακέτα ήταν κρυπτογραφημένο, ακόμη και το μεγαλύτερο μέρος της κεφαλίδας κάθε πακέτου. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","1 before the request (TCP + TLS: 2)":"1 πριν από το αίτημα (TCP + TLS: 2)","Lost packet":"Χαμένο πακέτο","Holds up one stream only":"Καθυστερεί μόνο μία ροή","Choosing HTTP/3":"Επιλογή HTTP/3","An earlier visit said it can":"Μια προηγούμενη επίσκεψη είπε ότι μπορεί",'On an earlier visit the server answered with Alt-Svc: h3=":443", meaning it also speaks HTTP/3 on UDP port 443 (DNS can say the same in an HTTPS record). So this time the browser skips TCP and talks QUIC.':'Σε μια προηγούμενη επίσκεψη ο διακομιστής απάντησε με Alt-Svc: h3=":443", που σημαίνει ότι μιλά και HTTP/3 στη θύρα UDP 443 (το DNS μπορεί να πει το ίδιο σε εγγραφή HTTPS). Οπότε αυτή τη φορά ο browser παραλείπει το TCP και μιλά QUIC.',"Learned from":"Το έμαθε από","Alt-Svc header, or DNS":"Κεφαλίδα Alt-Svc, ή DNS","QUIC over UDP 443":"QUIC πάνω από UDP 443","TLS 1.3, built in":"TLS 1.3, ενσωματωμένο","Initial Packets":"Πακέτα Initial","The Client Hello, straight away":"Το Client Hello, αμέσως","There is no separate TCP handshake: the very first packets carry the TLS Client Hello. With its post-quantum key share it is 1,880 bytes, too big for one packet, so it fills two Initial packets. Each datagram is padded to at least 1,200 bytes; a server may send back only three times what it has received, so a forged sender address can’t turn it into an amplifier.":"Δεν υπάρχει χωριστή χειραψία TCP: τα πρώτα κιόλας πακέτα φέρουν το TLS Client Hello. Με το μετακβαντικό μερίδιο κλειδιού έχει 1,880 byte, πολύ για ένα πακέτο, οπότε γεμίζει δύο πακέτα Initial. Κάθε datagram συμπληρώνεται ως τουλάχιστον 1,200 byte· ένας διακομιστής μπορεί να στείλει πίσω μόνο τριπλάσια απ’ όσα έλαβε, ώστε μια πλαστή διεύθυνση αποστολέα να μην τον κάνει ενισχυτή.","2 × 1,250 bytes":"2 × 1,250 byte","The TLS Client Hello":"Το TLS Client Hello","Readable?":"Αναγνώσιμο;","Yes (Initial keys are public)":"Ναι (τα κλειδιά Initial είναι δημόσια)","Client Hello, part 1":"Client Hello, μέρος 1","Client Hello, part 2":"Client Hello, μέρος 2",padding:"συμπλήρωση","Then the certificate, encrypted":"Μετά το πιστοποιητικό, κρυπτογραφημένο","The server answers with its Server Hello in an Initial packet. Both sides can now work out handshake keys, so the rest (the certificate, its signature and Finished) comes in Handshake packets that only the laptop can read. Four datagrams, well under three times what the laptop sent.":"Ο διακομιστής απαντά με το Server Hello του σε πακέτο Initial. Οι δύο πλευρές μπορούν πλέον να υπολογίσουν κλειδιά χειραψίας, οπότε τα υπόλοιπα (το πιστοποιητικό, η υπογραφή του και το Finished) έρχονται σε πακέτα Handshake που μόνο ο φορητός μπορεί να διαβάσει. Τέσσερα datagram, αρκετά κάτω από το τριπλάσιο όσων έστειλε ο φορητός.","Certificate, signature, Finished":"Πιστοποιητικό, υπογραφή, Finished","Server limit":"Όριο διακομιστή","3× the bytes received":"3× τα byte που έλαβε","certificate, Finished":"πιστοποιητικό, Finished","The request, one round trip in":"Το αίτημα, μετά από μία διαδρομή","The laptop checks the certificate and sends its Finished, and in the same moment its first HTTP/3 request in a 1-RTT packet: a HEADERS frame on stream 0, its headers compressed with QPACK. One round trip after the first packet, the request is on its way; TCP and TLS together would need two.":"Ο φορητός ελέγχει το πιστοποιητικό και στέλνει το Finished του, και την ίδια στιγμή το πρώτο αίτημα HTTP/3 σε πακέτο 1-RTT: ένα πλαίσιο HEADERS στη ροή 0, με κεφαλίδες συμπιεσμένες με QPACK. Μία διαδρομή μετ’ επιστροφής μετά το πρώτο πακέτο, το αίτημα είναι καθ’ οδόν· TCP και TLS μαζί θα χρειάζονταν δύο.","1 (TCP + TLS: 2)":"1 (TCP + TLS: 2)","HEADERS on stream 0":"HEADERS στη ροή 0",Headers:"Κεφαλίδες","Compressed (QPACK)":"Συμπιεσμένες (QPACK)","HTTP/3, stream 0":"HTTP/3, ροή 0","The Response":"Η απάντηση","On its own stream":"Στη δική της ροή","The server confirms the handshake is over (HANDSHAKE_DONE) and answers on stream 0: headers, then the page. Every request gets its own stream, so a lost packet holds up only the stream it belonged to. Over TCP one missing segment stalls everything behind it.":"Ο διακομιστής επιβεβαιώνει ότι η χειραψία τελείωσε (HANDSHAKE_DONE) και απαντά στη ροή 0: κεφαλίδες, μετά η σελίδα. Κάθε αίτημα έχει δική του ροή, οπότε ένα χαμένο πακέτο καθυστερεί μόνο τη ροή στην οποία ανήκε. Στο TCP ένα τμήμα που λείπει σταματά ό,τι ακολουθεί.","Frames on QUIC streams":"Πλαίσια σε ροές QUIC","Holds up one stream":"Καθυστερεί μία ροή","All but a few header bits":"Όλα εκτός από λίγα bit κεφαλίδας","the page":"η σελίδα","New Network":"Νέο δίκτυο","Known by ID, not by address":"Αναγνωρίζεται από ID, όχι από διεύθυνση","A QUIC connection is known by its connection IDs, not by addresses and ports. If the laptop moves from Wi-Fi to a phone’s hotspot, its address changes but the connection carries on: the server checks the new path and continues. And on the next visit the browser can send its request in its very first packets (0-RTT).":"Μια σύνδεση QUIC αναγνωρίζεται από τα ID σύνδεσής της, όχι από διευθύνσεις και θύρες. Αν ο φορητός περάσει από το Wi-Fi στο hotspot ενός κινητού, η διεύθυνσή του αλλάζει αλλά η σύνδεση συνεχίζει: ο διακομιστής ελέγχει τη νέα διαδρομή και συνεχίζει. Και στην επόμενη επίσκεψη ο browser μπορεί να στείλει το αίτημα στα πρώτα κιόλας πακέτα (0-RTT).","Known by":"Αναγνωρίζεται από","Connection ID":"ID σύνδεσης","New address":"Νέα διεύθυνση","The connection carries on":"Η σύνδεση συνεχίζει","Next visit":"Επόμενη επίσκεψη","0-RTT: request at once":"0-RTT: αίτημα αμέσως","SAME CONNECTION ON ANY NETWORK":"ΙΔΙΑ ΣΥΝΔΕΣΗ ΣΕ ΚΑΘΕ ΔΙΚΤΥΟ","Initial, CRYPTO (Client Hello, part 1)":"Initial, CRYPTO (Client Hello, μέρος 1)","Initial, CRYPTO (Client Hello, part 2), PADDING":"Initial, CRYPTO (Client Hello, μέρος 2), PADDING","Handshake, CRYPTO (Certificate, part 1)":"Handshake, CRYPTO (πιστοποιητικό, μέρος 1)","Handshake, CRYPTO (Certificate, part 2)":"Handshake, CRYPTO (πιστοποιητικό, μέρος 2)","Initial packet":"Πακέτο Initial","Header type":"Τύπος κεφαλίδας","long header, Initial":"μεγάλη κεφαλίδα, Initial","The top bits say what kind of packet this is; the last bits are disguised (header protection).":"Τα ανώτερα bit λένε τι είδους πακέτο είναι· τα τελευταία bit είναι μεταμφιεσμένα (προστασία κεφαλίδας).","Destination connection ID":"ID σύνδεσης προορισμού","Which connection this belongs to. Each side picks its own ID; the other writes it here.":"Σε ποια σύνδεση ανήκει. Κάθε πλευρά επιλέγει το δικό της ID· η άλλη το γράφει εδώ.","Source connection ID":"ID σύνδεσης προέλευσης","Token length":"Μήκος token","No token: the server hasn’t asked this client to prove its address first.":"Χωρίς token: ο διακομιστής δεν ζήτησε από αυτόν τον πελάτη να αποδείξει πρώτα τη διεύθυνσή του.","The packet number and payload. Whatever follows is another packet in the same datagram.":"Ο αριθμός πακέτου και το φορτίο. Ό,τι ακολουθεί είναι άλλο πακέτο στο ίδιο datagram.","Packet number":"Αριθμός πακέτου","Hidden by header protection, so nobody on the way can read or change it.":"Κρυμμένος με προστασία κεφαλίδας, ώστε κανείς στη διαδρομή να μην μπορεί να τον διαβάσει ή να τον αλλάξει.","Encrypted with keys anyone can work out from the connection ID, so it stops accidents, not eavesdroppers: the Client Hello inside can be read on the way.":"Κρυπτογραφημένο με κλειδιά που ο καθένας μπορεί να υπολογίσει από το ID σύνδεσης, οπότε σταματά ατυχήματα, όχι ωτακουστές: το Client Hello μέσα διαβάζεται στη διαδρομή.","CRYPTO: Client Hello, bytes 1–1,203 of 1,880":"CRYPTO: Client Hello, byte 1–1,203 από 1,880","SNI www.example.com, ALPN h3, X25519MLKEM768 key share":"SNI www.example.com, ALPN h3, μερίδιο κλειδιού X25519MLKEM768","CRYPTO: Client Hello, bytes 1,204–1,880":"CRYPTO: Client Hello, byte 1,204–1,880","PADDING, up to 1,250 bytes":"PADDING, έως 1,250 byte","ACK: packets 0–1 arrived":"ACK: τα πακέτα 0–1 έφτασαν","CRYPTO: Server Hello, with its half of the key (1,120 bytes)":"CRYPTO: Server Hello, με το δικό του μισό του κλειδιού (1,120 byte)","Handshake packet":"Πακέτο Handshake","long header, Handshake":"μεγάλη κεφαλίδα, Handshake","Encrypted with keys from the key exchange so far.":"Κρυπτογραφημένο με κλειδιά από την ανταλλαγή κλειδιών ως τώρα.","CRYPTO: Encrypted Extensions, Certificate (start)":"CRYPTO: Encrypted Extensions, Certificate (αρχή)","CRYPTO: Certificate (continued)":"CRYPTO: Certificate (συνέχεια)","CRYPTO: Certificate Verify, Finished":"CRYPTO: Certificate Verify, Finished","ACK: the server’s Initial arrived":"ACK: έφτασε το Initial του διακομιστή","ACK: the Handshake packets arrived":"ACK: έφτασαν τα πακέτα Handshake","1-RTT packet":"Πακέτο 1-RTT","short header":"μικρή κεφαλίδα","Only the receiver’s ID, and no length: it knows how long its own IDs are. It stays the same if the laptop changes network.":"Μόνο το ID του παραλήπτη, και χωρίς μήκος: ξέρει πόσο μεγάλα είναι τα δικά του ID. Μένει ίδιο αν ο φορητός αλλάξει δίκτυο.","Encrypted with the session keys.":"Κρυπτογραφημένο με τα κλειδιά συνεδρίας.","STREAM 2: SETTINGS (the control stream)":"STREAM 2: SETTINGS (η ροή ελέγχου)","STREAM 0: HEADERS, GET / (QPACK-compressed)":"STREAM 0: HEADERS, GET / (συμπιεσμένο με QPACK)","HANDSHAKE_DONE: the handshake is over":"HANDSHAKE_DONE: η χειραψία τελείωσε","STREAM 0: HEADERS 200, then DATA: the page (1,000 bytes)":"STREAM 0: HEADERS 200, μετά DATA: η σελίδα (1,000 byte)","ACK: the response arrived":"ACK: η απάντηση έφτασε","Address Setup":"Ρύθμιση διεύθυνσης","No IPv6 address":"Χωρίς διεύθυνση IPv6","IPv6: SLAAC and neighbour discovery":"IPv6: SLAAC και εύρεση γειτόνων","IPv6 addresses are 128 bits long, enough for every device to have its own. A device can usually set itself up with no DHCP server: it makes a link-local address, asks for a router, and builds its global address from the prefix the router advertises (SLAAC). Neighbour discovery, part of ICMPv6, finds MAC addresses and does the work ARP does for IPv4.":"Οι διευθύνσεις IPv6 έχουν μήκος 128 bit, αρκετό για να έχει κάθε συσκευή τη δική της. Μια συσκευή μπορεί συνήθως να ρυθμιστεί μόνη της χωρίς διακομιστή DHCP: φτιάχνει μια διεύθυνση link-local, ζητά δρομολογητή και χτίζει τη σφαιρική της διεύθυνση από το πρόθεμα που ανακοινώνει ο δρομολογητής (SLAAC). Η εύρεση γειτόνων, μέρος του ICMPv6, βρίσκει διευθύνσεις MAC και κάνει τη δουλειά που κάνει το ARP για το IPv4.","128 bits":"128 bit",Addresses:"Διευθύνσεις","SLAAC: no server needed":"SLAAC: χωρίς διακομιστή","Replaces ARP":"Αντικαθιστά το ARP","Neighbour discovery":"Εύρεση γειτόνων",Optional:"Προαιρετικό","Two addresses, no DHCP":"Δύο διευθύνσεις, χωρίς DHCP","Made by the laptop itself":"Φτιαγμένες από τον ίδιο τον φορητό","The laptop made a link-local address and a global one, checked that nobody else had either, and learned its router, MTU and DNS server from a single advertisement. When packets came for it, neighbour discovery found its MAC address. Press REPLAY to watch it again.":"Ο φορητός έφτιαξε μια διεύθυνση link-local και μια σφαιρική, έλεγξε ότι κανείς άλλος δεν είχε καμία από τις δύο, και έμαθε δρομολογητή, MTU και διακομιστή DNS από μία μόνο ανακοίνωση. Όταν ήρθαν πακέτα για αυτόν, η εύρεση γειτόνων βρήκε τη διεύθυνση MAC του. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","Link-local":"Link-local",Global:"Σφαιρική","2001:db8:1234:5678::/64 + its own ID":"2001:db8:1234:5678::/64 + δικό του ID","Router, DNS":"Δρομολογητής, DNS","From one advertisement":"Από μία ανακοίνωση","6, all ICMPv6":"6, όλα ICMPv6","Link-Local First":"Πρώτα το link-local","Every IPv6 interface gets a link-local address, usable only on its own network. The laptop makes one from fe80:: and a random-looking 64-bit interface ID. First it checks nobody already has it: a Neighbor Solicitation asking for that address, sent from :: because it can’t use the address yet. Nobody answers, so it’s the laptop’s.":"Κάθε διεπαφή IPv6 παίρνει μια διεύθυνση link-local, χρησιμοποιήσιμη μόνο στο δικό της δίκτυο. Ο φορητός φτιάχνει μία από το fe80:: και ένα ID διεπαφής 64 bit που μοιάζει τυχαίο. Πρώτα ελέγχει ότι δεν την έχει ήδη κανείς: ένα Neighbor Solicitation που ρωτά για αυτή τη διεύθυνση, σταλμένο από το :: επειδή δεν μπορεί ακόμη να τη χρησιμοποιήσει. Κανείς δεν απαντά, άρα είναι του φορητού.",Check:"Έλεγχος","Duplicate address detection":"Εντοπισμός διπλής διεύθυνσης","None: the address is free":"Καμία: η διεύθυνση είναι ελεύθερη","IS IT TAKEN?":"ΕΙΝΑΙ ΠΙΑΣΜΕΝΗ;","from ::":"από ::","target fe80::8d2e:4f61:a9b0:7c13":"στόχος fe80::8d2e:4f61:a9b0:7c13","NO ANSWER: ADDRESS IS FREE":"ΚΑΜΙΑ ΑΠΑΝΤΗΣΗ: Η ΔΙΕΥΘΥΝΣΗ ΕΙΝΑΙ ΕΛΕΥΘΕΡΗ","Any Routers?":"Υπάρχουν δρομολογητές;","A Router Solicitation":"Ένα Router Solicitation","Link-local addresses can’t reach the internet. The laptop sends a Router Solicitation to ff02::2, the address every router on the network listens to, with its own MAC address attached.":"Οι διευθύνσεις link-local δεν φτάνουν στο Διαδίκτυο. Ο φορητός στέλνει ένα Router Solicitation στο ff02::2, τη διεύθυνση που ακούει κάθε δρομολογητής του δικτύου, με συνημμένη τη δική του διεύθυνση MAC.","ff02::2 (all routers)":"ff02::2 (όλοι οι δρομολογητές)",Includes:"Περιλαμβάνει","ROUTERS?":"ΔΡΟΜΟΛΟΓΗΤΕΣ;","Router Answers":"Ο δρομολογητής απαντά","Prefix, MTU and DNS in one message":"Πρόθεμα, MTU και DNS σε ένα μήνυμα","The router answers to ff02::1, every device on the network, with a Router Advertisement: use me as your way out for 30 minutes, here is my MAC address, the MTU is 1500, the network’s prefix is 2001:db8:1234:5678::/64 and you may make your own address in it, and ask 2001:4860:4860::8888 for DNS. Routers also send these on their own every few minutes.":"Ο δρομολογητής απαντά στο ff02::1, σε κάθε συσκευή του δικτύου, με ένα Router Advertisement: χρησιμοποιήστε με ως έξοδο για 30 λεπτά, ορίστε η διεύθυνση MAC μου, το MTU είναι 1500, το πρόθεμα του δικτύου είναι 2001:db8:1234:5678::/64 και μπορείτε να φτιάξετε δική σας διεύθυνση μέσα του, και ρωτήστε το 2001:4860:4860::8888 για DNS. Οι δρομολογητές τα στέλνουν και μόνοι τους κάθε λίγα λεπτά.",Prefix:"Πρόθεμα","Make your own":"Φτιάξτε δική σας","Yes (flag A)":"Ναι (σημαία A)",ADVERTISEMENT:"ΑΝΑΚΟΙΝΩΣΗ","prefix 2001:db8:1234:5678::/64":"πρόθεμα 2001:db8:1234:5678::/64","A Global Address":"Μια σφαιρική διεύθυνση","Prefix + interface ID":"Πρόθεμα + ID διεπαφής","The laptop joins the prefix and its interface ID into a global address, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, and checks it the same way. Windows also makes a temporary address with a random ID that changes every day, used for outgoing connections so websites can’t follow one device by its address.":"Ο φορητός ενώνει το πρόθεμα και το ID διεπαφής του σε σφαιρική διεύθυνση, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, και την ελέγχει με τον ίδιο τρόπο. Τα Windows φτιάχνουν επίσης μια προσωρινή διεύθυνση με τυχαίο ID που αλλάζει κάθε μέρα, για τις εξερχόμενες συνδέσεις, ώστε οι ιστότοποι να μην παρακολουθούν μια συσκευή από τη διεύθυνσή της.","Also made":"Φτιάχνεται επίσης","A temporary address":"Μια προσωρινή διεύθυνση","target the global address":"στόχος η σφαιρική διεύθυνση","Neighbour Lookup":"Αναζήτηση γείτονα","Who has this address? (ARP’s job)":"Ποιος έχει αυτή τη διεύθυνση; (δουλειά του ARP)","A reply from the internet arrives at the router for the laptop’s global address. To deliver it, the router needs the MAC address that goes with it: it sends a Neighbor Solicitation to the address’s solicited-node group, so only devices whose address ends the same way even look. The laptop answers with a Neighbor Advertisement carrying its MAC address.":"Μια απάντηση από το Διαδίκτυο φτάνει στον δρομολογητή για τη σφαιρική διεύθυνση του φορητού. Για να την παραδώσει, ο δρομολογητής χρειάζεται την αντίστοιχη διεύθυνση MAC: στέλνει ένα Neighbor Solicitation στην ομάδα solicited-node της διεύθυνσης, ώστε να κοιτάξουν μόνο συσκευές των οποίων η διεύθυνση τελειώνει με τον ίδιο τρόπο. Ο φορητός απαντά με Neighbor Advertisement που φέρει τη διεύθυνση MAC του.","Asked to":"Ρωτήθηκε","Instead of":"Αντί για","ARP broadcasts to everyone":"Εκπομπές ARP προς όλους","WHO HAS?":"ΠΟΙΟΣ ΕΧΕΙ;","the global address":"τη σφαιρική διεύθυνση","Ready, No DHCP":"Έτοιμο, χωρίς DHCP","And no NAT either":"Και χωρίς NAT","The laptop is on the internet with its own global address, and no NAT changes it on the way: the address a website sees is the laptop’s. The home router’s firewall still turns away connections nobody inside asked for. Networks that want to hand out addresses centrally can use DHCPv6 instead.":"Ο φορητός είναι στο Διαδίκτυο με δική του σφαιρική διεύθυνση, και κανένα NAT δεν την αλλάζει στη διαδρομή: η διεύθυνση που βλέπει ένας ιστότοπος είναι του φορητού. Το τείχος προστασίας του οικιακού δρομολογητή εξακολουθεί να απορρίπτει συνδέσεις που κανείς μέσα δεν ζήτησε. Δίκτυα που θέλουν να μοιράζουν διευθύνσεις κεντρικά μπορούν να χρησιμοποιούν DHCPv6.","Not needed":"Δεν χρειάζεται",Incoming:"Εισερχόμενες","Blocked by the firewall":"Τις μπλοκάρει το τείχος προστασίας","Optional (flags M, O)":"Προαιρετικό (σημαίες M, O)","ONLINE OVER IPv6":"ΣΕ ΣΥΝΔΕΣΗ ΜΕ IPv6","A multicast MAC address: 33:33, then the last four bytes of the IPv6 address.":"Μια διεύθυνση MAC multicast: 33:33, μετά τα τελευταία τέσσερα byte της διεύθυνσης IPv6.","Version, class, flow":"Έκδοση, κλάση, ροή","IPv6, ordinary traffic, no flow label.":"IPv6, κανονική κίνηση, χωρίς ετικέτα ροής.","Payload length":"Μήκος φορτίου","What follows this 40-byte header.":"Ό,τι ακολουθεί αυτή την κεφαλίδα των 40 byte.","Next header":"Επόμενη κεφαλίδα","Hop limit":"Όριο βημάτων","Neighbour discovery must arrive with 255, proof that no router passed it on: it came from this network.":"Η εύρεση γειτόνων πρέπει να φτάνει με 255, απόδειξη ότι κανένας δρομολογητής δεν την προώθησε: ήρθε από αυτό το δίκτυο.","Unspecified: the laptop has no address it may use yet.":"Απροσδιόριστη: ο φορητός δεν έχει ακόμη διεύθυνση που να μπορεί να χρησιμοποιήσει.","Solicited-node multicast: only devices whose address ends in the same 24 bits are listening.":"Multicast solicited-node: ακούν μόνο συσκευές των οποίων η διεύθυνση τελειώνει στα ίδια 24 bit.","Covers the message and both IPv6 addresses.":"Καλύπτει το μήνυμα και τις δύο διευθύνσεις IPv6.",Target:"Στόχος","The address the laptop wants to use. If anyone answers, it’s taken.":"Η διεύθυνση που θέλει να χρησιμοποιήσει ο φορητός. Αν απαντήσει κάποιος, είναι πιασμένη.","A link-local address: usable only on this network.":"Μια διεύθυνση link-local: χρησιμοποιήσιμη μόνο σε αυτό το δίκτυο.","Every router on this network.":"Κάθε δρομολογητής αυτού του δικτύου.","Source link-layer address":"Διεύθυνση επιπέδου ζεύξης προέλευσης","The sender’s MAC address, so nobody has to ask for it.":"Η διεύθυνση MAC του αποστολέα, ώστε να μη χρειάζεται να τη ζητήσει κανείς.","Every device on this network.":"Κάθε συσκευή αυτού του δικτύου.","The hop limit devices here should put on their packets.":"Το όριο βημάτων που πρέπει να βάζουν εδώ οι συσκευές στα πακέτα τους.","M: take addresses from DHCPv6. O: take other settings from DHCPv6. Both off: this advertisement has everything.":"M: πάρτε διευθύνσεις από DHCPv6. O: πάρτε άλλες ρυθμίσεις από DHCPv6. Και τα δύο κλειστά: αυτή η ανακοίνωση έχει τα πάντα.","Router lifetime":"Διάρκεια δρομολογητή","How long the laptop may use this router as its way out.":"Πόσο μπορεί ο φορητός να χρησιμοποιεί αυτόν τον δρομολογητή ως έξοδο.","Reachable time":"Χρόνος προσβασιμότητας","0 (not set)":"0 (δεν ορίζεται)","Retransmit timer":"Χρονόμετρο επανεκπομπής","The largest packet this network carries.":"Το μεγαλύτερο πακέτο που μεταφέρει αυτό το δίκτυο.","2001:db8:1234:5678::/64, valid 86,400 s, preferred 14,400 s":"2001:db8:1234:5678::/64, ισχύει 86,400 s, προτιμάται 14,400 s","Flags L and A: addresses in this prefix are on this network, and devices may make their own (SLAAC).":"Σημαίες L και A: οι διευθύνσεις αυτού του προθέματος είναι σε αυτό το δίκτυο, και οι συσκευές μπορούν να φτιάξουν δική τους (SLAAC).","2001:4860:4860::8888, for 3,600 s":"2001:4860:4860::8888, για 3,600 s","Recursive DNS server: which resolver to ask, so no DHCP is needed for that either.":"Αναδρομικός διακομιστής DNS: ποιον επιλυτή να ρωτάτε, ώστε ούτε γι’ αυτό να χρειάζεται DHCP.","Whose MAC address is wanted.":"Ποιανού τη διεύθυνση MAC ζητάμε.","The device this frame is for.":"Η συσκευή για την οποία προορίζεται το πλαίσιο.","0x60000000: solicited, override":"0x60000000: solicited, override","Solicited: this answers a question. Override: replace any older entry for this address.":"Solicited: απαντά σε ερώτηση. Override: αντικαθιστά κάθε παλαιότερη εγγραφή για αυτή τη διεύθυνση.","Target link-layer address":"Διεύθυνση επιπέδου ζεύξης στόχου","The answer: the MAC address that goes with the target.":"Η απάντηση: η διεύθυνση MAC που αντιστοιχεί στον στόχο.","Setting the Clock":"Ρύθμιση του ρολογιού","Computer clocks drift by seconds a week, and a lot depends on them: certificates have dates, logins and payments expire, logs from different machines must line up. NTP sets a clock from a time server over the internet. One small request and answer carry four timestamps, enough to work out how far off the clock is and how long the network took.":"Τα ρολόγια των υπολογιστών αποκλίνουν κατά δευτερόλεπτα την εβδομάδα, και πολλά εξαρτώνται από αυτά: τα πιστοποιητικά έχουν ημερομηνίες, συνδέσεις και πληρωμές λήγουν, τα αρχεία καταγραφής από διαφορετικά μηχανήματα πρέπει να συμφωνούν. Το NTP ρυθμίζει ένα ρολόι από έναν διακομιστή ώρας στο Διαδίκτυο. Ένα μικρό αίτημα και μια απάντηση φέρουν τέσσερις χρονοσημάνσεις, αρκετές για να υπολογιστεί πόσο απέχει το ρολόι και πόσο χρόνο πήρε το δίκτυο.",Accuracy:"Ακρίβεια","A few milliseconds online":"Λίγα χιλιοστά του δευτερολέπτου online","Clock set":"Το ρολόι ρυθμίστηκε","Four timestamps, one answer":"Τέσσερις χρονοσημάνσεις, μία απάντηση","One request and one answer gave four timestamps. From them the laptop worked out that its clock was 0.25 s slow and that the network took 24 ms there and back, and it began easing its clock into line. Press REPLAY to watch it again.":"Ένα αίτημα και μία απάντηση έδωσαν τέσσερις χρονοσημάνσεις. Από αυτές ο φορητός υπολόγισε ότι το ρολόι του πήγαινε 0.25 s πίσω και ότι το δίκτυο χρειαζόταν 24 ms πήγαινε-έλα, και άρχισε να ευθυγραμμίζει σταδιακά το ρολόι. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Offset:"Απόκλιση","250.0 ms (slow)":"250.0 ms (πίσω)","Stratum 2":"Stratum 2","Next check":"Επόμενος έλεγχος","Minutes to days later":"Από λεπτά ως μέρες αργότερα","Clocks Drift":"Τα ρολόγια αποκλίνουν","The laptop’s clock is a little slow":"Το ρολόι του φορητού πάει λίγο πίσω","A computer keeps time with a quartz crystal that runs a little fast or slow, so clocks drift apart by seconds a week. This laptop’s clock is a quarter of a second behind. Windows sets it from time.windows.com, whose address it has already looked up by DNS.":"Ένας υπολογιστής μετρά τον χρόνο με έναν κρύσταλλο χαλαζία που πάει λίγο μπροστά ή πίσω, οπότε τα ρολόγια απομακρύνονται κατά δευτερόλεπτα την εβδομάδα. Το ρολόι αυτού του φορητού πάει ένα τέταρτο του δευτερολέπτου πίσω. Τα Windows το ρυθμίζουν από το time.windows.com, του οποίου τη διεύθυνση έχουν ήδη βρει με DNS.","Laptop clock":"Ρολόι φορητού","0.25 s slow":"0.25 s πίσω","Time server":"Διακομιστής ώρας","Why it matters":"Γιατί μετράει","Certificates, logins, logs":"Πιστοποιητικά, συνδέσεις, αρχεία καταγραφής","CLOCK 0.250 s SLOW":"ΡΟΛΟΙ 0.250 s ΠΙΣΩ","Ask for the Time":"Ερώτηση για την ώρα","T1: when the request leaves":"T1: όταν φεύγει το αίτημα","The laptop sends a 48-byte request to port 123. It writes in the time by its own clock as the request leaves: T1, 09:40:59.750. Everything else is empty.":"Ο φορητός στέλνει ένα αίτημα 48 byte στη θύρα 123. Γράφει μέσα την ώρα του δικού του ρολογιού τη στιγμή που φεύγει το αίτημα: T1, 09:40:59.750. Όλα τα άλλα είναι κενά.","T1 (laptop)":"T1 (φορητός)",Mode:"Λειτουργία","3 (client)":"3 (πελάτης)","The Answer":"Η απάντηση","T2 and T3 from the server, T4 on arrival":"T2 και T3 από τον διακομιστή, T4 στην άφιξη","The server copies T1 back, adds T2, when the request arrived, and T3, when its answer leaves, both by its own accurate clock. When the answer arrives, the laptop notes T4 by its own clock. The server is stratum 2: it sets its clock from a stratum 1 server, which has a GPS receiver or an atomic clock.":"Ο διακομιστής αντιγράφει πίσω το T1, προσθέτει το T2, πότε έφτασε το αίτημα, και το T3, πότε φεύγει η απάντησή του, και τα δύο με το δικό του ακριβές ρολόι. Όταν φτάνει η απάντηση, ο φορητός σημειώνει το T4 με το δικό του ρολόι. Ο διακομιστής είναι stratum 2: ρυθμίζει το ρολόι του από διακομιστή stratum 1, που έχει δέκτη GPS ή ατομικό ρολόι.","T4 (laptop)":"T4 (φορητός)",Stratum:"Stratum","The Offset":"Η απόκλιση","Four times, two answers":"Τέσσερις χρόνοι, δύο απαντήσεις","The time on the network, there and back, is (T4 − T1) − (T3 − T2) = 24.0 ms. The offset assumes the trip takes as long each way: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. The laptop’s clock is a quarter of a second slow. An uneven route (slower one way than the other) would skew the result by up to half the difference.":"Ο χρόνος στο δίκτυο, πήγαινε-έλα, είναι (T4 − T1) − (T3 − T2) = 24.0 ms. Η απόκλιση υποθέτει ότι η διαδρομή διαρκεί το ίδιο προς κάθε κατεύθυνση: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. Το ρολόι του φορητού πάει ένα τέταρτο του δευτερολέπτου πίσω. Μια άνιση διαδρομή (πιο αργή προς τη μία κατεύθυνση) θα αλλοίωνε το αποτέλεσμα έως το μισό της διαφοράς.",Assumes:"Υποθέτει","Equal time each way":"Ίδιο χρόνο προς κάθε κατεύθυνση","OFFSET +250.0 ms":"ΑΠΟΚΛΙΣΗ +250.0 ms","Ease It In":"Σταδιακή ευθυγράμμιση","No jumps backwards":"Χωρίς άλματα προς τα πίσω","A small error is not fixed in one jump: the clock is run slightly fast until it catches up, so time never stops or goes backwards for running programs. Only a big error is set straight away. As a clock settles, an NTP client asks less often, from every 64 seconds up to every 17 minutes or so; Windows on its own checks time.windows.com far less often, every several hours or less.":"Ένα μικρό σφάλμα δεν διορθώνεται με ένα άλμα: το ρολόι τρέχει λίγο πιο γρήγορα μέχρι να προλάβει, ώστε για τα προγράμματα που τρέχουν ο χρόνος να μη σταματά ούτε να γυρίζει ποτέ πίσω. Μόνο ένα μεγάλο σφάλμα διορθώνεται αμέσως. Καθώς ένα ρολόι σταθεροποιείται, ένας πελάτης NTP ρωτά πιο αραιά, από κάθε 64 δευτερόλεπτα έως περίπου κάθε 17 λεπτά· τα Windows μόνα τους ελέγχουν το time.windows.com πολύ πιο αραιά, κάθε μερικές ώρες ή λιγότερο.","Small offsets":"Μικρές αποκλίσεις","Eased in gradually":"Ευθυγραμμίζονται σταδιακά","Large offsets":"Μεγάλες αποκλίσεις","Set at once":"Ρυθμίζονται αμέσως","Asks again":"Ρωτά ξανά","Less often as it settles":"Πιο αραιά καθώς σταθεροποιείται","CLOCK IN STEP":"ΡΟΛΟΙ ΣΕ ΣΥΜΦΩΝΙΑ","Leap, version, mode":"Leap, έκδοση, λειτουργία","Mode 3: a client asking for the time.":"Λειτουργία 3: ένας πελάτης που ζητά την ώρα.",Poll:"Poll","How often the client means to ask (2 to the power 6 seconds). It grows as the clock settles.":"Πόσο συχνά σκοπεύει να ρωτά ο πελάτης (2 στην 6η δευτερόλεπτα). Μεγαλώνει καθώς σταθεροποιείται το ρολόι.",Precision:"Ακρίβεια","How finely this clock can be read.":"Πόσο λεπτομερώς διαβάζεται αυτό το ρολόι.","Root delay":"Καθυστέρηση ρίζας","Root dispersion":"Διασπορά ρίζας","Reference ID":"ID αναφοράς","Reference time":"Χρόνος αναφοράς","Origin time":"Χρόνος προέλευσης","Receive time":"Χρόνος λήψης","Transmit time":"Χρόνος αποστολής","T1: when the request left, by the laptop’s own (wrong) clock.":"T1: πότε έφυγε το αίτημα, με το δικό του (λάθος) ρολόι του φορητού.","Mode 4: an answer from a server.":"Λειτουργία 4: απάντηση από διακομιστή.","Two steps from a reference clock: it follows a stratum 1 server, which has its own GPS or atomic clock.":"Δύο βήματα από ένα ρολόι αναφοράς: ακολουθεί διακομιστή stratum 1, που έχει δικό του GPS ή ατομικό ρολόι.","Round-trip time from this server to the reference clock.":"Χρόνος μετ’ επιστροφής από αυτόν τον διακομιστή ως το ρολόι αναφοράς.","How far off this server could be, at most.":"Πόσο μπορεί να απέχει το πολύ αυτός ο διακομιστής.","192.0.2.123 (its own time source)":"192.0.2.123 (η δική του πηγή ώρας)","When this server last set its own clock.":"Πότε ρύθμισε τελευταία φορά αυτός ο διακομιστής το ρολόι του.","T1, copied from the request: the client can match the answer to its question.":"T1, αντιγραμμένο από το αίτημα: ο πελάτης μπορεί να αντιστοιχίσει την απάντηση στην ερώτησή του.","T2: when the request arrived, by the server’s clock.":"T2: πότε έφτασε το αίτημα, με το ρολόι του διακομιστή.","T3: when this answer left.":"T3: πότε έφυγε αυτή η απάντηση.",Private:"Ιδιωτικό","Plain DNS":"Απλό DNS","DNS inside HTTPS":"DNS μέσα σε HTTPS","DNS queries inside HTTPS":"Ερωτήματα DNS μέσα σε HTTPS","Ordinary DNS travels in the clear: anyone on the same Wi-Fi, and your internet provider, can read every name you look up and even change the answers. DNS over HTTPS (DoH) sends the same DNS messages inside an encrypted HTTPS connection to the resolver, so on the way they look like any other web traffic. Browsers and operating systems can turn it on.":"Το συνηθισμένο DNS ταξιδεύει ανοιχτά: όποιος είναι στο ίδιο Wi-Fi, και ο πάροχος Διαδικτύου σας, μπορεί να διαβάσει κάθε όνομα που αναζητάτε και ακόμη να αλλάξει τις απαντήσεις. Το DNS over HTTPS (DoH) στέλνει τα ίδια μηνύματα DNS μέσα σε κρυπτογραφημένη σύνδεση HTTPS προς τον επιλυτή, ώστε στη διαδρομή να μοιάζουν με οποιαδήποτε άλλη κίνηση web. Browser και λειτουργικά συστήματα μπορούν να το ενεργοποιήσουν.","Ordinary DNS messages":"Συνηθισμένα μηνύματα DNS",Hides:"Κρύβει","Which names you look up":"Ποια ονόματα αναζητάτε",Similar:"Παρόμοιο","DNS over TLS (port 853)":"DNS over TLS (θύρα 853)","Looked up in private":"Αναζήτηση ιδιωτικά","Same question, sealed":"Ίδια ερώτηση, σφραγισμένη","The plain lookup could be read by anyone on the path. Over HTTPS the same DNS message was sealed inside TLS, readable only by the resolver. The resolver still sees every question, so the trust moves to it, and the site you then visit can still be seen by its address. Press REPLAY to watch it again.":"Την απλή αναζήτηση μπορούσε να τη διαβάσει οποιοσδήποτε στη διαδρομή. Μέσω HTTPS το ίδιο μήνυμα DNS σφραγίστηκε μέσα σε TLS, αναγνώσιμο μόνο από τον επιλυτή. Ο επιλυτής βλέπει ακόμη κάθε ερώτηση, οπότε η εμπιστοσύνη μεταφέρεται σε αυτόν, και ο ιστότοπος που επισκέπτεστε μετά φαίνεται ακόμη από τη διεύθυνσή του. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","On the way":"Στη διαδρομή","Only “HTTPS to dns.google”":"Μόνο «HTTPS προς dns.google»","The resolver":"Ο επιλυτής","Still sees every name":"Βλέπει ακόμη κάθε όνομα","The site’s address you then visit":"Τη διεύθυνση του ιστότοπου που επισκέπτεστε μετά","Can’t be changed on the way":"Δεν αλλάζει στη διαδρομή","Readable by anyone on the way":"Αναγνώσιμο από οποιονδήποτε στη διαδρομή","This is the lookup from the other lessons: a UDP packet to port 53 asking for www.example.com, and the answer. Neither is encrypted, so everyone on the café’s Wi-Fi, and the internet provider, can see which names the laptop looks up, and could even answer with a false address.":"Αυτή είναι η αναζήτηση από τα άλλα μαθήματα: ένα πακέτο UDP στη θύρα 53 που ζητά το www.example.com, και η απάντηση. Κανένα δεν είναι κρυπτογραφημένο, οπότε όλοι στο Wi-Fi του καφέ, και ο πάροχος Διαδικτύου, βλέπουν ποια ονόματα αναζητά ο φορητός, και θα μπορούσαν ακόμη να απαντήσουν με ψεύτικη διεύθυνση.","UDP port 53":"Θύρα UDP 53","Can be changed":"Μπορεί να αλλάξει","Yes, on the way":"Ναι, στη διαδρομή",readable:"αναγνώσιμο","ANYONE HERE CAN READ IT":"ΟΠΟΙΟΣΔΗΠΟΤΕ ΕΔΩ ΜΠΟΡΕΙ ΝΑ ΤΟ ΔΙΑΒΑΣΕΙ","An HTTPS Link":"Μια σύνδεση HTTPS","TCP and TLS to dns.google":"TCP και TLS προς dns.google","With DNS over HTTPS on, the browser opens an HTTPS connection to the resolver instead: TCP to port 443 and a TLS handshake for dns.google. It keeps this connection open and sends every lookup down it.":"Με ενεργό DNS over HTTPS, ο browser ανοίγει αντί γι’ αυτό σύνδεση HTTPS προς τον επιλυτή: TCP στη θύρα 443 και χειραψία TLS για το dns.google. Κρατά ανοιχτή αυτή τη σύνδεση και στέλνει από εκεί κάθε αναζήτηση.","dns.google (8.8.8.8)":"dns.google (8.8.8.8)","443, like any website":"443, όπως κάθε ιστότοπος","Kept open":"Μένει ανοιχτή","For every lookup":"Για κάθε αναζήτηση","Sealed Question":"Σφραγισμένη ερώτηση","A DNS message in an HTTP request":"Ένα μήνυμα DNS σε αίτημα HTTP","The question is the same DNS message as before. It goes in an HTTP/2 request, GET /dns-query?dns= followed by the message in base64url, asking for an answer in the type application/dns-message. Inside TLS, nobody on the way can read it.":"Η ερώτηση είναι το ίδιο μήνυμα DNS με πριν. Μπαίνει σε ένα αίτημα HTTP/2, GET /dns-query?dns= ακολουθούμενο από το μήνυμα σε base64url, ζητώντας απάντηση τύπου application/dns-message. Μέσα σε TLS, κανείς στη διαδρομή δεν μπορεί να το διαβάσει.",Format:"Μορφή","application/dns-message":"application/dns-message","Encrypted (TLS)":"Κρυπτογραφημένο (TLS)","DoH QUERY":"ΕΡΩΤΗΜΑ DoH","inside: GET /dns-query?dns=…":"μέσα: GET /dns-query?dns=…","Sealed Answer":"Σφραγισμένη απάντηση","The DNS answer in an HTTP response":"Η απάντηση DNS σε απάντηση HTTP","The resolver answers 200 with a body of type application/dns-message: the same DNS answer as the plain lookup, A 203.0.113.10. Because it arrives through TLS from dns.google, nobody on the way could have changed it.":"Ο επιλυτής απαντά 200 με σώμα τύπου application/dns-message: την ίδια απάντηση DNS με την απλή αναζήτηση, A 203.0.113.10. Επειδή φτάνει μέσω TLS από το dns.google, κανείς στη διαδρομή δεν θα μπορούσε να την αλλάξει.","200, application/dns-message":"200, application/dns-message","The DNS answer (49 bytes)":"Η απάντηση DNS (49 byte)",Tampering:"Αλλοίωση","Impossible on the way":"Αδύνατη στη διαδρομή","DoH ANSWER":"ΑΠΑΝΤΗΣΗ DoH","inside: A 203.0.113.10":"μέσα: A 203.0.113.10","What Still Shows":"Τι φαίνεται ακόμη","Hidden on the way, not from the resolver":"Κρυφό στη διαδρομή, όχι από τον επιλυτή","On the way, the lookups now look like any HTTPS traffic to dns.google. But the resolver itself reads every question, so you are trusting it instead of whoever runs your network. And the site you then visit is still seen by its IP address, and by its name in the TLS Client Hello unless it supports Encrypted Client Hello. DNS over TLS does the same job on port 853.":"Στη διαδρομή οι αναζητήσεις μοιάζουν πλέον με οποιαδήποτε κίνηση HTTPS προς το dns.google. Όμως ο ίδιος ο επιλυτής διαβάζει κάθε ερώτηση, οπότε εμπιστεύεστε αυτόν αντί για όποιον διαχειρίζεται το δίκτυό σας. Και ο ιστότοπος που επισκέπτεστε μετά φαίνεται ακόμη από τη διεύθυνση IP του, και από το όνομά του στο TLS Client Hello, εκτός αν υποστηρίζει Encrypted Client Hello. Το DNS over TLS κάνει την ίδια δουλειά στη θύρα 853.","Sees every name":"Βλέπει κάθε όνομα","Then visible":"Μετά ορατά","The site’s IP, maybe its name":"Η IP του ιστότοπου, ίσως το όνομα",Alternative:"Εναλλακτική","TRUST MOVES TO THE RESOLVER":"Η ΕΜΠΙΣΤΟΣΥΝΗ ΠΕΡΝΑ ΣΤΟΝ ΕΠΙΛΥΤΗ","Application Data (HTTP/2: DNS query)":"Application Data (HTTP/2: ερώτημα DNS)","Application Data (HTTP/2: DNS answer)":"Application Data (HTTP/2: απάντηση DNS)","HTTP/2: the connection preface and settings, then the request":"HTTP/2: το προοίμιο σύνδεσης και οι ρυθμίσεις, μετά το αίτημα","HTTP/2: settings, the response headers, then the DNS answer":"HTTP/2: ρυθμίσεις, οι κεφαλίδες απάντησης, μετά η απάντηση DNS","Signed Answers":"Υπογεγραμμένες απαντήσεις","Question and answer":"Ερώτηση και απάντηση","To the name servers":"Προς τους διακομιστές ονομάτων","Signed answers":"Υπογεγραμμένες απαντήσεις","DNS Security Extensions":"DNS Security Extensions","Plain DNS answers can be forged: whoever answers first, or sits in the middle, can send a false address. DNSSEC lets a resolver check that an answer really comes from the domain’s owner. Every set of records is signed; each zone’s key is vouched for by its parent, up to the root, whose key resolvers have built in. DNSSEC proves answers are genuine; it doesn’t hide them.":"Οι απλές απαντήσεις DNS μπορούν να πλαστογραφηθούν: όποιος απαντήσει πρώτος, ή βρίσκεται στη μέση, μπορεί να στείλει ψεύτικη διεύθυνση. Το DNSSEC επιτρέπει σε έναν επιλυτή να ελέγξει ότι μια απάντηση έρχεται πράγματι από τον κάτοχο του τομέα. Κάθε σύνολο εγγραφών είναι υπογεγραμμένο· για το κλειδί κάθε ζώνης εγγυάται η γονική της, ως τη ρίζα, της οποίας το κλειδί είναι ενσωματωμένο στους επιλυτές. Το DNSSEC αποδεικνύει ότι οι απαντήσεις είναι γνήσιες· δεν τις κρύβει.","Adds records":"Προσθέτει εγγραφές","Checked by":"Ελέγχεται από","Trust anchor":"Άγκυρα εμπιστοσύνης","The root’s key (built in)":"Το κλειδί της ρίζας (ενσωματωμένο)","Hides queries":"Κρύβει ερωτήματα","No (that’s DoH)":"Όχι (αυτό είναι το DoH)","Answer checked":"Η απάντηση ελέγχθηκε","A chain of signatures to the root":"Μια αλυσίδα υπογραφών ως τη ρίζα","The resolver followed a chain: the address was signed by example.com’s key, that key by its key-signing key, which .com vouched for with a signed DS record, and .com’s key is vouched for by the root, whose key the resolver has built in. A forged answer would have broken the chain. Press REPLAY to watch it again.":"Ο επιλυτής ακολούθησε μια αλυσίδα: η διεύθυνση ήταν υπογεγραμμένη με το κλειδί του example.com, αυτό το κλειδί με το κλειδί υπογραφής κλειδιών, για το οποίο εγγυήθηκε το .com με υπογεγραμμένη εγγραφή DS, και για το κλειδί του .com εγγυάται η ρίζα, της οποίας το κλειδί είναι ενσωματωμένο στον επιλυτή. Μια πλαστή απάντηση θα έσπαγε την αλυσίδα. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","Signatures checked":"Υπογραφές που ελέγχθηκαν","3 here (plus cached ones)":"3 εδώ (συν όσες είναι στην cache)","The AD flag":"Η σημαία AD","Forged answer":"Πλαστή απάντηση","Fails the check":"Αποτυγχάνει στον έλεγχο","Ask as Usual":"Ερώτηση όπως πάντα","The laptop’s question doesn’t change":"Η ερώτηση του φορητού δεν αλλάζει","The laptop asks its resolver for www.example.com as always. The checking happens at the resolver, which asks the name servers with the DNSSEC OK flag set: send the signatures too.":"Ο φορητός ζητά από τον επιλυτή του το www.example.com όπως πάντα. Ο έλεγχος γίνεται στον επιλυτή, που ρωτά τους διακομιστές ονομάτων με ενεργή τη σημαία DNSSEC OK: στείλτε και τις υπογραφές.","Checking done by":"Τον έλεγχο κάνει","The resolver (8.8.8.8)":"Ο επιλυτής (8.8.8.8)","Resolver sets":"Ο επιλυτής ορίζει","Signed Answer":"Υπογεγραμμένη απάντηση","An RRSIG comes with the A record":"Ένα RRSIG έρχεται με την εγγραφή A","The resolver already knows example.com’s name server from earlier lookups. That server sends the address with an RRSIG record: a signature over the A record, made with the zone’s private key. The RRSIG says which key signed it (key 47362, the zone-signing key) and when the signature expires. To check it the resolver needs that key.":"Ο επιλυτής ξέρει ήδη τον διακομιστή ονομάτων του example.com από προηγούμενες αναζητήσεις. Αυτός ο διακομιστής στέλνει τη διεύθυνση με μια εγγραφή RRSIG: υπογραφή πάνω στην εγγραφή A, με το ιδιωτικό κλειδί της ζώνης. Το RRSIG λέει ποιο κλειδί υπέγραψε (κλειδί 47362, το κλειδί υπογραφής ζώνης) και πότε λήγει η υπογραφή. Για να την ελέγξει, ο επιλυτής χρειάζεται αυτό το κλειδί.","RRSIG by key 47362":"RRSIG με κλειδί 47362",Valid:"Ισχύει","31 Oct to 21 Nov 2026":"31 Οκτ έως 21 Νοε 2026","signed by key 47362":"υπογεγραμμένο με κλειδί 47362","The Zone’s Keys":"Τα κλειδιά της ζώνης","DNSKEY records, signed too":"Εγγραφές DNSKEY, κι αυτές υπογεγραμμένες","The resolver asks for example.com’s keys. There are two: the zone-signing key (flags 256) that signed the A record, and the key-signing key (flags 257), which signs only the set of keys. With them the resolver checks both signatures. But who says these keys belong to example.com?":"Ο επιλυτής ζητά τα κλειδιά του example.com. Είναι δύο: το κλειδί υπογραφής ζώνης (σημαίες 256) που υπέγραψε την εγγραφή A, και το κλειδί υπογραφής κλειδιών (σημαίες 257), που υπογράφει μόνο το σύνολο των κλειδιών. Με αυτά ο επιλυτής ελέγχει και τις δύο υπογραφές. Όμως ποιος λέει ότι αυτά τα κλειδιά ανήκουν στο example.com;","47362, zone-signing (256)":"47362, υπογραφή ζώνης (256)","61845, key-signing (257)":"61845, υπογραφή κλειδιών (257)","Keys signed by":"Υπογραφή κλειδιών","The key-signing key":"Το κλειδί υπογραφής κλειδιών","two keys":"δύο κλειδιά","signed by key 61845":"υπογεγραμμένα με κλειδί 61845","Vouched by .com":"Εγγύηση από το .com","The parent’s DS record":"Η εγγραφή DS της γονικής ζώνης","The parent zone answers that. The .com servers hold a DS record for example.com: a hash of its key-signing key, signed with .com’s own key. If the hash matches key 61845, the keys are example.com’s, as far as .com is concerned.":"Αυτό το απαντά η γονική ζώνη. Οι διακομιστές .com κρατούν μια εγγραφή DS για το example.com: κατακερματισμό του κλειδιού υπογραφής κλειδιών του, υπογεγραμμένο με το κλειδί του .com. Αν ο κατακερματισμός ταιριάζει με το κλειδί 61845, τα κλειδιά είναι του example.com, κατά το .com.","Hash of key 61845":"Κατακερματισμός κλειδιού 61845","Signed by":"Υπογεγραμμένο από",".com (key 19718)":".com (κλειδί 19718)",Matches:"Ταιριάζει","hash of key 61845":"κατακερματισμός κλειδιού 61845","signed by .com":"υπογεγραμμένο από το .com","Up to the Root":"Ως τη ρίζα","Where the chain ends":"Πού τελειώνει η αλυσίδα","The same goes on above: .com’s keys are vouched for by a DS record in the root zone, signed by the root’s key, and that key is built into every validating resolver: the trust anchor. The resolver had those links cached, so the chain is complete: root → .com → example.com → the address.":"Το ίδιο συνεχίζεται από πάνω: για τα κλειδιά του .com εγγυάται μια εγγραφή DS στη ζώνη της ρίζας, υπογεγραμμένη με το κλειδί της ρίζας, και αυτό το κλειδί είναι ενσωματωμένο σε κάθε επιλυτή που επικυρώνει: η άγκυρα εμπιστοσύνης. Ο επιλυτής είχε αυτούς τους κρίκους στη cache, οπότε η αλυσίδα είναι πλήρης: ρίζα → .com → example.com → η διεύθυνση.",".com’s key":"Το κλειδί του .com","Vouched for by the root":"Εγγυάται η ρίζα","Root’s key":"Το κλειδί της ρίζας","Built in (trust anchor)":"Ενσωματωμένο (άγκυρα εμπιστοσύνης)","Root → .com → example.com":"Ρίζα → .com → example.com","CHAIN OF TRUST CHECKED":"Η ΑΛΥΣΙΔΑ ΕΜΠΙΣΤΟΣΥΝΗΣ ΕΛΕΓΧΘΗΚΕ","A Checked Answer":"Μια ελεγμένη απάντηση","With the AD flag":"Με τη σημαία AD","The resolver answers the laptop with the address and the AD flag: authenticated data. Had any signature failed, the laptop would have got an error (SERVFAIL) instead of a forged address. DNSSEC doesn’t hide the question or the answer; for that there is DNS over HTTPS.":"Ο επιλυτής απαντά στον φορητό με τη διεύθυνση και τη σημαία AD: πιστοποιημένα δεδομένα. Αν κάποια υπογραφή είχε αποτύχει, ο φορητός θα έπαιρνε σφάλμα (SERVFAIL) αντί για ψεύτικη διεύθυνση. Το DNSSEC δεν κρύβει ούτε την ερώτηση ούτε την απάντηση· γι’ αυτό υπάρχει το DNS over HTTPS.",Flag:"Σημαία","AD (authenticated data)":"AD (πιστοποιημένα δεδομένα)","Bad signature":"Λάθος υπογραφή","SERVFAIL, no address":"SERVFAIL, χωρίς διεύθυνση","AD: checked":"AD: ελέγχθηκε","UDP size 1232, DNSSEC OK = 1":"Μέγεθος UDP 1232, DNSSEC OK = 1","Says how big a UDP answer can be, and DNSSEC OK: send the signatures too.":"Λέει πόσο μεγάλη μπορεί να είναι μια απάντηση UDP, και DNSSEC OK: στείλτε και τις υπογραφές.","www.example.com RRSIG A, signed by example.com key 47362, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"www.example.com RRSIG A, υπογεγραμμένο με το κλειδί 47362 του example.com, ισχύει 2026-10-31 έως 2026-11-21 (TTL 3,600 s)","A signature over the records above it, made with the zone’s private key.":"Υπογραφή πάνω στις παραπάνω εγγραφές, με το ιδιωτικό κλειδί της ζώνης.","example.com, type DNSKEY, class IN":"example.com, τύπος DNSKEY, κλάση IN","example.com DNSKEY 256 (zone-signing key 47362), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 256 (κλειδί υπογραφής ζώνης 47362), ECDSA P-256 (TTL 3,600 s)","One of the zone’s public keys; whoever checks a signature needs it.":"Ένα από τα δημόσια κλειδιά της ζώνης· όποιος ελέγχει μια υπογραφή το χρειάζεται.","example.com DNSKEY 257 (key-signing key 61845), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 257 (κλειδί υπογραφής κλειδιών 61845), ECDSA P-256 (TTL 3,600 s)","example.com RRSIG DNSKEY, signed by example.com key 61845, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"example.com RRSIG DNSKEY, υπογεγραμμένο με το κλειδί 61845 του example.com, ισχύει 2026-10-31 έως 2026-11-21 (TTL 3,600 s)","example.com, type DS, class IN":"example.com, τύπος DS, κλάση IN","example.com DS key 61845, SHA-256 digest (TTL 86,400 s)":"example.com DS κλειδί 61845, σύνοψη SHA-256 (TTL 86,400 s)","A hash of the child zone’s key-signing key, kept and signed by the parent zone.":"Κατακερματισμός του κλειδιού υπογραφής κλειδιών της θυγατρικής ζώνης, που τον κρατά και τον υπογράφει η γονική ζώνη.","example.com RRSIG DS, signed by com key 19718, valid 2026-10-31 to 2026-11-21 (TTL 86,400 s)":"example.com RRSIG DS, υπογεγραμμένο με το κλειδί 19718 του com, ισχύει 2026-10-31 έως 2026-11-21 (TTL 86,400 s)","0x81a0: response, RD (recursion desired), RA (recursion available), AD (authenticated data)":"0x81a0: απάντηση, RD (ζητείται αναδρομή), RA (διαθέσιμη αναδρομή), AD (πιστοποιημένα δεδομένα)","Wi-Fi Logins":"Συνδέσεις Wi-Fi","EAP over Wi-Fi":"EAP μέσω Wi-Fi","RADIUS Server":"Διακομιστής RADIUS","RADIUS and 802.1X (Enterprise Wi-Fi)":"RADIUS και 802.1X (εταιρικό Wi-Fi)","At home everyone shares one Wi-Fi password. Offices, universities and eduroam use WPA2- or WPA3-Enterprise instead: each person or device logs in with its own account or certificate, checked by a RADIUS server. The access point knows no passwords. It passes the login, a series of EAP messages, between the laptop and the server, and lets the laptop in only when the server says yes.":"Στο σπίτι όλοι μοιράζονται έναν κωδικό Wi-Fi. Γραφεία, πανεπιστήμια και το eduroam χρησιμοποιούν αντί γι’ αυτό WPA2- ή WPA3-Enterprise: κάθε άτομο ή συσκευή συνδέεται με δικό του λογαριασμό ή πιστοποιητικό, που ελέγχει ένας διακομιστής RADIUS. Το σημείο πρόσβασης δεν ξέρει κωδικούς. Μεταφέρει τη σύνδεση, μια σειρά μηνυμάτων EAP, ανάμεσα στον φορητό και τον διακομιστή, και αφήνει τον φορητό να μπει μόνο όταν ο διακομιστής πει ναι.","EAP (here EAP-TLS)":"EAP (εδώ EAP-TLS)",Keys:"Κλειδιά","Different for every login":"Διαφορετικά σε κάθε σύνδεση","Let in":"Έγινε δεκτός","Its own login, its own keys":"Δική του σύνδεση, δικά του κλειδιά","The laptop proved who it was with its certificate. The RADIUS server checked it and told the access point to let it in, on VLAN 20, with a key for this login alone. The access point never saw a password: it only passed the messages on. Press REPLAY to watch it again.":"Ο φορητός απέδειξε ποιος ήταν με το πιστοποιητικό του. Ο διακομιστής RADIUS το έλεγξε και είπε στο σημείο πρόσβασης να τον αφήσει να μπει, στο VLAN 20, με κλειδί μόνο για αυτή τη σύνδεση. Το σημείο πρόσβασης δεν είδε ποτέ κωδικό: απλώς μετέφερε τα μηνύματα. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","EAP-TLS (certificates)":"EAP-TLS (πιστοποιητικά)","17, then the 4-way handshake":"17, μετά η χειραψία 4 βημάτων","20 (staff)":"20 (προσωπικό)","A user leaves":"Ένας χρήστης φεύγει","Disable one account":"Απενεργοποίηση ενός λογαριασμού","Who Are You?":"Ποιος είστε;","The access point asks for an identity":"Το σημείο πρόσβασης ζητά ταυτότητα","The laptop has joined “Office”, a WPA2-Enterprise network, but until it has logged in the access point passes on nothing except login messages. It asks who the laptop is with an EAP Identity request, and the laptop answers alex@example.org. The access point knows no accounts: it will pass the answer on to the RADIUS server.":"Ο φορητός μπήκε στο «Office», ένα δίκτυο WPA2-Enterprise, αλλά μέχρι να συνδεθεί το σημείο πρόσβασης δεν αφήνει να περάσει τίποτα εκτός από μηνύματα σύνδεσης. Ρωτά ποιος είναι ο φορητός με ένα αίτημα EAP Identity, και ο φορητός απαντά alex@example.org. Το σημείο πρόσβασης δεν ξέρει λογαριασμούς: θα προωθήσει την απάντηση στον διακομιστή RADIUS.","Before login":"Πριν από τη σύνδεση","Only EAP gets through":"Περνά μόνο το EAP","IDENTITY?":"ΤΑΥΤΟΤΗΤΑ;","EAP Identity request":"Αίτημα EAP Identity",IDENTITY:"ΤΑΥΤΟΤΗΤΑ","Ask RADIUS":"Ερώτηση στο RADIUS","The login goes to the server":"Η σύνδεση πηγαίνει στον διακομιστή","The access point copies the EAP message into a RADIUS Access-Request and sends it to the RADIUS server on UDP port 1812, with the laptop’s MAC address and the network’s name. A secret that only the two of them share protects every packet. The server answers with an Access-Challenge: the next message for the laptop, which is “start EAP-TLS”.":"Το σημείο πρόσβασης αντιγράφει το μήνυμα EAP σε ένα RADIUS Access-Request και το στέλνει στον διακομιστή RADIUS στη θύρα UDP 1812, με τη διεύθυνση MAC του φορητού και το όνομα του δικτύου. Ένα μυστικό που μοιράζονται μόνο οι δυο τους προστατεύει κάθε πακέτο. Ο διακομιστής απαντά με Access-Challenge: το επόμενο μήνυμα για τον φορητό, δηλαδή «ξεκίνα EAP-TLS».","RADIUS server, UDP 1812":"Διακομιστής RADIUS, UDP 1812","A shared secret":"Ένα κοινό μυστικό","from the access point":"από το σημείο πρόσβασης","EAP-TLS start":"έναρξη EAP-TLS","TLS START":"ΕΝΑΡΞΗ TLS","TLS Inside EAP":"TLS μέσα σε EAP","The server proves who it is":"Ο διακομιστής αποδεικνύει ποιος είναι","The laptop and the server now run a TLS 1.3 handshake inside EAP; the access point repacks each message, EAPOL over the air and RADIUS on the wire. The server sends its certificate and asks for the laptop’s. The laptop checks that it was issued by the company’s own certificate authority to radius.example.org. That check is what stops a fake access point from catching the login.":"Ο φορητός και ο διακομιστής κάνουν τώρα μια χειραψία TLS 1.3 μέσα σε EAP· το σημείο πρόσβασης ξανασυσκευάζει κάθε μήνυμα, EAPOL στον αέρα και RADIUS στο καλώδιο. Ο διακομιστής στέλνει το πιστοποιητικό του και ζητά του φορητού. Ο φορητός ελέγχει ότι εκδόθηκε από την αρχή πιστοποίησης της εταιρείας για το radius.example.org. Αυτός ο έλεγχος εμποδίζει ένα ψεύτικο σημείο πρόσβασης να πιάσει τη σύνδεση.","TLS 1.3, inside EAP":"TLS 1.3, μέσα σε EAP","Its certificate":"Το πιστοποιητικό του","Laptop checks":"Ο φορητός ελέγχει","Issuer and name":"Εκδότη και όνομα","TLS inside EAP":"TLS μέσα σε EAP","certificate (encrypted)":"πιστοποιητικό (κρυπτογραφημένο)","Laptop’s Proof":"Η απόδειξη του φορητού","Its own certificate":"Το δικό του πιστοποιητικό","The laptop answers with its own certificate, which the company issued for this user, and a signature made with its private key; the key never leaves the laptop. No password is involved. The server checks the certificate and the signature and looks up the account. Many networks, eduroam among them, use a password instead, sent inside the TLS tunnel (PEAP or EAP-TTLS).":"Ο φορητός απαντά με το δικό του πιστοποιητικό, που εξέδωσε η εταιρεία για αυτόν τον χρήστη, και μια υπογραφή με το ιδιωτικό του κλειδί· το κλειδί δεν φεύγει ποτέ από τον φορητό. Δεν εμπλέκεται κωδικός. Ο διακομιστής ελέγχει το πιστοποιητικό και την υπογραφή και αναζητά τον λογαριασμό. Πολλά δίκτυα, μεταξύ τους και το eduroam, χρησιμοποιούν αντί γι’ αυτό κωδικό, σταλμένο μέσα στο τούνελ TLS (PEAP ή EAP-TTLS).","Its certificate, a signature":"Το πιστοποιητικό του, μια υπογραφή","None with EAP-TLS":"Κανένας με EAP-TLS","Or instead":"Ή αντί γι’ αυτό","PEAP: a password in TLS":"PEAP: κωδικός μέσα σε TLS",CERTIFICATE:"ΠΙΣΤΟΠΟΙΗΤΙΚΟ","laptop’s certificate":"πιστοποιητικό του φορητού","Handshake Done":"Η χειραψία τελείωσε","Nothing more to send":"Τίποτα άλλο για αποστολή","With TLS 1.3 the server then sends one tiny encrypted message, a single zero byte, to say the handshake is over, and the laptop answers with an empty EAP message. Both ends now hold the same 64 bytes of key material, worked out during the handshake. Nobody on the way has seen it, not even the access point.":"Με το TLS 1.3 ο διακομιστής στέλνει μετά ένα μικροσκοπικό κρυπτογραφημένο μήνυμα, ένα μόνο μηδενικό byte, για να πει ότι η χειραψία τελείωσε, και ο φορητός απαντά με ένα κενό μήνυμα EAP. Και τα δύο άκρα έχουν πλέον τα ίδια 64 byte υλικού κλειδιού, που υπολογίστηκαν κατά τη χειραψία. Κανείς στη διαδρομή δεν το είδε, ούτε καν το σημείο πρόσβασης.","Server sends":"Ο διακομιστής στέλνει","One encrypted 0 byte":"Ένα κρυπτογραφημένο byte 0","An empty EAP-TLS reply":"Μια κενή απάντηση EAP-TLS","Both hold":"Και τα δύο έχουν","64 bytes of key material":"64 byte υλικού κλειδιού","handshake over":"η χειραψία τελείωσε","one encrypted byte":"ένα κρυπτογραφημένο byte",EMPTY:"ΚΕΝΟ","nothing more":"τίποτα άλλο","empty EAP-TLS":"κενό EAP-TLS","And a key for the access point":"Και ένα κλειδί για το σημείο πρόσβασης","The server answers Access-Accept. Inside are EAP Success for the laptop; the first 32 bytes of the key material for the access point, encrypted with the shared secret (MS-MPPE-Recv-Key); and VLAN 20, so this user lands on the staff network. The same access point could put another user on another VLAN.":"Ο διακομιστής απαντά Access-Accept. Μέσα υπάρχουν το EAP Success για τον φορητό· τα πρώτα 32 byte του υλικού κλειδιού για το σημείο πρόσβασης, κρυπτογραφημένα με το κοινό μυστικό (MS-MPPE-Recv-Key)· και το VLAN 20, ώστε αυτός ο χρήστης να καταλήξει στο δίκτυο του προσωπικού. Το ίδιο σημείο πρόσβασης θα μπορούσε να βάλει άλλον χρήστη σε άλλο VLAN.","AP gets":"Το AP παίρνει","The key (MS-MPPE-Recv-Key)":"Το κλειδί (MS-MPPE-Recv-Key)","key, VLAN 20":"κλειδί, VLAN 20","4-Way Handshake":"Χειραψία 4 βημάτων","As at home, from a different key":"Όπως στο σπίτι, από άλλο κλειδί","The access point and the laptop now hold the same 32-byte key, the PMK. What follows is the 4-way handshake from the Wi-Fi lesson; only the PMK’s origin differs. At home it comes from the shared password, here from this one login, so every user gets different keys.":"Το σημείο πρόσβασης και ο φορητός έχουν πλέον το ίδιο κλειδί 32 byte, το PMK. Ακολουθεί η χειραψία 4 βημάτων του μαθήματος για το Wi-Fi· διαφέρει μόνο η προέλευση του PMK. Στο σπίτι προέρχεται από τον κοινό κωδικό, εδώ από αυτή τη μία σύνδεση, οπότε κάθε χρήστης παίρνει διαφορετικά κλειδιά.","PMK from":"PMK από","This login":"Αυτή τη σύνδεση","At home":"Στο σπίτι","From the shared password":"Από τον κοινό κωδικό","Encrypted data (CCMP)":"Κρυπτογραφημένα δεδομένα (CCMP)","group key, MIC":"κλειδί ομάδας, MIC","Why Enterprise":"Γιατί Enterprise","One account per person":"Ένας λογαριασμός ανά άτομο","When someone leaves, their account is disabled and nobody else changes a password. Every login gets its own keys, so users can’t read each other’s traffic, and the RADIUS server records who connected and when. eduroam works the same way: a visitor’s login for user@their-university is passed from RADIUS server to RADIUS server until it reaches their own university.":"Όταν κάποιος φεύγει, ο λογαριασμός του απενεργοποιείται και κανείς άλλος δεν αλλάζει κωδικό. Κάθε σύνδεση παίρνει δικά της κλειδιά, οπότε οι χρήστες δεν μπορούν να διαβάσουν ο ένας την κίνηση του άλλου, και ο διακομιστής RADIUS καταγράφει ποιος συνδέθηκε και πότε. Το eduroam λειτουργεί με τον ίδιο τρόπο: η σύνδεση ενός επισκέπτη για χρήστης@το-πανεπιστήμιό-του περνά από διακομιστή RADIUS σε διακομιστή RADIUS μέχρι να φτάσει στο δικό του πανεπιστήμιο.","Different for every user":"Διαφορετικά για κάθε χρήστη",eduroam:"eduroam","Login passed home":"Η σύνδεση προωθείται στο σπίτι","ONE ACCOUNT PER PERSON":"ΕΝΑΣ ΛΟΓΑΡΙΑΣΜΟΣ ΑΝΑ ΑΤΟΜΟ","Access-Challenge id=82: Server Hello, certificate":"Access-Challenge id=82: Server Hello, πιστοποιητικό","Request, TLS EAP: Server Hello, encrypted handshake":"Request, TLS EAP: Server Hello, κρυπτογραφημένη χειραψία","Response, TLS EAP: encrypted handshake":"Response, TLS EAP: κρυπτογραφημένη χειραψία","Access-Request id=83: encrypted handshake":"Access-Request id=83: κρυπτογραφημένη χειραψία","0 (EAP packet)":"0 (πακέτο EAP)","Carries an EAP message. The access point copies it into a RADIUS packet for the server, and back.":"Μεταφέρει ένα μήνυμα EAP. Το σημείο πρόσβασης το αντιγράφει σε πακέτο RADIUS για τον διακομιστή, και αντίστροφα.","A response carries the same number as the request it answers.":"Μια απάντηση φέρει τον ίδιο αριθμό με το αίτημα στο οποίο απαντά.","Who are you?":"Ποιος είστε;","Who is logging in. The realm after the @ tells the RADIUS server (or the servers that pass requests on) where the account lives.":"Ποιος συνδέεται. Το realm μετά το @ λέει στον διακομιστή RADIUS (ή στους διακομιστές που προωθούν αιτήματα) πού βρίσκεται ο λογαριασμός.","Seen on the office network":"Όπως φαίνεται στο δίκτυο του γραφείου","The server. It is on the same network, so the frame goes straight to it, not through the router.":"Ο διακομιστής. Είναι στο ίδιο δίκτυο, οπότε το πλαίσιο πηγαίνει κατευθείαν σε αυτόν, όχι μέσω του δρομολογητή.","The access point’s wired port.":"Η ενσύρματη θύρα του σημείου πρόσβασης.","Should this device be let in?":"Να γίνει δεκτή αυτή η συσκευή;","A reply carries the number of the request it answers.":"Μια απάντηση φέρει τον αριθμό του αιτήματος στο οποίο απαντά.",Authenticator:"Authenticator","Random, new in every request.":"Τυχαίο, νέο σε κάθε αίτημα.",Attributes:"Χαρακτηριστικά","An HMAC-MD5 of the whole packet, keyed with the shared secret. Every packet that carries EAP must have one; since the Blast-RADIUS attack of 2024, it goes first.":"Ένα HMAC-MD5 όλου του πακέτου, με κλειδί το κοινό μυστικό. Κάθε πακέτο που φέρει EAP πρέπει να έχει ένα· από την επίθεση Blast-RADIUS του 2024, μπαίνει πρώτο.","The identity the laptop gave.":"Η ταυτότητα που έδωσε ο φορητός.","The access point asking.":"Το σημείο πρόσβασης που ρωτά.","The access point’s MAC address and the network’s name.":"Η διεύθυνση MAC του σημείου πρόσβασης και το όνομα του δικτύου.","The laptop’s MAC address.":"Η διεύθυνση MAC του φορητού.","Keep each EAP message small enough for one frame.":"Κάθε μήνυμα EAP να είναι αρκετά μικρό για ένα πλαίσιο.","The EAP packet, passed on unchanged.":"Το πακέτο EAP, προωθημένο αμετάβλητο.","The server’s network card.":"Η κάρτα δικτύου του διακομιστή.","Not yet: here is the next message for the device.":"Όχι ακόμη: ορίστε το επόμενο μήνυμα για τη συσκευή.","A hash of this reply, the request’s authenticator and the shared secret: only the real server could have made it.":"Κατακερματισμός αυτής της απάντησης, του authenticator του αιτήματος και του κοινού μυστικού: μόνο ο πραγματικός διακομιστής θα μπορούσε να τον φτιάξει.","A TLS handshake, carried inside EAP.":"Μια χειραψία TLS, μεταφερμένη μέσα σε EAP.","0x20 (start)":"0x20 (έναρξη)","Start: the server is ready for the laptop’s Client Hello.":"Έναρξη: ο διακομιστής είναι έτοιμος για το Client Hello του φορητού.","The server’s bookmark for this login: the access point sends it back with the next request.":"Ο σελιδοδείκτης του διακομιστή για αυτή τη σύνδεση: το σημείο πρόσβασης τον στέλνει πίσω με το επόμενο αίτημα.","0x80 (length included)":"0x80 (περιλαμβάνεται μήκος)","TLS length":"Μήκος TLS","Longer TLS messages are split into pieces of about 1,000 bytes, each one acknowledged.":"Τα μακρύτερα μηνύματα TLS χωρίζονται σε κομμάτια περίπου 1,000 byte, το καθένα επιβεβαιωμένο.","TLS records":"Εγγραφές TLS","The same TLS records as over TCP, only carried in EAP.":"Οι ίδιες εγγραφές TLS όπως πάνω από TCP, απλώς μεταφερμένες σε EAP.","Client Hello: TLS 1.3, the laptop’s key share":"Client Hello: TLS 1.3, το μερίδιο κλειδιού του φορητού","The EAP packet (1,008 bytes), split over 4 attributes of up to 253 bytes.":"Το πακέτο EAP (1,008 byte), μοιρασμένο σε 4 χαρακτηριστικά έως 253 byte.","EAP-Message, continued":"EAP-Message, συνέχεια","TLS records, continued":"Εγγραφές TLS, συνέχεια","Server Hello: TLS 1.3, the server’s key share":"Server Hello: TLS 1.3, το μερίδιο κλειδιού του διακομιστή","Encrypted: certificate for radius.example.org, a request for the laptop’s certificate, signature, Finished":"Κρυπτογραφημένα: πιστοποιητικό για το radius.example.org, αίτημα για το πιστοποιητικό του φορητού, υπογραφή, Finished","Encrypted: the laptop’s certificate (for alex@example.org), its signature, Finished":"Κρυπτογραφημένα: το πιστοποιητικό του φορητού (για alex@example.org), η υπογραφή του, Finished","The EAP packet (822 bytes), split over 4 attributes of up to 253 bytes.":"Το πακέτο EAP (822 byte), μοιρασμένο σε 4 χαρακτηριστικά έως 253 byte.","Encrypted: one 0 byte, the “commitment message”: no more handshake messages":"Κρυπτογραφημένο: ένα byte 0, το «μήνυμα δέσμευσης»: όχι άλλα μηνύματα χειραψίας","0x00 (no data)":"0x00 (χωρίς δεδομένα)","Nothing to send: an empty answer that keeps the conversation going.":"Τίποτα για αποστολή: μια κενή απάντηση που κρατά τη συζήτηση σε εξέλιξη.","Yes: let it in.":"Ναι: αφήστε το να μπει.","Put this device on VLAN 20, the staff network.":"Βάλτε αυτή τη συσκευή στο VLAN 20, το δίκτυο του προσωπικού.","The first 32 bytes of the key material that both ends of the TLS handshake worked out. The access point uses it as the PMK, the starting key for the 4-way handshake.":"Τα πρώτα 32 byte του υλικού κλειδιού που υπολόγισαν και τα δύο άκρα της χειραψίας TLS. Το σημείο πρόσβασης το χρησιμοποιεί ως PMK, το αρχικό κλειδί της χειραψίας 4 βημάτων.","Salt, encrypted key":"Salt, κρυπτογραφημένο κλειδί","Encrypted with the shared secret, so only the access point can read the key.":"Κρυπτογραφημένο με το κοινό μυστικό, ώστε μόνο το σημείο πρόσβασης να διαβάζει το κλειδί.","The next 32 bytes of the key material. Wi-Fi doesn’t need them.":"Τα επόμενα 32 byte του υλικού κλειδιού. Το Wi-Fi δεν τα χρειάζεται.","The RADIUS server accepted the login.":"Ο διακομιστής RADIUS δέχτηκε τη σύνδεση.","1: 802.1X (logins checked by a RADIUS server)":"1: 802.1X (συνδέσεις που ελέγχει διακομιστής RADIUS)","Shared Folders":"Κοινόχρηστοι φάκελοι",Responses:"Απαντήσεις","nas (File Server)":"nas (διακομιστής αρχείων)","Server Message Block (SMB 3)":"Server Message Block (SMB 3)","SMB is how Windows shares files and printers: \\\\server\\share in File Explorer, a mapped network drive, a NAS at home. macOS and Linux speak it too. Over one TCP connection to port 445 the client agrees on a version, logs in and connects to a share, then opens, reads, writes and closes files with numbered requests.":"Το SMB είναι ο τρόπος με τον οποίο τα Windows μοιράζονται αρχεία και εκτυπωτές: \\\\server\\share στην Εξερεύνηση αρχείων, μια αντιστοιχισμένη μονάδα δικτύου, ένα NAS στο σπίτι. Το μιλούν και τα macOS και Linux. Πάνω από μία σύνδεση TCP στη θύρα 445 ο πελάτης συμφωνεί μια έκδοση, συνδέεται και ανοίγει έναν κοινόχρηστο πόρο, και μετά ανοίγει, διαβάζει, γράφει και κλείνει αρχεία με αριθμημένα αιτήματα.","TCP 445":"TCP 445","NTLM or Kerberos":"NTLM ή Kerberos",Protection:"Προστασία","Signing, optional encryption":"Υπογραφή, προαιρετική κρυπτογράφηση","File read":"Το αρχείο διαβάστηκε","Seven requests, one connection":"Επτά αιτήματα, μία σύνδεση","Over one TCP connection the laptop agreed on SMB 3.1.1, logged in with NTLM without sending its password, connected to the share and read a 240 KB file with a single request. Every message after the login was signed. Press REPLAY to watch it again.":"Πάνω από μία σύνδεση TCP ο φορητός συμφώνησε SMB 3.1.1, συνδέθηκε με NTLM χωρίς να στείλει τον κωδικό του, άνοιξε τον κοινόχρηστο πόρο και διάβασε ένα αρχείο 240 KB με ένα μόνο αίτημα. Κάθε μήνυμα μετά τη σύνδεση ήταν υπογεγραμμένο. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","7 on one connection":"7 σε μία σύνδεση","NTLMv2, no password sent":"NTLMv2, χωρίς αποστολή κωδικού","240 KB in 169 segments":"240 KB σε 169 τμήματα",Signed:"Υπογεγραμμένα","Every message after login":"Κάθε μήνυμα μετά τη σύνδεση","Port 445":"Θύρα 445","A TCP connection to the NAS":"Μια σύνδεση TCP προς το NAS","The laptop opens \\\\nas\\Documents, a shared folder on the NAS. It finds nas’s address with a local name lookup and opens a TCP connection to port 445. The packets pass through the home router to the NAS and never leave the home network.":"Ο φορητός ανοίγει το \\\\nas\\Documents, έναν κοινόχρηστο φάκελο στο NAS. Βρίσκει τη διεύθυνση του nas με τοπική αναζήτηση ονόματος και ανοίγει σύνδεση TCP στη θύρα 445. Τα πακέτα περνούν από τον οικιακό δρομολογητή στο NAS και δεν φεύγουν ποτέ από το οικιακό δίκτυο.","nas, 192.168.1.20":"nas, 192.168.1.20",Stays:"Μένει","On the home network":"Στο οικιακό δίκτυο",Negotiate:"Negotiate","Agree on a version":"Συμφωνία έκδοσης","The laptop lists every SMB version it speaks, from 2.0.2 to 3.1.1, and says it requires signing. The NAS picks 3.1.1, the newest. Both sides keep a SHA-512 hash of everything exchanged from here until the login is done. It goes into the keys, so if anyone changed these messages on the way, to force an older version for instance, the login would fail.":"Ο φορητός απαριθμεί κάθε έκδοση SMB που μιλά, από 2.0.2 έως 3.1.1, και λέει ότι απαιτεί υπογραφή. Το NAS επιλέγει την 3.1.1, τη νεότερη. Και οι δύο πλευρές κρατούν έναν κατακερματισμό SHA-512 όσων ανταλλάσσουν από εδώ ως το τέλος της σύνδεσης. Μπαίνει στα κλειδιά, οπότε αν κάποιος άλλαζε αυτά τα μηνύματα στη διαδρομή, για να επιβάλει για παράδειγμα μια παλαιότερη έκδοση, η σύνδεση θα αποτύγχανε.",Chosen:"Επιλέχθηκε","Tamper check":"Έλεγχος αλλοίωσης","SHA-512 of the exchange":"SHA-512 της ανταλλαγής","signing required":"απαιτείται υπογραφή","NTLM Challenge":"Πρόκληση NTLM","The NAS sends a random number":"Το NAS στέλνει έναν τυχαίο αριθμό","A home NAS has no domain, so there is no Kerberos: the laptop logs in with NTLM. Its first SESSION_SETUP says it wants to log in, and the NAS answers “more processing required” with a challenge of 8 random bytes. It also gives this login a session ID.":"Ένα οικιακό NAS δεν έχει τομέα, οπότε δεν υπάρχει Kerberos: ο φορητός συνδέεται με NTLM. Το πρώτο του SESSION_SETUP λέει ότι θέλει να συνδεθεί, και το NAS απαντά «απαιτείται περαιτέρω επεξεργασία» με μια πρόκληση 8 τυχαίων byte. Δίνει επίσης σε αυτή τη σύνδεση ένα ID συνεδρίας.","NTLMv2 (in a domain: Kerberos)":"NTLMv2 (σε τομέα: Kerberos)",Challenge:"Πρόκληση","More processing required":"Απαιτείται περαιτέρω επεξεργασία","NTLM: let me log in":"NTLM: άφησέ με να συνδεθώ","a session ID":"ένα ID συνεδρίας","NTLM Response":"Απάντηση NTLM","Proof, not the password":"Απόδειξη, όχι ο κωδικός","The laptop answers with the user name, alex, and an NTLMv2 response: an HMAC of the challenge and a few other values, keyed with a hash of the password. The NAS has the same hash and works out the same value. The password itself never crosses the network, and both sides now have a session key to sign messages with.":"Ο φορητός απαντά με το όνομα χρήστη, alex, και μια απάντηση NTLMv2: ένα HMAC της πρόκλησης και μερικών άλλων τιμών, με κλειδί έναν κατακερματισμό του κωδικού. Το NAS έχει τον ίδιο κατακερματισμό και υπολογίζει την ίδια τιμή. Ο ίδιος ο κωδικός δεν περνά ποτέ από το δίκτυο, και οι δύο πλευρές έχουν πλέον ένα κλειδί συνεδρίας για να υπογράφουν μηνύματα.",User:"Χρήστης",alex:"alex",Sends:"Στέλνει","An HMAC of the challenge":"Ένα HMAC της πρόκλησης","Never sent":"Δεν στέλνεται ποτέ","user alex":"χρήστης alex","NTLMv2 response":"απάντηση NTLMv2","LOGGED IN":"ΣΥΝΔΕΘΗΚΕ",signed:"υπογεγραμμένο","Connect a Share":"Σύνδεση κοινόχρηστου πόρου","\\\\nas\\Documents":"\\\\nas\\Documents","TREE_CONNECT asks for the share by its full name, \\\\nas\\Documents. The answer gives it a tree ID and says what this user may do there. Every message is now signed: each carries a tag over the whole message, made with a key from the login, so a changed or forged message would be caught.":"Το TREE_CONNECT ζητά τον κοινόχρηστο πόρο με το πλήρες όνομά του, \\\\nas\\Documents. Η απάντηση του δίνει ένα tree ID και λέει τι μπορεί να κάνει εκεί αυτός ο χρήστης. Κάθε μήνυμα είναι πλέον υπογεγραμμένο: το καθένα φέρει μια ετικέτα πάνω σε όλο το μήνυμα, με κλειδί από τη σύνδεση, ώστε ένα αλλαγμένο ή πλαστό μήνυμα να πιάνεται.",Share:"Κοινόχρηστος πόρος","Every message":"Κάθε μήνυμα","Signed (AES-GMAC)":"Υπογεγραμμένο (AES-GMAC)","tree ID 0x2a51":"tree ID 0x2a51","Open the File":"Άνοιγμα του αρχείου","With CREATE":"Με CREATE","SMB opens files with CREATE, which can also make new ones. This one opens report.pdf to read it, and fails if it doesn’t exist. The answer gives the file’s size and dates, and a file ID that the read and the close will use.":"Το SMB ανοίγει αρχεία με CREATE, που μπορεί και να φτιάξει νέα. Αυτό ανοίγει το report.pdf για ανάγνωση και αποτυγχάνει αν δεν υπάρχει. Η απάντηση δίνει το μέγεθος και τις ημερομηνίες του αρχείου, και ένα file ID που θα χρησιμοποιήσουν η ανάγνωση και το κλείσιμο.",Handle:"Handle","A 16-byte file ID":"Ένα file ID 16 byte","open to read":"άνοιγμα για ανάγνωση","file ID":"file ID","Read It":"Ανάγνωση","The whole file in one request":"Όλο το αρχείο σε ένα αίτημα","One READ asks for the whole file, 245,760 bytes from offset 0. It costs 4 credits, one for every 64 KB. The answer is 80 bytes of headers and then the file, in 169 TCP segments. A bigger file is read with several requests, many on their way at once, as far as the credits allow.":"Ένα μόνο READ ζητά όλο το αρχείο, 245,760 byte από τη θέση 0. Κοστίζει 4 credits, ένα ανά 64 KB. Η απάντηση είναι 80 byte κεφαλίδων και μετά το αρχείο, σε 169 τμήματα TCP. Ένα μεγαλύτερο αρχείο διαβάζεται με πολλά αιτήματα, πολλά καθ’ οδόν ταυτόχρονα, όσο επιτρέπουν τα credits.","245,760 bytes from 0":"245,760 byte από 0",Credits:"Credits","4 (one per 64 KB)":"4 (ένα ανά 64 KB)","Arrives in":"Φτάνει σε","from offset 0":"από τη θέση 0","Close the File":"Κλείσιμο του αρχείου","And keep 445 at home":"Και κρατήστε τη 445 μέσα στο σπίτι","CLOSE hands the file ID back; the connection stays open for the next file. SMB 3 can also encrypt every message with AES-GCM, for one share or a whole server. Here only signing protects the messages, so anyone on the network could read the file as it passed. Port 445 should never be reachable from the internet: the WannaCry worm (2017) spread through a flaw in the old SMB1.":"Το CLOSE επιστρέφει το file ID· η σύνδεση μένει ανοιχτή για το επόμενο αρχείο. Το SMB 3 μπορεί επίσης να κρυπτογραφεί κάθε μήνυμα με AES-GCM, για έναν κοινόχρηστο πόρο ή έναν ολόκληρο διακομιστή. Εδώ τα μηνύματα τα προστατεύει μόνο η υπογραφή, οπότε οποιοσδήποτε στο δίκτυο θα μπορούσε να διαβάσει το αρχείο καθώς περνά. Η θύρα 445 δεν πρέπει ποτέ να είναι προσβάσιμη από το Διαδίκτυο: το σκουλήκι WannaCry (2017) εξαπλώθηκε μέσω ενός κενού στο παλιό SMB1.","SMB 3: AES-GCM, optional":"SMB 3: AES-GCM, προαιρετικά","Switched off: old, unsafe":"Απενεργοποιημένο: παλιό, μη ασφαλές","Never open to the internet":"Ποτέ ανοιχτό στο Διαδίκτυο",done:"έτοιμο","KEEP PORT 445 OFF THE INTERNET":"ΚΡΑΤΗΣΤΕ ΤΗ ΘΥΡΑ 445 ΜΑΚΡΙΑ ΑΠΟ ΤΟ ΔΙΑΔΙΚΤΥΟ","On port 445 every SMB message starts with its length, a leftover from NetBIOS.":"Στη θύρα 445 κάθε μήνυμα SMB ξεκινά με το μήκος του, απομεινάρι του NetBIOS.",'0xFE "SMB" (SMB2 or 3)':'0xFE "SMB" (SMB2 ή 3)','SMB1 messages started 0xFF "SMB". SMB1 is switched off in Windows today.':'Τα μηνύματα SMB1 ξεκινούσαν με 0xFF "SMB". Το SMB1 είναι σήμερα απενεργοποιημένο στα Windows.',"Header size":"Μέγεθος κεφαλίδας","Credit charge":"Χρέωση credits","Channel sequence":"Ακολουθία καναλιού","Credits asked for":"Ζητούμενα credits","Credits limit how many requests the laptop may have waiting at once. The server hands them out.":"Τα credits περιορίζουν πόσα αιτήματα μπορεί να έχει ο φορητός σε αναμονή ταυτόχρονα. Τα μοιράζει ο διακομιστής.","Next command":"Επόμενη εντολή","0 (none chained)":"0 (καμία αλυσίδα)","Counts up with each request; the response carries the same number.":"Αυξάνεται με κάθε αίτημα· η απάντηση φέρει τον ίδιο αριθμό.","0 (no share yet)":"0 (ακόμη χωρίς πόρο)","Session ID":"ID συνεδρίας","0 (not logged in yet)":"0 (ακόμη χωρίς σύνδεση)","zeros (not signed)":"μηδενικά (χωρίς υπογραφή)","Structure size":"Μέγεθος δομής","Dialect count":"Πλήθος διαλέκτων","Security mode":"Λειτουργία ασφαλείας","0x0002 (signing required)":"0x0002 (απαιτείται υπογραφή)","Recent versions of Windows 11 require signing by default.":"Οι πρόσφατες εκδόσεις των Windows 11 απαιτούν υπογραφή από προεπιλογή.","DFS, leases, large reads and writes, multichannel, persistent handles, directory leases, encryption.":"DFS, leases, μεγάλες αναγνώσεις και εγγραφές, πολλαπλά κανάλια, μόνιμα handles, leases καταλόγων, κρυπτογράφηση.","Client GUID":"GUID πελάτη","A random ID for this computer.":"Ένα τυχαίο ID για αυτόν τον υπολογιστή.","Negotiate contexts":"Πλαίσια διαπραγμάτευσης","at offset 112, 4 of them":"στη θέση 112, 4 συνολικά",Dialects:"Διάλεκτοι","Every version the laptop speaks. The server picks the newest it also knows.":"Κάθε έκδοση που μιλά ο φορητός. Ο διακομιστής επιλέγει τη νεότερη που ξέρει κι αυτός.",Contexts:"Πλαίσια","SMB 3.1.1 extras, each in its own small block.":"Πρόσθετα του SMB 3.1.1, το καθένα στο δικό του μικρό μπλοκ.","Pre-authentication integrity: SHA-512, and a 32-byte random salt":"Ακεραιότητα πριν από την πιστοποίηση: SHA-512, και ένα τυχαίο salt 32 byte","Encryption: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM":"Κρυπτογράφηση: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM","Signing: AES-GMAC, AES-CMAC, HMAC-SHA256":"Υπογραφή: AES-GMAC, AES-CMAC, HMAC-SHA256","The server’s name: nas":"Το όνομα του διακομιστή: nas","Credits granted":"Credits που δόθηκαν","0x00000001 (response)":"0x00000001 (απάντηση)","0x0001 (signing enabled)":"0x0001 (υπογραφή ενεργή)",Dialect:"Διάλεκτος","The newest version both sides speak.":"Η νεότερη έκδοση που μιλούν και οι δύο πλευρές.","Context count":"Πλήθος πλαισίων","Server GUID":"GUID διακομιστή","Leases, large reads and writes.":"Leases, μεγάλες αναγνώσεις και εγγραφές.","Largest read, write":"Μέγιστη ανάγνωση, εγγραφή","8 MB each":"8 MB η καθεμιά","The most data one request may carry: transactions, reads and writes.":"Τα περισσότερα δεδομένα που μπορεί να φέρει ένα αίτημα: συναλλαγές, αναγνώσεις και εγγραφές.","System time":"Ώρα συστήματος","7 Nov 2026, 09:41:00":"7 Νοε 2026, 09:41:00","Security buffer":"Buffer ασφαλείας","Context offset":"Θέση πλαισίων","Security blob":"Blob ασφαλείας","GSS-API and SPNEGO wrapping, around NTLMSSP.":"Περιτύλιγμα GSS-API και SPNEGO, γύρω από το NTLMSSP.","The login methods the server accepts: NTLMSSP":"Οι μέθοδοι σύνδεσης που δέχεται ο διακομιστής: NTLMSSP","Pre-authentication integrity: SHA-512, and the server’s own salt":"Ακεραιότητα πριν από την πιστοποίηση: SHA-512, και το salt του διακομιστή","Encryption: AES-128-GCM":"Κρυπτογράφηση: AES-128-GCM","Signing: AES-GMAC":"Υπογραφή: AES-GMAC","0x02 (signing required)":"0x02 (απαιτείται υπογραφή)","Previous session":"Προηγούμενη συνεδρία","NTLMSSP NEGOTIATE: the NTLM options the laptop supports":"NTLMSSP NEGOTIATE: οι επιλογές NTLM που υποστηρίζει ο φορητός","Not an error: the login needs another round.":"Δεν είναι σφάλμα: η σύνδεση χρειάζεται άλλον έναν γύρο.","The server’s number for this login, from now on in every message.":"Ο αριθμός του διακομιστή για αυτή τη σύνδεση, από εδώ και πέρα σε κάθε μήνυμα.","Session flags":"Σημαίες συνεδρίας","NTLMSSP CHALLENGE: an 8-byte random challenge":"NTLMSSP CHALLENGE: μια τυχαία πρόκληση 8 byte","The NAS’s names and its clock":"Τα ονόματα του NAS και το ρολόι του","NTLMSSP AUTH: user alex, computer ALEX-PC":"NTLMSSP AUTH: χρήστης alex, υπολογιστής ALEX-PC","NTLMv2 response: an HMAC of the challenge, keyed with a hash of the password":"Απάντηση NTLMv2: ένα HMAC της πρόκλησης, με κλειδί έναν κατακερματισμό του κωδικού","A key for signing, encrypted":"Ένα κλειδί για υπογραφή, κρυπτογραφημένο","0x00000009 (response, signed)":"0x00000009 (απάντηση, υπογεγραμμένη)","AES-GMAC over the whole message, with a key from the login: a changed or forged message would be caught.":"AES-GMAC πάνω σε όλο το μήνυμα, με κλειδί από τη σύνδεση: ένα αλλαγμένο ή πλαστό μήνυμα θα πιανόταν.","The login is complete.":"Η σύνδεση ολοκληρώθηκε.","0x00000008 (signed)":"0x00000008 (υπογεγραμμένο)","Server and share name, in UTF-16.":"Όνομα διακομιστή και πόρου, σε UTF-16.","The number for this share; later requests carry it.":"Ο αριθμός αυτού του πόρου· τα επόμενα αιτήματα τον φέρουν.","Share type":"Τύπος πόρου","1 (disk)":"1 (δίσκος)","Share flags":"Σημαίες πόρου","Encryption not required for this share; signing still protects every message.":"Δεν απαιτείται κρυπτογράφηση για αυτόν τον πόρο· η υπογραφή προστατεύει ακόμη κάθε μήνυμα.","0x001f01ff (full control)":"0x001f01ff (πλήρης έλεγχος)","What this user may do in the share.":"Τι μπορεί να κάνει αυτός ο χρήστης στον πόρο.","Oplock, impersonation":"Oplock, αντιπροσώπευση","none, 2 (impersonation)":"κανένα, 2 (αντιπροσώπευση)","Desired access":"Επιθυμητή πρόσβαση","0x00120089 (read)":"0x00120089 (ανάγνωση)","Read the data, its attributes and its permissions.":"Ανάγνωση των δεδομένων, των χαρακτηριστικών και των δικαιωμάτων τους.","File attributes":"Χαρακτηριστικά αρχείου","Share access":"Κοινή πρόσβαση","0x00000001 (read)":"0x00000001 (ανάγνωση)","Others may read the file while it is open, but not change it.":"Άλλοι μπορούν να διαβάζουν το αρχείο όσο είναι ανοιχτό, αλλά όχι να το αλλάζουν.",Disposition:"Διάθεση","1 (open, fail if missing)":"1 (άνοιγμα, αποτυχία αν λείπει)","0x00000040 (a file, not a folder)":"0x00000040 (αρχείο, όχι φάκελος)",Name:"Όνομα","Create contexts":"Πλαίσια δημιουργίας","File name":"Όνομα αρχείου","Relative to the share.":"Σχετικά με τον κοινόχρηστο πόρο.","Oplock, flags":"Oplock, σημαίες","none, 0":"κανένα, 0",Action:"Ενέργεια","1 (opened)":"1 (άνοιξε)",Times:"Χρόνοι","created, accessed, written, changed":"δημιουργία, πρόσβαση, εγγραφή, αλλαγή","Windows FILETIME: 100-nanosecond steps since 1601.":"FILETIME των Windows: βήματα των 100 νανοδευτερολέπτων από το 1601.","Allocation size":"Μέγεθος κατανομής","File size":"Μέγεθος αρχείου","0x00000020 (archive)":"0x00000020 (αρχειοθέτηση)","File ID":"File ID","The handle for the open file: reads and the close name it.":"Το handle του ανοιχτού αρχείου: οι αναγνώσεις και το κλείσιμο το αναφέρουν.","A big read costs one credit per 64 KB.":"Μια μεγάλη ανάγνωση κοστίζει ένα credit ανά 64 KB.","Padding, flags":"Συμπλήρωση, σημαίες","Where the server should put the data in its answer: 80 bytes in, right after the headers.":"Πού να βάλει ο διακομιστής τα δεδομένα στην απάντησή του: 80 byte από την αρχή, αμέσως μετά τις κεφαλίδες.","The whole file in one request.":"Όλο το αρχείο σε ένα αίτημα.","Minimum, channel, remaining":"Ελάχιστο, κανάλι, υπόλοιπο","Channel info":"Πληροφορίες καναλιού","Data offset":"Θέση δεδομένων","Data length":"Μήκος δεδομένων","Remaining, flags":"Υπόλοιπο, σημαίες","The file itself; its contents are not part of the lesson.":"Το ίδιο το αρχείο· το περιεχόμενό του δεν είναι μέρος του μαθήματος.","The laptop didn’t ask for the file’s details, so the rest is zeros.":"Ο φορητός δεν ζήτησε τα στοιχεία του αρχείου, οπότε τα υπόλοιπα είναι μηδενικά.","Times, sizes, attributes":"Χρόνοι, μεγέθη, χαρακτηριστικά","Talking to a PLC":"Συζήτηση με ένα PLC",Switch:"Μεταγωγέας","Plant network":"Δίκτυο εγκατάστασης","Modbus/TCP, for industrial control":"Modbus/TCP, για βιομηχανικό έλεγχο","Modbus is one of the oldest and most widely used protocols in industrial control (OT, operational technology): PLCs, sensors, motor drives and meters in factories, water works and buildings speak it. A client reads and writes numbered registers and coils on a device. Modbus/TCP carries the same small messages over TCP port 502, with no login and no encryption.":"Το Modbus είναι ένα από τα παλαιότερα και πιο διαδεδομένα πρωτόκολλα στον βιομηχανικό έλεγχο (OT, επιχειρησιακή τεχνολογία): το μιλούν PLC, αισθητήρες, οδηγοί κινητήρων και μετρητές σε εργοστάσια, μονάδες ύδρευσης και κτίρια. Ένας πελάτης διαβάζει και γράφει αριθμημένους καταχωρητές και coils σε μια συσκευή. Το Modbus/TCP μεταφέρει τα ίδια μικρά μηνύματα μέσω της θύρας TCP 502, χωρίς σύνδεση χρήστη και χωρίς κρυπτογράφηση.","1979, by Modicon":"1979, από τη Modicon","16-bit registers, on/off coils":"Καταχωρητές 16 bit, coils ανοιχτό/κλειστό","None built in":"Καμία ενσωματωμένη","Modbus.org specifications":"Προδιαγραφές του Modbus.org","Pump running":"Η αντλία λειτουργεί","Simple, and wide open":"Απλό, και ορθάνοιχτο","The laptop read four registers, changed a setpoint and started a pump, each with a 12-byte request and a short answer. No message carried a password and none was encrypted: Modbus trusts whoever can reach it, so the network around it has to do the protecting. Press REPLAY to watch it again.":"Ο φορητός διάβασε τέσσερις καταχωρητές, άλλαξε ένα σημείο ρύθμισης και ξεκίνησε μια αντλία, κάθε φορά με αίτημα 12 byte και σύντομη απάντηση. Κανένα μήνυμα δεν έφερε κωδικό και κανένα δεν ήταν κρυπτογραφημένο: το Modbus εμπιστεύεται όποιον μπορεί να το φτάσει, οπότε την προστασία πρέπει να την κάνει το δίκτυο γύρω του. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","4 requests, 4 answers":"4 αιτήματα, 4 απαντήσεις",Biggest:"Μεγαλύτερο","17 bytes (the read answer)":"17 byte (η απάντηση ανάγνωσης)","Protect with":"Προστασία με","Separate networks":"Χωριστά δίκτυα","Port 502":"Θύρα 502","A TCP connection to the PLC":"Μια σύνδεση TCP προς το PLC","A PLC (programmable logic controller) runs a small pumping station: it reads the sensors and switches the pumps. An engineer’s laptop on the plant network talks to it in Modbus/TCP, so it opens a TCP connection to port 502. In Modbus terms the laptop is the client and the PLC the server.":"Ένα PLC (προγραμματιζόμενος λογικός ελεγκτής) διαχειρίζεται ένα μικρό αντλιοστάσιο: διαβάζει τους αισθητήρες και ανάβει τις αντλίες. Ο φορητός ενός μηχανικού στο δίκτυο της εγκατάστασης του μιλά με Modbus/TCP, οπότε ανοίγει σύνδεση TCP στη θύρα 502. Με όρους Modbus ο φορητός είναι ο πελάτης και το PLC ο διακομιστής.",Roles:"Ρόλοι","Client asks, server answers":"Ο πελάτης ρωτά, ο διακομιστής απαντά","Read Registers":"Ανάγνωση καταχωρητών","Function 3: four numbers":"Συνάρτηση 3: τέσσερις αριθμοί","The laptop asks for 4 holding registers starting at address 0, with function code 3. The PLC answers with 8 bytes: four 16-bit numbers. What they mean (the tank level in centimetres, the temperature in tenths of a degree) is written only in the PLC’s documentation; the message carries no names and no units. An HMI screen sends reads like this every second or so.":"Ο φορητός ζητά 4 holding registers από τη διεύθυνση 0, με κωδικό συνάρτησης 3. Το PLC απαντά με 8 byte: τέσσερις αριθμούς 16 bit. Τι σημαίνουν (η στάθμη της δεξαμενής σε εκατοστά, η θερμοκρασία σε δέκατα του βαθμού) γράφεται μόνο στην τεκμηρίωση του PLC· το μήνυμα δεν φέρει ονόματα ούτε μονάδες. Μια οθόνη HMI στέλνει τέτοιες αναγνώσεις περίπου κάθε δευτερόλεπτο.",Function:"Συνάρτηση","4 registers from 0":"4 καταχωρητές από 0","function 3":"συνάρτηση 3","registers 0–3":"καταχωρητές 0–3",VALUES:"ΤΙΜΕΣ","Write a Setpoint":"Εγγραφή σημείου ρύθμισης","Function 6: one register":"Συνάρτηση 6: ένας καταχωρητής","The engineer raises the tank’s level setpoint from 4.50 m to 5.00 m: function 6, write single register, register 3, value 500. The PLC answers by repeating the request, which means done. From now on its program keeps the tank fuller.":"Ο μηχανικός ανεβάζει το σημείο ρύθμισης στάθμης της δεξαμενής από 4.50 m σε 5.00 m: συνάρτηση 6, εγγραφή ενός καταχωρητή, καταχωρητής 3, τιμή 500. Το PLC απαντά επαναλαμβάνοντας το αίτημα, που σημαίνει έγινε. Από εδώ και πέρα το πρόγραμμά του κρατά τη δεξαμενή πιο γεμάτη.","Register 3":"Καταχωρητής 3","The request, repeated":"Το αίτημα, επαναλαμβανόμενο",WRITE:"ΕΓΓΡΑΦΗ","register 3 = 500":"καταχωρητής 3 = 500","Start a Pump":"Εκκίνηση αντλίας","Function 5: a coil":"Συνάρτηση 5: ένα coil","Coils are single on/off outputs. Function 5 writes one: coil 0, pump 2, value 0xFF00, which means on. The PLC switches the pump on and echoes the request. In a real plant the PLC’s own program usually decides this, with safety interlocks.":"Τα coils είναι μεμονωμένες έξοδοι ανοιχτό/κλειστό. Η συνάρτηση 5 γράφει ένα: coil 0, αντλία 2, τιμή 0xFF00, που σημαίνει ανοιχτό. Το PLC ανάβει την αντλία και επαναλαμβάνει το αίτημα. Σε πραγματική εγκατάσταση συνήθως το αποφασίζει το ίδιο το πρόγραμμα του PLC, με αλληλασφαλίσεις ασφαλείας.","Coil 0":"Coil 0","Pump 2: on":"Αντλία 2: σε λειτουργία","0xFF00 (off: 0x0000)":"0xFF00 (κλειστό: 0x0000)","COIL ON":"COIL ΑΝΟΙΧΤΟ","coil 0: pump 2":"coil 0: αντλία 2","pump 2 on":"αντλία 2 σε λειτουργία","PUMP 2 RUNNING":"Η ΑΝΤΛΙΑ 2 ΛΕΙΤΟΥΡΓΕΙ","An Exception":"Μια εξαίρεση","No such register":"Δεν υπάρχει τέτοιος καταχωρητής","A request for registers that don’t exist, here 100 and 101, gets an exception: the function code with its top bit set (3 + 128 = 131) and exception code 2, illegal data address. Other codes say the function isn’t supported or the device is busy.":"Ένα αίτημα για καταχωρητές που δεν υπάρχουν, εδώ 100 και 101, παίρνει εξαίρεση: τον κωδικό συνάρτησης με ενεργό το ανώτερο bit (3 + 128 = 131) και κωδικό εξαίρεσης 2, μη έγκυρη διεύθυνση δεδομένων. Άλλοι κωδικοί λένε ότι η συνάρτηση δεν υποστηρίζεται ή ότι η συσκευή είναι απασχολημένη.",Exception:"Εξαίρεση",Means:"Σημαίνει","No register there":"Κανένας καταχωρητής εκεί","registers 100–101":"καταχωρητές 100–101",EXCEPTION:"ΕΞΑΙΡΕΣΗ","code 2: no such register":"κωδικός 2: δεν υπάρχει καταχωρητής","No Security":"Καμία ασφάλεια","Anyone who can reach it":"Όποιος μπορεί να το φτάσει","Nothing in these messages says who sent them: Modbus, from 1979, has no login and no encryption, so any device that can reach port 502 can read the values and start the pump. Plants protect it with separate networks, firewalls between office and plant, lists of who may talk to each PLC, and monitoring. Modbus/TCP Security wraps the same messages in TLS, on port 802.":"Τίποτα σε αυτά τα μηνύματα δεν λέει ποιος τα έστειλε: το Modbus, του 1979, δεν έχει σύνδεση χρήστη ούτε κρυπτογράφηση, οπότε κάθε συσκευή που φτάνει τη θύρα 502 μπορεί να διαβάσει τις τιμές και να ξεκινήσει την αντλία. Οι εγκαταστάσεις το προστατεύουν με χωριστά δίκτυα, τείχη προστασίας μεταξύ γραφείου και εγκατάστασης, λίστες για το ποιος μπορεί να μιλά σε κάθε PLC, και παρακολούθηση. Το Modbus/TCP Security τυλίγει τα ίδια μηνύματα σε TLS, στη θύρα 802.","Separate networks, TLS":"Χωριστά δίκτυα, TLS","NO LOGIN, NO ENCRYPTION":"ΧΩΡΙΣ ΣΥΝΔΕΣΗ, ΧΩΡΙΣ ΚΡΥΠΤΟΓΡΑΦΗΣΗ","Seen on the plant network":"Όπως φαίνεται στο δίκτυο της εγκατάστασης","Picked by the client; the answer carries the same number.":"Το επιλέγει ο πελάτης· η απάντηση φέρει τον ίδιο αριθμό.","Protocol ID":"ID πρωτοκόλλου","The unit ID and everything after it.":"Το ID μονάδας και ό,τι ακολουθεί.","Unit ID":"ID μονάδας","Which device. It matters when a gateway passes requests on to devices on a serial line.":"Ποια συσκευή. Έχει σημασία όταν μια πύλη προωθεί αιτήματα σε συσκευές σε σειριακή γραμμή.","Function code":"Κωδικός συνάρτησης","Starting address":"Αρχική διεύθυνση","Modbus counts from 0, though manuals often number the same register 40001 and up.":"Το Modbus μετρά από το 0, αν και τα εγχειρίδια συχνά αριθμούν τον ίδιο καταχωρητή από 40001 και πάνω.",Quantity:"Ποσότητα","Modbus/TCP · Read Holding Registers, answer":"Modbus/TCP · Read Holding Registers, απάντηση","The same number as the request.":"Ο ίδιος αριθμός με το αίτημα.","Byte count":"Πλήθος byte","Register 0":"Καταχωρητής 0","412 (tank level, 4.12 m)":"412 (στάθμη δεξαμενής, 4.12 m)","Plain 16-bit numbers. What each one means is written in the PLC’s documentation, not in the message.":"Απλοί αριθμοί 16 bit. Τι σημαίνει ο καθένας γράφεται στην τεκμηρίωση του PLC, όχι στο μήνυμα.","Register 1":"Καταχωρητής 1","183 (temperature, 18.3 °C)":"183 (θερμοκρασία, 18.3 °C)","Register 2":"Καταχωρητής 2","1450 (pump speed, 1,450 rpm)":"1450 (ταχύτητα αντλίας, 1,450 σ.α.λ.)","450 (level setpoint, 4.50 m)":"450 (σημείο ρύθμισης στάθμης, 4.50 m)","Register address":"Διεύθυνση καταχωρητή","3 (level setpoint)":"3 (σημείο ρύθμισης στάθμης)",Value:"Τιμή","Modbus/TCP · Write Single Register, answer":"Modbus/TCP · Write Single Register, απάντηση","The answer repeats the request: done.":"Η απάντηση επαναλαμβάνει το αίτημα: έγινε.","Coil address":"Διεύθυνση coil","0 (pump 2)":"0 (αντλία 2)","A coil is a single on/off output. 0xFF00 switches it on.":"Ένα coil είναι μια μεμονωμένη έξοδος ανοιχτό/κλειστό. Το 0xFF00 το ανοίγει.","Modbus/TCP · Write Single Coil, answer":"Modbus/TCP · Write Single Coil, απάντηση","Modbus/TCP · exception":"Modbus/TCP · εξαίρεση","131 (3 + 128: an exception)":"131 (3 + 128: εξαίρεση)","The top bit set: the request failed.":"Ενεργό το ανώτερο bit: το αίτημα απέτυχε.","Exception code":"Κωδικός εξαίρεσης","There is no register at that address.":"Δεν υπάρχει καταχωρητής σε αυτή τη διεύθυνση.","Internet Routes":"Διαδρομές του Διαδικτύου",Routes:"Διαδρομές","The laptop’s packets":"Τα πακέτα του φορητού","Border Gateway Protocol":"Border Gateway Protocol","The internet is a network of networks: tens of thousands of them, run by internet providers, clouds, universities and companies, each with its own AS number. BGP is how their border routers tell each other which addresses they can reach. Every router passes on what it learns with its own number added, so each network builds its own map of the paths to every address on the internet.":"Το Διαδίκτυο είναι ένα δίκτυο δικτύων: δεκάδες χιλιάδες, που τα διαχειρίζονται πάροχοι Διαδικτύου, cloud, πανεπιστήμια και εταιρείες, το καθένα με δικό του αριθμό AS. Το BGP είναι ο τρόπος με τον οποίο οι δρομολογητές συνόρων τους λένε ο ένας στον άλλον ποιες διευθύνσεις μπορούν να φτάσουν. Κάθε δρομολογητής προωθεί ό,τι μαθαίνει προσθέτοντας τον δικό του αριθμό, οπότε κάθε δίκτυο χτίζει τον δικό του χάρτη με τις διαδρομές προς κάθε διεύθυνση του Διαδικτύου.",Between:"Ανάμεσα σε","Networks (ASes)":"Δίκτυα (AS)",Table:"Πίνακας","About a million IPv4 routes":"Περίπου ένα εκατομμύριο διαδρομές IPv4","Path choice":"Επιλογή διαδρομής","Policy, then shortest":"Πολιτική, μετά η συντομότερη","Route learned":"Η διαδρομή μαθεύτηκε","Announced, passed on, used":"Ανακοινώθηκε, προωθήθηκε, χρησιμοποιήθηκε","The hosting network announced its addresses, the transit network passed them on with its own number added, and the ISP’s router used that path for the laptop’s packets. When the route was withdrawn, the news spread the same way. There is no central map: every network builds its own from what its neighbours say. Press REPLAY to watch it again.":"Το δίκτυο φιλοξενίας ανακοίνωσε τις διευθύνσεις του, το δίκτυο διέλευσης τις προώθησε προσθέτοντας τον αριθμό του, και ο δρομολογητής του παρόχου χρησιμοποίησε αυτή τη διαδρομή για τα πακέτα του φορητού. Όταν η διαδρομή αποσύρθηκε, το νέο διαδόθηκε με τον ίδιο τρόπο. Δεν υπάρχει κεντρικός χάρτης: κάθε δίκτυο χτίζει τον δικό του από όσα λένε οι γείτονές του. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Map:"Χάρτης","Each network makes its own":"Κάθε δίκτυο φτιάχνει τον δικό του","RPKI and filters":"RPKI και φίλτρα","Many Networks":"Πολλά δίκτυα","Each with its own number":"Το καθένα με δικό του αριθμό","The internet is more than 75,000 separate networks, called autonomous systems (ASes): internet providers, clouds, universities, big companies, each with a number. Here are three: the laptop’s ISP (AS 64500), a transit network that carries others’ traffic (AS 64510), and the hosting network of www.example.com (AS 64511). BGP is how their routers tell each other where every address can be reached.":"Το Διαδίκτυο είναι πάνω από 75,000 χωριστά δίκτυα, που λέγονται αυτόνομα συστήματα (AS): πάροχοι Διαδικτύου, cloud, πανεπιστήμια, μεγάλες εταιρείες, το καθένα με αριθμό. Ορίστε τρία: ο πάροχος του φορητού (AS 64500), ένα δίκτυο διέλευσης που μεταφέρει την κίνηση άλλων (AS 64510) και το δίκτυο φιλοξενίας του www.example.com (AS 64511). Το BGP είναι ο τρόπος με τον οποίο οι δρομολογητές τους λένε ο ένας στον άλλον πού μπορεί να φτάσει κανείς κάθε διεύθυνση.",Networks:"Δίκτυα","More than 75,000 ASes":"Πάνω από 75,000 AS",Here:"Εδώ","3 ASes, a router each":"3 AS, από έναν δρομολογητή",Numbers:"Αριθμοί","TCP to port 179":"TCP στη θύρα 179","BGP routers don’t discover each other: engineers at both ends set each other up as neighbours. The ISP’s router opens a TCP connection to the transit router on port 179. They are directly connected, so their packets go out with a TTL of 1: they can’t cross even one more router, so the session only works between direct neighbours.":"Οι δρομολογητές BGP δεν ανακαλύπτουν ο ένας τον άλλον: μηχανικοί και στις δύο άκρες τους ρυθμίζουν ως γείτονες. Ο δρομολογητής του παρόχου ανοίγει σύνδεση TCP προς τον δρομολογητή διέλευσης στη θύρα 179. Συνδέονται απευθείας, οπότε τα πακέτα τους φεύγουν με TTL 1: δεν μπορούν να περάσουν ούτε έναν ακόμη δρομολογητή, άρα η συνεδρία λειτουργεί μόνο μεταξύ άμεσων γειτόνων.",Neighbours:"Γείτονες","Set up by hand":"Ρυθμίζονται με το χέρι","1: the next router only":"1: μόνο ο επόμενος δρομολογητής","OPEN, then KEEPALIVE":"OPEN, μετά KEEPALIVE","Each router sends an OPEN: its AS number, a hold time of 180 seconds, its router ID and what it supports, such as 4-byte AS numbers. Each answers with a KEEPALIVE, and the session is established. From now on a KEEPALIVE goes every 60 seconds when there’s nothing else to send; after 180 silent seconds the session would be dropped.":"Κάθε δρομολογητής στέλνει ένα OPEN: τον αριθμό AS του, χρόνο διατήρησης 180 δευτερολέπτων, το ID του δρομολογητή και τι υποστηρίζει, όπως αριθμούς AS 4 byte. Ο καθένας απαντά με KEEPALIVE, και η συνεδρία εγκαθίσταται. Από εδώ και πέρα φεύγει ένα KEEPALIVE κάθε 60 δευτερόλεπτα όταν δεν υπάρχει τίποτα άλλο να σταλεί· μετά από 180 σιωπηλά δευτερόλεπτα η συνεδρία θα έπεφτε.","AS, hold time, ID":"AS, χρόνος διατήρησης, ID","KEEPALIVE: established":"KEEPALIVE: εγκαταστάθηκε","Hold time":"Χρόνος διατήρησης","hold 180 s":"hold 180 s","SESSION ESTABLISHED":"Η ΣΥΝΕΔΡΙΑ ΕΓΚΑΤΑΣΤΑΘΗΚΕ","Announce a Route":"Ανακοίνωση διαδρομής","The hosting network: “I have these”":"Το δίκτυο φιλοξενίας: «έχω αυτές»","The hosting network’s router announces 203.0.113.0/24, the 256 addresses that include www.example.com, to the transit network, which it pays to carry its traffic. The UPDATE says how to get there: AS_PATH 64511, only its own network so far, and NEXT_HOP, its own address on the link between them.":"Ο δρομολογητής του δικτύου φιλοξενίας ανακοινώνει το 203.0.113.0/24, τις 256 διευθύνσεις που περιλαμβάνουν το www.example.com, στο δίκτυο διέλευσης, το οποίο πληρώνει για να μεταφέρει την κίνησή του. Το UPDATE λέει πώς να φτάσει κανείς εκεί: AS_PATH 64511, ως τώρα μόνο το δικό του δίκτυο, και NEXT_HOP, τη δική του διεύθυνση στη ζεύξη μεταξύ τους.","path 64511":"διαδρομή 64511","Passed On":"Προωθήθηκε","Each network adds its number":"Κάθε δίκτυο προσθέτει τον αριθμό του","The transit router accepts the route and passes it to its other neighbours, the ISP among them, with its own number added to the front: AS_PATH 64510 64511, and itself as the next hop. The ISP’s router may hear of the same prefix from several neighbours. It picks one by its own policy first (routes through paying customers before others, say), then by the shortest AS path.":"Ο δρομολογητής διέλευσης δέχεται τη διαδρομή και την προωθεί στους άλλους γείτονές του, μεταξύ τους και στον πάροχο, με τον δικό του αριθμό μπροστά: AS_PATH 64510 64511, και τον εαυτό του ως επόμενο βήμα. Ο δρομολογητής του παρόχου μπορεί να ακούσει για το ίδιο πρόθεμα από πολλούς γείτονες. Επιλέγει ένα πρώτα με βάση τη δική του πολιτική (για παράδειγμα διαδρομές μέσω πελατών που πληρώνουν πριν από άλλες), μετά με βάση τη συντομότερη διαδρομή AS.","Best path":"Καλύτερη διαδρομή","path 64510 64511":"διαδρομή 64510 64511","ROUTE TO 203.0.113.0/24":"ΔΙΑΔΡΟΜΗ ΠΡΟΣ 203.0.113.0/24","Follow the Route":"Ακολουθώντας τη διαδρομή","Packets go where BGP said":"Τα πακέτα πηγαίνουν όπου είπε το BGP","When the laptop connects to www.example.com (its address found by DNS as usual), its packets reach the ISP, whose router now sends anything for 203.0.113.0/24 to the transit router, and the transit router sends it on to the hosting network. The answer comes back by whatever route the hosting network chose towards the laptop’s ISP: on the internet the way back is often different from the way there.":"Όταν ο φορητός συνδέεται στο www.example.com (η διεύθυνση βρέθηκε με DNS όπως πάντα), τα πακέτα του φτάνουν στον πάροχο, του οποίου ο δρομολογητής στέλνει πλέον ό,τι είναι για το 203.0.113.0/24 στον δρομολογητή διέλευσης, κι αυτός το προωθεί στο δίκτυο φιλοξενίας. Η απάντηση επιστρέφει από όποια διαδρομή επέλεξε το δίκτυο φιλοξενίας προς τον πάροχο του φορητού: στο Διαδίκτυο ο δρόμος της επιστροφής συχνά διαφέρει από τον δρόμο της μετάβασης.","Way back":"Δρόμος επιστροφής","Chosen separately":"Επιλέγεται χωριστά","the way back":"ο δρόμος της επιστροφής",Withdrawn:"Αποσύρθηκε","Routes can be taken back":"Οι διαδρομές μπορούν να ανακληθούν","Later the hosting network takes the prefix back, as it would if a link failed: an UPDATE listing it under withdrawn routes. The transit router passes it on, and within seconds to minutes networks everywhere forget the path. A session that goes quiet past its hold time loses all its routes at once. In 2021 Facebook withdrew the routes to its own DNS servers and vanished from the internet for six hours.":"Αργότερα το δίκτυο φιλοξενίας ανακαλεί το πρόθεμα, όπως θα έκανε αν έπεφτε μια ζεύξη: ένα UPDATE που το αναφέρει στις αποσυρμένες διαδρομές. Ο δρομολογητής διέλευσης το προωθεί, και μέσα σε δευτερόλεπτα ως λεπτά δίκτυα παντού ξεχνούν τη διαδρομή. Μια συνεδρία που σωπαίνει πέρα από τον χρόνο διατήρησής της χάνει όλες τις διαδρομές της μονομιάς. Το 2021 το Facebook απέσυρε τις διαδρομές προς τους δικούς του διακομιστές DNS και εξαφανίστηκε από το Διαδίκτυο για έξι ώρες.","Spreads in":"Διαδίδεται σε","Seconds to minutes":"Δευτερόλεπτα ως λεπτά","Session lost":"Χαμένη συνεδρία","All its routes go":"Φεύγουν όλες οι διαδρομές της",WITHDRAW:"ΑΠΟΣΥΡΣΗ","Trust Problems":"Προβλήματα εμπιστοσύνης","BGP believes its neighbours":"Το BGP πιστεύει τους γείτονές του","A router accepts what its neighbours announce. A network that announces addresses that aren’t its own, by mistake or on purpose, pulls their traffic towards it: in 2008 a Pakistani ISP took YouTube offline worldwide this way. With RPKI the holder of a prefix signs which AS may announce it, and routers that check drop any other. Filters on what each neighbour may announce do the rest.":"Ένας δρομολογητής δέχεται ό,τι ανακοινώνουν οι γείτονές του. Ένα δίκτυο που ανακοινώνει διευθύνσεις που δεν είναι δικές του, κατά λάθος ή σκόπιμα, τραβά την κίνησή τους προς τον εαυτό του: το 2008 ένας πακιστανικός πάροχος έβγαλε έτσι το YouTube εκτός λειτουργίας παγκοσμίως. Με το RPKI ο κάτοχος ενός προθέματος υπογράφει ποιο AS μπορεί να το ανακοινώνει, και οι δρομολογητές που το ελέγχουν πετούν κάθε άλλο. Τα φίλτρα για το τι μπορεί να ανακοινώνει κάθε γείτονας κάνουν τα υπόλοιπα.",Risk:"Κίνδυνος","Hijacks and leaks":"Υφαρπαγές και διαρροές","Signed: who may announce":"Υπογεγραμμένο: ποιος μπορεί να ανακοινώνει",Also:"Επίσης","Filters per neighbour":"Φίλτρα ανά γείτονα","CHECK WHO MAY ANNOUNCE":"ΕΛΕΓΧΟΣ ΠΟΙΟΣ ΜΠΟΡΕΙ ΝΑ ΑΝΑΚΟΙΝΩΝΕΙ","UPDATE Message: withdrawn 203.0.113.0/24":"UPDATE Message: αποσύρθηκε το 203.0.113.0/24",Marker:"Δείκτης","16 bytes of 0xFF":"16 byte 0xFF","All ones: where a message starts.":"Όλα άσοι: εδώ ξεκινά ένα μήνυμα.","The first message on a session: who this router is and what it supports.":"Το πρώτο μήνυμα μιας συνεδρίας: ποιος είναι αυτός ο δρομολογητής και τι υποστηρίζει.","This router’s network. (A 4-byte AS number goes in the capability below, with 23456 here.)":"Το δίκτυο αυτού του δρομολογητή. (Ένας αριθμός AS 4 byte μπαίνει στο capability παρακάτω, με 23456 εδώ.)","If nothing at all arrives for this long, the session is dropped. Both sides use the lower offer.":"Αν δεν φτάσει απολύτως τίποτα για τόσο διάστημα, η συνεδρία πέφτει. Και οι δύο πλευρές χρησιμοποιούν τη χαμηλότερη προσφορά.","BGP identifier":"Αναγνωριστικό BGP","The router’s ID, usually one of its addresses.":"Το ID του δρομολογητή, συνήθως μία από τις διευθύνσεις του.","Optional parameters":"Προαιρετικές παράμετροι","parameter 2, 14 bytes":"παράμετρος 2, 14 byte","What this router can do beyond the basics.":"Τι μπορεί να κάνει αυτός ο δρομολογητής πέρα από τα βασικά.",Multiprotocol:"Πολυπρωτοκολλικό","Which kinds of routes it will exchange on this session.":"Ποια είδη διαδρομών θα ανταλλάσσει σε αυτή τη συνεδρία.","Route refresh":"Ανανέωση διαδρομών","It can ask the other side to send all its routes again.":"Μπορεί να ζητήσει από την άλλη πλευρά να ξαναστείλει όλες τις διαδρομές της.","4-byte AS numbers":"Αριθμοί AS 4 byte","2-byte AS numbers ran short, so newer ones are 4 bytes long.":"Οι αριθμοί AS 2 byte λιγόστεψαν, οπότε οι νεότεροι έχουν μήκος 4 byte.","Only the header: “still here”. Sent when there’s nothing else to say, every third of the hold time.":"Μόνο η κεφαλίδα: «είμαι ακόμη εδώ». Στέλνεται όταν δεν υπάρχει τίποτα άλλο να ειπωθεί, κάθε ένα τρίτο του χρόνου διατήρησης.","Routes: paths to new addresses, and ones taken back.":"Διαδρομές: διαδρομές προς νέες διευθύνσεις, και όσες ανακαλούνται.","Withdrawn routes":"Αποσυρμένες διαδρομές","Path attributes":"Χαρακτηριστικά διαδρομής","0 (IGP: from inside the network that announced it)":"0 (IGP: από μέσα από το δίκτυο που την ανακοίνωσε)","Every network the route has passed through, the latest first. Other things being equal, the shorter path wins; a router that finds its own number here drops the route, so routes can’t loop.":"Κάθε δίκτυο από το οποίο πέρασε η διαδρομή, το πιο πρόσφατο πρώτο. Αν τα άλλα είναι ίσα, κερδίζει η συντομότερη διαδρομή· ένας δρομολογητής που βρίσκει εδώ τον δικό του αριθμό πετά τη διαδρομή, ώστε οι διαδρομές να μην κάνουν κύκλους.","Send packets for these addresses to this router.":"Στείλτε τα πακέτα για αυτές τις διευθύνσεις σε αυτόν τον δρομολογητή.",Reachable:"Προσβάσιμες","The addresses this route leads to: a prefix, here 256 addresses.":"Οι διευθύνσεις στις οποίες οδηγεί αυτή η διαδρομή: ένα πρόθεμα, εδώ 256 διευθύνσεις.","BGP · UPDATE (withdrawal)":"BGP · UPDATE (απόσυρση)","These addresses can no longer be reached through this router.":"Αυτές οι διευθύνσεις δεν είναι πια προσβάσιμες μέσω αυτού του δρομολογητή.","A Video Call":"Μια βιντεοκλήση",Signalling:"Σηματοδοσία","STUN and ICE":"STUN και ICE",Media:"Πολυμέσα","STUN Server":"Διακομιστής STUN","Sam’s Router":"Δρομολογητής του Sam","Sam’s Laptop":"Φορητός του Sam","Web Real-Time Communication":"Web Real-Time Communication","WebRTC lets two browsers call each other, with audio, video and data going straight between them, not through a server. A server only introduces them: they swap descriptions of what they can send and where they can be reached (signalling), find a way through both home routers with ICE and STUN, encrypt with DTLS, and send the media over UDP as SRTP.":"Το WebRTC επιτρέπει σε δύο browser να καλέσουν ο ένας τον άλλον, με ήχο, βίντεο και δεδομένα να πηγαίνουν κατευθείαν μεταξύ τους, όχι μέσω διακομιστή. Ένας διακομιστής απλώς τους συστήνει: ανταλλάσσουν περιγραφές για το τι μπορούν να στείλουν και πού μπορούν να βρεθούν (σηματοδοσία), βρίσκουν δρόμο μέσα από τους δύο οικιακούς δρομολογητές με ICE και STUN, κρυπτογραφούν με DTLS και στέλνουν τα πολυμέσα πάνω από UDP ως SRTP.","Media over":"Πολυμέσα μέσω","Always on":"Πάντα ενεργή","Works in":"Λειτουργεί σε","Every major browser":"Κάθε μεγάλο browser","W3C; RFC 8825 and others":"W3C· RFC 8825 και άλλα","On the call":"Σε κλήση","Introduced by a server, then direct":"Τους σύστησε διακομιστής, μετά απευθείας","The signalling server passed the offer and the answer between the two browsers, a STUN server told the laptop its public address, and an ICE check found a way through both home routers. After a DTLS handshake, encrypted audio and video went straight from one laptop to the other. Press REPLAY to watch it again.":"Ο διακομιστής σηματοδοσίας μετέφερε την προσφορά και την απάντηση ανάμεσα στους δύο browser, ένας διακομιστής STUN είπε στον φορητό τη δημόσια διεύθυνσή του, και ένας έλεγχος ICE βρήκε δρόμο μέσα από τους δύο οικιακούς δρομολογητές. Μετά από χειραψία DTLS, κρυπτογραφημένος ήχος και βίντεο πήγαν κατευθείαν από τον έναν φορητό στον άλλον. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","Via call.example.com":"Μέσω call.example.com","Media path":"Διαδρομή πολυμέσων","Direct, through 2 NATs":"Απευθείας, μέσα από 2 NAT","DTLS, then SRTP":"DTLS, μετά SRTP","If blocked":"Αν μπλοκαριστεί","A TURN relay":"Ένας αναμεταδότης TURN","Join the Call":"Συμμετοχή στην κλήση","Through a signalling server":"Μέσω διακομιστή σηματοδοσίας","The laptop opens a call page on call.example.com, and the page keeps a WebSocket open to the server, inside TLS. It joins room 42, where Sam is already waiting. The server will pass messages between the two browsers. WebRTC doesn’t say how: every app does this signalling its own way.":"Ο φορητός ανοίγει μια σελίδα κλήσης στο call.example.com, και η σελίδα κρατά ανοιχτό ένα WebSocket προς τον διακομιστή, μέσα σε TLS. Μπαίνει στο δωμάτιο 42, όπου περιμένει ήδη ο Sam. Ο διακομιστής θα μεταφέρει μηνύματα ανάμεσα στους δύο browser. Το WebRTC δεν λέει πώς: κάθε εφαρμογή κάνει αυτή τη σηματοδοσία με τον δικό της τρόπο.","The app’s own server":"Ο διακομιστής της εφαρμογής","A WebSocket in TLS":"Ένα WebSocket σε TLS",Room:"Δωμάτιο","42, with Sam":"42, με τον Sam",JOIN:"ΣΥΜΜΕΤΟΧΗ","room 42":"δωμάτιο 42","SAM IS HERE":"Ο SAM ΕΙΝΑΙ ΕΔΩ","peer: Sam":"συνομιλητής: Sam","Public Address?":"Δημόσια διεύθυνση;","Ask a STUN server":"Ερώτηση σε διακομιστή STUN","Behind its home router the laptop knows only its private address, 192.168.1.10, which nobody on the internet can reach. So it asks a STUN server named in the call page’s settings, with one small UDP request. The answer says where the request seemed to come from, 198.51.100.7 port 61022: the router’s public address and the port its NAT opened for this conversation.":"Πίσω από τον οικιακό δρομολογητή ο φορητός ξέρει μόνο την ιδιωτική του διεύθυνση, 192.168.1.10, που κανείς στο Διαδίκτυο δεν μπορεί να φτάσει. Ρωτά λοιπόν έναν διακομιστή STUN που ορίζεται στις ρυθμίσεις της σελίδας κλήσης, με ένα μικρό αίτημα UDP. Η απάντηση λέει από πού φάνηκε να έρχεται το αίτημα, 198.51.100.7 θύρα 61022: τη δημόσια διεύθυνση του δρομολογητή και τη θύρα που άνοιξε το NAT του για αυτή τη συζήτηση.",Public:"Δημόσια","what is my address?":"ποια είναι η διεύθυνσή μου;","YOUR ADDRESS":"Η ΔΙΕΥΘΥΝΣΗ ΣΑΣ","The Offer":"Η προσφορά","An SDP description, via the server":"Μια περιγραφή SDP, μέσω του διακομιστή","The browser writes an offer in SDP: the media it wants to send (Opus audio; video in VP8, H.264 and others), the fingerprint of its DTLS certificate, its ICE user name and password, and its candidates, the addresses it might be reached at. Its private address is hidden behind a random .local name. The signalling server passes the offer on to Sam.":"Ο browser γράφει μια προσφορά σε SDP: τα πολυμέσα που θέλει να στείλει (ήχος Opus· βίντεο σε VP8, H.264 και άλλα), το αποτύπωμα του πιστοποιητικού DTLS του, το όνομα χρήστη και τον κωδικό ICE του, και τους υποψηφίους του, τις διευθύνσεις στις οποίες μπορεί να βρεθεί. Η ιδιωτική του διεύθυνση κρύβεται πίσω από ένα τυχαίο όνομα .local. Ο διακομιστής σηματοδοσίας προωθεί την προσφορά στον Sam.","SDP, in a JSON message":"SDP, σε μήνυμα JSON",Candidates:"Υποψήφιοι",".local name, 198.51.100.7":"όνομα .local, 198.51.100.7","About 4.7 KB":"Περίπου 4.7 KB","SDP: audio, video":"SDP: ήχος, βίντεο",candidates:"υποψήφιοι","to Sam":"προς Sam","Sam’s browser replies":"Απαντά ο browser του Sam","Sam accepts the call. Sam’s browser answers with SDP of its own: the codecs it picked from the offer, its certificate fingerprint, its ICE user name and password, and its candidates, including its public address, 198.51.100.200 port 49170, which it learned from a STUN server the same way. It also says it will start the encryption handshake. Now each browser knows where the other might be reached.":"Ο Sam δέχεται την κλήση. Ο browser του Sam απαντά με δικό του SDP: τους κωδικοποιητές που διάλεξε από την προσφορά, το αποτύπωμα του πιστοποιητικού του, το όνομα χρήστη και τον κωδικό ICE του, και τους υποψηφίους του, μαζί και τη δημόσια διεύθυνσή του, 198.51.100.200 θύρα 49170, που την έμαθε από διακομιστή STUN με τον ίδιο τρόπο. Λέει επίσης ότι θα ξεκινήσει αυτός τη χειραψία κρυπτογράφησης. Τώρα κάθε browser ξέρει πού μπορεί να βρεθεί ο άλλος.",Codecs:"Κωδικοποιητές","Sam’s address":"Διεύθυνση του Sam","Starts DTLS":"Ξεκινά DTLS","Sam’s browser":"Ο browser του Sam","from Sam":"από Sam","Punch Through":"Διάτρηση","Checks straight to each other":"Έλεγχοι απευθείας μεταξύ τους","Now the browsers try pairs of addresses with STUN checks sent straight to each other (ICE). Each check also opens a way back through the sender’s own router, so once both sides have sent one, checks get through both NATs. This one is answered: the direct path works. The laptop then repeats the check with USE-CANDIDATE, choosing this pair for the call.":"Τώρα οι browser δοκιμάζουν ζεύγη διευθύνσεων με ελέγχους STUN που στέλνουν απευθείας ο ένας στον άλλον (ICE). Κάθε έλεγχος ανοίγει και έναν δρόμο επιστροφής μέσα από τον δρομολογητή του αποστολέα, οπότε μόλις και οι δύο πλευρές στείλουν από έναν, οι έλεγχοι περνούν και τα δύο NAT. Αυτός παίρνει απάντηση: η απευθείας διαδρομή λειτουργεί. Ο φορητός επαναλαμβάνει μετά τον έλεγχο με USE-CANDIDATE, επιλέγοντας αυτό το ζεύγος για την κλήση.",Checks:"Έλεγχοι","STUN, peer to peer":"STUN, ομότιμα","The ICE password":"Ο κωδικός ICE","A direct path":"Μια απευθείας διαδρομή",CHECK:"ΕΛΕΓΧΟΣ","IT WORKS":"ΛΕΙΤΟΥΡΓΕΙ","direct path":"απευθείας διαδρομή","THROUGH BOTH ROUTERS":"ΜΕΣΑ ΑΠΟ ΤΟΥΣ ΔΥΟ ΔΡΟΜΟΛΟΓΗΤΕΣ","DTLS Handshake":"Χειραψία DTLS","Keys for the media":"Κλειδιά για τα πολυμέσα","Over the same path the browsers run a DTLS handshake: TLS for UDP. Their certificates are self-signed, so each checks the other’s against the fingerprint in the SDP, which came through the signalling server inside TLS. The handshake also agrees the keys for SRTP, which encrypts the audio and video. WebRTC never sends media unencrypted.":"Στην ίδια διαδρομή οι browser κάνουν μια χειραψία DTLS: TLS για UDP. Τα πιστοποιητικά τους είναι αυτοϋπογεγραμμένα, οπότε ο καθένας ελέγχει του άλλου με βάση το αποτύπωμα στο SDP, που ήρθε μέσω του διακομιστή σηματοδοσίας μέσα σε TLS. Η χειραψία συμφωνεί επίσης τα κλειδιά για το SRTP, που κρυπτογραφεί ήχο και βίντεο. Το WebRTC δεν στέλνει ποτέ μη κρυπτογραφημένα πολυμέσα.","1.2, TLS over UDP":"1.2, TLS πάνω από UDP","Checked by fingerprint":"Ελέγχεται με αποτύπωμα",Gives:"Δίνει","The SRTP keys":"Τα κλειδιά SRTP",certificate:"πιστοποιητικό","Media Flows":"Τα πολυμέσα ρέουν","Audio and video, direct":"Ήχος και βίντεο, απευθείας","Audio goes in an SRTP packet every 20 ms, and video as frames split over several packets. Each packet has a readable RTP header (sequence number, timestamp, stream ID) and encrypted media. None of it passes through call.example.com. Both browsers watch delay and loss and adjust the video quality to suit, and a data channel for chat or files can share the same path.":"Ο ήχος πηγαίνει σε ένα πακέτο SRTP κάθε 20 ms, και το βίντεο ως καρέ μοιρασμένα σε πολλά πακέτα. Κάθε πακέτο έχει μια αναγνώσιμη κεφαλίδα RTP (αριθμός ακολουθίας, χρονοσήμανση, ID ροής) και κρυπτογραφημένα πολυμέσα. Τίποτα δεν περνά από το call.example.com. Και οι δύο browser παρακολουθούν καθυστέρηση και απώλειες και προσαρμόζουν την ποιότητα του βίντεο, και ένα κανάλι δεδομένων για συνομιλία ή αρχεία μπορεί να μοιράζεται την ίδια διαδρομή.","Opus, a packet per 20 ms":"Opus, ένα πακέτο ανά 20 ms",Video:"Βίντεο","VP8, adapts to the network":"VP8, προσαρμόζεται στο δίκτυο","None of it":"Τίποτα",AUDIO:"ΗΧΟΣ","Opus, every 20 ms":"Opus, κάθε 20 ms",VIDEO:"ΒΙΝΤΕΟ","VP8, a frame in 3 packets":"VP8, ένα καρέ σε 3 πακέτα","Peer to Peer":"Ομότιμα","And when it can’t be":"Κι όταν δεν γίνεται","The server helped the two browsers find each other, then stepped aside: the call goes straight between the two homes. When a network won’t let direct packets through (some company firewalls, some mobile networks), ICE falls back to a TURN server that relays the encrypted media without being able to read it. Group calls usually send media through a server too, called an SFU.":"Ο διακομιστής βοήθησε τους δύο browser να βρεθούν και μετά παραμέρισε: η κλήση πηγαίνει απευθείας ανάμεσα στα δύο σπίτια. Όταν ένα δίκτυο δεν αφήνει να περάσουν απευθείας πακέτα (κάποια εταιρικά τείχη προστασίας, κάποια δίκτυα κινητής), το ICE καταφεύγει σε διακομιστή TURN που αναμεταδίδει τα κρυπτογραφημένα πολυμέσα χωρίς να μπορεί να τα διαβάσει. Οι ομαδικές κλήσεις συνήθως στέλνουν κι αυτές τα πολυμέσα μέσω διακομιστή, που λέγεται SFU.","Laptop to laptop":"Από φορητό σε φορητό",Fallback:"Εφεδρεία","TURN relay (encrypted)":"Αναμεταδότης TURN (κρυπτογραφημένο)","Group calls":"Ομαδικές κλήσεις","Usually via an SFU":"Συνήθως μέσω SFU","NO SERVER IN THE MIDDLE":"ΚΑΝΕΝΑΣ ΔΙΑΚΟΜΙΣΤΗΣ ΣΤΗ ΜΕΣΗ","A WebSocket text message":"Ένα μήνυμα κειμένου WebSocket","The attributes; the 20-byte header isn’t counted.":"Τα χαρακτηριστικά· η κεφαλίδα των 20 byte δεν μετριέται.","Always this value: tells STUN apart from the other traffic on the same port.":"Πάντα αυτή η τιμή: ξεχωρίζει το STUN από την άλλη κίνηση στην ίδια θύρα.","Random; the response carries the same ID.":"Τυχαίο· η απάντηση φέρει το ίδιο ID.","Where the request came from, as the server saw it: the home router’s public address, and the port its NAT picked for this conversation.":"Από πού ήρθε το αίτημα, όπως το είδε ο διακομιστής: η δημόσια διεύθυνση του οικιακού δρομολογητή και η θύρα που επέλεξε το NAT του για αυτή τη συζήτηση.","Their internet provider’s router, the next hop.":"Ο δρομολογητής του παρόχου Διαδικτύου του άλλου, το επόμενο βήμα.","Their router’s internet-facing port.":"Η θύρα του δρομολογητή του άλλου προς το Διαδίκτυο.","The ICE user names from the offer and the answer, the other side’s first: proves the check belongs to this call.":"Τα ονόματα χρήστη ICE από την προσφορά και την απάντηση, της άλλης πλευράς πρώτα: αποδεικνύει ότι ο έλεγχος ανήκει σε αυτή την κλήση.","The priority a new candidate found by this check would get.":"Η προτεραιότητα που θα έπαιρνε ένας νέος υποψήφιος που θα έβρισκε αυτός ο έλεγχος.","This side, the caller, makes the final choice of path. The random number settles a tie.":"Αυτή η πλευρά, αυτός που καλεί, κάνει την τελική επιλογή διαδρομής. Ο τυχαίος αριθμός λύνει την ισοπαλία.","HMAC-SHA1 of the message, keyed with an ICE password swapped through the signalling server, so a stranger can’t fake a check or its answer.":"HMAC-SHA1 του μηνύματος, με κλειδί έναν κωδικό ICE που ανταλλάχθηκε μέσω του διακομιστή σηματοδοσίας, ώστε ένας ξένος να μην μπορεί να πλαστογραφήσει έλεγχο ή απάντηση.","A CRC-32 of the message: marks it clearly as STUN.":"Ένα CRC-32 του μηνύματος: το σημειώνει ξεκάθαρα ως STUN.","Where the check came from, as the other laptop saw it: the home router’s public address and port.":"Από πού ήρθε ο έλεγχος, όπως τον είδε ο άλλος φορητός: η δημόσια διεύθυνση και η θύρα του οικιακού δρομολογητή.",Epoch:"Εποχή","Counts this side’s records, so repeats and stale ones can be spotted.":"Μετρά τις εγγραφές αυτής της πλευράς, ώστε να εντοπίζονται επαναλήψεις και παλιές εγγραφές.","Message length":"Μήκος μηνύματος","Message sequence":"Σειρά μηνύματος","Handshake messages are numbered, so they can be put back in order.":"Τα μηνύματα χειραψίας είναι αριθμημένα, ώστε να μπαίνουν ξανά στη σειρά.",Fragment:"Κομμάτι","Cipher suites: ECDHE-ECDSA with AES-GCM, and others":"Σουίτες κρυπτογράφησης: ECDHE-ECDSA με AES-GCM, και άλλες","use_srtp: the SRTP protection it supports":"use_srtp: η προστασία SRTP που υποστηρίζει","Chosen: ECDHE-ECDSA-AES128-GCM-SHA256":"Επιλέχθηκε: ECDHE-ECDSA-AES128-GCM-SHA256","A self-signed certificate the browser made; its fingerprint was in the offer":"Ένα αυτοϋπογεγραμμένο πιστοποιητικό που έφτιαξε ο browser· το αποτύπωμά του ήταν στην προσφορά","Its half of an X25519 key exchange, signed":"Το μισό του μιας ανταλλαγής κλειδιών X25519, υπογεγραμμένο","Asks Sam’s browser for its certificate too":"Ζητά και από τον browser του Sam το πιστοποιητικό του","Sam’s self-signed certificate; its fingerprint was in the answer":"Το αυτοϋπογεγραμμένο πιστοποιητικό του Sam· το αποτύπωμά του ήταν στην απάντηση","Its half of the X25519 key exchange":"Το μισό του της ανταλλαγής κλειδιών X25519","A signature that proves it holds the certificate’s key":"Μια υπογραφή που αποδεικνύει ότι κατέχει το κλειδί του πιστοποιητικού","From the next record on, this side encrypts.":"Από την επόμενη εγγραφή, αυτή η πλευρά κρυπτογραφεί.","Finished (encrypted)":"Finished (κρυπτογραφημένο)","Epoch 1: protected with the keys just agreed.":"Εποχή 1: προστατεύεται με τα κλειδιά που μόλις συμφωνήθηκαν.","An 8-byte nonce, the Finished message and a 16-byte tag (AES-128-GCM).":"Ένα nonce 8 byte, το μήνυμα Finished και μια ετικέτα 16 byte (AES-128-GCM).","SRTP · audio":"SRTP · ήχος","2, no padding, extension, no CSRCs":"2, χωρίς συμπλήρωση, επέκταση, χωρίς CSRC","X set: a header extension follows the fixed header.":"X ενεργό: μια επέκταση κεφαλίδας ακολουθεί τη σταθερή κεφαλίδα.","One more for each packet, so a lost or late one shows.":"Ένα παραπάνω σε κάθε πακέτο, ώστε να φαίνεται ένα χαμένο ή καθυστερημένο.","Audio clock, 48,000 ticks a second: +960 per 20 ms.":"Ρολόι ήχου, 48,000 χτύποι το δευτερόλεπτο: +960 ανά 20 ms.","Which stream this is; announced in the SDP.":"Ποια ροή είναι· ανακοινώνεται στο SDP.","Header extension":"Επέκταση κεφαλίδας","0xbede, 2 words":"0xbede, 2 λέξεις","One-byte elements: an ID (from the SDP’s a=extmap lines) and a length.":"Στοιχεία ενός byte: ένα ID (από τις γραμμές a=extmap του SDP) και ένα μήκος.","Audio level":"Στάθμη ήχου","How loud this packet is, so a group call can show who is talking without decrypting.":"Πόσο δυνατό είναι αυτό το πακέτο, ώστε μια ομαδική κλήση να δείχνει ποιος μιλά χωρίς αποκρυπτογράφηση.","Transport sequence":"Ακολουθία μεταφοράς","Numbers every packet of the call; the receiver reports what arrived when, for congestion control.":"Αριθμεί κάθε πακέτο της κλήσης· ο παραλήπτης αναφέρει τι έφτασε και πότε, για τον έλεγχο συμφόρησης.","Encrypted media":"Κρυπτογραφημένα πολυμέσα","20 ms of Opus audio, encrypted with keys from the DTLS handshake (AES-128-GCM).":"20 ms ήχου Opus, κρυπτογραφημένα με κλειδιά από τη χειραψία DTLS (AES-128-GCM).","Authentication tag":"Ετικέτα πιστοποίησης","Proves the packet came from the other side unchanged; the header is covered too.":"Αποδεικνύει ότι το πακέτο ήρθε από την άλλη πλευρά αναλλοίωτο· καλύπτει και την κεφαλίδα.","SRTP · video":"SRTP · βίντεο","Video clock, 90,000 ticks a second: +3,000 per frame at 30 frames a second.":"Ρολόι βίντεο, 90,000 χτύποι το δευτερόλεπτο: +3,000 ανά καρέ σε 30 καρέ το δευτερόλεπτο.","Absolute send time":"Απόλυτος χρόνος αποστολής","When the packet was sent, so the receiver can tell when the network is filling up.":"Πότε στάλθηκε το πακέτο, ώστε ο παραλήπτης να καταλαβαίνει πότε γεμίζει το δίκτυο.","1 byte":"1 byte","Part of a VP8 video frame, encrypted with keys from the DTLS handshake (AES-128-GCM).":"Μέρος ενός καρέ βίντεο VP8, κρυπτογραφημένο με κλειδιά από τη χειραψία DTLS (AES-128-GCM).","Marker set: the last packet of a video frame.":"Δείκτης ενεργός: το τελευταίο πακέτο ενός καρέ βίντεο.","8 ports":"8 θύρες","Frames and switches":"Πλαίσια και μεταγωγείς","Broadband logins":"Σύνδεση ευρυζωνικής","The laptop sent it with 128; the router took 1 when it passed it on.":"Ο φορητός το έστειλε με 128· ο δρομολογητής αφαίρεσε 1 όταν το προώθησε.","Frames & Switches":"Πλαίσια και μεταγωγείς","To the NAS":"Προς το NAS","To the internet":"Προς το Διαδίκτυο","Ethernet and Switches":"Ethernet και μεταγωγείς","Ethernet carries almost every wired network, and Wi-Fi access points pass their traffic on to it. Every network card has a 48-bit MAC address. A frame says which card it is for and which card sent it, and a switch delivers it: it learns which port each address is behind from the frames it sees, and sends each frame only where it needs to go.":"Το Ethernet μεταφέρει σχεδόν κάθε ενσύρματο δίκτυο, και τα σημεία πρόσβασης Wi-Fi του παραδίδουν την κίνησή τους. Κάθε κάρτα δικτύου έχει διεύθυνση MAC 48 bit. Ένα πλαίσιο λέει για ποια κάρτα είναι και ποια κάρτα το έστειλε, και ο μεταγωγέας το παραδίδει: μαθαίνει από τα πλαίσια που βλέπει πίσω από ποια θύρα βρίσκεται κάθε διεύθυνση, και στέλνει κάθε πλαίσιο μόνο εκεί που πρέπει να πάει.","48-bit MAC":"MAC 48 bit","14 bytes, plus a 4-byte FCS":"14 byte, συν FCS 4 byte","Frame size":"Μέγεθος πλαισίου","64 to 1,518 bytes":"Από 64 έως 1.518 byte",Speeds:"Ταχύτητες",Switched:"Μεταγωγή","Learned, flooded, forwarded":"Έμαθε, πλημμύρισε, προώθησε","The switch learned where the laptop and the NAS were from the frames they sent, flooded only the broadcast, and sent every other frame out of just the port it needed. MAC addresses carried each frame across one link; at the router the packet moved into a new frame. Press REPLAY to watch it again.":"Ο μεταγωγέας έμαθε πού είναι ο φορητός και το NAS από τα πλαίσια που έστειλαν, πλημμύρισε μόνο την εκπομπή, και έστειλε κάθε άλλο πλαίσιο μόνο από τη θύρα που χρειαζόταν. Οι διευθύνσεις MAC μετέφεραν κάθε πλαίσιο σε μία ζεύξη· στον δρομολογητή το πακέτο πέρασε σε νέο πλαίσιο. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Learned:"Έμαθε","2 addresses, 2 ports":"2 διευθύνσεις, 2 θύρες",Flooded:"Πλημμύρα","Only the broadcast":"Μόνο η εκπομπή",Frame:"Πλαίσιο","14-byte header, 4-byte FCS":"Κεφαλίδα 14 byte, FCS 4 byte","Forgets after":"Ξεχνά μετά","5 minutes unused":"5 λεπτά αχρησιμοποίητο","Who Has the NAS?":"Ποιος έχει το NAS;","A broadcast asks for a MAC address":"Μια εκπομπή ρωτά για διεύθυνση MAC","The laptop wants to reach the NAS at 192.168.1.20. On a local network, frames are delivered by MAC address, and the laptop doesn’t know the NAS’s yet. So it sends an ARP request to ff:ff:ff:ff:ff:ff, the broadcast address, into port 1 of the switch.":"Ο φορητός θέλει να φτάσει στο NAS στη 192.168.1.20. Σε τοπικό δίκτυο τα πλαίσια παραδίδονται με βάση τη διεύθυνση MAC, και ο φορητός δεν ξέρει ακόμη του NAS. Στέλνει λοιπόν αίτημα ARP στη ff:ff:ff:ff:ff:ff, τη διεύθυνση εκπομπής, στη θύρα 1 του μεταγωγέα.","Looking for":"Ψάχνει","ff:ff:ff:ff:ff:ff (all)":"ff:ff:ff:ff:ff:ff (όλοι)",Into:"Μπαίνει από","Switch port 1":"Θύρα 1 μεταγωγέα","who has 192.168.1.20?":"ποιος έχει τη 192.168.1.20;","Learn, Then Flood":"Μάθε, μετά πλημμύρισε","The switch notes where the laptop is":"Ο μεταγωγέας σημειώνει πού είναι ο φορητός","A switch reads each frame’s source address and notes it in its MAC table: 00:00:5e:00:53:10 is on port 1. A broadcast is for everyone, so it sends a copy out of every other port: to the NAS on port 2 and the router on port 8. Frames for unknown addresses are flooded too.":"Ο μεταγωγέας διαβάζει τη διεύθυνση προέλευσης κάθε πλαισίου και τη σημειώνει στον πίνακα MAC: η 00:00:5e:00:53:10 είναι στη θύρα 1. Μια εκπομπή είναι για όλους, οπότε στέλνει ένα αντίγραφο από κάθε άλλη θύρα: στο NAS στη θύρα 2 και στον δρομολογητή στη θύρα 8. Και τα πλαίσια για άγνωστες διευθύνσεις πλημμυρίζονται.","…:53:10 is on port 1":"…:53:10 στη θύρα 1",Copies:"Αντίγραφα","Out of every other port":"Από κάθε άλλη θύρα","Unknown address":"Άγνωστη διεύθυνση","Flooded the same way":"Πλημμυρίζεται κι αυτή","…:53:10 IS ON PORT 1":"…:53:10 ΣΤΗ ΘΥΡΑ 1","copies out of ports 2 and 8":"αντίγραφα από θύρες 2 και 8","Only the NAS Answers":"Απαντά μόνο το NAS","The reply goes to one port":"Η απάντηση πάει σε μία θύρα","Every device reads the request, but only the NAS has 192.168.1.20, so only it answers, straight to the laptop’s MAC; the router ignores it. The switch learns that 00:00:5e:00:53:20 is on port 2. It already knows where the laptop is, so the reply leaves by port 1 alone.":"Κάθε συσκευή διαβάζει το αίτημα, αλλά μόνο το NAS έχει τη 192.168.1.20, οπότε μόνο αυτό απαντά, κατευθείαν στη MAC του φορητού· ο δρομολογητής το αγνοεί. Ο μεταγωγέας μαθαίνει ότι η 00:00:5e:00:53:20 είναι στη θύρα 2. Ξέρει ήδη πού είναι ο φορητός, οπότε η απάντηση βγαίνει μόνο από τη θύρα 1.","To the laptop only":"Μόνο στον φορητό","…:53:20 is on port 2":"…:53:20 στη θύρα 2","Out of":"Βγαίνει από","Port 1":"Θύρα 1","…:53:20 IS ON PORT 2":"…:53:20 ΣΤΗ ΘΥΡΑ 2","port 1 only":"μόνο θύρα 1","Port to Port":"Από θύρα σε θύρα","Frames go only where they must":"Τα πλαίσια πάνε μόνο όπου πρέπει","The laptop connects to the NAS. Each frame starts with the NAS’s MAC, then its own, then a type: 0x0800, an IPv4 packet. After the packet, the card adds a 4-byte checksum. The switch looks up the destination and sends each frame out of port 2 only. The router never sees them.":"Ο φορητός συνδέεται με το NAS. Κάθε πλαίσιο αρχίζει με τη MAC του NAS, μετά τη δική του, μετά έναν τύπο: 0x0800, πακέτο IPv4. Μετά το πακέτο η κάρτα προσθέτει άθροισμα ελέγχου 4 byte. Ο μεταγωγέας βρίσκει τον προορισμό και στέλνει κάθε πλαίσιο μόνο από τη θύρα 2. Ο δρομολογητής δεν τα βλέπει ποτέ.","To, from, type: 14 bytes":"Προς, από, τύπος: 14 byte","4 bytes, added by the card":"4 byte, από την κάρτα","Router sees":"Ο δρομολογητής βλέπει",Nothing:"Τίποτα","type 0x0800 (IPv4)":"τύπος 0x0800 (IPv4)","out of port 2 only":"μόνο από τη θύρα 2","Off the Network":"Έξω από το δίκτυο","A frame for the router":"Πλαίσιο για τον δρομολογητή","Next the laptop opens a website at 203.0.113.10. That address isn’t on the local network, so the frame goes to the router: the router’s MAC, known from an earlier ARP, is the destination, while the packet inside still names 203.0.113.10. The switch sends it out of port 8.":"Στη συνέχεια ο φορητός ανοίγει έναν ιστότοπο στη 203.0.113.10. Η διεύθυνση αυτή δεν είναι στο τοπικό δίκτυο, οπότε το πλαίσιο πάει στον δρομολογητή: προορισμός είναι η MAC του δρομολογητή, γνωστή από προηγούμενο ARP, ενώ το πακέτο μέσα γράφει ακόμη 203.0.113.10. Ο μεταγωγέας το στέλνει από τη θύρα 8.","Frame to":"Πλαίσιο προς","The router’s MAC":"Η MAC του δρομολογητή","Packet to":"Πακέτο προς","Port 8":"Θύρα 8","IP packet to 203.0.113.10":"πακέτο IP προς 203.0.113.10","out of port 8":"από τη θύρα 8","A New Frame":"Νέο πλαίσιο","Every hop rewraps the packet":"Κάθε άλμα ξανατυλίγει το πακέτο","The router takes the packet out of the frame, lowers its TTL and swaps in its public address (NAT). Then it puts the packet in a new frame for its next link: its internet-side MAC as the source, the provider’s router as the destination. MAC addresses only ever cross one link.":"Ο δρομολογητής βγάζει το πακέτο από το πλαίσιο, μειώνει το TTL και βάζει τη δημόσια διεύθυνσή του (NAT). Μετά βάζει το πακέτο σε νέο πλαίσιο για την επόμενη ζεύξη: τη MAC του από την πλευρά του Διαδικτύου ως προέλευση, τον δρομολογητή του παρόχου ως προορισμό. Οι διευθύνσεις MAC δεν περνούν ποτέ πάνω από μία ζεύξη.","The router’s internet port":"Η θύρα Διαδικτύου του δρομολογητή","The provider’s router":"Ο δρομολογητής του παρόχου","Still 203.0.113.10":"Ακόμη 203.0.113.10","NEW FRAME":"ΝΕΟ ΠΛΑΙΣΙΟ","from the router’s internet port":"από τη θύρα Διαδικτύου του δρομολογητή","IP still to 203.0.113.10":"IP ακόμη προς 203.0.113.10","In port 1 · Who has 192.168.1.20? Tell 192.168.1.10":"Είσοδος, θύρα 1 · Who has 192.168.1.20? Tell 192.168.1.10","Out port 2 (flooded) · Who has 192.168.1.20?":"Έξοδος, θύρα 2 (πλημμύρα) · Who has 192.168.1.20?","Out port 8 (flooded) · Who has 192.168.1.20?":"Έξοδος, θύρα 8 (πλημμύρα) · Who has 192.168.1.20?","In port 2 · 192.168.1.20 is at 00:00:5e:00:53:20":"Είσοδος, θύρα 2 · 192.168.1.20 is at 00:00:5e:00:53:20","Out port 1 only · 192.168.1.20 is at 00:00:5e:00:53:20":"Έξοδος μόνο από θύρα 1 · 192.168.1.20 is at 00:00:5e:00:53:20","In port 1 · 50532 → 445 [SYN]":"Είσοδος, θύρα 1 · 50532 → 445 [SYN]","Out port 2 · 50532 → 445 [SYN]":"Έξοδος, θύρα 2 · 50532 → 445 [SYN]","In port 2 · 445 → 50532 [SYN, ACK]":"Είσοδος, θύρα 2 · 445 → 50532 [SYN, ACK]","Out port 1 · 445 → 50532 [SYN, ACK]":"Έξοδος, θύρα 1 · 445 → 50532 [SYN, ACK]","In port 1 · 52344 → 443 [SYN] (frame to the router)":"Είσοδος, θύρα 1 · 52344 → 443 [SYN] (πλαίσιο προς τον δρομολογητή)","Out port 8 · 52344 → 443 [SYN]":"Έξοδος, θύρα 8 · 52344 → 443 [SYN]","TTL 127 · 40112 → 443 [SYN] (new frame, after NAT)":"TTL 127 · 40112 → 443 [SYN] (νέο πλαίσιο, μετά το NAT)","Seen going into the switch, port 1":"Φαίνεται μπαίνοντας στον μεταγωγέα, θύρα 1","Seen leaving the switch, port 2":"Φαίνεται βγαίνοντας από τον μεταγωγέα, θύρα 2","Seen leaving the switch, port 8":"Φαίνεται βγαίνοντας από τον μεταγωγέα, θύρα 8","Seen going into the switch, port 2":"Φαίνεται μπαίνοντας στον μεταγωγέα, θύρα 2","Seen leaving the switch, port 1":"Φαίνεται βγαίνοντας από τον μεταγωγέα, θύρα 1","Broadband Logins":"Σύνδεση ευρυζωνικής",Discovery:"Ανακάλυψη","PPP setup":"Στήσιμο PPP","Home Router":"Οικιακός δρομολογητής","Access Server":"Διακομιστής πρόσβασης","Point-to-Point Protocol over Ethernet":"Πρωτόκολλο σημείου προς σημείο πάνω από Ethernet","Many DSL and fibre providers make the home router log in before it gets online. PPPoE is how: the router finds the provider’s access server and opens a session with it, then runs PPP inside, agreeing on the link’s settings, logging in with the username and password from the provider and receiving its public IP address. Every packet then carries an 8-byte PPPoE header.":"Πολλοί πάροχοι DSL και οπτικής ίνας ζητούν από τον οικιακό δρομολογητή να συνδεθεί με λογαριασμό πριν βγει στο Διαδίκτυο. Το PPPoE είναι ο τρόπος: ο δρομολογητής βρίσκει τον διακομιστή πρόσβασης του παρόχου και ανοίγει σύνοδο μαζί του, και μέσα τρέχει PPP, συμφωνεί τις ρυθμίσεις της ζεύξης, συνδέεται με το όνομα χρήστη και τον κωδικό του παρόχου και λαμβάνει τη δημόσια διεύθυνση IP του. Από εκεί και πέρα κάθε πακέτο φέρει κεφαλίδα PPPoE 8 byte.","CHAP or PAP":"CHAP ή PAP","From IPCP":"Από το IPCP","8 bytes (MTU 1,492)":"8 byte (MTU 1.492)","Logged in":"Συνδέθηκε","Found, agreed, checked, addressed":"Βρέθηκε, συμφωνήθηκε, ελέγχθηκε, πήρε διεύθυνση","The router found the provider’s access server, got a session, agreed on the link’s settings, proved its password without sending it and was given its public address. Every packet now travels inside that session, until a PADT ends it. Press REPLAY to watch it again.":"Ο δρομολογητής βρήκε τον διακομιστή πρόσβασης του παρόχου, πήρε σύνοδο, συμφώνησε τις ρυθμίσεις της ζεύξης, απέδειξε τον κωδικό του χωρίς να τον στείλει και πήρε τη δημόσια διεύθυνσή του. Κάθε πακέτο ταξιδεύει πια μέσα σε αυτή τη σύνοδο, μέχρι να τη λήξει ένα PADT. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","17 to get online":"17 μέχρι τη σύνδεση","Public IP":"Δημόσια IP","8 bytes per packet":"8 byte ανά πακέτο","Anyone There?":"Είναι κανείς εκεί;","The router looks for an access server":"Ο δρομολογητής ψάχνει διακομιστή πρόσβασης","The home router is plugged into the provider’s fibre or DSL line. Before it can log in, it has to find the provider’s access server, so it broadcasts a PADI: “PPPoE Active Discovery Initiation”. An access server answers with a PADO, an offer that names it: bng-1.example.net.":"Ο οικιακός δρομολογητής είναι συνδεδεμένος στη γραμμή οπτικής ίνας ή DSL του παρόχου. Πριν συνδεθεί, πρέπει να βρει τον διακομιστή πρόσβασης του παρόχου, γι’ αυτό εκπέμπει ένα PADI: «PPPoE Active Discovery Initiation». Ένας διακομιστής πρόσβασης απαντά με ένα PADO, μια προσφορά με το όνομά του: bng-1.example.net.","PADI, to everyone":"PADI, προς όλους","PADO, from the server":"PADO, από τον διακομιστή","Ethernet type":"Τύπος Ethernet","0x8863 (discovery)":"0x8863 (ανακάλυψη)","is there an access server?":"υπάρχει διακομιστής πρόσβασης;","and a cookie":"και ένα cookie","Pick a Server":"Επιλογή διακομιστή","A session number for the line":"Αριθμός συνόδου για τη γραμμή","If several servers answered, the router picks one and asks it directly with a PADR, sending back the cookie it was given. The server replies with a PADS carrying a session ID, 0x2f1c. From now on every frame between the two of them carries that number.":"Αν απάντησαν πολλοί διακομιστές, ο δρομολογητής διαλέγει έναν και τον ζητά απευθείας με ένα PADR, στέλνοντας πίσω το cookie που πήρε. Ο διακομιστής απαντά με ένα PADS που φέρει αναγνωριστικό συνόδου, 0x2f1c. Από εδώ και πέρα κάθε πλαίσιο ανάμεσά τους φέρει αυτόν τον αριθμό.",Confirmed:"Επιβεβαιώθηκε","this server, please":"αυτόν τον διακομιστή, παρακαλώ","with its cookie":"με το cookie του","session ID 0x2f1c":"ID συνόδου 0x2f1c","SESSION 0x2F1C":"ΣΥΝΟΔΟΣ 0x2F1C","Link Settings":"Ρυθμίσεις ζεύξης","LCP agrees on size and login":"Το LCP συμφωνεί μέγεθος και σύνδεση","Now PPP runs inside the session, starting with LCP. Each side asks for its settings: packets of at most 1,492 bytes, since PPPoE’s 8 bytes have to fit in Ethernet’s 1,500, and a random magic number to spot loops. The server also asks for a CHAP login. Both agree.":"Τώρα το PPP τρέχει μέσα στη σύνοδο, ξεκινώντας με το LCP. Κάθε πλευρά ζητά τις ρυθμίσεις της: πακέτα το πολύ 1.492 byte, αφού τα 8 byte του PPPoE πρέπει να χωρούν στα 1.500 του Ethernet, και έναν τυχαίο μαγικό αριθμό για να εντοπίζονται βρόχοι. Ο διακομιστής ζητά επίσης σύνδεση με CHAP. Συμφωνούν και οι δύο.","Largest packet":"Μεγαλύτερο πακέτο","1,492 bytes (MRU)":"1.492 byte (MRU)","CHAP with MD5":"CHAP με MD5","0x8864 (session)":"0x8864 (σύνοδος)","LCP REQUEST":"ΑΙΤΗΜΑ LCP","magic number":"μαγικός αριθμός","MRU 1492, log in with CHAP":"MRU 1492, σύνδεση με CHAP","LCP ACK":"LCP ACK","A password check without the password":"Έλεγχος κωδικού χωρίς τον κωδικό","The server sends a random challenge. The router answers with its username, alex@fibre.example, and an MD5 hash of the challenge and its password, so the password itself never crosses the line. The server checks the answer with the provider’s RADIUS server, then says Success.":"Ο διακομιστής στέλνει μια τυχαία πρόκληση. Ο δρομολογητής απαντά με το όνομα χρήστη του, alex@fibre.example, και ένα hash MD5 της πρόκλησης και του κωδικού του, οπότε ο ίδιος ο κωδικός δεν περνά ποτέ από τη γραμμή. Ο διακομιστής ελέγχει την απάντηση στον διακομιστή RADIUS του παρόχου και μετά απαντά Success.",Username:"Όνομα χρήστη","A hash, not the password":"Ένα hash, όχι ο κωδικός","The provider’s RADIUS":"Το RADIUS του παρόχου","MD5(id, password, challenge)":"MD5(id, κωδικός, πρόκληση)","CHECKED WITH RADIUS":"ΕΛΕΓΧΘΗΚΕ ΜΕ RADIUS","Get an Address":"Λήψη διεύθυνσης","IPCP hands out the public IP":"Το IPCP μοιράζει τη δημόσια IP","The server first tells the router its own end, 198.51.100.1. The router asks for an address and DNS servers, offering 0.0.0.0: “anything”. The server says no and suggests 198.51.100.7 and two DNS servers. The router asks again with those, and the server agrees.":"Ο διακομιστής πρώτα λέει στον δρομολογητή το δικό του άκρο, 198.51.100.1. Ο δρομολογητής ζητά διεύθυνση και διακομιστές DNS, προτείνοντας 0.0.0.0: «οποιαδήποτε». Ο διακομιστής αρνείται και προτείνει 198.51.100.7 και δύο διακομιστές DNS. Ο δρομολογητής ζητά ξανά με αυτές τις τιμές, και ο διακομιστής συμφωνεί.","Other end":"Άλλο άκρο","IPCP REQUEST":"ΑΙΤΗΜΑ IPCP","my end: 198.51.100.1":"το άκρο μου: 198.51.100.1","address? 0.0.0.0":"διεύθυνση; 0.0.0.0","IPCP ACK":"IPCP ACK","IPCP NAK":"IPCP NAK","use 198.51.100.7":"πάρε 198.51.100.7","198.51.100.7, please":"198.51.100.7, παρακαλώ",agreed:"συμφωνώ","Every packet in an 8-byte wrapper":"Κάθε πακέτο σε περιτύλιγμα 8 byte","The laptop opens a website. The router swaps in its public address (NAT) and sends the packet inside the session: a 6-byte PPPoE header, then 2 bytes saying “IPv4”. It also lowers the MSS the laptop offered from 1460 to 1452, so the replies fit in 1,492 bytes.":"Ο φορητός ανοίγει έναν ιστότοπο. Ο δρομολογητής βάζει τη δημόσια διεύθυνσή του (NAT) και στέλνει το πακέτο μέσα στη σύνοδο: κεφαλίδα PPPoE 6 byte, μετά 2 byte που λένε «IPv4». Επίσης μειώνει το MSS που πρότεινε ο φορητός από 1460 σε 1452, ώστε οι απαντήσεις να χωρούν σε 1.492 byte.",Wrapper:"Περιτύλιγμα","6 + 2 bytes":"6 + 2 byte","1460 → 1452 (clamped)":"1460 → 1452 (περιορισμένο)","in session 0x2f1c":"στη σύνοδο 0x2f1c","MSS now 1452":"MSS τώρα 1452","Seen on the router’s line to the provider":"Φαίνεται στη γραμμή του δρομολογητή προς τον πάροχο","PPPoE PADI · 18 bytes":"PPPoE PADI · 18 byte","PADI, 2 tags":"PADI, 2 ετικέτες","Broadcast: everything on the line receives it.":"Εκπομπή: τη λαμβάνει ό,τι υπάρχει στη γραμμή.","0x8863 (PPPoE discovery)":"0x8863 (ανακάλυψη PPPoE)","Version, type":"Έκδοση, τύπος","Active Discovery Initiation: is there an access server out there?":"Active Discovery Initiation: υπάρχει κάπου εκεί έξω διακομιστής πρόσβασης;","0 (none yet)":"0 (κανένα ακόμη)","What follows this header.":"Ό,τι ακολουθεί αυτή την κεφαλίδα.","The service the router wants; empty means any.":"Η υπηρεσία που θέλει ο δρομολογητής· κενό σημαίνει οποιαδήποτε.","Type, length":"Τύπος, μήκος","A value the router made up. Answers carry it back, so the router can match them to its request.":"Μια τιμή που επινόησε ο δρομολογητής. Οι απαντήσεις τη φέρνουν πίσω, ώστε ο δρομολογητής να τις αντιστοιχίσει στο αίτημά του.","PPPoE PADO · 59 bytes":"PPPoE PADO · 59 byte","PADO, 4 tags":"PADO, 4 ετικέτες","The access server’s port.":"Η θύρα του διακομιστή πρόσβασης.","Active Discovery Offer: an access server answers.":"Active Discovery Offer: απαντά ένας διακομιστής πρόσβασης.","The access server’s name.":"Το όνομα του διακομιστή πρόσβασης.","A value the server will recognise when the router asks for it again, so floods of fake requests cost it nothing.":"Μια τιμή που ο διακομιστής θα αναγνωρίσει όταν ο δρομολογητής τον ζητήσει ξανά, οπότε μια πλημμύρα ψεύτικων αιτημάτων δεν του κοστίζει τίποτα.","PPPoE PADR · 38 bytes":"PPPoE PADR · 38 byte","PADR, 3 tags":"PADR, 3 ετικέτες","The access server that answered.":"Ο διακομιστής πρόσβασης που απάντησε.","Active Discovery Request: the router picks this server.":"Active Discovery Request: ο δρομολογητής διαλέγει αυτόν τον διακομιστή.","PPPoE PADS · 18 bytes":"PPPoE PADS · 18 byte","PADS, 2 tags":"PADS, 2 ετικέτες","Active Discovery Session-confirmation: here is the session ID.":"Active Discovery Session-confirmation: ορίστε το αναγνωριστικό συνόδου.","Given by the server in its PADS; every frame of the session carries it.":"Το δίνει ο διακομιστής στο PADS του· το φέρει κάθε πλαίσιο της συνόδου.","PPPoE · 6 bytes":"PPPoE · 6 byte","PPP LCP Configure-Request · 16 bytes":"PPP LCP Configure-Request · 16 byte","0x8864 (PPPoE session)":"0x8864 (σύνοδος PPPoE)","0x00 (Session)":"0x00 (σύνοδος)","Session data: one PPP packet.":"Δεδομένα συνόδου: ένα πακέτο PPP.","Link Control Protocol: the link’s settings.":"Link Control Protocol: οι ρυθμίσεις της ζεύξης.","The settings this side wants.":"Οι ρυθμίσεις που θέλει αυτή η πλευρά.","The answer carries the same number.":"Η απάντηση φέρει τον ίδιο αριθμό.","The largest packet this side will take: 1,500 bytes of Ethernet minus PPPoE’s 8.":"Το μεγαλύτερο πακέτο που δέχεται αυτή η πλευρά: 1.500 byte Ethernet μείον τα 8 του PPPoE.","Random. Seeing its own number come back would mean the line loops back on itself.":"Τυχαίος. Αν γύριζε πίσω ο δικός του αριθμός, η γραμμή θα έκανε βρόχο πάνω στον εαυτό της.","PPP LCP Configure-Request · 21 bytes":"PPP LCP Configure-Request · 21 byte","How the server wants the router to log in.":"Πώς θέλει ο διακομιστής να συνδεθεί ο δρομολογητής.","PPP LCP Configure-Ack · 16 bytes":"PPP LCP Configure-Ack · 16 byte","Every setting accepted, exactly as asked.":"Κάθε ρύθμιση έγινε δεκτή, ακριβώς όπως ζητήθηκε.","The number of the request this answers.":"Ο αριθμός του αιτήματος στο οποίο απαντά.","PPP LCP Configure-Ack · 21 bytes":"PPP LCP Configure-Ack · 21 byte","PPP CHAP Challenge · 40 bytes":"PPP CHAP Challenge · 40 byte","Challenge Handshake Authentication Protocol: the login.":"Challenge Handshake Authentication Protocol: η σύνδεση.","A random value for the router to prove its password with.":"Μια τυχαία τιμή με την οποία ο δρομολογητής αποδεικνύει τον κωδικό του.","The response must carry the same number.":"Η απάντηση πρέπει να φέρει τον ίδιο αριθμό.","Value size":"Μέγεθος τιμής","Random, new for every login.":"Τυχαία, καινούρια σε κάθε σύνδεση.","The server’s name.":"Το όνομα του διακομιστή.","PPP CHAP Response · 41 bytes":"PPP CHAP Response · 41 byte","The proof, and who is logging in.":"Η απόδειξη, και ποιος συνδέεται.","The number of the challenge this answers.":"Ο αριθμός της πρόκλησης στην οποία απαντά.","MD5 of the identifier, the password and the challenge: it proves the password without sending it.":"MD5 του αναγνωριστικού, του κωδικού και της πρόκλησης: αποδεικνύει τον κωδικό χωρίς να τον στέλνει.","The username the provider gave.":"Το όνομα χρήστη από τον πάροχο.","PPP CHAP Success · 13 bytes":"PPP CHAP Success · 13 byte","The login worked.":"Η σύνδεση πέτυχε.","Text for people to read; any words will do.":"Κείμενο για να το διαβάζουν άνθρωποι· οποιεσδήποτε λέξεις κάνουν.","PPP IPCP Configure-Request · 12 bytes":"PPP IPCP Configure-Request · 12 byte","IP Control Protocol: the IP address and DNS servers.":"IP Control Protocol: η διεύθυνση IP και οι διακομιστές DNS.","The address of the server’s end of the link.":"Η διεύθυνση του άκρου του διακομιστή στη ζεύξη.","PPP IPCP Configure-Request · 24 bytes":"PPP IPCP Configure-Request · 24 byte","Zero: “please give me an address”.":"Μηδέν: «δώσε μου μια διεύθυνση, παρακαλώ».","Zero: “which DNS server should I use?”":"Μηδέν: «ποιον διακομιστή DNS να χρησιμοποιήσω;»","PPP IPCP Configure-Ack · 12 bytes":"PPP IPCP Configure-Ack · 12 byte","PPP IPCP Configure-Nak · 24 bytes":"PPP IPCP Configure-Nak · 24 byte","Not these values: here are ones that would be accepted.":"Όχι αυτές οι τιμές: ορίστε κάποιες που θα γίνονταν δεκτές.","The address for the router.":"Η διεύθυνση για τον δρομολογητή.","PPP IPCP Configure-Ack · 24 bytes":"PPP IPCP Configure-Ack · 24 byte","PPP · 2 bytes":"PPP · 2 byte","An IPv4 packet follows.":"Ακολουθεί ένα πακέτο IPv4.","Lowered from 1460 by the router, so packets back fit in the 1,492 bytes PPPoE leaves.":"Ο δρομολογητής το μείωσε από 1460, ώστε τα πακέτα επιστροφής να χωρούν στα 1.492 byte που αφήνει το PPPoE.","Internet phone calls":"Κλήσεις μέσω διαδικτύου","IP camera streams":"Ροές από κάμερες IP","Live streaming upload":"Ανέβασμα ζωντανών μεταδόσεων","Multicast and TV channels":"Πολυεκπομπή και τηλεοπτικά κανάλια","IP Camera":"Κάμερα IP","TV Box":"TV box",Camera:"Κάμερα","Internet Phone Calls":"Κλήσεις μέσω διαδικτύου","Voice (RTP)":"Φωνή (RTP)","SIP Server":"Διακομιστής SIP","Bob’s Router":"Δρομολογητής του Bob","Session Initiation Protocol":"Session Initiation Protocol","SIP sets up phone calls over the internet: office desk phones, phone apps and the providers behind them. A phone signs in with its provider’s SIP server. To call someone it sends an INVITE; the other phone rings and answers, and the two agree on how to send the voice, which then flows as RTP. The messages are plain text, a lot like HTTP.":"Το SIP στήνει τηλεφωνικές κλήσεις μέσω διαδικτύου: τηλέφωνα γραφείου, εφαρμογές τηλεφωνίας και τους παρόχους πίσω τους. Ένα τηλέφωνο συνδέεται στον διακομιστή SIP του παρόχου του. Για να καλέσει κάποιον στέλνει ένα INVITE· το άλλο τηλέφωνο χτυπά και απαντά, και τα δύο συμφωνούν πώς θα σταλεί η φωνή, που μετά ρέει ως RTP. Τα μηνύματα είναι απλό κείμενο, πολύ σαν το HTTP.","UDP or TCP 5060":"UDP ή TCP 5060","Call setup":"Στήσιμο κλήσης",Voice:"Φωνή","RTP, described by SDP":"RTP, περιγραφή με SDP","Codec here":"Codec εδώ","Call ended":"Η κλήση έληξε","Signed in, rang, talked, hung up":"Εγγραφή, κουδούνισμα, κουβέντα, κλείσιμο","Alice’s phone signed in with a password it never sent, invited Bob’s phone through the SIP server, heard it ring, and talked over RTP until Bob hung up with a BYE. SIP only set the call up and took it down; the voice travelled as packets of its own. Press REPLAY to watch it again.":"Το τηλέφωνο της Alice συνδέθηκε με έναν κωδικό που δεν έστειλε ποτέ, κάλεσε το τηλέφωνο του Bob μέσω του διακομιστή SIP, το άκουσε να χτυπά και μίλησε μέσω RTP μέχρι ο Bob να κλείσει με ένα BYE. Το SIP μόνο έστησε και τερμάτισε την κλήση· η φωνή ταξίδεψε σε δικά της πακέτα. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","50 packets a second each way":"50 πακέτα το δευτερόλεπτο ανά κατεύθυνση",Through:"Μέσω","The provider’s server":"Του διακομιστή του παρόχου","No (SIPS and SRTP add it)":"Όχι (το προσθέτουν SIPS και SRTP)","Sign In":"Σύνδεση","The phone tells the server where it is":"Το τηλέφωνο λέει στον διακομιστή πού βρίσκεται","Alice’s phone, an app on her laptop, registers with her provider’s SIP server: alice@example.net can be reached here. The server answers 401 with a challenge, so the phone asks again with a hash made from the challenge and its password. 200 OK: registered for an hour.":"Το τηλέφωνο της Alice, μια εφαρμογή στο laptop της, εγγράφεται στον διακομιστή SIP του παρόχου της: η alice@example.net βρίσκεται εδώ. Ο διακομιστής απαντά 401 με μια πρόκληση, οπότε το τηλέφωνο ρωτά ξανά με ένα hash από την πρόκληση και τον κωδικό. 200 OK: εγγεγραμμένο για μία ώρα.","Good for":"Ισχύει για","3600 s, then again":"3600 s, και ξανά","is here":"είναι εδώ","with a challenge":"με πρόκληση","again, with a hash":"ξανά, με hash",registered:"εγγράφηκε","Call Bob":"Κλήση στον Bob","An INVITE, passed on by the server":"Ένα INVITE, που προωθεί ο διακομιστής","Alice calls bob@example.net. Her INVITE carries SDP: G.711 audio, sent to her phone. The server answers 100 Trying, finds where Bob’s phone registered and passes the INVITE on, with its own Via and Record-Route and its own address in the SDP: the voice will go through it.":"Η Alice καλεί το bob@example.net. Το INVITE της φέρει SDP: ήχος G.711, να σταλεί στο τηλέφωνό της. Ο διακομιστής απαντά 100 Trying, βρίσκει πού εγγράφηκε το τηλέφωνο του Bob και προωθεί το INVITE, με δικό του Via και Record-Route και τη δική του διεύθυνση στο SDP: η φωνή θα περάσει από αυτόν.","Offer (SDP)":"Προσφορά (SDP)","G.711, port 49170":"G.711, θύρα 49170","Stops Alice resending":"Η Alice σταματά τις επαναλήψεις","call bob@example.net":"κλήση στο bob@example.net","SDP: G.711 audio":"SDP: ήχος G.711","passed on to Bob":"προωθήθηκε στον Bob","voice via the server":"φωνή μέσω διακομιστή",Ringing:"Χτυπά","The answer retraces the route":"Η απάντηση γυρνά από τον ίδιο δρόμο","Bob’s phone starts ringing and says so: 180 Ringing. Responses follow the Via headers back the way the request came, so it goes to the server, which removes its own Via and passes it on to Alice. Her phone plays the ringing tone.":"Το τηλέφωνο του Bob αρχίζει να χτυπά και το λέει: 180 Ringing. Οι απαντήσεις ακολουθούν τις κεφαλίδες Via πίσω από τον δρόμο του αιτήματος, οπότε πάει στον διακομιστή, που αφαιρεί το δικό του Via και τη δίνει στην Alice. Το τηλέφωνό της παίζει τον ήχο κλήσης.","Route back":"Δρόμος επιστροφής","The Via headers, in reverse":"Οι κεφαλίδες Via, ανάποδα","Alice hears":"Η Alice ακούει","The ringing tone":"Τον ήχο κλήσης","Bob’s phone rings":"χτυπά του Bob","to Alice":"προς την Alice",Answered:"Απαντήθηκε","200 OK, then ACK":"200 OK, μετά ACK","Bob picks up. His 200 OK carries his SDP answer: G.711, sent to his phone. The server swaps in its own address again before passing it to Alice. Her phone confirms with an ACK, which the server passes to Bob. The call is set up.":"Ο Bob σηκώνει. Το 200 OK του φέρει την απάντηση SDP του: G.711, να σταλεί στο τηλέφωνό του. Ο διακομιστής βάζει ξανά τη δική του διεύθυνση πριν τη δώσει στην Alice. Το τηλέφωνό της επιβεβαιώνει με ένα ACK, που ο διακομιστής δίνει στον Bob. Η κλήση στήθηκε.","Answer (SDP)":"Απάντηση (SDP)","G.711, port 49172":"G.711, θύρα 49172","Confirmed by":"Επιβεβαίωση με","Voice goes to":"Η φωνή πάει","The server, ports 40000, 40002":"Στον διακομιστή, θύρες 40000, 40002","Bob answers":"Ο Bob απαντά",answered:"απαντήθηκε",Talking:"Συνομιλία","Voice flows as RTP":"Η φωνή ρέει ως RTP","Now the voice: every 20 ms each phone sends an RTP packet with 160 bytes of G.711 sound, a sequence number and a timestamp, over UDP. They go to the server, which passes them on to the other phone. SIP stays quiet while they talk.":"Τώρα η φωνή: κάθε 20 ms κάθε τηλέφωνο στέλνει ένα πακέτο RTP με 160 byte ήχου G.711, έναν αριθμό ακολουθίας και μια χρονοσήμανση, μέσω UDP. Πάνε στον διακομιστή, που τα δίνει στο άλλο τηλέφωνο. Το SIP σωπαίνει όσο μιλούν.",Every:"Κάθε","20 ms, 160 bytes of sound":"20 ms, 160 byte ήχου","Carried by":"Μεταφέρεται με","RTP over UDP":"RTP πάνω σε UDP","SIP meanwhile":"Το SIP στο μεταξύ","Nothing to say":"Τίποτα να πει",VOICE:"ΦΩΝΗ","20 ms of Alice":"20 ms από την Alice","20 ms of Bob":"20 ms από τον Bob","Hang Up":"Κλείσιμο","BYE, and 200 OK":"BYE, και 200 OK","Bob hangs up: his phone sends BYE, routed through the server as the Record-Route asked, and Alice’s phone answers 200 OK. Both stop sending voice. The call took four kinds of request; the voice itself was never part of SIP.":"Ο Bob κλείνει: το τηλέφωνό του στέλνει BYE, μέσω του διακομιστή όπως ζήτησε το Record-Route, και το τηλέφωνο της Alice απαντά 200 OK. Και τα δύο σταματούν να στέλνουν φωνή. Η κλήση χρειάστηκε τέσσερα είδη αιτημάτων· η ίδια η φωνή δεν ήταν ποτέ μέρος του SIP.","No more RTP":"Τέλος το RTP","Bob hangs up":"Ο Bob κλείνει","1, 0 (PCMU: G.711 μ-law, the classic phone codec)":"1, 0 (PCMU: G.711 νόμος μ, το κλασικό τηλεφωνικό codec)","Audio clock at 8,000 per second: +160 per 20 ms of sound.":"Ρολόι ήχου στα 8000 το δευτερόλεπτο: +160 ανά 20 ms ήχου.","160 bytes of G.711 audio (20 ms, one byte per sample)":"160 byte ήχου G.711 (20 ms, ένα byte ανά δείγμα)","IP Camera Streams":"Ροές από κάμερες IP","Video (RTP)":"Βίντεο (RTP)","Real Time Streaming Protocol":"Real Time Streaming Protocol","RTSP is how video players, recorders and security apps get live video from IP cameras. It works like a remote control: the player asks what the camera offers, sets up a stream, and says PLAY and later TEARDOWN, in text messages much like HTTP. The video itself doesn’t travel in RTSP: it flows separately as RTP, here over UDP.":"Το RTSP είναι ο τρόπος που οι εφαρμογές αναπαραγωγής, οι καταγραφείς και οι εφαρμογές ασφαλείας παίρνουν ζωντανή εικόνα από κάμερες IP. Λειτουργεί σαν τηλεχειριστήριο: η εφαρμογή ρωτά τι προσφέρει η κάμερα, στήνει μια ροή και λέει PLAY και αργότερα TEARDOWN, με μηνύματα κειμένου πολύ σαν το HTTP. Το ίδιο το βίντεο δεν ταξιδεύει στο RTSP: ρέει χωριστά ως RTP, εδώ πάνω σε UDP.",Controls:"Εντολές",Watched:"Το είδαμε","Described, set up, played, stopped":"Περιγραφή, στήσιμο, αναπαραγωγή, στοπ","VLC asked the camera what it had, logged in with a hash of its password, set up one video track and pressed PLAY. The video came as RTP packets on ports of its own, a key frame in three pieces, until TEARDOWN ended the session. Press REPLAY to watch it again.":"Το VLC ρώτησε την κάμερα τι έχει, συνδέθηκε με ένα hash του κωδικού του, έστησε ένα κομμάτι βίντεο και πάτησε PLAY. Το βίντεο ήρθε ως πακέτα RTP σε δικές του θύρες, ένα καρέ-κλειδί σε τρία κομμάτια, μέχρι το TEARDOWN να κλείσει τη συνεδρία. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","6 on one TCP connection":"6 σε μία σύνδεση TCP","Key frame":"Καρέ-κλειδί","Split into 3 packets":"Σε 3 πακέτα","1185d200, 60 s timeout":"1185d200, λήγει σε 60 s","What Can You Do?":"Τι μπορείς να κάνεις;","OPTIONS over a TCP connection":"OPTIONS σε σύνδεση TCP","VLC opens rtsp://192.168.1.64/stream1. It connects to the camera on TCP port 554 and starts with OPTIONS: which commands do you support? The camera lists them. As in HTTP, every request and reply is text; a CSeq header numbers them.":"Το VLC ανοίγει το rtsp://192.168.1.64/stream1. Συνδέεται στην κάμερα στη θύρα TCP 554 και ξεκινά με OPTIONS: ποιες εντολές υποστηρίζεις; Η κάμερα τις απαριθμεί. Όπως στο HTTP, κάθε αίτημα και απάντηση είναι κείμενο· μια κεφαλίδα CSeq τα αριθμεί.","Numbered by":"Αρίθμηση με","what can you do?":"τι μπορείς να κάνεις;","Describe the Stream":"Περιγραφή της ροής","SDP says what the video is":"Το SDP λέει τι είναι το βίντεο","DESCRIBE asks for the stream’s description. The camera wants a login first: 401, with a digest challenge. VLC asks again with a hash of the password, and the reply carries SDP: one H.264 video track, RTP payload type 96, with a 90 kHz clock.":"Το DESCRIBE ζητά την περιγραφή της ροής. Η κάμερα θέλει πρώτα σύνδεση: 401, με μια πρόκληση digest. Το VLC ρωτά ξανά με ένα hash του κωδικού, και η απάντηση φέρει SDP: ένα κομμάτι βίντεο H.264, τύπος φορτίου RTP 96, με ρολόι 90 kHz.","Digest: a hash":"Digest: ένα hash","H.264, payload type 96":"H.264, τύπος φορτίου 96",Track:"Κομμάτι","describe stream1":"περίγραψε το stream1","log in first":"πρώτα σύνδεση","SDP: H.264 video":"SDP: βίντεο H.264","track 1":"κομμάτι 1","Set Up":"Στήσιμο","Agree on ports for the video":"Συμφωνία θυρών για το βίντεο","SETUP for trackID=1 says how to deliver it: RTP over UDP, to the laptop’s ports 50000 (video) and 50001 (RTCP reports). The camera agrees, picks its own ports, 6970 and 6971, and opens a session, 1185d200, that every later request names.":"Το SETUP για το trackID=1 λέει πώς να παραδοθεί: RTP πάνω σε UDP, στις θύρες 50000 (βίντεο) και 50001 (αναφορές RTCP) του laptop. Η κάμερα συμφωνεί, διαλέγει δικές της θύρες, 6970 και 6971, και ανοίγει μια συνεδρία, 1185d200, που αναφέρει κάθε επόμενο αίτημα.","Laptop ports":"Θύρες του laptop","track 1, RTP over UDP":"κομμάτι 1, RTP πάνω σε UDP","to ports 50000-50001":"στις θύρες 50000-50001","session 1185d200":"συνεδρία 1185d200","from ports 6970-6971":"από τις θύρες 6970-6971",Play:"Αναπαραγωγή","The remote control’s PLAY button":"Το κουμπί PLAY του τηλεχειριστηρίου","PLAY starts the stream from now (npt=0.000-). The reply tells VLC which RTP sequence number and timestamp come first, so it can line the video up. From here on, the video doesn’t travel in RTSP at all.":"Το PLAY ξεκινά τη ροή από τώρα (npt=0.000-). Η απάντηση λέει στο VLC ποιος αριθμός ακολουθίας και ποια χρονοσήμανση RTP έρχονται πρώτα, για να ευθυγραμμίσει το βίντεο. Από εδώ και πέρα το βίντεο δεν ταξιδεύει καθόλου στο RTSP.",Range:"Εύρος","From now":"Από τώρα","First packet":"Πρώτο πακέτο","Video arrives":"Το βίντεο φτάνει","On the UDP ports":"Στις θύρες UDP","play from now":"παίξε από τώρα",playing:"παίζει","Video Arrives":"Έρχεται το βίντεο","A key frame in RTP packets":"Ένα καρέ-κλειδί σε πακέτα RTP","The camera sends a key frame, a whole picture, in three RTP packets: H.264 fragments marked first, middle and last, with the marker bit on the last. All three carry the same 90 kHz timestamp. Smaller frames holding only the changes follow, 25 a second.":"Η κάμερα στέλνει ένα καρέ-κλειδί, μια ολόκληρη εικόνα, σε τρία πακέτα RTP: θραύσματα H.264 σημαδεμένα ως πρώτο, μεσαίο και τελευταίο, με το bit σήμανσης στο τελευταίο. Και τα τρία έχουν την ίδια χρονοσήμανση 90 kHz. Ακολουθούν μικρότερα καρέ με μόνο τις αλλαγές, 25 το δευτερόλεπτο.",Packets:"Πακέτα","3 for one key frame":"3 για ένα καρέ-κλειδί","Same for the whole frame":"Ίδια για όλο το καρέ",Frames:"Καρέ","25 a second":"25 το δευτερόλεπτο","a key frame in 3 packets":"καρέ-κλειδί σε 3 πακέτα",Stop:"Στοπ","TEARDOWN ends the session":"Το TEARDOWN κλείνει τη συνεδρία","When the viewer closes the stream, VLC sends TEARDOWN with the session ID. The camera stops sending video and confirms. Had VLC simply vanished, the camera would stop anyway once 60 seconds passed without a word from it.":"Όταν ο θεατής κλείνει τη ροή, το VLC στέλνει TEARDOWN με το ID της συνεδρίας. Η κάμερα σταματά να στέλνει βίντεο και επιβεβαιώνει. Αν το VLC απλώς εξαφανιζόταν, η κάμερα θα σταματούσε ούτως ή άλλως μετά από 60 δευτερόλεπτα χωρίς λέξη από αυτό.",Ended:"Έκλεισε",Otherwise:"Αλλιώς","Timeout after 60 s":"Λήξη μετά από 60 s","stop session 1185d200":"κλείσε τη συνεδρία 1185d200",stopped:"σταμάτησε","The camera. It is on the same network, so the frame goes straight to it, not through the router.":"Η κάμερα. Είναι στο ίδιο δίκτυο, οπότε το πλαίσιο πηγαίνει κατευθείαν σε αυτήν, όχι μέσω του δρομολογητή.","The camera’s network port.":"Η θύρα δικτύου της κάμερας.","RTP + video":"RTP + βίντεο","0, 96 (H.264, as the camera’s description said)":"0, 96 (H.264, όπως έλεγε η περιγραφή της κάμερας)","Marker clear: more of this frame follows.":"Χωρίς σήμανση: ακολουθεί κι άλλο από αυτό το καρέ.","Video clock at 90,000 per second; every packet of one frame has the same value.":"Ρολόι βίντεο στα 90.000 το δευτερόλεπτο· όλα τα πακέτα ενός καρέ έχουν την ίδια τιμή.","Identifies this video stream.":"Αναγνωρίζει αυτή τη ροή βίντεο.","FU indicator":"Δείκτης FU","0x7c (fragment of a frame)":"0x7c (θραύσμα καρέ)","Fragmentation unit: one piece of a frame too big for one packet.":"Μονάδα κατάτμησης: ένα κομμάτι καρέ πολύ μεγάλου για ένα πακέτο.","FU header":"Κεφαλίδα FU","0x85 (first piece of a key frame)":"0x85 (πρώτο κομμάτι καρέ-κλειδιού)","Type 5: a key frame (IDR), a whole picture the decoder can start from.":"Τύπος 5: καρέ-κλειδί (IDR), μια ολόκληρη εικόνα από την οποία μπορεί να ξεκινήσει ο αποκωδικοποιητής.","1398 bytes of the key frame":"1398 byte του καρέ-κλειδιού","0x05 (middle piece of a key frame)":"0x05 (μεσαίο κομμάτι καρέ-κλειδιού)","1, 96 (H.264, as the camera’s description said)":"1, 96 (H.264, όπως έλεγε η περιγραφή της κάμερας)","Marker set: the last packet of a frame.":"Με σήμανση: το τελευταίο πακέτο ενός καρέ.","0x45 (last piece of a key frame)":"0x45 (τελευταίο κομμάτι καρέ-κλειδιού)","900 bytes of the key frame":"900 byte του καρέ-κλειδιού","Multicast TV":"Τηλεόραση με πολυεκπομπή","Joins and leaves":"Εγγραφές και αποχωρήσεις","Channel 1":"Κανάλι 1","TV channels":"Τηλεοπτικά κανάλια","Internet Group Management Protocol":"Internet Group Management Protocol","Multicast sends one stream to a group address, and the network copies it only where it’s wanted: it’s how internet providers deliver live TV channels. IGMP is how a device tells its router which groups it wants. Switches listen in (IGMP snooping), so each stream reaches only the ports that asked for it.":"Η πολυεκπομπή στέλνει μία ροή σε μια διεύθυνση ομάδας, και το δίκτυο την αντιγράφει μόνο όπου τη θέλουν: έτσι οι πάροχοι διαδικτύου μεταδίδουν ζωντανά τηλεοπτικά κανάλια. Το IGMP είναι ο τρόπος που μια συσκευή λέει στον δρομολογητή της ποιες ομάδες θέλει. Οι μεταγωγείς κρυφακούν (IGMP snooping), οπότε κάθε ροή φτάνει μόνο στις θύρες που τη ζήτησαν.","IP protocol 2":"Πρωτόκολλο IP 2",Groups:"Ομάδες","Version here":"Έκδοση εδώ","Tuned In":"Συντονίστηκε","Joined, copied, checked, left":"Εγγραφή, αντιγραφή, έλεγχος, αποχώρηση","The TV box and then the laptop joined channel 1 with IGMP reports. The router joined once for the whole home, and the switch, listening in, copied the channel only to the ports that wanted it. Queries kept it flowing, and when the laptop left, the TV box’s answer kept it on. Press REPLAY to watch it again.":"Το TV box και μετά το laptop μπήκαν στο κανάλι 1 με αναφορές IGMP. Ο δρομολογητής μπήκε μόνο μία φορά για όλο το σπίτι, και ο μεταγωγέας, κρυφακούγοντας, αντέγραψε το κανάλι μόνο στις θύρες που το ήθελαν. Τα ερωτήματα το κράτησαν σε ροή, και όταν το laptop έφυγε, η απάντηση του TV box το κράτησε ανοιχτό. Πατήστε ΞΑΝΑ για να το ξαναδείτε.",Upstream:"Προς τον πάροχο","One stream for the home":"Μία ροή για όλο το σπίτι","Copies to ports that joined":"Αντίγραφα στις θύρες μελών","Every 125 s":"Κάθε 125 s","Pick a Channel":"Επιλογή καναλιού","The TV box joins a group":"Το TV box μπαίνει σε μια ομάδα","The viewer picks channel 1. Each channel is a multicast group, here 233.252.0.1, and the TV box sends an IGMP Membership Report to that address: I want this group. The switch listens in (IGMP snooping), notes port 2, and passes the report to the router alone.":"Ο θεατής επιλέγει το κανάλι 1. Κάθε κανάλι είναι μια ομάδα πολυεκπομπής, εδώ η 233.252.0.1, και το TV box στέλνει ένα IGMP Membership Report σε αυτή τη διεύθυνση: θέλω αυτή την ομάδα. Ο μεταγωγέας κρυφακούει (IGMP snooping), σημειώνει τη θύρα 2 και δίνει την αναφορά μόνο στον δρομολογητή.","Switch notes":"Ο μεταγωγέας σημειώνει","Port 2 wants it":"Η θύρα 2 το θέλει","233.252.0.1, please":"233.252.0.1, παρακαλώ","to the router port only":"μόνο στη θύρα του δρομολογητή","Ask the Provider":"Αίτημα στον πάροχο","The router joins for the home":"Ο δρομολογητής μπαίνει για το σπίτι","The router is an IGMP proxy: it joins the group on its internet side with a report of its own, from its public address, and the provider’s network starts sending channel 1 down the line. However many screens at home tune in, the router joins only once.":"Ο δρομολογητής είναι διαμεσολαβητής IGMP: μπαίνει στην ομάδα από την πλευρά του διαδικτύου με δική του αναφορά, από τη δημόσια διεύθυνσή του, και το δίκτυο του παρόχου αρχίζει να στέλνει το κανάλι 1 στη γραμμή. Όσες οθόνες κι αν συντονιστούν στο σπίτι, ο δρομολογητής μπαίνει μόνο μία φορά.","Router role":"Ρόλος δρομολογητή","IGMP proxy":"Διαμεσολαβητής IGMP",Joins:"Μπαίνει","Once for the whole home":"Μία φορά για όλο το σπίτι","for the whole home":"για όλο το σπίτι","The Channel Flows":"Το κανάλι ρέει","Sent only where it was asked for":"Μόνο όπου ζητήθηκε","The provider’s TV server sends channel 1 to 233.252.0.1: UDP datagrams holding seven 188-byte MPEG-TS packets of video and audio each. The router passes them in, and the switch sends them out of port 2 alone: only the TV box joined, so the laptop gets none.":"Ο τηλεοπτικός διακομιστής του παρόχου στέλνει το κανάλι 1 στη 233.252.0.1: datagram UDP που το καθένα φέρει επτά πακέτα MPEG-TS των 188 byte με βίντεο και ήχο. Ο δρομολογητής τα περνά μέσα, και ο μεταγωγέας τα βγάζει μόνο από τη θύρα 2: μόνο το TV box μπήκε, οπότε το laptop δεν παίρνει κανένα.",Datagram:"Datagram","UDP, 1,316 bytes of TV":"UDP, 1.316 byte τηλεόρασης",Holds:"Περιέχει","7 MPEG-TS packets":"7 πακέτα MPEG-TS","CHANNEL 1":"ΚΑΝΑΛΙ 1","MPEG-TS over UDP":"MPEG-TS πάνω σε UDP","passed into the home":"πέρασε στο σπίτι","port 2 only":"μόνο θύρα 2","A Second Screen":"Δεύτερη οθόνη","The laptop tunes in too":"Και το laptop συντονίζεται","The laptop opens channel 1 in VLC and sends its own report. The switch adds port 1 and now makes two copies of every datagram. The router already gets the channel, so it asks the provider for nothing: one stream still comes down the line.":"Το laptop ανοίγει το κανάλι 1 στο VLC και στέλνει δική του αναφορά. Ο μεταγωγέας προσθέτει τη θύρα 1 και τώρα φτιάχνει δύο αντίγραφα από κάθε datagram. Ο δρομολογητής παίρνει ήδη το κανάλι, οπότε δεν ζητά τίποτα από τον πάροχο: στη γραμμή έρχεται ακόμα μία ροή.","Switch sends to":"Ο μεταγωγέας στέλνει σε","Ports 1 and 2":"Θύρες 1 και 2","Still one stream":"Ακόμα μία ροή","Router asks":"Ο δρομολογητής ζητά","Nothing new":"Τίποτα νέο","the same one stream":"η ίδια μία ροή","copied to ports 1 and 2":"αντιγράφηκε στις θύρες 1 και 2","Still Watching?":"Βλέπεις ακόμα;","The router checks regularly":"Ο δρομολογητής ελέγχει τακτικά","Every 125 seconds the router sends a General Query to 224.0.0.1, every device: which groups do you still want? The switch passes it to every port. Each member answers at a random moment within 10 seconds, so the router and the switch keep the channel coming.":"Κάθε 125 δευτερόλεπτα ο δρομολογητής στέλνει ένα General Query στη 224.0.0.1, σε όλες τις συσκευές: ποιες ομάδες θέλετε ακόμα; Ο μεταγωγέας το δίνει σε κάθε θύρα. Κάθε μέλος απαντά σε τυχαία στιγμή μέσα σε 10 δευτερόλεπτα, οπότε δρομολογητής και μεταγωγέας κρατούν το κανάλι να έρχεται.","125 seconds":"125 δευτερόλεπτα","224.0.0.1, all devices":"224.0.0.1, όλες οι συσκευές","Answer within":"Απάντηση μέσα σε","10 seconds":"10 δευτερόλεπτα",QUERY:"ΕΡΩΤΗΜΑ","any groups wanted?":"ποιες ομάδες θέλετε;","to every port":"σε κάθε θύρα",REPORT:"ΑΝΑΦΟΡΑ","still watching":"βλέπω ακόμα",Leave:"Αποχώρηση","The laptop stops watching":"Το laptop σταματά να βλέπει","Closing VLC sends a Leave Group to 224.0.0.2, all routers. Others may still watch, so the router asks about that group alone and waits 1 second. The TV box answers, so the channel stays; the switch just stops sending it to port 1.":"Το κλείσιμο του VLC στέλνει ένα Leave Group στη 224.0.0.2, σε όλους τους δρομολογητές. Άλλοι μπορεί να βλέπουν ακόμα, οπότε ο δρομολογητής ρωτά μόνο για εκείνη την ομάδα και περιμένει 1 δευτερόλεπτο. Το TV box απαντά, άρα το κανάλι μένει· ο μεταγωγέας απλώς σταματά να το στέλνει στη θύρα 1.","Leave sent to":"Αποχώρηση προς","224.0.0.2, all routers":"224.0.0.2, όλοι οι δρομολογητές","About that group alone":"Μόνο για εκείνη την ομάδα","Stays: the TV box answered":"Μένει: απάντησε το TV box",LEAVE:"ΑΠΟΧΩΡΗΣΗ","done with 233.252.0.1":"τέλος με το 233.252.0.1","anyone for 233.252.0.1?":"θέλει κανείς το 233.252.0.1;","to the ports that joined":"στις θύρες μελών","Multicast: 01:00:5e, then the last 23 bits of the group address. Network cards listen for the groups their system has joined.":"Πολυεκπομπή: 01:00:5e, μετά τα τελευταία 23 bit της διεύθυνσης ομάδας. Οι κάρτες δικτύου ακούν τις ομάδες στις οποίες έχει μπει το σύστημά τους.","The TV box’s network port.":"Η θύρα δικτύου του TV box.","4, 24 bytes":"4, 24 byte","IPv4, with one 4-byte option.":"IPv4, με μία επιλογή 4 byte.","48 (network control), 0":"48 (έλεγχος δικτύου), 0","Marked as network control, so it is sent ahead of ordinary traffic.":"Σημασμένο ως έλεγχος δικτύου, οπότε φεύγει πριν από τη συνηθισμένη κίνηση.","Always 1: IGMP never goes past the first router.":"Πάντα 1: το IGMP δεν περνά ποτέ πέρα από τον πρώτο δρομολογητή.","A multicast group address.":"Μια διεύθυνση ομάδας πολυεκπομπής.","Router Alert option":"Επιλογή Router Alert","Asks every router on the way to look inside, though the packet isn’t addressed to it.":"Ζητά από κάθε δρομολογητή στον δρόμο να κοιτάξει μέσα, αν και το πακέτο δεν απευθύνεται σε αυτόν.","This device wants the group’s traffic.":"Αυτή η συσκευή θέλει την κίνηση της ομάδας.","Max response time":"Μέγιστος χρόνος απάντησης","Only queries use it.":"Τον χρησιμοποιούν μόνο τα ερωτήματα.","Covers the IGMP message.":"Καλύπτει το μήνυμα IGMP.","Group address":"Διεύθυνση ομάδας","The multicast group: one TV channel.":"Η ομάδα πολυεκπομπής: ένα τηλεοπτικό κανάλι.","Seen arriving on the router’s internet side":"Φαίνεται φτάνοντας στην πλευρά διαδικτύου του δρομολογητή","MPEG-TS · 7 packets":"MPEG-TS · 7 πακέτα","The provider’s router, passing the channel on.":"Ο δρομολογητής του παρόχου, που προωθεί το κανάλι.","Sync byte":"Byte συγχρονισμού","Every transport stream packet starts with 0x47, so the receiver can find where packets begin.":"Κάθε πακέτο transport stream αρχίζει με 0x47, ώστε ο παραλήπτης να βρίσκει πού αρχίζουν τα πακέτα.","Flags, PID":"Σημαίες, PID","0x0100 (PID 256: video)":"0x0100 (PID 256: βίντεο)","Which stream the packet belongs to: the channel’s video, its audio, or the tables that list them.":"Σε ποια ροή ανήκει το πακέτο: στο βίντεο του καναλιού, στον ήχο του, ή στους πίνακες που τα απαριθμούν.","Payload, counter":"Φορτίο, μετρητής","0x14 (payload only, counter 4)":"0x14 (μόνο φορτίο, μετρητής 4)","Counts 0 to 15 for each PID, so a lost packet shows up as a gap.":"Μετρά από 0 έως 15 για κάθε PID, οπότε ένα χαμένο πακέτο φαίνεται ως κενό.","184 bytes of the channel’s video":"184 byte από το βίντεο του καναλιού","More packets":"Άλλα πακέτα","6 × 188 bytes: video and audio":"6 × 188 byte: βίντεο και ήχος","Six more transport stream packets, each with its own 4-byte header.":"Άλλα έξι πακέτα transport stream, το καθένα με δική του κεφαλίδα 4 byte.","Seen going into the switch, port 8":"Φαίνεται μπαίνοντας στον μεταγωγέα, θύρα 8","The router, passing the channel into the home.":"Ο δρομολογητής, που περνά το κανάλι μέσα στο σπίτι.","0x19 (payload only, counter 9)":"0x19 (μόνο φορτίο, μετρητής 9)","The router asks: which groups does anyone here still want?":"Ο δρομολογητής ρωτά: ποιες ομάδες θέλει ακόμα κάποιος εδώ;","Members answer at a random moment within this time, so their answers don’t all arrive at once.":"Τα μέλη απαντούν σε τυχαία στιγμή μέσα σε αυτόν τον χρόνο, ώστε οι απαντήσεις να μη φτάνουν όλες μαζί.","Zero in a general query: every group.":"Μηδέν σε γενικό ερώτημα: όλες οι ομάδες.","This device no longer wants the group.":"Αυτή η συσκευή δεν θέλει πια την ομάδα.","The router asks: does anyone still want this group?":"Ο δρομολογητής ρωτά: θέλει κανείς ακόμα αυτή την ομάδα;","Live Streaming Upload":"Ανέβασμα ζωντανών μεταδόσεων","RTMP handshake":"Χειραψία RTMP","Video and audio":"Βίντεο και ήχος","Ingest Server":"Διακομιστής λήψης","Real-Time Messaging Protocol":"Real-Time Messaging Protocol","RTMP is how most streamers send live video to a platform: OBS and other apps push it to an ingest server, which turns it into streams for viewers. Made for Flash, it outlived Flash as the way to upload. Everything shares one TCP connection: commands, audio and video, cut into chunks.":"Το RTMP είναι ο τρόπος που οι περισσότεροι streamers στέλνουν ζωντανό βίντεο σε μια πλατφόρμα: το OBS και άλλες εφαρμογές το σπρώχνουν σε έναν διακομιστή λήψης, που το κάνει μεταδόσεις για τους θεατές. Φτιαγμένο για το Flash, επέζησε του Flash ως τρόπος ανεβάσματος. Όλα μοιράζονται μία σύνδεση TCP: εντολές, ήχος και βίντεο, κομμένα σε chunks.","H.264 video, AAC audio":"Βίντεο H.264, ήχος AAC","Encoded in AMF0":"Κωδικοποίηση σε AMF0","Secure version":"Ασφαλής εκδοχή","RTMPS, over TLS":"RTMPS, πάνω σε TLS","Adobe specification (2012)":"Προδιαγραφή της Adobe (2012)",Live:"Ζωντανά","Connected, published, streamed":"Σύνδεση, δημοσίευση, μετάδοση","OBS shook hands with the ingest server, connected to its live app, got stream 1 and published to it with the stream key. The video and audio then flowed in chunks over the same TCP connection until the streamer stopped. Press REPLAY to watch it again.":"Το OBS έκανε χειραψία με τον διακομιστή λήψης, συνδέθηκε στην εφαρμογή live του, πήρε το stream 1 και δημοσίευσε σε αυτό με το κλειδί ροής. Βίντεο και ήχος έρρευσαν μετά σε chunks στην ίδια σύνδεση TCP μέχρι να σταματήσει ο streamer. Πατήστε ΞΑΝΑ για να το ξαναδείτε.","One TCP, port 1935":"Μία TCP, θύρα 1935",Stream:"Ροή",Chunks:"Chunks","Up to 4,096 bytes":"Έως 4.096 byte","None: RTMPS adds TLS":"Καμία: το RTMPS προσθέτει TLS","TCP, then RTMP’s own":"TCP, μετά του RTMP","The streamer clicks Start Streaming. OBS connects to the ingest server on TCP port 1935, then RTMP has its own handshake: version 3 and 1,536 random bytes each way, which each side sends back. It shows both ends speak RTMP; it encrypts nothing.":"Ο streamer πατά Έναρξη μετάδοσης. Το OBS συνδέεται στον διακομιστή λήψης στη θύρα TCP 1935, και μετά το RTMP κάνει δική του χειραψία: έκδοση 3 και 1.536 τυχαία byte προς κάθε κατεύθυνση, που κάθε πλευρά τα επιστρέφει. Δείχνει ότι και οι δύο άκρες μιλούν RTMP· δεν κρυπτογραφεί τίποτα.","Each side":"Κάθε πλευρά","Sends 3,073 bytes":"Στέλνει 3.073 byte","version 3":"έκδοση 3","1,536 random bytes":"1.536 τυχαία byte","version 3, its own bytes":"έκδοση 3, δικά του byte","and C1 sent back":"και το C1 πίσω","S1 sent back":"το S1 πίσω",Connect:"Σύνδεση","To the server’s live app":"Στην εφαρμογή live του διακομιστή","OBS raises its chunk size to 4,096 bytes and sends connect for the app called live, in AMF0, a compact binary format from Flash. The server sets its own window, bandwidth and chunk size, and answers _result: NetConnection.Connect.Success.":"Το OBS ανεβάζει το μέγεθος chunk στα 4.096 byte και στέλνει connect για την εφαρμογή live, σε AMF0, μια συμπαγή δυαδική μορφή από το Flash. Ο διακομιστής ορίζει δικό του παράθυρο, εύρος ζώνης και μέγεθος chunk, και απαντά _result: NetConnection.Connect.Success.",App:"Εφαρμογή",Encoding:"Κωδικοποίηση","chunk size 4,096":"μέγεθος chunk 4.096","window, bandwidth, chunks":"παράθυρο, εύρος ζώνης, chunks","Make a Stream":"Δημιουργία ροής","createStream returns stream 1":"Το createStream δίνει το stream 1","Every message names a message stream; 0 is the connection itself. OBS releases and announces its stream key, then asks createStream for a stream to send on, all three commands in one packet. The server answers with stream ID 1.":"Κάθε μήνυμα αναφέρει μια ροή μηνυμάτων· το 0 είναι η ίδια η σύνδεση. Το OBS αποδεσμεύει και ανακοινώνει το κλειδί ροής του, και μετά ζητά με το createStream μια ροή για να στέλνει, και οι τρεις εντολές σε ένα πακέτο. Ο διακομιστής απαντά με stream ID 1.","3 in one packet":"3 σε ένα πακέτο",Gets:"Παίρνει","Stream ID 1":"Stream ID 1","stream ID 1":"stream ID 1",Publish:"Δημοσίευση","The stream key goes live":"Το κλειδί ροής βγαίνει στον αέρα","publish names the stream key, the secret that says whose channel this is. RTMP has no encryption, so the key crosses in plain text; platforms prefer RTMPS, the same over TLS. The server checks the key and answers NetStream.Publish.Start.":"Το publish δίνει το κλειδί ροής, το μυστικό που λέει ποιανού είναι το κανάλι. Το RTMP δεν κρυπτογραφεί τίποτα, οπότε το κλειδί περνά ως απλό κείμενο· οι πλατφόρμες προτιμούν το RTMPS, το ίδιο πάνω σε TLS. Ο διακομιστής ελέγχει το κλειδί και απαντά NetStream.Publish.Start.","The stream key":"Το κλειδί ροής","None (RTMPS adds TLS)":"Καμία (το RTMPS προσθέτει TLS)","on stream 1":"στο stream 1","stream key, live":"κλειδί ροής, live","Video and Sound":"Εικόνα και ήχος","Metadata, settings, then frames":"Μεταδεδομένα, ρυθμίσεις, μετά καρέ","OBS describes the stream: 1920×1080 at 30 frames a second, H.264 video, AAC audio. It sends the decoders’ settings, then a key frame, about 30 KB cut into 4,096-byte chunks. Frames follow non-stop, on the same TCP connection.":"Το OBS περιγράφει τη ροή: 1920×1080 με 30 καρέ το δευτερόλεπτο, βίντεο H.264, ήχος AAC. Στέλνει τις ρυθμίσεις των αποκωδικοποιητών, μετά ένα καρέ-κλειδί περίπου 30 KB κομμένο σε chunks των 4.096 byte. Τα καρέ ακολουθούν ασταμάτητα, στην ίδια σύνδεση TCP.","AAC, 48 kHz stereo":"AAC, 48 kHz στερεοφωνικό","30 KB in 8 chunks":"30 KB σε 8 chunks",METADATA:"ΜΕΤΑΔΕΔΟΜΕΝΑ","H.264 + AAC settings":"ρυθμίσεις H.264 και AAC","KEY FRAME":"ΚΑΡΕ-ΚΛΕΙΔΙ","8 chunks":"8 chunks","Stop Streaming":"Τέλος μετάδοσης","FCUnpublish and deleteStream":"FCUnpublish και deleteStream","When the streamer clicks Stop Streaming, OBS sends FCUnpublish and deleteStream for stream 1. The server answers NetStream.Unpublish.Success and ends the broadcast for viewers. Then OBS closes the TCP connection.":"Όταν ο streamer πατά Διακοπή μετάδοσης, το OBS στέλνει FCUnpublish και deleteStream για το stream 1. Ο διακομιστής απαντά NetStream.Unpublish.Success και τερματίζει τη μετάδοση για τους θεατές. Μετά το OBS κλείνει τη σύνδεση TCP.","C0: version":"C0: έκδοση","RTMP version 3, the only one in use.":"Έκδοση 3 του RTMP, η μόνη σε χρήση.",Time:"Χρόνος","A timestamp; zero is allowed.":"Μια χρονοσήμανση· επιτρέπεται το μηδέν.",Zero:"Μηδέν","Random data":"Τυχαία δεδομένα","Random bytes the server must send back.":"Τυχαία byte που πρέπει να επιστρέψει ο διακομιστής.","S0: version":"S0: έκδοση","Random bytes the client must send back.":"Τυχαία byte που πρέπει να επιστρέψει ο πελάτης.","1,536 bytes: C1 back":"1.536 byte: το C1 πίσω","The timestamp from the block it echoes.":"Η χρονοσήμανση από το μπλοκ που επιστρέφει.","Time read":"Χρόνος ανάγνωσης","C1’s random bytes, sent back unchanged.":"Τα τυχαία byte του C1, επιστρεμμένα αμετάβλητα.","1,536 bytes: S1 back":"1.536 byte: το S1 πίσω","S1’s random bytes, sent back unchanged.":"Τα τυχαία byte του S1, επιστρεμμένα αμετάβλητα.","RTMP · 2 messages":"RTMP · 2 μηνύματα","First message":"Πρώτο μήνυμα","Chunk header":"Κεφαλίδα chunk","type 0, chunk stream 2":"τύπος 0, ροή chunk 2","A full header follows: this chunk starts a message.":"Ακολουθεί πλήρης κεφαλίδα: αυτό το chunk ξεκινά ένα μήνυμα.","Message stream":"Ροή μηνυμάτων","Stream 0: the connection itself. (This number alone is little-endian.)":"Ροή 0: η ίδια η σύνδεση. (Μόνο αυτός ο αριθμός είναι little-endian.)","Chunk size":"Μέγεθος chunk","From now on this side cuts messages into chunks of up to this size (128 until it says otherwise).":"Από τώρα αυτή η πλευρά κόβει τα μηνύματα σε chunks έως αυτό το μέγεθος (128 μέχρι να πει κάτι άλλο).","Second message":"Δεύτερο μήνυμα","type 0, chunk stream 3":"τύπος 0, ροή chunk 3","Matches a reply to its request.":"Ταιριάζει μια απάντηση με το αίτημά της.","Command object":"Αντικείμενο εντολής","object, 5 properties":"αντικείμενο, 5 ιδιότητες","Which app on the server, and the address OBS was given.":"Ποια εφαρμογή στον διακομιστή, και η διεύθυνση που δόθηκε στο OBS.","End of object":"Τέλος αντικειμένου","RTMP · 4 messages":"RTMP · 4 μηνύματα","The other side should hear back after every this many bytes it sends.":"Η άλλη πλευρά πρέπει να παίρνει απάντηση μετά από κάθε τόσα byte που στέλνει.","Bandwidth, limit":"Εύρος ζώνης, όριο","5,000,000 bytes, dynamic":"5.000.000 byte, δυναμικό","How much the sender may have unacknowledged at once.":"Πόσα μπορεί να έχει ο αποστολέας ανεπιβεβαίωτα ταυτόχρονα.","Third message":"Τρίτο μήνυμα","Fourth message":"Τέταρτο μήνυμα",Properties:"Ιδιότητες","object, 2 properties":"αντικείμενο, 2 ιδιότητες",Information:"Πληροφορίες","object, 4 properties":"αντικείμενο, 4 ιδιότητες","RTMP · 3 messages":"RTMP · 3 μηνύματα","Nothing: AMF0 null.":"Τίποτα: null του AMF0.","Stream key":"Κλειδί ροής","Which channel this is. It works like a password, and here it travels unencrypted.":"Ποιο κανάλι είναι αυτό. Λειτουργεί σαν κωδικός, και εδώ ταξιδεύει χωρίς κρυπτογράφηση.","Stream ID":"Stream ID","The new stream: video and audio will go on it.":"Η νέα ροή: βίντεο και ήχος θα πάνε από εκεί.","type 0, chunk stream 4":"τύπος 0, ροή chunk 4","Stream 1, the one createStream made.":"Ροή 1, αυτή που έφτιαξε το createStream.","Publishing type":"Τύπος δημοσίευσης","Live: not recorded by this request.":"Live: αυτό το αίτημα δεν καταγράφει.","type 0, chunk stream 5":"τύπος 0, ροή chunk 5","object, 3 properties":"αντικείμενο, 3 ιδιότητες",Handler:"Χειριστής",Event:"Συμβάν",Metadata:"Μεταδεδομένα","array of 14":"πίνακας 14 στοιχείων","Codec IDs as in Flash video files: 7 is H.264, 10 is AAC.":"Αναγνωριστικά codec όπως στα αρχεία βίντεο Flash: το 7 είναι H.264, το 10 AAC.","type 0, chunk stream 6":"τύπος 0, ροή chunk 6","Frame, codec":"Καρέ, codec","0x17 (key frame, H.264)":"0x17 (καρέ-κλειδί, H.264)","AVC packet type":"Τύπος πακέτου AVC","0 (decoder settings)":"0 (ρυθμίσεις αποκωδικοποιητή)","The sequence header: the settings a decoder needs before the first frame.":"Η κεφαλίδα ακολουθίας: οι ρυθμίσεις που χρειάζεται ένας αποκωδικοποιητής πριν από το πρώτο καρέ.","Composition time":"Χρόνος σύνθεσης","The H.264 profile, level and parameter sets.":"Το προφίλ, το επίπεδο και τα σύνολα παραμέτρων του H.264.","AAC; the other bits are fixed for AAC.":"AAC· τα υπόλοιπα bit είναι σταθερά για το AAC.","AAC packet type":"Τύπος πακέτου AAC","Sample rate and channels, for the decoder.":"Ρυθμός δειγματοληψίας και κανάλια, για τον αποκωδικοποιητή.","1 (video)":"1 (βίντεο)","Compressed picture data.":"Συμπιεσμένα δεδομένα εικόνας.","The key frame: a whole picture. Every 4,096 bytes a 1-byte chunk header continues it.":"Το καρέ-κλειδί: μια ολόκληρη εικόνα. Κάθε 4.096 byte, μια κεφαλίδα chunk 1 byte το συνεχίζει."},r=t=>`${t} ${t==="1"?"τμήμα":"τμήματα"}`,n=t=>`${t} ${t==="1"?"εγγραφή":"εγγραφές"}`,p={strings:{...c,...d,...h},patterns:[[/^([\d,]+) bytes$/,"$1 byte"],[/^(Ethernet II|IPv4|IPv6|UDP|TCP|802\.11|LLC\/SNAP|EAPOL) · (\d+) bytes$/,"$1 · $2 byte"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$1, $2 byte"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 byte: report.pdf, byte $2"],[/^(.+) h later$/,"$1 h αργότερα"],[/^(.+) min later$/,"$1 min αργότερα"],[/^(.+) s later$/,"$1 s αργότερα"],[/^(\S+) \(relative\)$/,"$1 (σχετικό)"],[/^(\d+) \(ephemeral\)$/,"$1 (εφήμερη)"],[/^(\d+) TCP segments$/,(t,e)=>`${r(e)} TCP`],[/^(\d+) segments$/,(t,e)=>r(e)],[/^(.*), (\d+) segments$/,(t,e,s)=>`${e}, ${r(s)}`],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(t,e,s,o)=>`TLS 1.3 · ${n(e)} · byte ${s} από ${o}`],[/^TLS 1\.3 · (\d+) records?$/,(t,e)=>`TLS 1.3 · ${n(e)}`],[/^Ethernet padding · (\d+) bytes$/,"Συμπλήρωμα Ethernet · $1 byte"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 μηδενικά byte, ως το ελάχιστο των 300 byte"],[/^(\d+) zero bytes$/,"$1 μηδενικά byte"],[/^(\d+) random bytes$/,"$1 τυχαία byte"],[/^Seen as it leaves (.+)$/,"Όπως φαίνεται καθώς φεύγει από το $1"],[/^Option (\d+)$/,"Επιλογή $1"],[/^value (\d+), echo (\d+)$/,"τιμή $1, ηχώ $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 byte, συν $1 για επιλογές."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Τα Windows ξεκινούν από $1. Εδώ ορίστηκε σκόπιμα στο $2."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(t,e,s)=>s==="1"?`Ξεκίνησε από ${e}· ο δρομολογητής στη διαδρομή αφαίρεσε 1.`:`Ξεκίνησε από ${e}· καθένας από τους ${s} δρομολογητές στη διαδρομή αφαίρεσε 1.`],[/^all (\d+) bytes of it$/,"και τα $1 byte του"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Το πακέτο που το προκάλεσε, όπως το έλαβε η συσκευή που το αναφέρει (TTL $1), ώστε ο αποστολέας να ξέρει ποιο πακέτο ήταν."],[/^Port (\d+), TLS from the start$/,"Θύρα $1, TLS από την αρχή"],[/^(\d+), TLS from the start$/,"$1, TLS από την αρχή"],[/^type 79, (\d+) bytes$/,"τύπος 79, $1 byte"],[/^(\d+) of (\d+) bytes$/,"$1 από $2 byte"],[/^(\d+) more bytes$/,"ακόμη $1 byte"],[/^offset (\d+), (\d+) bytes$/,"μετατόπιση $1, $2 byte"],[/^offset 0, (\d+) bytes \(all of it\)$/,"μετατόπιση 0, $1 byte (όλο)"],[/^record, (\d+) bytes$/,"εγγραφή, $1 byte"],[/^EAPOL-Key · message (\d) of 4$/,"EAPOL-Key · μήνυμα $1 από 4"],[/^((?:SMB2|IKEv2) · )?([A-Z_]+) (request|response)$/,(t,e,s,o)=>{const a=o==="request"?"αίτημα":"απάντηση";return e?`${e}${a} ${s}`:`${a[0].toUpperCase()}${a.slice(1)} ${s}`}],[/^(\d+) registers$/,(t,e)=>`${e} ${e==="1"?"καταχωρητής":"καταχωρητές"}`],[/^id 1: −(\d+) dBov, voice$/,"id 1: −$1 dBov, ομιλία"],[/^"(.*)" \(([\d,]+) bytes\)$/,'"$1" ($2 byte)'],[/^(masked|not masked), (\d+) bytes?$/,(t,e,s)=>`${e==="masked"?"με μάσκα":"χωρίς μάσκα"}, ${s} byte`],[/^(\d+) \(disguised\)$/,"$1 (κρυμμένο)"],[/^(\d+) \((KE|Nonce|Notify|IDi|IDr)\), (\d+) bytes$/,"$1 ($2), $3 byte"],[/^0 \(none\), (\d+) bytes$/,"0 (κανένα), $1 byte"],[/^Microsoft \(311\), type (\d+)$/,"Microsoft (311), τύπος $1"],[/^(\d+) \(register (\d+)\)$/,"$1 (καταχωρητής $2)"],[/^yes, AS (\d+)$/,"ναι, AS $1"],[/^id 2, (\d+) bytes$/,"id 2, $1 byte"],[/^(\d), (\d+) \((Opus|VP8), as agreed in the SDP\)$/,"$1, $2 ($3, όπως συμφωνήθηκε στο SDP)"]],post:i};export{p as default};
